-- ============================================================
-- Qazax4b (2/3): Günə-özəl push bildirişlərinin Qazax (kk) tərcüməsi
-- pregnancy_day_notifications + mommy_day_notifications — Azure/gpt-5.6-sol
-- ƏVVƏL Qazax1.sql (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('e02612f3-415f-450d-9411-e60c3bd32d09'::uuid, 'Тыныштық үні 🌧️', 'Қарбалас күннен кейін мидың жұмысын баяулату қажет. Бөлмеде Ақ шулардан жаңбыр дыбысын қосып, ұйқыға жайлы әрі табиғи тыныш орта қалыптастырыңыз.'),
  ('3dca59c4-0add-4ccb-919d-3806c0dfdbf4', 'Табиғи тыныштандырғыш 🍃', 'Бүгін мазасыз әрі шулы күн болды ма? Ақ шулардан жапырақ сыбдырын қосып, бөпеңіздің де, өзіңіздің де жүйке жүйеңізді тынықтырыңыз.'),
  ('3f5ef83a-d114-41da-8dd2-6bd3c11c45e8', '5 минуттық қуат ⚡', 'Таңертең үй шаруасына бірден кіріспеңіз. Пайдалы рецептілерден антиоксиданттарға бай жидек қосылған сұлы ботқасын дайындап, бойыңызға қуат жинаңыз.'),
  ('e5117ef0-d242-45f1-b114-50b3bfca72d9', 'Сізге де орта қажет ☕', 'Тек бөпеңізбен сөйлесуден шаршадыңыз ба? Аналарға жайлы орындардан аналар жиі жиналатын балалар кафелерін тауып, араласыңыз.'),
  ('622216cc-100d-4e85-95dc-7d70e41c5761', 'Өзі тамақтанғысы келеді 🥣', 'Қасықты Сізге бермей ме? Тамақтану таймерін қосып, өз бетінше тамақтану талпынысына қанша уақыт кететінін талдаңыз. Шашылған тамаққа жай ғана күлімсіреңіз.'),
  ('9387504c-dde1-4fdb-977d-53c3dfbb83a2', 'Қауіпсіз зерттеу ⚠️', 'Шкафтар, тартпалар... Кішкентай зерттеуші үшін қауіпті! Ұсынылатын өнімдерден жиһаз қорғаныштары мен қауіпсіздік құлыптарын қарап шығыңыз.'),
  ('bdef77ef-7476-4b14-a4a3-51d31635951f', 'Күн тәртібін талдайық ⏱️', 'Кешкі сергектік уақыты тым ұзарып кетті ме? Ұйқы таймерін қосыңыз. Мүмкін, күндізгі ұйқыны 15 минутқа қысқартатын уақыт келген шығар.'),
  ('1221d1a0-4818-4be5-bd89-1e05d41e52f3', 'Ананың бел ауруы 🧘‍♀️', 'Бөпеңізді көтере бергеннен беліңіз ауыра ма? Пайдалы рецептілерден қабынуға қарсы әрі қалпына келуге көмектесетін зімбір қосылған көк шай демдеп, денсаулығыңызға күтім жасаңыз.'),
  ('5e592d03-eefe-420f-a53e-496dd3dda1cc', 'Стақанға бола шу шықты ма? 🥤', 'Суды қызыл емес, көк стақанға құйғаныңыз үшін бөпеңіз ашуланды ма? Қисынсыз көрінетін мұндай ашу ұстамаларын сабырмен қалай шешуге болатынын Anacan AI-дан дереу сұраңыз.'),
  ('5fa9e0c4-2198-4898-832b-73dabf54c160', 'Ішіңіздегіні ақтарыңыз 📝', 'Бүгін бөпеңіз тоқтамай жылады, ал Сіз қатты шаршадыңыз. Өзіңізді кінәламаңыз. Барлық шаршағаныңызды Көңіл күй күнделігіне жазып, ойыңызды жеңілдетіп, демалыңыз.'),
  ('17a5c3c0-5b0c-46d3-a055-3e4119a58d57', 'Ертегіні өзі айтсын 📖', 'Кітаптағы суреттерге қарап, өз тілінде бірдеңелер айтып отыр ма? Қиялы шарықтаған осы тамаша сәтті дыбысы бар видео ретінде Бөпе альбомына дереу қосып, болашаққа сақтап қойыңыз.'),
  ('200bc386-90fc-4565-9a45-00b11604777d', 'Төрт қабырғадан шығыңыз 🌳', 'Үйде энергиясын шығара алмай, бәрін шашып жүр ме? Аналарға қолайлы орындар картасын ашып, қауіпсіз жүгіретін алаңы бар саябақты тауып, таза ауаға шығыңыз.'),
  ('f2808bcb-7bbf-4422-8d7a-f49af045384f', 'Бөліскісі келмей ме? 🧸', 'Саябақта ойыншығын ешкімге бермей ме? Блогтар бөліміндегі 22 айлық балаларға кезекпен ойнауды үйрететін практикалық мақаланы міндетті түрде оқыңыз.'),
  ('5ba12c84-c569-4cd8-9800-87090cc15d44', 'Кальций қалқаны 🦴', 'Сүйектер мен тістерге кальций қажет. Тамақтануды бақылау құралы арқылы бүгінгі йогурт пен ірімшік мөлшері нормаға сай екенін тексеріңіз.'),
  ('7ecc82ad-1a38-4c53-9465-dd5ae12ea103', 'Аяқ киімі қысып жүр ме? 📏', 'Соңғы кезде жүгіргенде жиі сүріне ме? Аяғының өлшемі үлкейген болуы мүмкін! Қазіргі бойы мен өлшемдерін Салмақ трекеріне енгізіп, дене дамуын бақылаңыз.'),
  ('d79dc60f-8bf8-4657-a15d-609886c6c332', 'Тамағын жерге лақтыра ма? 🥣', 'Қасығы мен тамағын үстелден төмен лақтыра бастаса, тойған немесе жалыққан болуы мүмкін. Тамақтану таймерін тоқтатып, тәбетінің өзгерісін график арқылы талдаңыз да, тамақтануды аяқтаңыз.'),
  ('bafa81ec-ed9b-4642-a5cd-3249a43a8c84', 'Ұру немесе итеру 🛑', 'Ашуланғанда қолын бірден көтере ме? Осы жасқа тән агрессиялық эмоцияларды ойын арқылы қалай жұмсақ өзгертуге болатынын білу үшін Anacan AI-ға жүгініңіз.'),
  ('1b86b21d-6e02-4ac7-a965-21bdbcf95db5', 'Логикалық серпіліс 🧩', 'Ол себеп-салдар байланысын түсіне бастады. Блогтар бөлімінен 22 айлық балалардың танымдық дамуын жеделдететін ең жақсы үй ойындары туралы оқып, қолданып көріңіз.'),
  ('6351737e-949c-4fb6-a2b3-5af919c832cf', 'Күн тәртібін талдайық ⏱️', 'Кешкі сергектік уақыты тым ұзарып кетті ме? Ұйқы таймерін қосып, кестені бақылаңыз. Күндізгі ұйқыны 15 минутқа қысқартатын уақыт келген шығар.'),
  ('f36fcaba-998e-48e4-a1c2-d085b47ccd2f', 'Темір қорын тексеру 🥩', 'Белсенді қимылдайтын бұлшықеттер үшін қаназдық болмауы керек. Тамақтануды бақылау құралы арқылы бүгін қанша темір қабылдағанын тексеріп, жетіспеген мөлшерін дереу толықтырыңыз.'),
  ('04a88ead-f1bb-44fb-a8ea-9c02adfcfb9b', 'Қантсыз тіскебасар 🍪', 'Дүкен печеньелерінің қажеті жоқ. Бөпелерге арналған рецептілерден үйде 10 минутта дайындалатын, құрма мен алмадан жасалған пайдалы тәттілерді тауып, тәбетін ашыңыз.'),
  ('7b343e4c-3369-4f05-b976-97c243e8ed13', 'Бой өсу серпілісі! 📏', 'Жейделерінің жеңі қайтадан қысқарып қалды ма? Дене дамуы қарқын алып келеді. Даму трекеріне қазіргі өлшемдерін енгізіп, өсу кестесіне мақтанышпен қараңыз.'),
  ('7c55b3cc-0f0f-47b0-8148-d026b3b7590e', 'Жаңа сөздер келе жатыр! 🗣️', 'Көп дыбыс шығарады, бірақ әлі толық сөз айтпай ма? Пассив сөздік қорын белсендіру үшін оның буындарды күлкілі айту әрекеттерін дыбыстық жазба түрінде Бөпе альбомына қосып, бақылаңыз.'),
  ('614145be-ebb6-498c-9b3f-26a829cb6b6d', 'Тазалық көмекшісі 🧹', 'Ол енді үй шаруасына қатысқысы келеді. Блогтар бөлімінен 22.5 айлық балаға жауапкершілік сезімін ойын арқылы қалай сіңіруге болатынын оқып, қолданып көріңіз.'),
  ('1a8b991b-0214-44d5-b2fa-cca54722c709', 'Қабырғадағы өнер туындысы 🎨', 'Қолына қарындаш алып, қабырғаны бояп тастады ма? Ашуланбаңыз! Осы сүйкімді тентектігін Бөпе фотосессиясындағы көңілді жиектемелермен альбомға қосып, жай ғана жымиыңыз.'),
  ('5ded1b01-b65d-40da-8990-d4cd09688a69', 'Кенеттен ояну қайта басталды ма? ⏱️', 'Түн ортасында жылап ояна ма? Ұйқы таймерінің кестесін қараңыз. Күндізгі ұйқысы тым кеш аяқталса, кешке терең ұйқыға кетуі қиындайды.'),
  ('79c4c89f-ba17-4c97-96b0-f5dc444414e9', 'Ананың кофе ішуге арналған үзілісі ☕', 'Өзіңізді ұмытпаңыз! Әйелдерге арналған пайдалы рецептілерден қуат беретін сұлы тіскебасарын дайындап, кофеңізден ләззат алыңыз.'),
  ('178de938-0734-4759-bd61-91671bd355ba', 'Түбекті дұрыс таңдау 🚽', 'Дәретке үйретуге көрнекі дайындық басталсын! Ұсынылатын өнімдер бөлімінен аналар сынап көрген ең ыңғайлы әрі тартымды түбек үлгілерін міндетті түрде қарап шығыңыз.'),
  ('2f6cc31a-8b1b-415e-861a-b476799ab26e', 'Омега-3 қоры жеткілікті ме? 🐟', 'Мидың қарқынды дамуы үшін балық немесе жаңғақ қажет! Тамақтануды бақылау құралы арқылы осы аптадағы Омега-3 тұтыну мөлшерін тексеріп, мәзірді бірден жаңартыңыз.'),
  ('f1e65e7a-efb2-4ee4-9b90-639511a93965', 'Мінсіз болуға міндетті емессіз 💖', 'Бүгін үй шашылып, тамақ кешікті ме? Ештеңе етпейді! Көңіл күй күнделігіне ішкі ойыңызды жазып, балаңыздың Сізді қандай күйде болсаңыз да жақсы көретінін есіңізге түсіріңіз.'),
  ('0ec68466-1a64-4bc2-ab11-6f19a539925d', 'Көп су — жеңіл ас қорыту 💧', 'Белсенді бөпеңіздің ішегі қалай жұмыс істеп жүр? Жөргегін ауыстырған кезде мәліметтерді енгізіңіз. Іш қату қаупі болса, қолданбадан табиғи талшыққа бай тағамдар туралы ұсыныстарды қараңыз.'),
  ('60b3ac1d-dc8e-4802-b644-6bc09bfcea1f', 'Тамақ үшін тартыс аяқталды ⏱️', 'Үстел басында қасықты лақтырып жібере ме? Тамақтану таймерін тоқтатыңыз — бала тойды. Тәбет кестесін талдау арқылы күштеп тамақтандырудан аулақ болыңыз.'),
  ('685f831c-092e-4c6a-aaf1-8fc0973b0182', '5 минуттық қуат ⚡', 'Таңертең үй шаруасына бірден кірісіп кетпеңіз. Әйелдерге арналған пайдалы рецептілерден антиоксиданттарға бай жидекті сұлы ботқасын дайындап, бойыңызға қуат жинаңыз.'),
  ('a2d43041-fecf-4b9c-87c8-b48f899e1810', 'Түнде ояну ⏱️', 'Ұйқы таймерін қосыңыз! Таймердің статистикалық графигі арқылы түнгі қорқыныш немесе ұйқы регрессиясы бар-жоғын нақты талдап, режимді реттеңіз.'),
  ('ca7d5385-3628-4318-a29d-52e41611d6dd', 'Зияткерлік даму тоқтамайды 🧠', 'Ол бәрін сұрыптағанды жақсы көреді! Түс пен пішінді қабылдауын дамытып, миын ынталандыратын геометриялық басқатырғыштарды (пазлдарды) Ұсынылатын өнімдер бөлімінен дәл қазір қараңыз.'),
  ('2c09d1ae-89ad-4429-b136-e47270b6a957', 'Бүгінгі күннің қаһарманы — Сіз 🌟', 'Оның күн сайын меңгерген әрбір жаңа дағдысы — Сіздің еңбегіңіздің жемісі. Көңіл күй күнделігін ашып, бүгін өзіңізді тік тұрып қол соғуға лайық сезіндіретін жазба қалдырыңыз!'),
  ('61d69ed1-ecb9-44fd-ac6a-cb922359921f', 'Бояуға малынған суретші! 📸', 'Өзін де, қабырғаны да бояп тастады ма? Ашуланудың орнына, осы күлкілі шимайлау сәтін Бөпе фотосессиясындағы көңілді стикерлермен безендіріп, мәңгілік естелік ретінде альбомға жүктеңіз.'),
  ('f52268ca-f991-4824-88f4-73fcbe961356', 'Іш қату мәселесі бар ма? 💩', 'Таңертең жөргегін ауыстырғанда нәжісін бақылаңыз. Іші қатса, оны қолданбаға белгілеп, Тамақтануды бақылау құралы арқылы мәзіріне міндетті түрде талшыққа бай тағамдар қосыңыз.'),
  ('596bb7f3-6693-46d8-ab7c-2abd702c9a04', 'Қауіпсіздік сезімі 🌌', 'Бөлменің жарығын өшіргенде қорқа ма? Ақ шулардан ана құрсағындағы дыбысты (жүрек соғысын) қосып, бөпеңізге бұрыннан таныс жылы қауіпсіздік сезімін сыйлаңыз әрі ұйқыға дайындаңыз.'),
  ('85644ffd-0693-4b98-8af6-f0210f7b50a9', 'Сізге де араласу қажет ☕', 'Тек баламен сөйлесуден шаршадыңыз ба? Анаға жайлы орындар бөлімінен аналар жиі жиналатын балалар кафелерін тауып, өзіңізге де жаңа орта қалыптастырыңыз.'),
  ('e1d32a6a-e4ea-4c4f-8731-157813de9284', 'Басқа аналармен танысу 👯‍♀️', 'Балаңыз ойнасын, ал Сіз әңгімелесіңіз! Анаға қолайлы орындар картасынан ойын топтары бар орталықты тауып, серуендеп қайтыңыз.'),
  ('2e576d6b-3baa-4d91-b939-7173553eee26', 'Тіс тазалайсыздар ма? 🪥', 'Тіс щеткасын көре сала аузын ашпай қоя ма? Осы гигиеналық әдетті көңілді ойынға айналдыру жолдарын білу үшін Anacan AI-дан пайдалы кеңестер алыңыз.'),
  ('8e98b7fa-b3a5-48a4-896a-9431c201a988', 'Табиғи тыныштандырғыш 🍃', 'Бүгін тым қарбалас күн болды ма? Таймер тоқтады. Үй шаруасын ұмытып, Пайдалы рецепттерден мелисса шайын демдеңіз де, тыныштықтан ләззат алыңыз.'),
  ('e49913ea-33f5-4d6e-8204-24fdfbb6dfec', 'Пайдалы тәтті іздейміз 🍎', 'Дүкен печеньесімен қоштасыңыз! Бөпеге арналған рецепттерден үйде 10 минутта дайындалатын құрма мен алмадан жасалған пайдалы печеньелерді тауып, тәбетін ашыңыз.'),
  ('8566be64-ecf0-4dc1-8d90-20c831db74ad', 'Ажырасудан қорқу қайта басталды ма? 🌌', 'Бөлмеден шыға салысымен артыңыздан жылай ма? Ақ шу бөлімінен жүрек соғысының дыбысын қосып, оған қауіпсіздік сезімін сыйлаңыз әрі ұйқыға бейімдеңіз.'),
  ('942d7419-7926-47e6-b70e-db59dc58e301', 'Шалбарлары тағы да қысқарып қалды! 📏', 'Жейделерінің жеңдері тарылып бара ма? Бұл — дене дамуының қарқынды кезеңі. Салмақ бақылау құралына қазіргі өлшемдерін енгізіп, өсу графигін мақтанышпен тамашалаңыз.'),
  ('95ec49ae-492b-442d-be59-8db9c9f8c8e4', 'Күлкілі айтылған сөздер 🗣️', 'Кейбір сөздерді сондай сүйкімді әрі қате айтады! Осындай қымбат сәттерді жіберіп алмаңыз. Бөпе альбомына дыбысы бар видео ретінде жүктеп, болашақта бірге күліңіздер.'),
  ('25439bfb-873c-4735-bc03-f5aa2d6b8ff2', 'Ақуыз қоры жеткілікті ме? 🍗', 'Белсенді бұлшықеттер үшін ақуыз қажет. Тамақтануды бақылау құралы арқылы оның күнделікті ас мәзірінің теңгерімін бағалап, мәзірін байытыңыз.'),
  ('6d017679-be1f-4b11-b8fd-36574013a33a', 'Қиялдың шегі жоқ 🧸', 'Қонжығына тамақ беріп жатыр ма, әлде Сізді емдеп жүр ме? Эмпатиясының дамуын қысқа видеоға түсіріп, Бөпе альбомына қосыңыз да, өмірлік естелік жасаңыз.'),
  ('f542a783-2187-4790-b865-10366397c49d', 'Қауіпсіз зерттеу ⚠️', 'Шкафтар, тартпалар... Кішкентай зерттеуші үшін қауіпті болуы мүмкін! Ұсынылатын өнімдер бөлімінен жиһазға арналған қорғаныштар мен қауіпсіздік құлыптарын міндетті түрде қарап шығыңыз.'),
  ('8497fe17-ba82-4513-8de8-e30bada196eb', 'Күннің шаршауын басыңыз 🛋️', 'Артынан жүгіріп әбден қалжырадыңыз. Бөпе ұйықтады, енді бүкіл күйзелісті Көңіл күй күнделігіне жазып, өзіңізге бір кесе шөп шайын құйып алыңыз.'),
  ('8fc02957-0717-4600-94a0-03ec95b3ecc9', 'Түбекке дайындық белгілері? 🚽', 'Таңертең жөргегі мүлде құрғақ па? Бұл түбекке үйретуді бастауға қолайлы уақыт болуы мүмкін. Жөргек бақылағышына белгілеңіз және қолданбадағы дайындық туралы мақалаларды қарап шығыңыз.'),
  ('924176de-d987-4381-ba5c-3bdf618f72f9', 'Ет жегісі келмей ме? 🥩', 'Ақуыз қажет, бірақ еттен бас тарта ма? Бөпеге арналған рецепттерден шайнауға оңай, дәмді тауық тефтельдерін дайындап, Тамақтануды бақылау құралындағы нормасын толықтырыңыз.'),
  ('75bd2c8f-8af9-437f-ac84-6c69bc76ea8c', 'Төсектен қашу жоспары 🏃‍♂️', 'Ұйықтайтын уақыт келгенде бөлмеден қаша ма? Ұйқы таймерін қосып, Ақ шулардан орманның шуылын таңдаңыз да, бөлмені тыныш үңгірге айналдырыңыз.'),
  ('bd146fb2-5002-4d8c-824b-58bbd81c0c9b', 'Таңғы қырсықтық 🛑', '«Мұны кимеймін, оны жемеймін!» деген қылықтары таңыңызды қиындата ма? Дереу Anacan AI-ға жазып, осы жастағы шекараны сынау әрекеттерін қалай басқаруға болатынын біліңіз.'),
  ('fdf24d1a-f6c7-451f-974c-c9a5a3bf1aa7', 'Қабырғадан диванға секіру! 🧗‍♂️', 'Ол нағыз каскадер! Үйде жиналған энергиясын шығару үшін Анаға қолайлы орындардан кең ойын залдары бар орталықтарды тауып, еркін ойнауына мүмкіндік беріңіз.'),
  ('057bf87f-0bbd-415e-a240-9562e85f263d', 'Киіну дауы! 👗', 'Таңертең киіну үлкен мәселеге айнала ма? Оған екі түрлі жейде ұсынып, өзіне таңдау жасауға мүмкіндік беріңіз.'),
  ('2ac666c9-f3bd-4794-a981-76652151d626', 'Көзін уқалап жүр ме? 🥱', 'Бұл — ұйқысының келгенін білдіретін белгі! Ұйқы таймерін қосып, Ақ шу бөлімінен орман сыбдырын ойнатыңыз. Оны жайлап ұйқыға дайындап, ұйқы кестесін қадағалаңыз.'),
  ('5ce76677-164d-4bc6-835d-9ba614b47d9b', 'Ананың кофе ішетін уақыты ☕', 'Енді үзіліс жасайтын уақыт келді. Балаңыз өз бетінше ойнап жатқанда, Әйелдерге арналған пайдалы рецепттер бөліміндегі антиоксиданттарға бай көк шай немесе жеңіл кофе ішіп, күш жинаңыз.'),
  ('35dcaff3-d09c-4c5a-87b5-8fa048fa86b8', 'Үйде тыным таппай жүр ме? 🧗', 'Бойындағы энергиясын шығаруы керек! Анаға қолайлы орындар картасын ашып, қауіпсіз жүгіру алаңы мен сырғанағы бар жаңа саябақты тауып, балаңызға еркін ойнауға мүмкіндік беріңіз.'),
  ('3eefbe35-a241-4512-8320-0993efa296ef', 'Үстелден қашып кете ме? 🏃‍♂️', 'Тамағын жартылай тастап, қашып кете ме? Тамақтану таймерін тоқтатыңыз. Күштеп тамақтандырудың орнына, Блогтар бөлімінен тәбетті табиғи жолмен ашудың құпияларын оқыңыз.'),
  ('ecf28bb2-147f-47c5-8e81-503885a13db6', 'Аяқ киімі неге қысады? 👟', 'Жүгіргенде жиі сүріне ме? Аяғы өсіп кеткен болуы мүмкін! Даму трекеріне қазіргі өлшемдерін енгізіп, өсу қарқынын бірден тексеріңіз және дамуын талдаңыз.'),
  ('c795e5c9-7249-46e0-9227-8cae7b9774c9', 'Пішіндерді дұрыс таба ма? 🧩', 'Логикалық дамуын қолдау үшін жасына сай геометриялық пазлдар мен үйретуші ағаш ойыншықтарды Ұсынылатын өнімдер бөлімінен дәл қазір іздеңіз.'),
  ('ce8c0e6d-8b04-4829-9134-54da2f1cc621', 'Ақуыз қоры жеткілікті ме? 🥚', 'Қарқынды өсіп жатқан бұлшықеттерге ақуыз қажет. Тамақтануды бақылау құралы арқылы бүгінгі норманы есептеп, жетіспесе, мәзірді реттеңіз.'),
  ('a458d5c8-d74f-4a15-a4a9-53e24632f8f7', 'Мұны өзім істеймін! 👕', 'Таңертең киіну үлкен жанжалға айнала ма? Қырсықтықпен күресу және бөпеңізге таңдау құқығын беру жолдарын қазір Anacan AI-дан біліңіз.'),
  ('f5dd0c22-b8ec-461e-a5b4-9045aa3ae282', 'Кітапты жыртпай, оқу 📖', 'Кешкі ертегі кезінде кітап беттерін жырта ма? Оқуға деген қызығушылығына зиян келтірмей, бұл мәселені қалай шешуге болатынын Блогтар бөлімінен қазір оқыңыз.'),
  ('19a9511e-358f-41a2-bbf2-d966afa6ffa9', 'Күн тәртібін талдайық ⏱️', 'Кешкі сергектік уақыты тым ұзарып кетті ме? Ұйқы таймерін қосып, кестені бақылаңыз. Бәлкім, күндізгі ұйқыны 15 минутқа қысқартатын уақыт келген шығар.'),
  ('65db46df-45b6-4a1e-ae35-6797a38fafce', 'Құм және балшық терапиясы 🏖️', 'Кірлеуден қорықпаңыз! Кинетикалық құмға немесе сенсорлық ойындарға арналған ең жақсы құралдарды Ұсынылатын өнімдер бөлімінен қазір табыңыз.'),
  ('dc3f8791-df91-4f2d-8dc5-44a0fff017da', 'Бұл – Сіздің еңбегіңіз 🌟', 'Күн сайын үйренген әрбір жаңа дағдысы, әрбір сенімді қадамы – Сіздің еңбегіңіздің жемісі. Көңіл күй күнделігін ашып, бүгін өзіңізді мақтан тұтатын жазба қалдырыңыз!'),
  ('2dafd9b8-26be-4b73-a1b1-cede334643cd', 'Бүгін неше рет «Жоқ» дедіңіз? 💆‍♀️', 'Қатты шаршадыңыз, солай ма? Терең тыныс алыңыз. Барлық сезіміңізді Көңіл күй күнделігіне жазып, өзіңізді кінәлауды доғарыңыз да, жай ғана демалыңыз.'),
  ('379a5991-8f1e-48b3-9f27-5e21468d8859', 'Жөргегі құрғақ күйде оянды ма? 🩲', 'Таңертең жөргегін ауыстырғанда оның құрғақ екенін байқадыңыз ба? Түбекке үйретуді бастаудың ең қолайлы уақыты мен психологиялық әдістерін қазір Anacan AI-дан сұраңыз.'),
  ('9728ea76-627d-4390-8b60-df7f4a0dc917', 'Кекске деген сүйіспеншілік 🧁', 'Тәтті сұрап жүр ме? Дүкенге асықпаңыз. Бөпеге арналған рецепттерден қантсыз, банан мен сұлы қосылған 10 минуттық үй кексін дайындап, Тамақтануды бақылау құралындағы денсаулық көрсеткішін сақтаңыз.'),
  ('19e2869e-6998-4c65-b3a4-edbc6a06f435', 'Көкөністі көрсе, қаша ма? 🥦', 'Тағамды түсіне қарап таңдай бастады ма? Бөпеге арналған рецепттерден шпинат пен сәбізді дәмді құймақтарға шебер жасыру жолын біліп, тәбетін ашыңыз.'),
  ('b793a816-4035-4e2c-8e9a-647949d5fa3a', 'Кішкентай суретші іске кірісті 🎨', 'Үсті-басы бояу болса да, ашуланбаңыз! Осы шығармашылық сәтті бірден Бөпе фотосессиясындағы көңілді стикерлермен безендіріп, альбомға қосыңыз да, күлімсіреңіз.'),
  ('addb392c-deee-4dda-99c7-ed94d64cd987', 'Ұру немесе итеру 🦖', 'Ашуланғанда кенет қол көтере ме немесе достарын итере ме? Осы жаста күшейетін агрессиялық сезімдерді жұмсақ түрде қалай өзгертуге болатынын Anacan AI-дан біліңіз.'),
  ('ebc52a7e-1091-4bf2-89de-cc6e528ddbe1', 'Сүйектері нығайып келеді 🦴', 'Қарқынды өсу үшін кальций қажет. Тамақтануды бақылау құралы арқылы бүгінгі ірімшік пен айран мөлшерін жеткілікті қабылдағаныңызды тексеріп, жетіспегенін толықтырыңыз.'),
  ('ee59618a-2d83-4249-b1e6-0323265cd134', 'Табиғи тыныштандырғыш 🍃', 'Бүгін тым қарбалас әрі шулы күн болды ма? Таймер тоқтады. Үй шаруасын ұмытып, Ақ шулардан бұлақ сылдырын қосыңыз да, демалу үшін диванға жатыңыз.'),
  ('5557465c-fb11-48b9-90c2-fc336972f19c', 'Кітапты жыртпай, оқиық 📖', 'Кешкі ертегі кезінде беттерін жырта ма? Блогтар бөлімінен кітап оқуға деген қызығушылығына зиян келтірмей, бұл мәселені қалай шешуге болатынын қазір оқыңыз.'),
  ('5b487ba9-a209-4653-a8fe-4315e87398df', 'Төсектегі бітпейтін шоу 🛌', 'Ұйықтаудың орнына төсекте секіре ме? Ұйқы таймерін қосып, кестені бақылаңыз. Қуатын толық жұмсамағанын немесе шамадан тыс шаршағанын анықтаңыз.'),
  ('9fb4af87-300a-4df0-8f02-48703cd4da3a', 'Тіс тазалау тартысы 🪥', 'Тіс щеткасын көрген бойда аузын ашпай қоя ма? Ұсынылатын өнімдерден музыкалық немесе саусаққа киілетін щеткаларды қарап, осы маңызды әдетті көңілді ойынға айналдыру жолын біліңіз.'),
  ('d5a7dad1-9dd5-40f2-bc6d-27d7e6052c76', 'Алғашқы маңызды әңгімелер 🗣️', 'Сізбен өз тілінде ұзақ уақыт бір нәрсені талқылап жүр ме? Осы күлкілі әрі баға жетпес сәтті дыбысы бар бейне ретінде Бөпе альбомына сақтап қойыңыз.'),
  ('6d0154ad-03f9-4392-b21e-d18f214374b2', 'Кенеттен айғайлау! 🛑', 'Қалағаны болмаған кезде өзін жерге тастай ма? 23-ші айға қарай жиілейтін осындай эмоциялық күйзелістерді ойынға айналдыру жолдарын Anacan AI сарапшы көмекшімізден сұраңыз.'),
  ('9e25f59c-eab1-44ee-ae76-e1b1ae42dc4c', 'Су ішуді ұмытпасын 💧', 'Тыным таппай жүгіретін балақайдың ішегі қалай жұмыс істеп жүр? Жөргегін ауыстырған кезде нәжісін белгілеп отырыңыз. Іш қату қаупі болса, қолданбадағы табиғи талшықтарға бай тағамдар туралы ұсыныстарды міндетті түрде қараңыз.'),
  ('bc4d0552-0cde-4c7a-bca8-4b2551c95ad7', 'Қараңғыдан қорқа ма? 🌌', 'Бөлменің жарығын өшіргенде жылай ма? Ақ шу бөлімінен ана құрсағындағы дыбысты (жүрек соғысын) қосып, оған бұрынғыдай мінсіз қауіпсіздік сезімін сыйлаңыз.'),
  ('1ecb40c2-379b-4b51-a326-4d93bf0ac050', 'Таңғы қуатыңызды сақтаңыз ⚡', 'Күніңізді ашқарынға бастамаңыз! Әйелдерге арналған пайдалы рецепттерден 5 минутта дайындалатын, тойымды әрі дәмді сұлы кексін таңдап, өзіңізге қамқорлық жасаңыз.'),
  ('69fe7fde-913c-4ff4-8fe2-fcbdad210e16', 'Сізге де достар керек 👯‍♀️', 'Тек баламен сөйлесуден шаршадыңыз ба? Анаға қолайлы орындар бөлімінен ойын топтары бар орталықтарды тауып, басқа аналармен араласыңыз және тәжірибе бөлісіңіз.'),
  ('f7991ada-b885-400f-9f72-4df6d1f9477e', 'Күндізгі ұйқысы қысқарып жүр ме? ⏱️', 'Түнде ұйықтауы ұзаққа созылды ма? Ұйқы таймерін қосып, кестесін бақылаңыз. Мүмкін, күндізгі ұйқысын 15-20 минутқа қысқартатын уақыт келген шығар.'),
  ('0347ce08-669e-4477-9fbc-63c1580b9edb', 'Бүгінгі күннің қаһарманы — Сіз 🌟', 'Оның күн сайын меңгерген жаңа дағдысы мен әрбір сенімді қадамы — Сіздің еңбегіңіздің жемісі. Көңіл күй күнделігін ашып, бүгін өзіңізді мақтан тұтуға себеп болатын бір жазба қалдырыңыз!'),
  ('0b69ffc4-e10f-4228-a354-3609a2cf48bb', 'Ашуланып тістеу 🦖', 'Ашуланғанда достарын немесе Сізді тістей ме? Бұл күрделі мінез-құлықты сүйіспеншілікпен қалай түзетуге болатынын Anacan AI сарапшы көмекшімізден қазір сұраңыз.'),
  ('0bd19a92-8f32-4626-9053-67019de34d6b', 'Тек нан жей ме? 🍞', 'Ақуыз бен көкөністерден бас тартып, тек көмірсу сұрай ма? Тамақтануды бақылау құралы арқылы бүгін қанша пайдалы тағам жегенін есептеп, мөлшерін реттеңіз.'),
  ('3794ac2c-9f00-4406-8f93-da27c84ffed3', 'Кітап беттерін жыртқысы келе ме? 📖', 'Кешкі ертегі кезінде кітаптың беттерін жыртқысы келе ме? Блогтар бөлімінен кітап оқуға деген қызығушылығына зиян келтірмей, бұл мәселені қалай шешуге болатынын оқыңыз.'),
  ('21c31221-548f-42a2-945f-424351b307be', 'Қабырғадағы өнер туындысы 🎨', 'Қолына қалам алып, қабырғаға сурет салып қойды ма? Ашуланбаңыз! Осы сүйкімді тентектігін Бөпе фотосессиясындағы көңілді жиектемелермен альбомға қосып, жай ғана күлімсіреңіз.'),
  ('cb6101a7-dbfd-4d36-944e-5acbfd6bc964', 'Беліңіз ауыра ма? 🧘‍♀️', 'Салмағы 12+ kq бөпені қайта-қайта көтеру оңай емес. Пайдалы рецепттер бөліміндегі бұлшықетті босаңсытатын, қабынуға қарсы зімбір шайын демдеп, демалыңыз.'),
  ('e15645b0-86cf-412b-8fdc-f53e32110fb7', 'Төсектен қашу жоспары 🏃‍♂️', 'Ұйықтайтын уақыт келгенде кереуетінен өрмелеп шыға ма? Ұйқы таймерін қосып, Ақ шулардан бірқалыпты пойыз дыбысын таңдаңыз да, оны жайлап ұйқыға дайындаңыз.'),
  ('406278a2-debe-4851-9b00-479abeb4b13e', 'Түбекке дайындық белгілері? 🚽', 'Таңертең жөргегі мүлде құрғақ па? Дәретханаға үйретуді бастауға қолайлы уақыт болуы мүмкін. Мұны жөргек трекеріне белгілеп, Ұсынылатын өнімдер бөлімінен эргономикалық түбек таңдаңыз.'),
  ('67af77d4-bcc0-42c9-9d93-190208cee7c5', 'Жалғыз ойнағысы келе ме? 👶', 'Саябақта басқа балаларға қосылмай, сырттай бақылап тұра ма? Бұл қалыпты параллель ойын туралы ең қызықты әрі ғылыми деректерді Блогтар бөлімінен біліңіз.'),
  ('789f31a5-225d-4210-8e89-eb69a6524d9d', 'Мінсіз ана болуға ұмтылу 💖', 'Бүгін даусыңызды сәл көтеріп қойдыңыз ба? Өзіңізді кінәламаңыз. Сезімдеріңізді Көңіл күй күнделігіне жазыңыз, Сіз онсыз да бөпеңіз үшін ең жақсы анасыз.'),
  ('354016aa-fdff-494e-9db1-d11124a417c8', 'Күн тәртібін талдайық ⏱️', 'Кешкі сергектік уақыты тым ұзақ болып кетті ме? Ұйқы таймерін қосып, кестені бақылаңыз. Бәлкім, күндізгі ұйқыны 15 минутқа қысқартатын кез келген шығар.'),
  ('d03661d9-e587-4637-b9c4-cf2d9c6ce6c8', 'Құм және балшық терапиясы 🏖️', 'Киімі кірлейді деп қорықпаңыз! Сенсорлық дамуы үшін Анаға жайлы орындардан құм алаңы бар қауіпсіз саябақты тауып, бөпеңізге табиғатты еркін зерттеуге мүмкіндік беріңіз.'),
  ('dd733e39-eed2-478b-9a6a-adcec13e6fc1', 'Темірдің ең жақын досы 🥩', 'Темірдің ағзаға сіңуі үшін C дәрумені қажет! Тамақтануды бақылау құралы арқылы бүгінгі мәзірді тексеріп, еттің қасына лимоны мол салат қосыңыз.'),
  ('97ab1430-c17a-4645-93d1-2d0b7261c822', 'Тек нан жей ме? 🍞', 'Ақуыз бен көкөністерді ысырып қойып, тек көмірсу жегісі келе ме? Тамақтануды бақылау құралы арқылы бүгін қанша пайдалы тағам жегенін есептеп, мөлшерін реттеңіз.'),
  ('b991e93f-39a2-4eb7-afdb-453c13a1d55b', 'Кітап беттерін жыртқысы келе ме? 📖', 'Кешкі ертегі кезінде кітаптың беттерін жыртуға тырыса ма? Кітап оқуға деген қызығушылығына зиян келтірмей, бұл мәселені қалай шешуге болатынын Блогтар бөлімінен оқыңыз.'),
  ('fa426bdb-bb7f-4a4f-9e93-d26f8fe4998a', 'Ашуланып тістеу 🦖', 'Ашуланғанда достарын немесе Сізді тістей ме? Бұл күрделі мінез-құлықты сүйіспеншілікпен қалай түзетуге болатынын Anacan AI сарапшы көмекшімізден бірден сұраңыз.'),
  ('1c3f0685-89ab-4827-a123-f84fa8b82551', 'Беліңіз ауыра ма? 🧘‍♀️', 'Салмағы 12+ kq бөпені қайта-қайта көтеру оңай емес. Әйелдерге арналған пайдалы рецепттерден бұлшықетті босаңсытып, қабынуды басатын зімбір шайын демдеп, тынығып алыңыз.'),
  ('71912e32-5753-4990-97c7-dcf5458c45d1', 'Қабырғадағы өнер туындысы 🎨', 'Қолына қалам алып, қабырғаны бояп тастады ма? Ашуланбаңыз! Осы сүйкімді тентектігін Бөпе фотосессиясындағы күлкілі жақтаулармен альбомға қосып, жай ғана жымиыңыз.'),
  ('aa4285be-2d37-4c2f-82d8-24587b052512', 'Төсектен қашу жоспары 🏃‍♂️', 'Ұйықтайтын уақыт келгенде кереуетінен өрмелеп шығып кете ме? Ұйқы таймерін қосып, Ақ шулардан пойыздың бірқалыпты дыбысын ойнатыңыз да, оны жайлап ұйқыға дайындаңыз.'),
  ('7057ef80-4efd-430a-a44f-a695f7bd7b53', 'Қос аяқтап секіру 🦘', 'Бір орында тұрып, екі аяғымен бір уақытта секіруге тырыса ма? Өте күлкілі көрінеді, солай емес пе? Бұл сәтті міндетті түрде мәңгілікке сақтап қойыңыз.'),
  ('a5fa8450-6478-40eb-8c4a-42d08f636974', 'Әуен сыйлаған тыныштық 🎶', 'Кешкі мазасыздықты басудың ең оңай жолы — оның сүйікті әуенін қосып, құшақтап, бірге баяу билеу.'),
  ('cea6f894-72c1-48a7-91fc-bc8637fa2cca', 'Ұйықтағысы келмей ме? 🥱', 'Күндіз ұйықтағысы келмей, қарсылық көрсете ме? Anacan AI-дан 2 жасқа таяған кездегі ұйқы аралықтары туралы нақты ақпарат пен күн тәртібін сұраңыз.'),
  ('b7bcd4fe-cc33-4ea9-a97e-59e15168cb31', 'Пайдалы тәтті іздейміз 🍎', 'Дүкен печеньелерімен қоштасыңыз! Бөпе рецептерінен үйде 10 минутта дайындалатын құрма мен алмадан жасалған пайдалы тәттілерді тауып, тәбетін ашыңыз.'),
  ('ed519633-a8d9-4eaa-a80a-911f5bc80cd1', 'Тіс тазалау тартысы 🪥', 'Тіс щеткасын көре сала аузын ашпай қоя ма? Осы маңызды гигиеналық әдетті көңілді ойынға айналдыру жолдарын білу үшін Anacan AI-дан пайдалы кеңестер алыңыз.'),
  ('fc53997b-db7d-4e51-803e-f6bd3797e9e3', 'Күлкілі айтылған сөздер 🗣️', 'Кейбір сөздерді сондай сүйкімді әрі қате айтады! Бұл алтын сәттерді жіберіп алмаңыз. Бөпе альбомына дыбысы бар видео ретінде жүктеп, болашақта бірге күліңіз.'),
  ('8c8e48b0-6f8d-4855-bb6b-3ff2edd9fbb3', 'Шалбар тағы да қысқарып қалды! 📏', 'Жейделерінің жеңі тар болып қалды ма? Бұл — бойының күрт өсіп жатқанын білдіреді. Даму трекеріне қазіргі өлшемдерін енгізіп, өсу кестесіне мақтанышпен қараңыз.'),
  ('24f24fa2-f109-4ee8-b9c0-2fe64e74bf4d', 'Ананың ақуыз қоры ⚡', 'Қимылы ширақ бөпенің соңынан жүгіру оңай емес. Әйелдерге арналған пайдалы рецепттердің ішінен ақуыз бен жеміске бай энергетикалық смузи дайындап, күш-қуатыңызды толықтырыңыз.'),
  ('5e6168f7-641f-4f35-ba96-328826769e77', 'Мұны өзім істеймін! 👕', 'Таңертең киіну үлкен дағдарысқа айнала ма? Қырсықтықпен күресу және бөпеге таңдау құқығын беру жолдарын дәл қазір Anacan AI-дан біліңіз.'),
  ('a40e092a-696e-4da1-98b1-5b56a4f49122', 'Тойғанын қалай білеміз? ⏱️', 'Тамақты лақтыра немесе түкіре бастаса, бұл оның тойғанын білдіреді. Тамақтану таймерін тоқтатып, қажетті мөлшерді жегенін белгілеңіз де, тәбетін талдаңыз.'),
  ('5266953d-d239-48ef-aac1-e6e5bcca5cbf', 'Кітапқа деген сүйіспеншілік 📖', 'Сүйікті ертегі кітабын әкеліп, тізеңізге отыра ма? Оның зейін қою уақыты ұзарып келеді. Бірге оқып, суреттердегі заттарды атап шығыңыз.'),
  ('b3334b05-05eb-4d1a-9a1b-b94086c6493b', 'Қорқыныш пайда болды ма? 👻', 'Бұрын қорықпаған шаңсорғыштан енді қорқа ма? Қиялы дамыған сайын негізсіз қорқыныштар пайда болуы мүмкін. Оны құшақтап, қауіпсіз жерде екенін айтыңыз.'),
  ('c2a4b3f4-3db4-4b1d-a807-2effcd0ace08', 'Таза ауа қажет 🌳', 'Балаңыз қатты мазасызданып, үйде отырғысы келмей ме? Ауа райын тексеріп, лайықты киіндіріңіз де, бірден саябаққа барыңыз. Табиғат — оны тыныштандырудың ең жылдам жолы.'),
  ('387df56f-151e-4857-83aa-f757db180cee', 'Сізге де достар қажет 👯‍♀️', 'Тек баламен сөйлесуден шаршадыңыз ба? Анаға қолайлы орындардан ойын топтары бар орталықтарды тауып, басқа аналармен араласыңыз әрі тәжірибе бөлісіңіз.'),
  ('4ee32e6d-768e-4628-8838-47e0599752e7', 'Диван альпинисі! 🧗', 'Жиһаздардың үстіне өрмелеу — оның ең сүйікті ісі ме? Оның осы батыл әрі күлкілі қимылдарын Бөпе фотосессиясындағы көңілді стикерлермен безендіріп, альбомға жүктеңіз.'),
  ('74a21e11-19bb-4326-af8e-197831260dd5', 'Ананың қуаты таусылды ма? 🔋', 'Түсте түрегеп тұрып-ақ қалғып кетесіз бе? Әйелдерге арналған пайдалы рецепттерден кофеинсіз-ақ бірден қуат беретін, ақуызға бай жержаңғақ пастасы қосылған смузи дайындаңыз.'),
  ('842a46f0-f832-4901-8e08-572103acff74', 'Бүгін бәрі қиын болды ма? 💆‍♀️', 'Күні бойы айғай мен жылау естідіңіз бе? Терең тыныс алыңыз, өзіңізді кінәлауды доғарыңыз — Сіз керемет анасыз!'),
  ('25dc715a-32c8-4d74-92d1-69586eb52b13', 'Асүйдегі барлық қазан еденде жатыр ма?', 'Қауіпсіз заттармен ойнау оның логикалық ойлауын дамытады. Өз қазынасын емін-еркін зерттей берсін.'),
  ('43609cdd-bc75-4be9-80ac-98506e0aba38', 'Тыныштық қажет 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — ең сезімтал кезең. Дыбыс өлшегішпен бөлмедегі децибел деңгейін тексеріп, кенеттен шығатын қатты дыбыстардан сақтаңыз.'),
  ('8b59959d-35b3-4803-a8d5-668ef810ded0', 'Мінсіздік елесі 🛋️', 'Әлеуметтік желілердегі үнемі көңілді аналарға қарап, өзіңізді кінәламаңыз. Сіздің шаршауыңыз да, шашылып жатқан бөлмеңіз де — өмірдің қалыпты көрінісі.'),
  ('17e385d1-c634-49cd-9d0d-e1c98c9b0fd8', 'Сөздерден сөйлемдерге 🗣️', 'Бөпеңіз үш сөзден тұратын күлкілі сөйлемдер құрай бастады ма? Тіл дамуындағы осы керемет серпілісті және сөздерді сүйкімді айтуын дыбысы бар видеоға түсіріп, болашаққа сақтап қойыңыз.'),
  ('3fe4d415-9d24-4577-93ed-654921e52b2c', 'Кітап беттері жанданады 📖', 'Ертегі оқығанда кітаптағы жануарлардың дауысын салады ма? Блогтар бөлімінен қиялының дамуын қолдайтын интерактивті кітап оқу тәсілдері туралы міндетті түрде оқыңыз.'),
  ('c13703f6-090d-418f-ba78-30e2aa25d678', 'Тазалыққа көмектесуші 🧹', 'Ол енді үй шаруасына көмектескісі келеді. Блогтар бөлімінен шамамен 2 жастағы балаға жауапкершілік сезімін ойын арқылы қалай үйретуге болатынын оқып, қолданып көріңіз.'),
  ('c6d0e6b3-90f7-4c66-9fd0-1f47e6d714c9', 'Өзіңізді мақтан тұтыңыз! 🌟', 'Оның күн сайын меңгерген әрбір жаңа дағдысы мен нық басқан әрбір қадамы — Сіздің еңбегіңіздің жемісі. Көңіл-күй күнделігін ашып, бүгін өзіңізді мақтан тұтатын бір жазба қалдырыңыз!'),
  ('85abdfc2-20eb-4a57-a2bc-cb822114eada', 'Көкөністі жасыру операциясы 🥦', 'Брокколиді көре сала тәрелкесін итеріп жібере ме? Бөпеге арналған рецепттерден осы дәруменді көкөністі дәмді құймақтың ішіне шебер жасыру жолын тауып, тәбетін ашыңыз.'),
  ('8a4be0f9-7229-4996-baf5-618ca78de14d', 'Ойын бітпей қоя ма? ⏱️', 'Ұйықтаудың орнына қашып, тығылып жүр ме? Ұйқы таймерін қосып, Ақ шудан мұхит толқынының дыбысын таңдаңыз да, бөлмені тыныш ұйқы үңгіріне айналдырыңыз.'),
  ('b333371b-bfc0-429c-bd23-a3e9996c1c00', 'Таңертең тым ерте ояна ма? 🌅', 'Күн шықпай тұрып оянып, бойы қуатқа толып тұра ма? Ұйқы режимін қолайлырақ уақытқа қалай ауыстыруға болатынын білу үшін дәл қазір Anacan AI сарапшы көмекшімізден кеңес алыңыз.'),
  ('3c7a1c30-6e81-411e-a8e2-8748214141cf', 'Логикалық ойындар 🧩', 'Ойыншықтарды қорапқа салып, кейін бәрін қайта төгіп тастай ма? Осылайша «ішінде» және «сыртында» ұғымдарын түсіне бастайды. Даму трекеріне осы когнитивті дағдыны белгілеңіз.'),
  ('b06ec056-54a0-4363-b389-839031267542', 'Аяқ киімге қатысты қырсықтық 👟', 'Далаға шығарда жаздың күні міндетті түрде қысқы аяқ киімін кигісі келе ме? Кейде таңдау жасауына мүмкіндік беріңіз — бұл оның ерік-жігерін нығайтады.'),
  ('ff08789a-eee1-4756-9d40-5ac5e65f75a9', 'Сұрағыңыз бар ма? 🤖', '2 жас дағдарысы туралы оқығандарыңыз Сізді қорқыта ма? Интернеттен жауап іздеп әуре болмаңыз, бірден Anacan AI-ға жазып, бұл кезеңнен қалай жеңіл өтуге болатынын біліңіз.'),
  ('41e1758f-79bb-43e3-8304-d4d74fa983b0', 'Ауа райы құбылып тұр деп үйде қалып қойдыңыз ба?', 'Ауа райы және киім құралы желдің жылдамдығын және қалай дұрыс киіну керегін бірден көрсетсін — саябаққа батыл шығыңыз.'),
  ('bcfad7da-e488-4ced-aa83-11c72d34ebec', 'Соңғы азу тістері ме? 🦷', 'Еш себепсіз бәрін кеміріп, ашушаң болып кетті ме? Ең артқы азу тістері жарып келе жатқан болуы мүмкін. Тіс жаруын бақылау құралында үдерісті белгілеп, салқын тіс қаситын ойыншықтарды дайындаңыз.'),
  ('c57b31e1-ab4c-412f-95b1-bcfc05812865', 'Ертегі кейіпкері 🪄', 'Бүгін кешке Ақылды ертегілерде басты кейіпкері өз балаңыз болатын ерекше хикая құрыңыз: тісін тазалағанды жақсы көретін батыл бөпеш.'),
  ('3dd0cee4-66f4-4904-9285-5b0b7b0dfa7b', 'Өзіңізге уақыт бөліңіз 🛋️', 'Артынан жүгіріп әбден шаршадыңыз. Бала ұйықтады, енді Көңіл күй күнделігіне бүкіл күйзелісіңізді жазып, өзіңізге бір стақан мелисса шайын құйып алыңыз.'),
  ('6721af60-2c7e-45f7-a60e-e27511cbb049', 'Қарны ашты ма, әлде шөлдеді ме? 💧', 'Кейде шөлдеуді тәбеттің болмауымен шатастырады. Жаялықты бақылау құралындағы дәрет туралы жазбаларды тексеріп, сұйықтықты жеткілікті қабылдап жүргеніне бірден көз жеткізіңіз.'),
  ('be975b82-781b-4e9e-b454-14728754957f', 'Кішкентай әнші 🎤', 'Бір әнді қайта-қайта айта бере ме? Бұл ырғақты сезіну қабілеті мен тілінің дамуына ықпал етеді.'),
  ('12f1dbe9-33ce-4aad-aead-7be2d360eb1e', 'Қиялда шек жоқ 🧸', 'Қонжығына тамақ беріп немесе Сізді емдеп жүр ме? Эмпатияның керемет дамуына ықпал ететін дәрігер немесе асүй жиынтықтарын Ұсынылатын өнімдерден қараңыз.'),
  ('813a036f-96ee-4802-8c36-c3d573f602c0', 'Ажырасудан қорқу қайта басталды ма? 🌌', 'Бөлмеден шыққан бойда артыңыздан жылай ма? Ақ дыбыстардан жүрек соғысының үнін қосып, оған қауіпсіздік сезімін сыйлаңыз әрі ұйқыға бейімдеңіз.'),
  ('bad958b0-7da3-4a62-ae7d-c35289ff6f57', 'Тасыған энергия 💥', 'Үйдің төрт қабырғасы мұндай жүгіріске шыдамайды. Анаға қолайлы орындар картасын ашып, жұмсақ төсемі мен үлкен сырғанағы бар қауіпсіз саябақты табыңыз да, бөпеңіздің еркін ойнауына мүмкіндік беріңіз.'),
  ('6dabe6f9-b86b-4347-9d8c-8d189d8a1224', 'Өзім тазалаймын! 🪥', 'Тіс щеткасын Сізден алып, өзі тазалағысы келеді, бірақ шын мәнінде дұрыс тазаламай ма? Бұл үдерісті жеңілдететін музыкалық әрі эргономикалық үлгілерді Ұсынылатын өнімдер бөлімінен дәл қазір іздеңіз.'),
  ('a9e849fb-b58a-4614-9ca7-0396de5c5865', 'Сұйықтық ішу және іш қату 💧', 'Көп жүгіріп, суды аз іше ме? Жөргегін ауыстырған кезде нәжісін бақылаңыз. Іш қату қаупі болса, оны қолданбаға белгілеп, бірден Тамақтануды бақылау құралы арқылы талшыққа бай тағамдарды қосыңыз.'),
  ('d816b4dc-5206-4a90-9e61-8c02ef8f5c68', 'Дастарқан басындағы шыдам сынағы 🥣', 'Тамақпен ойнап, айналаның бәрін былғай ма? Тамақтану таймерін қосып, тәбетінің өзгерісін график арқылы талдаңыз және тамақтануға қанша уақыт кеткенін нақты бақылаңыз.'),
  ('5f435409-af45-4f28-ad39-0362ac580462', 'Бәрін жерге лақтырғысы келеді 🛑', 'Ашуланғанда немесе іші пысқанда қолындағы затты сермеп, лақтырып жібере ме? Мұндай эмоциялық реакцияларды жұмсақ түрде қалай дұрыс бағыттауға болатынын Anacan AI-дан сұраңыз.'),
  ('cf7b282d-cfc2-4ce1-9f7c-e71f0a8529ba', 'Киімдері қысқарып барады! 📏', 'Киіндіргенде жеңдері тар болып қалғанын байқадыңыз ба? 2 жасқа таяғанда бойы күрт өседі! Даму трекеріне қазіргі бойын енгізіп, өсу қисығына мақтанышпен қараңыз.'),
  ('d1b0bfba-8ace-4234-8eb6-40647f25ce47', 'Ыстық шай мен тыныштық 🍵', 'Таймер тоқтады, бөпеңіз ұйықтады. Үй шаруасына асықпаңыз! Әйелдерге арналған пайдалы рецепттер бөліміндегі мелисса шайын демдеп, Көңіл күй күнделігіне бүгінгі шағын жетістіктеріңізді жазып қойыңыз.'),
  ('1c764980-a64f-44cc-b47e-9bb7c39ae099', 'Темірдің күші 🥩', 'Белсенді бөпеңізде қаназдық болмауы және оның энергиясы мол болуы үшін Тамақтануды бақылау құралынан бүгін қанша темір қабылдағанын тексеріп, жеткіліксіз болса, мәзірін реттеңіз.'),
  ('2754ee28-07df-42f6-ba7d-9d86b1edf758', 'Бірсарынды дыбыстың сиқыры 🌬️', 'Теледидар өшкеннен кейінгі кенет тыныштық оны мазалай ма? Бөлмеде «Ақ шу» бөлімінен желдеткіштің немесе шаш кептіргіштің дыбысын қосып, оның ұйықтайтын ортада қауіпсіздік сезімін қалай қалыптастыратынын байқап көріңіз.'),
  ('301a1109-2563-49a6-a096-aa057de78fa7', 'Бояуға малынған қолдар өнері 🎨', 'Бояулармен ойнап отырып, бет-аузын түгел бояп тастады ма? Ашуланудың орнына осы көңілді шығармашылық сәтті бірден суретке түсіріп, альбомға ең жарқын естелік ретінде қосыңыз.'),
  ('3112ae5c-eae2-4dc5-ae42-0bb7f83e1fdb', 'Түнгі әдеттер 🧸', 'Күн сайын кешке бір ойыншықты құшақтап ұйықтай ма? Осы сүйкімді әрі жанға тыныштық сыйлайтын сәтті суретсіз-ақ, жай ғана сипаттама түрінде Бөпе альбомының жазбалар бөліміне жазып, мәңгілік естелікке айналдырыңыз.'),
  ('363e202f-bc22-4752-9313-7e506d91cf84', 'Достасуға алғашқы талпыныстар 👶', 'Саябақта басқа баланың ойыншығына қызығып, дыбыс шығара ма? Осы әлеуметтену кезеңін қалай қолдау керегін Аналарға қолайлы орындарда басқа аналармен әңгімелесу арқылы біліңіз.'),
  ('a11c68a5-ec27-4659-9acb-bdcc422f80f8', 'Кішкентай дәрігер жұмыс үстінде 🩺', 'Қонжығына екпе салып немесе ішін тыңдап жүр ме? Қиялға негізделген ойындар нағыз шарықтау шегінде! Блогтар бөлімінен рөлдік ойындардың зияткерлік дамуға тигізетін ғажайып әсері туралы оқыңыз.'),
  ('053139e2-7d9f-4a00-9462-2ddb17d7e133', 'Жөргегі мүлде құрғақ күйде оянды ма? 🩲', 'Таңертең жөргегін ауыстырғанда оның құрғақ екенін байқадыңыз ба? Бұл — баланың физикалық тұрғыдан түбекке дайын екенінің негізгі белгісі! Мұны жөргек бақылағышына жазып, статистиканы мұқият қадағалаңыз.'),
  ('d7110781-b463-4661-96ac-270a072de535', 'Қантсыз, бірақ тәтті 🍪', 'Түстен кейін жүрек жалғайтын тағам сұрай ма? Дүкен печеньелерінің қажеті жоқ. Бөпеге арналған рецепттерден 10 минутта дайындалатын құрма мен сұлы қосылған пайдалы тәттілерді табыңыз.'),
  ('f9924ca2-641b-4911-b60a-55193623479d', 'Күн тәртібін толық талдайық ⏱️', 'Кешке ұйықтап кетуіне 40 минут кетті ме? Ұйқы таймерінің кестесіне қараңыз. Бәлкім, күндізгі ұйқысын 20 минутқа қысқартып, кешкі ұйқы уақытын ертерекке ауыстыратын кез келген шығар.'),
  ('fe937f54-e4d9-4674-821c-ae81d7c0c2cc', 'Дұрыс емес стақан үшін жанжал ма? 🥤', 'Суды қызыл емес, көк стақанға құйғаныңыз үшін айқай-шу басталды ма? Бір қарағанда қисынсыз көрінетін мұндай дағдарыстарды сабырмен басқаруды Anacan AI-дан үйреніңіз.'),
  ('4582098e-0228-4efe-b173-11bb966a75f4', 'Түнде ояну ⏱️', 'Ұйқы таймерін қосыңыз! Таймердің статистикалық графигі арқылы түнгі қорқыныш немесе ұйқы регрессиясы бар-жоғын нақты талдап, режимді реттеңіз.'),
  ('91af8067-4bf1-4cab-af7f-58a96c7e04b3', 'Сізге де үзіліс қажет ☕', 'Үйден шығып, біраз сергіп қайтыңыз! Аналарға қолайлы орындардан балалар бұрышы бар жақын маңдағы дәмхананы тауып, ыстық кофеңізді асықпай ішіңіз.'),
  ('e6513be5-cd7d-41ca-afb7-bc1d9cfbc0d8', 'Іш қату мәселесі бар ма? 🚽', 'Таңертең жөргегін ауыстырғанда нәжісін бақылаңыз. Іші қатса, оны қолданбаға белгілеп, бірден Тамақтануды бақылау құралы арқылы талшыққа бай тағамдарды қосып, теңгерімді сақтаңыз.'),
  ('442e022d-5a7b-4ad3-bb7f-6aecb9da6631', 'Экранға байланысты дағдарыс 📱', 'Телефонды қолынан алғанда жерге жата қалып, жылай ма? Экран уақытын күйзеліссіз шектеуді және дұрыс шекара белгілеуді Anacan AI-дан үйреніңіз.'),
  ('70c5aa02-8fdb-44ad-8a7f-cb5e6e2076a9', 'Бүгінгі күннің қаһарманы — Сіз 🌟', 'Бөпеңіздің күн сайын меңгерген әрбір жаңа дағдысы — Сіздің еңбегіңіздің жемісі. Көңіл күй күнделігін ашып, бүгін өзіңізді мақтан тұтатын бір жазба қалдырыңыз!'),
  ('d0802019-8ab1-4450-b744-1d4846aeaf76', 'Тіс тазалау үшін тартыс 🪥', 'Тіс щеткасын көре сала қаша ма? Ұсынылатын өнімдерден әуенді немесе айналмалы балалар тіс щеткаларын қарап, осы маңызды гигиеналық үдерісті көңілді ойынға айналдырыңыз.'),
  ('134f77a6-22c5-4894-83a4-bbdf2a3551b0', 'Табиғи тыныштандыру тәсілі 🍃', 'Күніңіз у-шу мен жүгіріске толы болды ма? Таймер тоқтады. Бөлмені қараңғылап, Ақ шулардан өзен сылдырының дыбысын қосыңыз да, бөпеңіздің де, өзіңіздің де миыңызға тынығуға мүмкіндік беріңіз.'),
  ('94201b9a-86d5-4505-89c9-5202248a32f0', 'Таңғы қырсықтық 👗', '«Бұл аяқкиімді кимеймін!» деген қырсықтығы таңғы уақытыңызды қиындатып жүр ме? Оған бірнеше нұсқа ұсынып, таңдау еркіндігін берудің ең тиімді психологиялық тәсілдерін Anacan AI-дан біліңіз.'),
  ('c7ffac8f-2df5-4b9d-8171-edd5730bbcb9', 'Ананың ақуыз қоры ⚡', 'Тынымсыз бөпенің соңынан жүгіру оңай емес. Өзіңізді титықтатпаңыз! Пайдалы рецепттер бөліміндегі ақуыз бен жеміске бай энергетикалық смузиді дайындап, күш-қуатыңызды қалпына келтіріңіз.'),
  ('fdd42343-56c5-47a1-8eaa-9e8b57c16e15', 'Табиғи тыныштандырғыш 🍃', 'Бүгін у-шу мен жүгіріске толы күн болды ма? Таймер тоқтады. Бөлмені қараңғылап, Ақ шулардан өзен сылдырын қосыңыз да, бөпеңіз бен өзіңізге ой тыныштығын сыйлаңыз.'),
  ('06ba8468-2412-484c-9b4b-12b5ce2a132b', 'Тәуелсіздік үшін күрес! 👕', 'Өзі киінгісі келіп, көмегіңізден бас тарта ма? Бұл қырсықтықты салауатты дамуға қалай бағыттауға болатынын дәл қазір Anacan AI сарапшы көмекшімізден сұраңыз.'),
  ('10c5438d-d27e-4125-a092-12fa2afc9118', 'Темір қорын тексеру 🥩', 'Белсенді бөпеде қаназдық болмауы үшін Тамақтануды бақылау құралынан бүгін қанша темір (ет, бұршақ тұқымдастар) қабылдағанын тексеріп, мәзірін жаңартыңыз.'),
  ('f5441f5e-36e8-4685-812e-3b947ba2fe54', 'Түнгі қарқынды бәсеңдету 🎶', 'Жүгіруден шаршамай, төсекке жатқысы келмей ме? Ұйқы таймерін қосып, Ақ шулардан мұхит толқындарының дыбысын таңдаңыз да, бөлмеде тыныш әрі жайлы ұйқы ортасын қалыптастырыңыз.'),
  ('194c05a1-f79c-496c-b1f4-f1316b804846', 'Ертегіні өзі айтсын 📖', 'Кітаптағы суреттерге қарап, өз тілінде бірдеңелер айтып отыр ма? Қиялы қанаттанған осы ғажайып сәтті дереу дыбысы бар видеоға түсіріп, Бөпе альбомына қосыңыз да, болашаққа сақтап қойыңыз.'),
  ('81278832-aa98-446b-b9de-87731d74c2b6', 'Қауіпсіз жүгіру алаңы 🏃‍♀️', 'Үйде күш-қуатын жұмсай алмай, бәрін шашып жүр ме? Аналарға қолайлы орындар картасын ашып, қауіпсіз жүгіру алаңы бар саябақты табыңыз да, таза ауаға шығыңыз.'),
  ('247c6eba-b9c7-406d-95d9-27a9c74871bf', 'Ақылды ойыншықтар 🧩', '2 жастағы баланың ой-өрісін дамыту үшін жай ғана дыбыс шығаратын емес, үйрететін ойыншықтар қажет. Ұсынылатын өнімдер бөлімінен логикалық ойлауды дамытатын ағаш пазлдарды қараңыз.'),
  ('50a05ffc-5382-423e-b256-bdeac07c78eb', 'Қантсыз торт дайындау 🎂', 'Ертеңгі ерекше күнге пайдалы торт керек! Бөпеге арналған рецептілер бөлімінен тазартылған қантсыз, жеміс қосылған және балаларға толықтай жарамды торт рецептілерін табыңыз.'),
  ('9c2176f9-4583-459e-b4a3-631c624068de', 'Ананың қуат көзі 🥗', 'Өз күш-қуатыңызды толықтыруды ұмытпаңыз! Пайдалы рецептілер бөліміндегі жержаңғақ пастасы қосылған ақуызды смузиді дайындап, бойыңызға бірден қуат жинаңыз.'),
  ('19814a91-cb64-4bf7-bdcb-7655e0d384a4', 'Міне, 2 жасқа да толды! 🎈', 'Тынымсыз еңбекке, махаббат пен ұйқысыз түндерге толы 2 жыл. Көңіл күй күнделігіне осы 730 күн үшін сезінген мақтанышыңызды жазыңыз. Сіз шынымен керемет анасыз!'),
  ('6a49b5e2-afea-42a7-8643-310e7b5b7642', 'Сіздің қолыңыздан келді 🥂', 'Екі жылдық жанкештілік! Бала ұйықтап қалса, үй шаруасын қоя тұрыңыз. Көңіл күй күнделігін ашып, өзіңізге алғыс жазыңыз да, жай ғана демалыңыз.'),
  ('e00156cd-d1b9-4727-b3d4-e86b004b8681', '2 жас дағдарысы ма? 🌪️', '«Жоқ» деу мен айқайлау жиіледі ме? Осы белгілі кезеңнен жеңіл өту үшін Anacan AI-дан эмоциялық дағдарыстарды басқару тәсілдерін дәл қазір алыңыз.'),
  ('17c8a3a6-67b0-49ab-a185-9e25f788bb11', 'Үстел басында отырғысы келмейді 🥣', 'Тамақтан тез жалығып, қашып кете ме? Тамақтану таймерін қосып, процестің ұзақтығын белгілеңіз және күштеп тамақтандырудан толықтай бас тартыңыз.'),
  ('32abe85c-b2ef-4ebb-aa71-2ad4fbb4e416', 'Тыныштық қажет 🤫', 'Кешегі у-шудан кейін бөлмедегі тыныштықты Дыбыс өлшегішпен бақылаңыз. Түнде бөлінген ұйқы оның да, Сіздің де көңіл күйіңізге кері әсер етеді.'),
  ('c38c019f-d84f-4e70-a98d-688ae4d3f657', 'Логикалық серпіліс 🧩', 'Бөпеңіз себеп-салдар байланысын түсіне бастады. Блогтар бөлімінен шамамен 2 жастағы балалардың танымдық дамуын жеделдететін ең жақсы үй ойындары туралы оқып, оларды қолданып көріңіз.'),
  ('e1d2d8e1-5d2b-4afe-b927-cf13cedf3cda', 'Кальций қалқаны 🦴', 'Тіс пен сүйекке кальций қажет. Тамақтануды бақылау құралы арқылы бөпеңіздің бүгінгі йогурт пен ірімшік мөлшерін жеткілікті қабылдағанын тексеріңіз.'),
  ('20e07ee8-1ee8-4d24-9dc9-8aeafced1a45', 'Құймақ құмар 🥞', 'Таңғы ас ішуден бас тарта ма? Бөпелерге арналған рецептілер бөлімінен қантсыз банан құймағының рецептін қарап көріңіз. Оны қолына ұстап, өзі жей алады әрі тәбеті де ашылады.'),
  ('98f28b6b-3cea-495d-a58b-704216aa3a0d', 'Дастарқан басындағы сабыр сынағы 🥣', 'Тамақпен ойнап, айналаның бәрін былғай ма? Тамақтану таймерін қосып, тәбет динамикасын график арқылы талдаңыз және бүкіл процестің қанша уақытқа созылғанын нақты бақылаңыз.'),
  ('a8ac0c29-0fa0-4dec-a0ed-2411236fabc2', 'Құм және балшық терапиясы 🏖️', 'Кірлеуден қорықпаңыз! Кинетикалық құмға немесе сенсорлық ойындарға арналған ең жақсы құралдарды Ұсынылатын өнімдер бөлімінен дәл қазір табыңыз.'),
  ('5c1b9d9c-ddd2-4dad-b93e-0902ebeb2417', 'Энергияны жұмсау өнері 🧗', 'Үйдің іші оған тар болып жүр. Анаға қолайлы орындар картасын ашып, секіріп, жүгіре алатын, жұмсақ төсемі бар қауіпсіз ойын аймағын табыңыз.'),
  ('7c5f1c11-9db4-4f7a-913f-8ca7bf583cb6', 'Талғампаз тәбет 🥦', 'Тек макарон немесе нан сұрай ма? Тамақтануды бақылау құралы арқылы мәзірін талдап, жетіспейтін дәрумендердің орнын Бөпелерге арналған рецептілер бөліміндегі қызықты тағамдармен толықтырыңыз.'),
  ('ea466226-d28d-4765-94f7-982ef3a85a8e', 'Жарықты бәсеңдетіңіз 🌙', 'Ұйқыға 1 сағат қалғанда үйдегі барлық жарық шамдарды және экрандарды өшіріңіз. Мелатонин тек тыныш әрі көмескі жарық ортада бөлінеді.'),
  ('8796a078-f4e3-4ea5-9258-919333a4b718', 'Туған күннен кейінгі аласапыран 🌪️', 'Кешегі кештен кейін үйдің астан-кестені шықты ма? Тазалық жасауға асықпаңыз. Жаңа ғана 2 жасқа толған бөпеңізбен бүгін жай ғана демалыңыз.'),
  ('07c79611-988f-4228-b928-f34af1a7425a', 'Табиғат суретшісі 🍂', 'Үйден шығыңыз! Саябақтағы жапырақтар мен тастар — ең жақсы сенсорлық материалдар. Анаға қолайлы орындардан жасыл желегі мол жерді табыңыз.'),
  ('14d525a3-b7d6-43c1-9919-132c8691cf60', 'Су жеткілікті болса, ас қорыту да жеңіл 💧', 'Жүгіріп ойнап жүріп су ішуді ұмыта ма? Жөргек трекеріне таңғы жазбаны енгізіп, іш қату қаупін азайту үшін сұйықтық пен жасұнық теңгерімін бірден талдаңыз.'),
  ('8a2ef907-aa42-42a0-b57d-125e83745fe9', 'Ұйықтар алдындағы ертегі әдеті 📖', 'Сіз оқыған ертегіні өз тілімен қайталай ма? Тілінің осындай керемет дамуын дыбысы бар видеоға түсіріп, бірден Бөпе альбомына қосыңыз да, болашаққа сақтап қойыңыз.'),
  ('031b0761-047d-4d63-84ce-fd41ce83245b', '«Менікі!» кезеңі 🧸', 'Саябақта ойыншығын бөліспей, айқайлай ма? 2 жастағы эгоцентризмді агрессияға ұластырмай, дұрыс басқару жолдарын Anacan AI-дан біліңіз.'),
  ('16c2ca9a-7971-49b0-9210-b9dd3baea775', 'Қабынуға қарсы күш 🍵', 'Баланы көтере бергеннен беліңіз бен қолдарыңыз ауыра ма? Әйелдерге арналған пайдалы рецепттердің бірі — зімбір мен лимон қосылған шайды демдеп, ағзаңыздың қалпына келуіне көмектесіңіз.'),
  ('4645899a-65b7-4ec6-9619-57e71d7569de', 'Күн тәртібін талдайық ⏱️', 'Кешкі сергектік уақыты тым ұзарып кетті ме? Ұйқы таймерін қосып, кестені бақылаңыз. Мүмкін, күндізгі ұйқыны 20 минутқа қысқартатын уақыт келген шығар!'),
  ('5bc99c8b-11ed-40cb-90ff-db30ccb7cbdb', 'Еліктеу жалғасуда 🦜', 'Сіз телефонмен сөйлескенде, ол да пультті қолына алып, құлағына тақай ма? Ол Сізді 100% қайталайды! Оған жақсы үлгі болуға тырысыңыз.'),
  ('bfbd5b7b-bf9b-48f6-a1a2-f194c1a573f8', '«Жоқ» сөзінің күші 🛑', 'Бір нәрсе ұсынсаңыз, басын шайқап, «жоқ» дейді! Бұл қырсықтық емес, өз ойын білдіру тәсілі. Бірнеше нұсқа ұсынып, оны тыныштандырыңыз.'),
  ('e590043b-d98d-4bab-915d-caf59d5351e3', 'Әкенің көңілді қылықтары 🤡', 'Бөпені күлдірудің ең жақсы жолы — әкесінің түрлі күлкілі дыбыс шығаруы. Бүгін кешке балаңызбен бірге осы көңілді сәттердің рақатын көріңіз.'),
  ('72f63b03-217f-4966-9286-177869cd7d59', 'Қантсыз, бірақ дәмді 🥞', 'Тәтті жегісі келіп жүр ме? Дүкенге барудың қажеті жоқ. Бөпеге арналған рецепттерден небәрі 10 минутта дайын болатын банан мен алма қосылған панкейктерді жасап көріп, тәбетін ашыңыз.'),
  ('c2a3a287-3762-4751-aa0e-2e7d2c1d038c', 'Тіс щеткасымен шайқас 🪥', 'Тісін тазалау үлкен шайқасқа айнала ма? Ұсынылатын өнімдерден әуенді немесе сүйікті мультфильм кейіпкері бейнеленген щеткаларды қарап, тіс тазалауды бірден ойынға айналдырыңыз.'),
  ('d3ffa760-4dfc-4872-9709-1f13cf644f4a', 'Табиғи тыныштандырғыш 🍃', 'Бүгінгі күн у-шу мен жүгіріске толы болды ма? Енді үзіліс жасайтын уақыт келді. Бөлмені қараңғылап, Ақ шулардан өзен сылдырының дыбысын қосыңыз да, өзіңіз де тынығып алыңыз.'),
  ('3b32f5ba-4db0-47e2-ab4a-893183710c64', 'Темір қалқаны 🥩', 'Қуаты азайды ма, әлде жай ғана шаршады ма? Тамақтануды бақылау құралы арқылы бүгін қанша темір (ет, бұршақ тұқымдастар) қабылдағанын тексеріп, жетіспеген мөлшерін бірден толықтырыңыз.'),
  ('a743db36-b967-433a-8695-0780f7195e63', 'Дәрігер ойыны басталды 🩺', 'Қонжығына екпе салып жатыр ма? Қиялға толы ойындардың нағыз қызған шағы. Осы сүйкімді сәтті Бөпе фотосессиясына түсіріп, ең есте қаларлық естелік ретінде сақтаңыз.'),
  ('d6af2d07-9e24-449e-843c-4a4fbcab142b', 'Сізге де үзіліс қажет ☕', 'Балаңыздан бір сәтке алыстап, тынығып алыңыз! Анаға қолайлы орындардан балалар бұрышы бар кафе тауып, ыстық кофеңізді асықпай ішіңіз.'),
  ('78846b79-c47d-4a00-947e-59f644b0393d', 'Темір қалқаны 🥩', 'Белсенді бөпеңіз қаназдыққа шалдықпай, сергек жүруі үшін Бөпеге арналған рецептерден шайнауға оңай әрі дәмді көкөніс қосылған ет котлеттерін тауып, тәбетін ашыңыз.'),
  ('14cb8a25-67e3-4a93-92e7-813bc9ea34c1', 'Кітап беттерін жыртуға құмарлық 📖', 'Кітап оқудың орнына оның беттерін жырта ма? Кітап оқуға деген қызығушылығына нұқсан келтірмей, бұл мәселені қалай шешуге болатынын дәл қазір Anacan AI-дан сұраңыз.'),
  ('ce2cdb1e-e1d2-4e44-a336-1708ff489505', '5 минутта қуат алыңыз ⚡', 'Түсте тұрып-ақ қалғып кетесіз бе? Әйелдерге арналған пайдалы рецептерден бірден қуат беретін, антиоксиданттарға бай жидек қосылған сұлы ботқасын дайындап, күшіңізді қалпына келтіріңіз.'),
  ('d83ebff1-21e6-4964-94da-2347551c7e01', 'Сөздерден сөйлемдерге 🗣️', 'Бөпеңіз 3-4 сөзден тұратын күлкілі сөйлемдер құрай бастады ма? Тіл дамуындағы осы керемет серпілісті қолдайтын ең жақсы үй ойындары мен буынға арналған жаттығулар туралы Блогтар бөлімінен оқыңыз.'),
  ('25c00809-7707-4080-969f-0093aea099c2', 'Массаж уақыты 💆‍♂️', 'Бала ұйықтағаннан кейін күндізгі күйзелістен арылу үшін серігіңізбен бір-біріңіздің иығыңызға массаж жасаңыз. Сіздер бір командасыздар!'),
  ('3708efde-5f63-47e0-b30e-19b8bf533ad8', 'Қиялдағы көлік жүргізу 🚗', 'Бос қорапты немесе ойыншықты руль сияқты айналдырып, көліктің дыбысын сала ма? Бұл — символдық ойындардың (pretend play) қарқынды дамып келе жатқанының белгісі!'),
  ('c1efd894-6c8f-4d33-9cdd-4d863998e9be', 'Аналардың сырласуы 💬', '«Менің балам неге бұлай істейді?» деген ой мазаңызды ала ма? Anacan қауымдастығына кіріп, басқа аналардың осыған ұқсас оқиғаларын оқыңыз.'),
  ('71d54817-9c7d-4b6a-a083-cfc9af5ca532', 'Кальций қоры 🦴', 'Тіс пен сүйекке кальций өте қажет. Тамақтануды бақылау құралы арқылы бүгінгі йогурт пен ірімшік мөлшерін жеткілікті тұтынғаныңызды тексеріп, жетіспегенін толықтырыңыз.'),
  ('10e42611-20e5-4efa-b449-859dcdf79439', 'Төсектен қашу жоспары 🏃‍♂️', 'Ұйықтайтын уақыт келгенде қашып, тығылып қала ма? Ұйқы таймерін қосып, Ақ шулардан орманның сыбдырын таңдаңыз да, бөлмені тыныш үңгірге айналдырыңыз.'),
  ('a00ab8a1-2a6c-4ace-a218-64e35136c179', 'Қатар ойнаудан бірге ойнауға 👶', 'Басқа балалармен бір ортада ойнауға қызығушылығы арта бастайды. Блогтар бөлімінен 2 жастағы балаларды әлеуметтендірудің құпиялары мен ойын алаңындағы қарым-қатынас психологиясы туралы біліңіз.'),
  ('ab2766ea-1937-4401-b3fe-78b7aa14f747', 'Киінуге қырсығу 👗', '«Мына шалбарды кимеймін!» деп жылай ма? Таңертеңгі киіну дағдарысын азайтып, оған өз бетінше таңдау жасауға мүмкіндік берудің жолдарын Anacan AI-дан біліңіз.'),
  ('3743e0d0-daf8-4b16-9966-a5c865827254', 'Кішкентай аспаз іске кірісті 👨‍🍳', 'Асүйде Сізге көмектесіп, қамыр илей ме? Үсті-басы ұн болған осы көңілді сәтті дыбысы бар видеоға түсіріп, өмірлік естелік жасаңыз.'),
  ('8b9210f4-74fc-4c2d-b35a-90728df0c189', 'Дүкендегі айқай 🛒', 'Қоғамдық жерде қалағанын алып бермегеніңіз үшін жерге жатып алып, жылап-шулады ма? Айналадағы адамдардың көзқарасына мән бермей, 2 жас дағдарысын сабырмен басқару үшін Anacan AI-мен сырласыңыз.'),
  ('d5d9b1e2-d062-4d67-8535-5d3b9126d7d2', 'Түнде ұйықтай алмадыңыз ба? ☕', 'Түнде қайта-қайта ояну күш-қуатыңызды тауысты ма? Әйелдерге арналған пайдалы рецептілер бөлімінен кофеинсіз-ақ бірден сергітетін, ақуызға бай жержаңғақ пастасы қосылған смузи дайындап, күш жинаңыз.'),
  ('02f4d85d-ea15-4227-a58f-b7dba39b78d0', 'Кенеттен ояну 🌌', 'Түн ортасында жылап оянып, тыныштала алмай ма? Түнгі үрей мен қорқынышты түстің айырмашылығын түсініп, дұрыс әрекет ету үшін Anacan AI сарапшысына жазыңыз.'),
  ('3a940a2c-0062-4cd0-9553-c25d5aadd4ea', 'Тіс тазалау тартысы аяқталады 🪥', 'Тіс щеткасын көре сала аузын ашпай қоя ма? Бұл үдерісті жеңілдететін әуенді әрі эргономикалық үлгілерді Ұсынылатын өнімдер бөлімінен қазір іздеп, күнделікті тіс тазалауды ойынға айналдырыңыз.'),
  ('725e419e-e208-48ec-ad13-bc8e5886eebb', '«Өзім жеймін» деген қырсықтық 🥦', 'Қасықты қолыңыздан алғысы келеді. Ала берсін. Үсті-басы былғанады, бірақ өз бетінше әрекет ету сезімі ол үшін өте маңызды.'),
  ('b6c449a4-eac7-47b9-9e9b-4c3b2deebe5b', 'Бүгінгі күннің қаһарманы — Сіз 🌟', 'Оның күн сайын меңгерген әрбір жаңа дағдысы мен өз бетінше жасаған әрбір қадамы — Сіздің еңбегіңіздің жемісі.'),
  ('2a9eaf13-aaf9-41fd-baa3-5fdcb48e56ca', 'Ақылды ойыншықтар 🧩', '2 жастағы баланың ой-өрісіне жай ғана дыбыс шығаратын емес, үйрететін ойыншықтар қажет. Ұсынылатын өнімдер бөлімінен логикалық ойлау қабілетін дамытатын ағаш пазлдар мен пішіндерді табыңыз.'),
  ('5592a39d-90a2-449d-9f20-3a71ba9dddad', 'Іш қату мәселесі бар ма? 🚽', 'Ойнап жүріп су ішуді ұмыта ма? Жөргегін ауыстырған кезде үлкен дәретін бақылаңыз. Іш қату қаупі болса, оны қолданбаға белгілеп, бірден Тамақтануды бақылау құралы арқылы талшыққа бай тағамдарды қосыңыз.'),
  ('a589907e-1ec5-4668-9a51-f72995d314f0', 'Күн тәртібін талдайық ⏱️', 'Кешке ұйықтауға 40 минут кетті ме? Ұйқы таймерінің кестесін қараңыз. Күндізгі ұйқыны 20 минутқа қысқартып, кешкі ұйқы уақытын ертерек жылжытатын кез келген шығар.'),
  ('1966178b-773a-4205-ab76-e8693f0abf72', 'Қантсыз, бірақ тәтті 🍪', 'Түстен кейін жеңіл ас жегісі келе ме? Дүкен печеньесін алудың қажеті жоқ. Бөпеге арналған рецепттер бөлімінен 10 минутта дайындалатын құрма мен сұлыдан жасалған пайдалы тәттілерді пісіріңіз.'),
  ('6f0ae293-593e-4249-828e-c2ec4c4fce2b', 'Күлкілі бет әлпеттері 🤪', 'Айна алдында бет-аузын қисайтып тұр ма? Осы көңілді сәтті жіберіп алмаңыз! Бірден Бөпе фотосессиясындағы күлкілі жақтаулармен безендіріп, альбомға қосыңыз.'),
  ('853c16b5-ec48-42df-a039-bc81b5a0ae1e', 'Сізге де үзіліс қажет ☕', 'Үйден шығып, біраз сергіп қайтыңыз! Анаға қолайлы орындар бөлімінен маңайдағы балалар бұрышы бар дәмхананы тауып, ыстық кофеңізден рақаттанып, басқа аналармен танысыңыз.'),
  ('7f7e8cbd-f54d-475a-9880-5e509bceab0e', 'Түсі дұрыс емес тәрелке! 🎨', 'Тамақты жасыл емес, қызыл тәрелкеге салғаныңыз үшін бөпеңіз ашуланып кетті ме? Осы жастағы қисынсыз қырсықтықты қалай басқаруға болатыны туралы кеңестерді Блогтар бөлімінен оқыңыз.'),
  ('967e4cff-99ce-432e-991e-40e75469ba59', 'Ананың белі ауырса 🧘‍♀️', '13+ кг бөпеңізді көтере бергеннен беліңіз сырқырай ма? Әйелдерге арналған пайдалы рецепттер бөлімінен бұлшықетті босаңсытатын зімбір шайын демдеп, өзіңізге күтім жасаңыз.'),
  ('a1d9ccbc-d633-4cf7-8231-4a3a870b0696', 'Кішкентай еліктегіш 📸', 'Сіз сияқты телефонмен сөйлесіп, қимылдарыңызды қайталай ма? Осы күлкілі сәтті Бөпе фотосессиясындағы көңілді стикерлермен безендіріп, альбомға қосыңыз.'),
  ('43a58d7e-e492-4b05-8142-e4389027f185', 'Бәрін жерге лақтырғысы келеді 🛑', 'Ашуланғанда немесе іші пысқанда қолындағы затын сермеп лақтыра ма? Мұндай эмоциялық реакцияларды жұмсақ түрде дұрыс арнаға қалай бағыттауға болатынын Блогтар бөліміндегі мақалалардан оқыңыз.'),
  ('cec4b4c4-52ab-4e49-adea-d05ca6bfff30', 'Бояулы алақандар өнері 🎨', 'Бояулармен ойнап отырып, бет-аузын түгел бояп тастады ма? Ашуланудың орнына осы көңілді, шығармашылық сәтті дереу суретке түсіріп, Бөпе альбомына ең түрлі-түсті естелік ретінде қосыңыз.'),
  ('deb2e459-e0cf-41a4-8379-c85e410b286a', 'Табиғи тыныштандырғыш 🍃', 'Таймер тоқтады. Бала ұйықтады. Енді өзіңізге көңіл бөліңіз! Әйелдерге арналған пайдалы рецепттер бөлімінен мелисса шайын демдеп, диванға жайғасып, осы шаршататын күннен кейін тыныштыққа бөленіңіз.'),
  ('6653e097-de4e-4ae0-8162-9b9f5ea59388', 'Өзім жуамын! 🧽', 'Ваннада щетканы немесе жөкемені қолыңыздан тартып ала ма? Баланың дербестікке ұмтылысын қолдайтын, балаларға қауіпсіз шомылу құралдарын Ұсынылатын өнімдер бөлімінен іздеңіз.'),
  ('74cf7a22-e38a-436b-abf9-30e1ae8f9815', '5 минутта қуат жинаңыз ⚡', 'Бөпеңіздің артынан жүгіріп, әбден шаршадыңыз ба? Әйелдерге арналған пайдалы рецепттер бөлімінен бірден қуат беретін, ақуызға бай жержаңғақ пастасы қосылған смузи дайындап, сергіп алыңыз.'),
  ('86c19953-fc54-4688-b5d9-b4feaed16fa5', 'Ұйқы режимін талдау ⏱️', 'Кешке төсекте көп аунақши ма? Ұйқы таймерінің кестесіне қараңыз. Мүмкін, күндізгі ұйқысын 20 минутқа қысқартып, кешкі ұйқы уақытын ертерек жылжытатын кез келген шығар.'),
  ('69468bd3-2ce5-4731-b30e-3685775a4a1a', 'Тыныштықтың сиқырлы әуені 🌊', 'Күніңіз мазасыз әрі шулы өтті ме? Ақ шудан мұхит толқындарының дыбысын қосып, бөпеңіздің де, өзіңіздің де жүйке жүйеңізді тыныштандырыңыз.'),
  ('86704e7d-f300-4ac8-a2e1-2a5068e8a7e2', 'Көкөністермен ойын 🥦', 'Саумалдықты жемей қоя ма? Бөпелерге арналған рецепттерден осы дәруменге бай көкөністі дәмді құймақтарға еппен жасыру жолын біліп, тәбетін ашыңыз.'),
  ('c422d14a-eccf-4f6a-bcbb-1ec2a5bdfc3a', 'Бойы күрт өсіп жатыр! 📏', 'Шалбары тағы да қысқарып қалды ма? 25-ші айға қарай дене дамуы жеделдейді. Даму трекеріне қазіргі өлшемдерін енгізіп, өсу кестесіне мақтанышпен қараңыз.'),
  ('2f36e03e-8050-4c96-a7d2-3231c5e8bf3f', 'Таза ауаны зерттеу 🌳', 'Үйдің іші оған тар болып кетті ме? Аналарға қолайлы орындардан кең әрі қауіпсіз саябақ тауып, еркін жүгіріп, бар энергиясын жұмсауына мүмкіндік беріңіз.'),
  ('484ef066-dacc-4b23-98a9-ef3409b6f055', 'Дастарқан басындағы сабыр сынағы ⏱️', 'Тамақпен ойнайды, бірақ жемей ме? Тамақтану таймерін қосып, үдерістің ұзақтығын бақылаңыз және қолданбадағы кесте арқылы тәбетінің өзгеруін талдаңыз.'),
  ('d99bde2e-2ab1-43d0-b2d0-95122a7f44ce', 'Неліктен кенеттен ұрады? 🛑', 'Ашуланғанда қол жұмсай ма? Осы жасқа тән агрессиялық эмоцияларды ойынға айналдырып, мінез-құлқын жұмсақ түрде өзгертуді Anacan AI сарапшысынан үйреніңіз.'),
  ('1a858fa5-276f-440e-972b-2b83e93db467', 'Кофе үзілісі ☕', 'Үй шаруасы мен бала күтімі... Енді демалатын уақыт! Аналарға қолайлы орындардан балалар бұрышы бар кафе тауып, ыстық кофеңізді асықпай ішіңіз.'),
  ('e6b6723c-fd0e-4884-94df-d412f5e903e7', 'Тым ерте ояну! 🌅', 'Күн шықпай жатып ояна ма? Ұйқы тәртібін қалай реттеуге болатынын білу үшін дәл қазір Anacan AI сарапшы көмекшісінен пайдалы кеңестер алыңыз.'),
  ('498eede0-22c9-4d0a-b512-067c46777cb9', 'Жаңа сөздер ашу 🗣️', 'Бүгін қандай күлкілі сөз ойлап тапты? Тілінің осындай керемет дамуын дыбысы бар бейне түрінде Бөпе альбомына сақтап қойыңыз — бірнеше жылдан кейін көріп, бірге мәз боласыз.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('710fba45-03e1-4e84-9d81-f9c99d7d2c40'::uuid, 'Түсте тік тұрып-ақ қалғып кетесіз бе?', 'Пайдалы рецептілер бөлімінен кофеинсіз-ақ бірден қуат беретін жержаңғақ пастасы қосылған смузи дайындаңыз.'),
  ('78d6a4b5-d4db-4754-8341-cf2bcc10342a', 'Төсектегі бітпейтін шоу 🛌', 'Ұйықтаудың орнына төсекте секіріп жүр ме? Ұйқы таймерінің кестесін бақылаңыз. Оның энергиясын толық жұмсамағанын немесе шамадан тыс шаршағанын бірден анықтаңыз.'),
  ('4622294e-c362-48ed-b4bf-63c35923b3ce', 'Ыстық шай мен тыныштық 🍵', 'Таймер тоқтады, бала ұйықтады. Үй шаруасына асықпаңыз! Мелисса шайын демдеп, тыныштықтан ләззат алыңыз.'),
  ('53c02e98-c468-40ac-9f02-6cb3c5e5158c', 'Кальций қалқаны 🦴', 'Тіс пен сүйекке кальций қажет. Тамақтануды бақылау құралы арқылы бүгінгі йогурт пен ірімшік мөлшерін жеткілікті тұтынғаныңызды тексеріп, жетіспегенін толықтырыңыз.'),
  ('f10247de-df8b-47ef-a539-e87f8db55ae2', 'Кішкентай дәрігер жұмыс үстінде 🩺', 'Қонжығына екпе жасап немесе ішін тыңдап жүр ме? Қиялға негізделген ойындар қызған шақ! Осы сүйкімді сәтті Бөпе фотосессиясы арқылы бірден түсіріп, ұмытылмас естелікке айналдырыңыз.'),
  ('1a31af42-99cc-4ebb-8d30-72e007760f62', 'Тыныштық қажет 🤫', 'Бөлмедегі тыныштықты Дыбыс өлшегішпен сақтаңыз. Түнде бөлінген ұйқы бөпеңіздің дамуына да, Сіздің таңертеңгі көңіл күйіңізге де кері әсер етеді.'),
  ('bcb1a85f-15a5-4fe9-bbeb-6c1ae564f15a', 'Соңғы азу тістер ме? 🦷', 'Еш себепсіз бәрін кеміріп, қолын аузына сала бере ме? Ең артқы азу тістері (екінші азу тістер) жарып келе жатқан болуы мүмкін. Тіс шығуын бақылау құралын міндетті түрде тексеріңіз.'),
  ('e490e4c7-7ef7-4eec-a03a-11da14534526', 'Үй шаруасы күте тұрады 🛑', 'Еден жуылмады ма? Қоя тұрыңыз. Лас үйді жинауға болады, ал әбден қажыған ананың қалпына келуіне көп уақыт керек. Диванға жатып, тыныштыққа құлақ түріңіз.'),
  ('753bfaff-7926-4516-b6b5-e78d2b60a270', 'Жеміспен араздық 🍎', 'Кеше жақсы көрген жемісін бүгін жерге лақтырып жатыр ма? Тамақ талғау — осы жасқа тән қалыпты мәселе. Пайдалы рецептілерден қызықты әрі ерекше ұсыну тәсілдерін қараңыз.'),
  ('8b287134-38e5-4f28-8d41-3ba7f9bcd5b7', 'Қиялға толы ойындар күрделене түседі 🧸', 'Ойыншықтарын тамақтандырып, ұйықтатып жүр ме? Бұл — қиял дамуының шарықтау кезеңі! Эмпатия танытуға бағытталған осы әрекеттерін даму трекеріне белгілеңіз.'),
  ('b884ea59-629f-4f5c-a2db-ce8f7aee5def', 'Күшіміз — бірлікте🥂', 'Бөпе ұйықтағаннан кейін, күннің күйзелісін басу үшін серігіңізбен бірге шай ішіп, «біз керемет командамыз» деп бір-біріңізге ризашылық білдіріңіздер.'),
  ('26ecdf90-afa5-4aeb-a939-0e9c19c4397d', 'Күн тәртібін талдайық ⏱️', 'Кешке ұйықтату 40 минутқа созылды ма? Ұйқы таймерінің кестесін қараңыз. Мүмкін, күндізгі ұйқыны 20 минутқа қысқартып, кешкі ұйқы уақытын ертерек жылжытатын кез келген шығар.'),
  ('4efacff1-8d44-47f9-9c4b-52dbb8de0f37', 'Қоғамдық жерде айқайлау 🛒', 'Дүкенде қалағанын алып бермегеніңіз үшін жерге жата қалып, айқайлады ма? Айналадағылардың көзқарасына мән бермеңіз және мұндай ашу ұстамаларын сабырмен басқару үшін Anacan AI-мен сырласыңыз.'),
  ('6e38a4cd-2c0a-4585-9a87-c6dd4f83a0a6', 'Ластанудан қорықпаңыз!', 'Кинетикалық құмға немесе сенсорлық ойындарға арналған ең жақсы құралдарды «Ұсынылатын өнімдер» бөлімінен дәл қазір тауып, үйге тапсырыс беріңіз.'),
  ('40782485-009f-459f-b399-6e2d09a90f95', 'Күннің қаһарманы — Сіз 🌟', 'Оның күн сайын меңгеріп жатқан әрбір жаңа дағдысы — Сіздің еңбегіңіздің жемісі.'),
  ('9fcf0a97-e2c0-4a40-994a-17bcfcd07b1b', 'С дәруменінің теңгерімі 🍊', 'Иммунитет мықты болуы керек. Тамақтануды бақылау құралы арқылы оның бүгін С дәруменін жеткілікті мөлшерде алған-алмағанын есептеп, мәзірді жаңартыңыз.'),
  ('0ef06d2c-90d7-4377-9290-8bde591b5f45', 'Бітпейтін «неге?» кезеңі 🤔', '«Бұл не?», «Неге олай?»... Ол енді әлемді танып-білуге ұмтылып жүр! Сұрақтарына шыдамдылықпен жауап беріңіз, өйткені дәл осы сәттерде оның миындағы нейрондар нағыз мереке жасап жатады.'),
  ('23204200-aac5-4b32-bb1b-c194a2fa62c8', 'Мінсіздік тізбегін үзіңіз 🛑', 'Балаңыз бүгін түскі ұйқыға жатпады, ал үй астан-кестен болып жатыр ма? Ештеңе етпейді! Терең тыныс алыңыз, бәрін бір мезетте бақылауда ұстай алмайсыз. Бәрін қоя тұрыңыз.'),
  ('c615cbe9-985e-4212-bc61-219d1808967f', 'Шыдамыңыз таусылды ма?', 'Бөлменің есігін жауып, баланы әкесімен оңаша қалдырыңыз. Бүгін кешке үйдегі ойын алаңын сол басқарсын.'),
  ('5d64edd3-2a7c-4881-81d2-2b0ca3685e08', 'Үйдің төрт қабырғасы қысып бара ма?', 'Аналарға қолайлы орындардан балаларға арналған ойын бұрышы бар дәмхана тауып көріңіз. Балаңыз ойнасын, ал Сіз асықпай кофе ішіп, демалыңыз.'),
  ('752be34d-ef64-4eb5-9d4c-e6d82cd2a840', 'Өзім киінемін 👕', 'Шалбарын басына киюге тырысса да, өздігінен киінуіне кедергі жасамаңыз. Оның дербестікке деген ұмтылысы шарықтау шегінде! Осы кішкентай жеңісті даму трекеріне белгілеңіз.'),
  ('84770b0a-8d36-4d8c-9fce-09146969d787', 'Музыка сыйлаған тыныштық 🎶', 'Кешкі мазасыздықты басудың ең оңай жолы — оның сүйікті әуенін қосып, құшақтап, бірге баяу билеу.'),
  ('04f27cd2-d5c6-4a88-a758-f59dfedfac03', 'Асқазан-ішек белгілері 💩', 'Жөргегін ауыстырған кезде мәліметтерді енгізіңіз. Іш қату қаупі болса, қолданбадағы табиғи талшықтарға бай тағамдар туралы ұсыныстар мен жеміс қосылған су рецептерін міндетті түрде қарап шығыңыз.'),
  ('2312b09a-1559-4ed0-aada-ff2063057e72', 'Ажырау мазасыздығы ма? 🌌', 'Бөлмеден шыға салысымен артыңыздан жылай ма? Ақ шулардан ана құрсағындағы дыбысты қосып, оған бұрыннан таныс жылылық пен қауіпсіздік сезімін сыйлаңыз да, ұйқыға бейімдеңіз.'),
  ('a2bb6939-4631-4be2-a871-cb519c3fdacb', 'Қантсыз, бірақ тәтті 🍪', 'Дүкен печеньелерімен қоштасыңыз! Бөпеге арналған рецептерден үйде 10 минутта дайындалатын құрма мен сұлыдан жасалған пайдалы тәттілерді табыңыз.'),
  ('5e9c412f-bcfb-4d5e-a447-66eebbf03e51', '«Жоқ!» деу өнері 🛑', 'Бәріне «жоқ» дей ме? Бұл Сізге қарсы шығу емес, өзінің жеке тұлғасын танып-білуі. Жабық сұрақтар қоймай, екі нұсқаның бірін таңдауға мүмкіндік беріп, қырсықтығын жұмсартыңыз.'),
  ('64707418-d2a0-43f8-b7ef-86936fa426fe', 'Тағы да есіңізден шығып кетті ме?', 'Үйде таусылған әрбір ұсақ-түйекті есте сақтауға тырыспаңыз, бірден Сатып алу тізіміне қосыңыз — қалғанын жұбайыңыз реттесін.'),
  ('d3a41958-709d-460d-ae40-910c3a69b580', 'Түн ортасында айғайлап оянып, тынышталмай ма?', '2 жас дағдарысы ұйқыға да әсер етеді. Дауысын Жылауды талдау функциясына тыңдатып, мәселенің неде екенін анықтаңыз.'),
  ('07a0b7ef-0c8f-405e-aede-5d8c497ab1df', 'Үңгір тыныштығы 🌌', 'Жүгіруден шаршамай, төсекке жатқысы келмей ме? Ұйқы таймерін қосып, Ақ шулардан орманның гуілін таңдаңыз да, бөлмені тыныш ұйқы үңгіріне айналдырыңыз.'),
  ('9849f311-0e6e-4965-b1a2-164cf002508c', 'Секіретін уақыт 🦘', 'Үйде диванның үстінде секіре ме? Анаға жайлы орындардан батуты мен жұмсақ төсеніштері бар ойын-сауық орталығын тауып, энергиясын қауіпсіз жұмсауына мүмкіндік беріңіз.'),
  ('3c1dc66a-c7fe-45c2-99c5-908555ae99a9', 'Ананың энергия бомбасы ⚡', 'Жүгіріп жүріп, көзіңіз ілініп бара ма? Тәттіге емес, ақуызға жүгініңіз! Әйелдерге арналған пайдалы рецепттер ішіндегі 5 минутта дайын болатын жержаңғақ пастасы қосылған смузимен қуатыңызды толықтырыңыз.'),
  ('83cfece3-b100-41d8-bb8e-0c02263c9e3e', 'Көлеңкелерден қорқа ма? 🌌', 'Бөлмені қараңғылағанда қабырғадағы көлеңкелер оны мазалай ма? Қиялының дамуы қорқыныш тудыруы мүмкін. Ақ шулардан ана құрсағындағы дыбысты қосып, бөлмеде қауіпсіздік сезімін қалыптастырыңыз.'),
  ('a23bc347-ea83-491e-af00-0e80deaecf0f', 'Түбекке алғашқы қадам? 🧻', 'Таңертең жөргегі мүлде құрғақ болып, өзі мазасыздана ма? Бұл — керемет белгі. Оны жөргек трекеріне белгілеп, Блогтар бөлімінен түбекке үйретуге дайындық кезеңдері туралы оқи бастаңыз.'),
  ('46824a50-cc48-4a9c-ad3e-91d5073cd55e', '«Жоқ!» дауылы 🛑', 'Әр ұсынысыңызға айқайлап қарсылық білдіре ме? 2 жас дағдарысының осындай қиын сәттерінде сабыр сақтап, қырсығуды ойынға айналдырудың құпияларын Anacan AI сарапшымыздан дәл қазір біліңіз.'),
  ('51c7f01a-f92a-4f7e-97c1-5893c5304d42', 'Логика ізденісі 🧩', 'Ол қарапайым ойыншықтардан тез жалығады. Зердесін шыңдап, зейінін шоғырландыратын ағаш пазлдар мен геометриялық ойындарды Ұсынылатын өнімдер бөлімінен табыңыз.'),
  ('a1d0bf30-60c8-4128-8527-423ff92dd8f8', 'Бітпейтін қуаласпақ 🏃‍♂️', 'Төсекке жатудың орнына дивандардың үстінде секіріп жүр ме? Ұйқы таймерін қосып, үдерістің ұзақтығын белгілеңіз және кестеге сүйеніп, кешкі режимді ертерек бастауды қарастырыңыз.'),
  ('1e0042aa-0b2b-4948-aaf5-3b9cec37c61f', 'Күлкілі сөйлемдер 🗣️', 'Тәтті қателері бар 3-4 сөзден құралған сөйлемдерінің құны алтынға тең! Осы керемет даму кезеңін өткізіп алмаңыз: оны дыбысы бар видео ретінде бірден Бөпе альбомына қосып, мәңгілік естелікке айналдырыңыз.'),
  ('4d28b1d1-1b59-430b-a6d9-3d3ad8b1e671', 'Энергиясын шығара алмай, бәрін қиратып жүр ме?', 'Анаға қолайлы орындар картасын ашып, жұмсақ төсемі мен сырғанағы бар қауіпсіз саябақты тауып, бөпеңіздің еркін ойнауына мүмкіндік беріңіз.'),
  ('031a9c48-32b8-49a9-a9d1-55eb165785a3', 'Ақуыз қорын тексеру 🥚', 'Қарқынды өсіп жатқан бұлшықеттерге ақуыз қажет. Тамақтануды бақылау құралы арқылы бүгінгі норманы (жұмыртқа, ет, бұршақ тұқымдастар) есептеп, жетіспесе, мәзірді реттеңіз.'),
  ('9a014c54-2569-48f1-8b59-1e18b3b2e5b1', 'Саусақпен сурет салу өнері! 🎨', 'Бояумен ойнап отырып, бет-аузын түгел былғап алды ма? Ашуланудың орнына, осы көңілді әрі шығармашылық сәтті бірден Бөпе фотосессиясындағы қызықты стикерлермен безендіріп, альбомға жүктеңіз.'),
  ('9b9b6d7f-8fb9-448e-ba10-0598457b94a6', 'Түнгі оянулар қайта басталды ма? ⏱️', 'Түн ортасында жылап оянып, қайта ұйықтауы қиындай ма? Ұйқы таймерінің статистикасын талдаңыз. Мүмкін, күндізгі ұйқысы тым ұзақ болып, кешкі ұйқысына әсер етіп жүрген шығар?'),
  ('87f68482-c94a-42ff-b3af-66083c5353fb', 'Оқу емес, әңгімелеу 📖', 'Кешкі ертегі кезінде ол Сізге суреттерге қарап әңгіме айтып бере ме? Қиялы шарықтаған осы ғажайып сәтті дыбыс түрінде жазып алыңыз.'),
  ('9bde240a-b972-41fa-8294-7b553545ae04', 'Сүйектері нығайып келеді 🦴', 'Қарқынды өсу үшін кальций қажет. Тамақтануды бақылау құралы арқылы бүгінгі ірімшік пен йогурт нормасын орындағаныңызды тексеріп, жетіспегенін толықтырыңыз.'),
  ('ffa8de8b-2edf-4c8a-82b0-fb8a5415ce7b', 'Бөліскісі келмей ме? 🧸', 'Саябақта басқа балалардың ойыншығына қарай жүгіріп, бірақ өзінікін бермей ме? Блогтар бөлімінен 2 жастағы балаға кезекпен ойнауды қалай үйретуге болатынын біліңіз.'),
  ('0fca32b2-cafe-4f95-9933-261c2771f460', 'Күн тәртібін толық талдайық ⏱️', 'Кешке ұйықтауға 40 минут кетті ме? Ұйқы таймерінің кестесіне қараңыз. Мүмкін, күндізгі ұйқысын 20 минутқа қысқартып, кешкі ұйқы уақытын ертерек жылжытатын кез келген шығар.'),
  ('0e790195-f407-4908-a021-252afa265e2e', 'Ананың су теңгерімі 💧', 'Бөпеңіздің соңынан жүгіріп жүріп, су ішуді ұмытып кеттіңіз бе? Бас ауруының себебі осы болуы мүмкін. Әйелдерге арналған пайдалы рецепттерден жалбыз бен лимон қосылған детокс суын дайындап, сергіп алыңыз.'),
  ('704cb940-aadd-424e-94f9-6bfecacafa6d', 'Таңғы ас қорытуды тексеру 💩', 'Жөргегін ауыстырғанда нәжісін бақылаңыз. Қатты тағам көбейген сайын іш қату қаупі артады. Мұны қолданбаға белгілеп, бірден Тамақтануды бақылау құралы арқылы талшыққа бай тағамдарды (алмұрт, сұлы) қосыңыз.'),
  ('94804bde-ee95-44e1-87c0-8fe6a051dfb6', 'Кенет шыққан дыбыстардан қорқу 🌪️', 'Шаңсорғыштың немесе блендердің дыбысынан қорқа ма? Бөлмеде Ақ шу бөлімінен феннің дыбысын қосып, қорқынышын азайтыңыз әрі оны біртіндеп ұйқыға дайындаңыз.'),
  ('0c2ed459-b6ef-4583-9c57-19766bfe4257', 'Түстерді сұрыптау 🔴🔵', 'Логикалық дамуын қолдау үшін жасына сай геометриялық басқатырғыштар (пазлдар) мен түрлі түсті ағаш ойыншықтарды бірден Ұсынылатын өнімдер бөлімінен тауып, ойлау қабілетін шыңдаңыз.'),
  ('1d490bb4-d589-47e3-911a-0660496e1c17', 'Тістеу және ұру 🦖', 'Ашуланғанда кенет қол көтере ме немесе тістей ме? Осы жасқа тән күшейген эмоцияларды жұмсақ түрде қалай реттеуге болатынын Блогтар бөліміндегі психологиялық мақалалардан оқыңыз.'),
  ('f82f821d-7bd9-4cb7-9d17-c92628dde594', 'Аяқ киімі кенет тар болып қалды ма? 👟', 'Жүгіргенде жиі сүріне ме? Аяғы өскен болуы мүмкін! Салмақ бақылау құралына қазіргі бойы мен аяқ киім өлшемін енгізіп, дене дамуын қадағалаңыз.'),
  ('ca3c13b4-94b6-44d7-a1be-1829a1d0e718', 'Сүйектері нығайып келеді 🦴', 'Қарқынды өсуге кальций қажет. Тамақтануды бақылау құралы арқылы бүгінгі ірімшік пен йогурт мөлшерінің жеткілікті болғанын тексеріп, жетіспегенін бірден толықтырыңыз.'),
  ('cbda41ad-a761-4c07-b60f-6e77f3dd54cc', 'Сіз онсыз да кереметсіз 🌟', 'Бүгін күні бойы оның соңынан жүгіріп, шаршадыңыз. Көңіл күй күнделігін ашып, бүгін ол үшін жасаған ең кішкентай жақсылығыңызды да жазып, өзіңізге тік тұрып қол соғыңыз!'),
  ('63d48088-e9cb-43c1-afc1-9e4bb32ff340', 'Сіздің кішкентай көшірмеңіз 📸', 'Сіз бөлмені сыпырғанда, ол да шүберекпен сүрте ме немесе Сіз сияқты жүре ме? Еліктеу шегіне жетті!'),
  ('669259fd-a22a-4d24-b932-9eedd58dff3f', 'Қантсыз, бірақ тәтті 🍪', 'Дүкен печеньелерімен қоштасыңыз! Бөпеге арналған рецепттерден үйде 10 минутта дайындалатын, құрма мен алмадан жасалған пайдалы тәттілерді тауып, оны қуантыңыз.'),
  ('14d92f0a-2caa-441a-b66e-e4531b0f2c30', 'Кенеттен пайда болған агрессия 🛑', 'Ашуланғанда достарын итере ме немесе Сізге қол көтере ме? Осы жаста күшейетін агрессиялық эмоцияларды қалай жұмсақ бағыттауға болатынын дәл қазір Anacan AI-дан сұраңыз.'),
  ('a1ab1785-3fde-4782-bfe0-d24e5fc6ec72', 'Беліңіз ауыра ма? 🧘‍♀️', 'Салмағы 13+ kq бөпені көтергеннен беліңіз сырқырай ма? Пайдалы рецепттерден бұлшықеттерді босаңсытатын, қабынуға қарсы зімбір шайын демдеп, өзіңізге күтім жасаңыз.'),
  ('e3fde63e-bd7b-46c0-8b54-9e79a9f6fb65', 'Тыныштық оны қорқыта ма?', 'Бөлмеде «Ақ шу» бөлімінен желдеткіштің немесе шаш кептіргіштің дыбысын қосып, ұйықтайтын ортада бөпеге қауіпсіздік сезімін қалай қалыптастыратынын көріңіз.'),
  ('7ac3c96c-42b7-4566-aa71-c52f9eb0b4eb', 'Ми тұманы 🌫️', 'Қатты шаршап, бәрін ұмытып жүрсіз бе? Әйелдерге арналған пайдалы рецепттерден Омега-3-ке бай жаңғақ тіскебасарын дайындап, Көңіл күй күнделігіне ойларыңызды жазып, санаңызды сергітіңіз.'),
  ('8144388a-1733-475c-83c3-62e4fa74eb05', 'Түбекке отырғысы келмей ме? 🚽', 'Дәретханаға барғысы келмей, жылай ма? Үйретуді уақытша тоқтату керек пе, әлде басқа әдісті қолданып көру қажет пе — мұны дәл қазір Anacan AI сарапшы көмекшімізден сұраңыз.'),
  ('aff8f3ff-854b-4c58-ae45-b01d9a3d3fdb', 'Тек жеміс жей ме? 🍎', 'Ақуызды тағамдардан немесе көкөністерден бас тарта ма? Тамақтануды бақылау құралы арқылы бүгін қанша пайдалы тағам жегенін есептеп, жеміс қосылған йогурт сияқты дәмді үйлесімдер дайындаңыз.'),
  ('53d8ad5e-ba3b-4f31-a266-650eb5f83382', 'Кішкентай тазалық көмекшісі 🧹', 'Сіз бөлмені сыпырғанда, ол да шүберекпен сүрте ме немесе шаңсорғышқа ұмтыла ма? Осы күлкілі еліктеу сәтін бірден Бөпе фотосессиясындағы стикерлермен безендіріп, альбомға жүктеңіз.'),
  ('9d0ac1c5-216f-4fa0-95d2-f983474b4839', 'Темір қорын тексеру 🥩', 'Белсенді балақайда қаназдық болмауы үшін Тамақтануды бақылау құралынан оның бүгін қанша темір (ет, бұршақ тұқымдастар) қабылдағанын тексеріп, мәзірін жаңартыңыз.'),
  ('8f01b040-4aa3-4a5f-a127-4287f88b0ef1', 'Секіру өнері 🦘', 'Енді оған диван да аздық етеді! Батуты бар қауіпсіз жабық ойын-сауық орталығын тауып, бойындағы энергиясын шығаруға көмектесіңіз.'),
  ('cf348bab-0260-4da9-bc53-4069f0a6ddf3', 'Кішкентай суретші іске кірісті 🎨', 'Бояулармен ойнап, бет-аузын түгел бояп тастады ма? Ашуланудың орнына осы көңілді шығармашылық сәттен ләззат алыңыз.'),
  ('d6dd1818-c4fb-46af-be6f-20980791db71', 'Түнгі оянулар қайта басталды ма? ⏱️', 'Түн ортасында жылап оянып, қайта ұйықтауы қиындады ма? Ұйқы таймерінің статистикасын талдаңыз. Бұған 2 жастағы ұйқы регрессиясы немесе тіс жаруы себеп болуы мүмкін.'),
  ('1d5cbb75-8a18-4083-a6e5-10d5b00dd31c', 'Табиғи тыныштандыру тәсілі 🍃', 'Бүгінгі күн у-шуға және жүгіріске толы болды ма? Бөлмені қараңғылап, Ақ шулардан өзен сылдырының дыбысын қосып, бөпеңізбен бірге ойыңызды тынықтырыңыз.'),
  ('947b2874-60ed-46dc-82cb-4ddf972a50b1', 'Ақуыз қоры жеткілікті ме? 🍗', 'Белсенді бұлшықеттер үшін ақуыз қажет. Тамақтануды бақылау құралы арқылы оның күнделікті тағамдық теңгерімін бағалап, мәзірін байытыңыз.'),
  ('f56b8fb7-fe66-42a7-afb0-9342dd02a543', 'Сүйікті әндер 🎤', 'Бір әнді қайта-қайта айтып немесе ыңылдап жүр ме? Оның ырғақты сезінуі мен тілінің дамуын Бөпе фотосессиясындағы музыкалық стикерлермен безендіріп, альбомға қосыңыз.'),
  ('dc8f916f-27ea-45e1-9c5f-84435b0902fd', 'Өзім жеймін деген қырсықтық 🥄', 'Қасықты қолыңыздан алып, айналаның бәрін былғай ма? Тамақтану таймерін қосып, өз бетінше жеуге талпынысы қанша уақыт алатынын талдаңыз. Шашылған тағамға жай ғана күлімсіреңіз.'),
  ('1d9a17fb-3ed7-4382-9eaf-1517914b5b98', 'Мына шалбарды кимеймін! 👗', '«Өзім киінемін!» деген қырсықтығы басталды ма? Таңертеңгі киіну кезіндегі дағдарысты азайтып, оған өз бетінше таңдау жасауға мүмкіндік берудің жолдарын Anacan AI-дан біліңіз.'),
  ('98d988ed-7e7f-4eb3-8b84-734112bb1929', 'Сізге де достар керек 👯‍♀️', 'Тек баламен сөйлесуден шаршадыңыз ба? Анаға жайлы орындардан ойын топтары бар орталықтарды тауып, басқа аналармен араласыңыз әрі тәжірибе бөлісіңіз.'),
  ('f6ae40aa-d27d-4aed-a0d9-bd51bad467d7', 'Кітапты жыртпай, оқиық 📖', 'Кешкі ертегі кезінде кітаптың беттерін жырта ма немесе оқуға кедергі келтіре ме? Кітап оқуға деген қызығушылығына зиян келтірмей, бұл мәселені қалай шешуге болатынын дәл қазір Anacan AI-дан сұраңыз.'),
  ('27d6b395-9576-4f2d-9566-57d41e7c6f41', 'Күн тәртібін толық талдайық ⏱️', 'Кешке ұйықтауға 40 минут кетті ме? Ұйқы таймерінің графигін қараңыз. Мүмкін, күндізгі ұйқыны 20 минутқа қысқартып, кешкі ұйқы уақытын ертерек жылжытатын кез келген шығар.'),
  ('dec1d9f5-52bc-4c79-9c9c-281f44046beb', 'Таусылмайтын «Неге?» сұрақтары 🤔', 'Сұрақ қоюдан жалықпай ма? «Бұл не? Неге?» кезеңі ресми түрде басталды! Баланың білуге деген қызығушылығына қалай сабырмен жауап беруге болатынын блогтардан біліңіз.'),
  ('e68bbf03-3f37-41e8-a1d9-32feba8b86d7', 'Қантсыз, бірақ тәтті 🍪', 'Дүкен печеньесімен қоштасыңыз! Бөпелерге арналған рецепттерден үйде 10 минутта дайындалатын пайдалы тәттілерді тауып, оны қуантыңыз.'),
  ('32443a45-bb1d-40cd-8cbf-77a3eda300d7', 'Ыстық шай мен тыныштық 🍵', 'Таймер тоқтады, бала ұйықтап қалды. Үй шаруасына асықпаңыз! Пайдалы рецепттердің бірінен ерекше кофе дайындап, диванға жайғасып, тыныштықтан ләззат алыңыз.'),
  ('0963259b-f909-4657-ae5e-475b63d595ec', 'Күндізгі ұйқыға қарсылық! 🛌', 'Түсте ұйықтағысы келмей, қашып жүр ме? Anacan AI-дан 2 жастағы балалардың ұйқы қажеттілігі және тыныш уақытты (quiet time) ұйымдастырудың қыр-сырын сұраңыз.'),
  ('0bba2ea7-ff2c-40db-9921-cae50208c766', 'Шешінудің шебері! 🧦', 'Шұлығын немесе шалбарын өз бетінше шешуге тырысып жүр ме? Бұл — қимыл-қозғалыс дағдыларының жақсы дамып жатқанының белгісі.'),
  ('160a2dee-dfe4-4a75-b257-c4a10c478741', 'Зімбірдің күші 🫖', 'Күні бойы жүгіріп жүріп, беліңіз бен аяғыңыз ауырып кетті ме? Пайдалы рецепттерден бұлшықетті босаңсытатын шай демдеп, тынығып алыңыз.'),
  ('20369d8a-500f-4d0c-8f13-a85f623e07d2', 'Құстарды бақылаймыз 🕊️', 'Үйде қатты зерігіп кетті ме? Жасыл желекке толы саябақ тауып, құстарға жем беріңіз — бұл оның табиғатқа деген жанашырлығын арттырады.'),
  ('69fc5add-e558-46f8-bee8-37acee27a9c1', 'Ертегі ойлап табатын уақыт 📖', 'Кітап оқудан жалықтыңыз ба? Жарықты өшіріп, Ақ шудан жаңбыр дыбысын қосыңыз да, қараңғыда бірге қиял-ғажайып ертегілер ойлап тауып, ұйқыға кетіңіздер.'),
  ('d25adde2-a568-4bad-bacf-b25822698f2a', 'Қайтадан езбе ме? 🥣', 'Қатты тағамды шайнағысы келмей, қайтадан езбе сұрай ма? Бөпеге арналған рецепттерден шайнауға оңай, бірақ езбе емес қызықты котлет рецепттерін қарап көріңіз.'),
  ('181e78e0-6fdf-4595-ab68-0d67492cb40c', 'Өзім құямын! 🥛', 'Суды стақанға өзі құйғысы келіп, айналаның бәрін сулап жүр ме? Күнделікті тұрмыс дағдыларын дамыту үшін Ұсынылатын өнімдер бөліміндегі төгілмейтін ақылды стақандарды қарап көріңіз.'),
  ('68364d15-562a-4922-a1dc-902274f2d63c', 'Есікті тарс жаба ма? 🚪', 'Ашуланғанда есікті тарс жауып, жылай ма? Осындай қатты эмоциялық күйзелістерді басқару стратегияларын білу үшін Anacan AI сарапшымызға дереу хабарласыңыз.'),
  ('de0f5d4f-9f96-42d7-a940-e7558af5d045', 'Аяқүсті жүріп ас ішпеңіз 🍎', 'Өзіңізді бағалаңыз! Пайдалы рецепттер ішінен антиоксиданттарға бай жидек салатын дайындаңыз.'),
  ('7a5b3c40-a866-426b-8ed4-dd68302d6513', 'Дәретхана қағазына қызыға ма? 🧻', 'Жуынатын бөлмеде дәретхана қағазын орамынан тарқатып ойнай ма? Бұл қызығушылықты мүмкіндікке айналдырыңыз: Блогтар бөліміндегі құмыраға ойын арқылы үйрету туралы мақаланы дәл қазір оқыңыз.'),
  ('d2a5512c-c089-47a6-aba1-367f406306e5', 'Бір, екі, үш... 🔢', 'Баспалдақпен көтерілгенде бір нәрселерді санауға тырыса ма? Бұл — математикалық дамудың алғашқы нышандары.'),
  ('f4ef4af2-bbdc-456f-a980-4eeb315c77b8', 'Тістері түгел шықты ма? 🦷', 'Соңғы азу тістері шығып жатыр ма? Кальцийге деген қажеттілігін өтеу үшін Тамақтануды бақылау құралы арқылы бүгін қанша йогурт пен ірімшік тұтынғанын міндетті түрде тексеріңіз.'),
  ('0480de3f-fc2e-475f-9c9a-7f062b43912d', 'Жатын бөлме тым ыстық па? 🌡️', 'Төсекте көп аунап, терлей ме? Бөлме температурасын тексеріңіз, ұйқы таймерін қосып, Ақ шулар бөліміндегі желдеткіш дыбысы арқылы бөлмеде психологиялық тұрғыдан салқындық сезімін қалыптастырыңыз.'),
  ('2b885719-7eb3-49f2-a501-3fdceb08a1dc', 'Сіз кетсеңіз, жылай ма? 🚪', 'Бөлмеден шыққаныңызда артыңыздан айқайлап жылай ма? Ажырасу мазасыздығының осы жаңа кезеңін жұмсақ еңсеру жолдарын Anacan AI-дан сұраңыз.'),
  ('4ef212ee-e501-41a3-bd1b-0f62028addbd', 'Логика іске қосылды 🧩', 'Геометриялық пішіндерді сәйкестендіруді жақсы меңгеріп келе ме? Ойлау қабілетін одан әрі сынайтын күрделірек ойындарды табу үшін Ұсынылатын өнімдер бөлімін қараңыз.'),
  ('132f97c4-bee0-471c-ad8b-a7fc3585b9d6', 'Тіс пастасын таңдау 🪥', 'Аузындағы суды түкіруді үйрене бастады ма? Құрамында фтор бар немесе фторсыз пастаны таңдау туралы Блогтар бөліміндегі ғылыми мақаламызды міндетті түрде оқыңыз.'),
  ('c85cd72a-3a99-42a3-86ab-1fa1d9a4f422', 'Балшықтан жасалған торттар! 🧁', 'Аулада топырақпен ойнағысы келе ме? Үстін былғауына рұқсат етіңіз! Сенсорлық дамуды қолдайтын осы тамаша сәттерді Бөпе фотосессиясы арқылы мәңгі есте қалдырыңыз.'),
  ('da905da7-70f6-46f4-b372-c620f421daf8', 'Миыңызды қайта жүктеңіз 🧘‍♀️', 'Бәрі бірден басыңызға үйіліп жатқандай сезіле ме? Көңіл күй күнделігін ашып, 3 минут бойы тоқтамай не сезіп отырғаныңызды жазыңыз. Ойыңызды қағазға түсіру күйзелісті бірден азайтады.'),
  ('929b30f1-695d-4f66-a22b-9182b15561c4', 'Гравитация сынағы! 🍎', 'Тамақты немесе ойыншықтарды жоғарыдан төмен тастағанды ұната ма? Осы физикалық тәжірибелеріне тыйым салмай, оларды басқа арнаға бағыттауды Anacan AI-дан үйреніңіз.'),
  ('a100b8dd-35f6-4549-ae5f-d60352e46cb5', 'Талшық жетіспей ме? 💩', 'Нәжісі қатайып, іш қату мазалай ма? Мұны Жөргек бақылағышына белгілеп, бірден Тамақтануды бақылау құралы арқылы мәзірге қара өрік немесе сұлы қосыңыз.'),
  ('f0258928-f8cb-46a1-adb3-9d7138af115d', 'Алғашқы ойын досы 👯‍♂️', 'Саябақта басқа баламен үнемі ойнауға талпына ма? Ана достары орындары бөлімінен әлеуметтенудің осы жаңа кезеңін қолдайтын балалар кафелерін қарап шығыңыз.'),
  ('0b94a795-dee1-49c6-a4fb-e07d6174147f', 'Ұйқы таймерін талдау ⏱️', 'Кешкісін тым кеш ұйықтай ма? Ұйқы таймерінің кестесіне қараңыз. Күндізгі ұйқыны қысқартып, кешкі ұйқыны ертерек бастайтын уақыт жақындап қалды.'),
  ('225bd8fb-b294-42ab-8941-6c8eee154c5f', 'Аяқкиімі кенеттен тар болып қалды ма? 👟', 'Жүгіргенде жиі сүріне ме? Аяғы өсіп кеткен болуы мүмкін! Даму бақылағышына қазіргі бойы мен аяқкиім өлшемін енгізіп, физикалық дамуын қадағалаңыз.'),
  ('f7cd700a-6bea-4a3e-a6b4-0018529f2ea2', 'Кофе ме, әлде су ма? 💧', 'Шаршауды кофеинмен басуға тырыспаңыз! Әйелдерге арналған пайдалы рецепттерден қуат беретін ақуызды әрі жемісті детокс сусындарын табыңыз.'),
  ('51803c0a-8b62-474c-8ecd-e45188efdf2a', 'Киім бүктеу ойыны 🧺', 'Сіз киімдерді жинап жатқанда, ол да көмектескісі келе ме? Оған шұлықтардың жұбын табуды тапсырыңыз! Блогтардан ойын арқылы жауапкершілікке баулудың қыр-сырын оқыңыз.'),
  ('ede1e4a9-4d71-4eca-bacd-697cb6454edc', 'Қараңғы бөлмеден қорқу 🌌', 'Жарықты өшіргенде жылай ма? Қиялы дамыған сайын қорқыныштары да көбейеді. Ақ шу бөлімінен ана құрсағындағы дыбысты қосып, оған бұрынғы қауіпсіздік сезімін сыйлаңыз.'),
  ('13aac5b4-c714-41fb-8e2e-16c1c92d8390', 'Кітапқа қызығушылықты қалай оятуға болады? 📖', 'Оқудың орнына кітап беттерін жыртқысы келе ме? Кітап оқу әдетіне кері әсер етпей, оның назарын ертегіге аударудың тиімді жолдарын Anacan AI-дан сұраңыз.'),
  ('542e3a59-e25b-4803-a553-c3183744d2dc', 'Темірдің құпиясы: C дәрумені 🍋', 'Темір ағзаға жақсы сіңуі үшін Тамақтануды бақылау құралындағы бүгінгі мәзірді қараңыз. Ет тағамының қасына міндетті түрде лимоны немесе қызанағы мол салат қосыңыз.'),
  ('bb3d49d9-8e03-48af-9a82-d11c505ca32b', 'Ананың кофе ішетін уақыты ☕', 'Үй шаруасын бір сәтке қоя тұрып, тынығып алыңыз! Анаға қолайлы орындардан балаларға арналған ойын бұрышы бар дәмхана тауып, ыстық кофеңізді асықпай ішіңіз және басқа аналармен танысыңыз.'),
  ('0d828df8-79e8-40c6-a759-0255d981435d', 'Түнгі дыбыс: Пойыз 🚂', 'Күндізгі шудан кейінгі кенет тыныштық оны мазалай ма? Үйдегі басқа дыбыстарды басу үшін Ақ шу бөлімінен пойыздың бірқалыпты дыбысын қосып, бөпеңізді ұйқыға бейімдеңіз.'),
  ('8776b932-7a29-4e58-81cd-88646f84a4c7', 'Аяқкиімі кенет тар болып қалды ма? 👟', 'Жүгіргенде сүріне ме немесе аяқкиімін шешкісі келе ме? Аяғы өсіп кеткен болуы мүмкін! Даму трекеріне қазіргі өлшемдерін енгізіп, физикалық дамуын бірден бақылаңыз.'),
  ('e742c56f-494a-46b7-82c7-113a5d4f0287', 'Қантсыз энергетикалық шарлар 🍪', 'Дүкен тәттілерімен қоштасыңыз! Бөпеге арналған рецепттерден небәрі 10 минутта дайындалатын, құрма мен сұлы қосылған пайдалы әрі дәмді тіскебасарларды тауып, оны қуантыңыз.'),
  ('250e2ef0-defa-4388-a9c2-8574f1be0fed', 'Асүйдегі аспаз 👩‍🍳', 'Бөпелерге арналған рецепттердегі қантсыз печенье қамырын бірге илеңіздер. Осылайша оның ұсақ моторикасы дамып, өз қолымен жасағанын сүйсініп жейді.'),
  ('2ee3ac65-4c9f-4558-a181-e43a5be6a221', 'Кішкентай альпинист 🧗', 'Жиһаздың үстіне шығу оның сүйікті ісіне айналды ма? Үйдің қауіпсіздігін барынша арттыру үшін Ұсынылатын өнімдер бөліміндегі арнайы қорғаныш құралдарын қарап шығыңыз.'),
  ('e1c7d8a6-1882-42b5-8d1e-5420a73cc054', 'Судың сылдыры 🌊', 'Бүгін тым қарбалас әрі жүгіріске толы күн болды ма? Жарықты бәсеңдетіп, Ақ шулардан өзеннің сылдырын қосыңыз да, бөпеңізбен бірге тыныштық құшағына еніңіз.'),
  ('09840996-6ece-429b-8105-2969a0ec7d4b', 'Өзіңізді мақтаңыз 🌟', 'Бүгінгі күнді ешбір дағдарыссыз аяқтай алдыңыз ба? Сіз болмағанда, мұндай даму да болмас еді. Көңіл күй күнделігін ашып, жанкешті еңбегіңіз үшін өзіңізге үлкен алғыс жазыңыз!'),
  ('152dc6e1-3207-4818-a59d-35cf71d6d914', 'Ойыншықтарға деген мейірім 🧸', 'Қонжығына бесік жырын айтып немесе үстін жауып жүр ме? Бұл — эмпатиясының жақсы дамып келе жатқанының белгісі. Осы сәтті дыбысы бар видео ретінде Бөпе альбомына қосып, оның мейірімділігін сақтап қойыңыз.'),
  ('cb411136-f146-4918-b034-820fe50cfd21', 'Сөздік қордың қарқынды өсуі 🗣️', 'Сөздік қоры қалай дамып жатыр? Блогтар бөлімінен осы айға тән сөйлеу дамуының көрсеткіштері мен оны қолдайтын үй ойындарын табыңыз.'),
  ('047ed43c-bb7c-4206-afa0-67d1dc0f765d', 'Тағамдар түрлі пішінге енеді ⭐️', 'Кәдімгі туралған жемісті жемей ме? Бөпе рецептеріндегі жұлдыз немесе жануар пішініндегі көңілді тәрелке безендіру үлгілерін қарап, тамақтануды қызықты көрнекі ойынға айналдырыңыз.'),
  ('5f17b1b2-9554-4ba7-b535-5f0af1522385', 'Жасырынып үлкен дәретке отыра ма? 🙈', 'Перденің артына немесе бір бұрышқа барып, үлкен дәретке отыра ма? Бұл — түбекке үйретуге дайын екенінің ең маңызды психологиялық белгісі! Мұны Жөргек бақылағышына белгілеп, Блогтардағы үйрету туралы мақалаларды оқыңыз.'),
  ('81b85e80-d265-4f32-8c47-4b14aa23d8e1', 'Кенеттен пайда болған агрессия 🦖', 'Ашуланғанда достарын итере ме немесе Сізді ұра ма? Осы жаста күшейе түсетін агрессиялық эмоцияларды қалай жұмсақ бағыттауға болатынын дәл қазір Anacan AI-дан сұраңыз.'),
  ('bf03a99b-eae8-47d0-a5c6-eb2e17e62b7d', 'Өзіңізді ұмытпаңыз ⚡', 'Түсте әбден әлсіреп қаласыз ба? Тәттіге ұмтылмаңыз! Әйелдерге арналған пайдалы рецептерден бірден қуат беретін, ақуызға бай жержаңғақ пастасы қосылған смузи дайындап, күш-қуатыңызды толықтырыңыз.'),
  ('fdde906c-a398-4012-a073-4015f9852301', 'Таймермен ұйқыны талдау ⏱️', 'Кешке ұйықтап кетуі тым ұзаққа созылды ма? Ұйқы таймерін қосып, кестені бақылаңыз. Оның энергиясын толық жұмсамағанын немесе шамадан тыс шаршағанын талдаңыз.'),
  ('63af320f-f496-491d-b573-f5b6663a91e4', 'Ыстық шай мен тыныштық 🍵', 'Таймер тоқтады, бала ұйықтап қалды. Енді үй шаруасына кіріспеңіз! Әйелдерге арналған пайдалы рецептерден мелисса шайын демдеп, күннің шаршауын ыстық бумен бірге шығарып жіберіңіз.'),
  ('86e064b7-8da1-4aa9-b551-ca85b1a25e7c', 'Ақуыз қоры жеткілікті ме? 🍗', 'Тынымсыз жүгіріп, секіретін бұлшықеттерге ақуыз міндетті түрде қажет. Тамақтануды бақылау құралы арқылы оның күнделікті тағамдық теңгерімін бағалап, ас мәзірін байытыңыз.'),
  ('947ec858-749d-4a0f-bf72-73a1503e2c5f', 'Таусылмайтын «Неге?» сұрақтары 🤔', '«Бұл не? Неге бұлай?» кезеңі ресми түрде басталды! Баланың шексіз зерттеуге деген қызығушылығына қалай сабырмен әрі дамуына ықпал ететіндей жауап беруге болатынын блогтардан біліңіз.'),
  ('5d69eb5c-8ed9-4c1d-9b48-d1c46bb4e1fb', 'Ескі дауыс жазбалары 🎤', 'Бала ұйықтағаннан кейін Бөпе альбомын ашып, бірнеше ай бұрын шығарған сол сүйкімді дыбыстарын тыңдаңыз. Оның қаншалықты тез өсіп келе жатқанын көріп, мақтаныңыз!'),
  ('c3ea09ec-b61b-40ca-8245-a6b47232b78f', '«Менікі!» кезеңі 🧸', 'Саябақта ойыншығын ешкімге бермей ме? 2.5 жасқа жақындаған балаға кезекпен ойнау ұғымын қалай үйретуге болатынын Anacan AI-дан сұрап біліңіз.'),
  ('c569bc01-3134-4ece-a6d6-d600fb0bf88b', 'Беліңіз сырқырай ма? 🧘‍♀️', 'Салмағы артып келе жатқан бөпені көтеруден бұлшықеттеріңізге күш түскен. Әйелдерге арналған пайдалы рецепттерден қабынуға қарсы әсері бар зімбір шайын демдеп, жатып демалуға уақыт бөліңіз.'),
  ('504aaa66-e4f6-4eca-bd17-eead2d69deec', '«Өзім киінемін» өнері 👕', 'Шалбарын басына, жейдесін аяғына киюге тырыса ма? Осы күлкілі дербестік әрекетін өткізіп алмаңыз! Бірден Бөпе фотосессиясындағы көңілді стикерлермен безендіріп, альбомға жүктеңіз.'),
  ('c0ee7f2f-8895-4772-8368-647fe5fed56e', 'Шалшықтарды зерттеу 🌧️', 'Жаңбырдан кейін үйде отыруға болмайды! Анаға қолайлы орындардан жақын маңдағы саябақты тауып, резеңке етігін кигізіп, балшықта секіруіне рұқсат етіңіз.'),
  ('e70f443c-46d9-4882-ab14-fad93c425a0f', 'Ұйқы уақыты жылжып барады ⏱️', 'Күндіз ұйықтаудан бас тартты ма? Кешке қатты шаршап, мазасызданбауы үшін ұйқы таймерін қосып, кешкі режимді 30 минут ертерек бастаңыз.'),
  ('65eaf451-e5ab-4c54-9b0f-1a6331bd0312', 'Саусақ моторикасы дамып келеді 🧩', 'Ол қарапайым пазлдарды меңгеріп алды. Зердесіне көбірек күш түсіретін күрделі әрі көп бөлшекті ағаш басқатырғыштарды Ұсынылатын өнімдер бөлімінен табыңыз.'),
  ('c2a5ae09-9d8c-4ef8-afa7-4f35fb948c6f', 'Еденге жатып алып жылау 🛑', 'Қоғамдық жерде өзін жерге тастап, айқайлай ма? Айналадағылардың көзқарасына мән бермеңіз! Осындай күшті эмоциялық күйзелістерді сабырмен басқару үшін Anacan AI-мен сырласып, тиімді тәсілдерді үйреніңіз.'),
  ('f9afcff7-9182-4728-9ed2-135f5b97e440', 'Кітапты жыртпай, оқу керек 📖', 'Кешкі ертегі кезінде кітап беттерін жырта ма? Кітап оқу әдетіне зиян келтірмей, оның назарын ертегіге қалай аударуға болатынын Блогтар бөлімінен оқыңыз.'),
  ('11eb0bc9-4158-4fbc-8d65-97be316f8b92', 'Кальций тек сүтте емес 🧀', 'Сүт ішуден бас тарта ма? Сүйектер үшін кальций міндетті түрде қажет. Тамақтануды бақылау құралы арқылы бүгін жеген ірімшік, йогурт немесе брокколи мөлшерін есептеп, жетіспегенін толықтырыңыз.'),
  ('d4efd00f-6d87-4868-a912-9b76b79425d0', 'Айна алдындағы шоу 🤪', 'Бет-аузын құбылтып, айнаға қарап қарқылдап күле ме? Өзін танып-білудің осы қызықты сәтін бірден видеоға түсіріп, Бөпе альбомына қосыңыз да, күннің күйзелісін ұмытыңыз.'),
  ('3f2f1108-7831-4796-88a8-5de7f4f81912', 'Сізге де үзіліс қажет ☕', 'Үйден шығып, біраз сергіп қайтыңыз! Анаға қолайлы орындардан балалар бұрышы бар жақын маңдағы дәмхананы табыңыз, ыстық кофеңізді асықпай ішіп, басқа аналармен танысыңыз.'),
  ('875b72c1-d353-4eb2-8649-bca828613387', 'Өзіңізді мақтан тұтыңыз 🌟', 'Оның күн сайын үйренген әрбір жаңа дағдысы мен сенімді басқан әрбір қадамы — Сіздің еңбегіңіздің жемісі. Көңіл күй күнделігін ашып, бүгін өзіңізге тік тұрып қол соғуға тұрарлық жазба қалдырыңыз!'),
  ('9ccd2cce-af67-4d8c-b8c4-0ddfa25c77b1', 'Тамағын айналдырып ойнап, лақтыра ма? 🥣', 'Үстел басында отырудан жалығып, қасығын лақтыра ма? Тамақтану таймерін қосып, үдерістің ұзақтығын график арқылы талдаңыз және күштеп тамақтандырудан толықтай бас тартыңыз.'),
  ('4bafd57a-0f5f-4a7d-8215-cfd63b08cad2', 'Бір түсті тағамдар ғана ма? 🟡', 'Тек сары түсті тағамдарды (картоп, макарон, банан) сұрай ма? Тамақтануды бақылау құралы арқылы оның мәзірін талдап, Бөпеге арналған рецепттерден түрлі түсті әрі көкөнісі білдіртпей қосылған баламаларды табыңыз.'),
  ('accea8e1-cb5f-4833-9081-056b6237ac04', '«Мен» мен «Сеннің» айырмашылығы 🗣️', 'Енді өзі туралы 3-ші жақта емес, «Мен» деп айта бастады ма? Танымдық дамудағы осы үлкен серпілісті қолдау үшін Anacan AI-дан дұрыс диалог құрудың қыр-сырын бірден сұраңыз.'),
  ('f9e8a36b-3135-4421-adad-49b6ce187cf2', 'Тағы бір ертегі! 📚', 'Ұйықтамау үшін қайта-қайта жаңа сылтау ойлап таба ма? Ұйқы таймерін қосып, белгіленген шекараны сақтаңыз және Ақ шулардан мұхит толқынының дыбысын қосып, бөлмеде тыныштық орнатыңыз.'),
  ('52ee49fe-425d-44ef-9429-5ef1f4410d82', 'Секіру өнері 🦘', 'Баспалдақтан немесе диваннан секіруге тырыса ма? Қимыл-қозғалыс дағдыларын дамыту үшін қауіпсіз орын қажет. Анаға қолайлы орындардан батуты бар жабық ойын-сауық орталығын тауып, оның энергиясын дұрыс арнаға бағыттаңыз.'),
  ('f8fbff5d-2a79-4ebc-90f5-c58d315a80ab', 'Сіздің де қуатыңыз шектеулі 🔋', 'Күні бойы «Жоқ» деуден және жүгіріп жүруден шаршадыңыз ба? Ішіңізде жиналған сезімдерді Көңіл күй күнделігіне жазыңыз. Есіңізде болсын, өзіңізге уақыт бөлу — сән-салтанат емес, қажеттілік.'),
  ('fb79060e-f7c1-4e3e-983a-bf84e747b66e', 'Аяқкиімдері теріс киілген! 👟', 'Оң аяқкиімін сол аяғына, сол аяқкиімін оң аяғына киіп алып, шешкісі келмей ме? Осы күлкілі дербестік әрекетін Бөпе фотосессиясындағы көңілді стикерлермен безендіріп, альбомдағы ең қызықты кадрға айналдырыңыз.'),
  ('10f0ddfb-06ae-4780-9b39-ba433d0edc10', 'Банан ба, әлде телефон ба? 🍌', 'Бананды немесе теледидар пультін құлағына тақап, ойдан шығарылған әңгіме жүргізе ме? Бұл — қиял ойынының шыңы! Осы баға жетпес сәтті дыбысы бар видео ретінде бірден Бөпе альбомына қосып, мәңгілік естелікке айналдырыңыз.'),
  ('24cc9d6f-2286-4f7a-a81a-633ab5dd91df', 'Қараңғы бөлмеден қорқу 🌌', 'Жарықты өшіргенде бөлмедегі заттарды құбыжыққа ұқсата ма? Қиялы дамыған сайын қорқыныштар да пайда болады. Ақ шу бөлімінен ана құрсағындағы дыбысты қосып, оған бұрынғыдай толық қауіпсіздік сезімін сыйлаңыз.'),
  ('3c29abba-6cf4-47d2-a227-99611ccf0101', 'Темір мен қуаттың құпиясы 🥩', 'Белсенді балақайда қаназдық болмауы үшін Тамақтануды бақылау құралынан оның бүгін қанша темір (ет, жасымық, саумалдық) қабылдағанын тексеріп, мәзірін С дәрумені бар тағамдармен толықтырыңыз.'),
  ('074c97a3-66b5-4499-b8dd-c6ca41189da1', 'Сұйықтық ішу және іш қату 💧', 'Көп жүгіріп, бірақ суды аз іше ме? Жөргегін ауыстырғанда нәжісін бақылаңыз. Іш қату қаупі болса, оны қолданбаға белгілеп, Тамақтануды бақылау құралы арқылы бірден талшыққа бай тағамдарды (алмұрт, сұлы) қосыңыз.'),
  ('33f7b16f-fd6e-4686-be50-8b9aabfa4a20', 'Түстер мен пішіндердің шебері 🔴🟩', 'Заттарды, түймелерді немесе ойыншықтарды түсіне қарай топтастыра ма? Ойлау қабілетін шыңдап, логикасын дамытатын ағаш пазлдарды Ұсынылатын өнімдер бөлімінен дәл қазір табыңыз.'),
  ('912d3d15-f8b0-4ade-8219-5e9c81b99f0a', 'Түнгі қорқыныш па, әлде жаман түс пе? 🤖', 'Түн ортасында жылап оянып, тыныштала алмай ма? Екеуінің айырмашылығын түсініп, дұрыс психологиялық көмек көрсету үшін Блогтар бөліміндегі ғылыми мақалаларымызды оқыңыз.'),
  ('0ba368ce-9746-48c2-a3e5-a973ee982121', 'Макаронға деген махаббат 🍝', 'Балаңыз бірнеше күннен бері бір тағамды ғана сұрай ма? Тамақ талғауы шегіне жетті. Пайдалы рецептілер бөлімінен көкөністерді білдірмей қосуға болатын қызықты тұздықтарды іздеп көріңіз.'),
  ('92abce30-d667-4f40-9371-ee7642e09a28', 'Тыныштықтың ләззаты 🤫', 'Бөлмеде ақыры тыныштық орнады. Шаруаларды қоя тұрып, қараңғыда отыра тұрыңыз. Дыбыс өлшегішті қосып, тыныштық деңгейін өлшеңіз де, миыңызды тынықтырыңыз.'),
  ('e50a9ce1-a01a-4462-9bc9-e410e94685ff', '800-ді еңсердік!🚀', 'Енді көбірек сұрақ, көбірек қимыл-қозғалыс және жарқын мінез танытатын кез келді. Осы жаңа әрі қызықты кезеңді терең тыныс алып бастаңыз.'),
  ('0ea063ed-fd41-47e6-9ae7-1268a3f1138f', 'Мінсіз ана туралы аңыздар 🛑', 'Бүгін экран алдында көп уақыт өткізді деп өзіңізді кінәлап жүрсіз бе? Интернеттегі мінсіз аналарды ұмытыңыз. Сіз өз болмысыңызбен мінсізсіз.'),
  ('6e5882b6-b1b9-4876-8253-b97551d73f12', 'Әкенің ойын алаңы 👨‍👧', 'Шыдамыңыз таусылып бара ма? Бөлменің есігін жауып, баланы әкесімен оңаша қалдырыңыз. Бүгін кешке үйдегі ойындарды әкесі басқарсын.'),
  ('c72b4558-e629-4a4b-bb39-ef072b6603b3', '«Неге?» кезеңі 🤔', 'Барлығына «Бұл неге бұлай?» деп сұрай ма? Оның миы ақпаратты губка секілді сіңіріп жатыр. Сабыр сақтап, оған қысқа әрі қисынды жауаптар беріңіз.'),
  ('015a0c8f-c960-422b-8198-6bdb85909e68', 'Қиын күн болды ма? 📝', 'Көңіл күй күнделігіне бүгінгі күйзелісті жазып, ішіңіздегіні ақтарыңыз. Мұндай дағдарыстарды барлық ана бастан кешіреді, Сіз жалғыз емессіз.'),
  ('5229a519-68a8-4340-8bba-d14464123530', 'Қиялға толы ойындар 🧸', 'Көліктерді сөйлетіп, ойыншық қонжығын тамақтандыра ма? Оның қиялы шарықтап келеді. Даму трекеріне осы когнитивтік серпілісті белгілеп, ойынға қосылыңыз.'),
  ('f0d11fbf-f594-485d-b316-f567d5c6731d', 'Үйде ішіңіз пысты ма?', '«Анаға қолайлы орындар» бөлімінен балалар ойын бұрышы бар кафе тауып көріңіз. Бөпеңіз ойнасын, ал Сіз кофеңізді суытпай ішіңіз.'),
  ('b9ab0ee4-3e32-4c6f-9669-cbb581181150', 'Әуен сыйлаған тыныштық 🎶', 'Кешкі мазасыздықты басудың ең оңай жолы — бөпеңіздің сүйікті әуенін қосып, оны құшақтап, бірге баяу билеу.'),
  ('c4cbfe42-b7f8-4e4c-ad6a-198774caa2d6', 'Күн райы құбылмалы болғандықтан үйде қалдыңыз ба?', 'Ауа райы мен киім құралы терезеден байқалмайтын нақты температураны бірден көрсетсін — саябаққа шығып қайтыңыз.'),
  ('ce87972f-2f28-45fe-80b3-aa0ec4116930', 'Өзім киінемін 👕', 'Шалбарын басына киіп алса да, өздігінен киінуге талпынысына кедергі жасамаңыз. Қазір дербестікке ұмтылысы шарықтау шегінде! Оған уақыт беріп, өзі байқап көрсін.'),
  ('43a750e7-aff2-4c1a-baec-6890bc56e642', 'Өзім құямын! 🥛', 'Суды стақанға өзі құйғысы келіп, айналаның бәрін сулап қоя ма? Практикалық дағдыларын дамытатын әрі төгілмейтін балаларға арналған ақылды стақандарды Ұсынылатын өнімдер бөлімінен тауып, жұмысыңызды жеңілдетіңіз.'),
  ('8d131ccb-5e19-4d42-b8a6-86bf255b1f23', 'Аспаз асүйде 👩‍🍳', 'Бөпелерге арналған рецепттер бөліміндегі қантсыз банан печеньесінің қамырын бірге илеңіз. Ұсақ моторикасы дамып, өзі дайындаған дәмді асын сүйсіне жесін.'),
  ('bd7400ff-b3f7-4318-9c68-166242aa98f9', 'Ыстық шай мен тыныштық 🍵', 'Таймер тоқтады, бала ұйықтап қалды. Үй шаруасына асықпаңыз! Пайдалы рецепттер бөліміндегі мелисса немесе түймедақ шайын демдеп, диванға жайғасып, тыныштықтан ләззат алыңыз.'),
  ('65e69d4e-9f8b-4e23-8934-10178d918f6b', 'Сенікі де менікі! 🧸', 'Саябақта өзгенің ойыншығын қайтарғысы келмей ме? Бұл — эгоцентризм кезеңі. Бөлісуді мәжбүрлеу арқылы емес, кезекпен ойнауды үйрету арқылы қалыптастырыңыз.'),
  ('36818534-e1f7-451b-9f88-51bf852bc139', 'Күндізгі ұйқыға қарсылық! ⏱️', 'Түскі ұйқыдан бас тартып, енді қатты шаршады ма? Ұйқы таймерінің кестесін қарап, түнгі үрей ұстамаларының алдын алу үшін кешкі режимді кемінде 40 минут ертерек бастаңыз.'),
  ('54668cb8-852a-467f-9492-c88f3b1ba329', 'Үлкен дәретін ұстап жүр ме? 💩', 'Түбекке үйрету кезінде түрегеп тұрып, үлкен дәретін ұстап қала ма? Бұл психологиялық іш қатуға әкелуі мүмкін. Мұны жөргек трекеріне белгілеп, мәзіріне бірден өрік немесе сұлы қосыңыз.'),
  ('d3a86832-34ed-43f4-90d5-a80f77b22f80', 'Төрт қабырғада іші пысады 🌳', 'Үйде энергиясын шығара алмай, бәрін жан-жаққа лақтырып жүр ме? Анаға қолайлы орындар картасын ашып, жұмсақ төсемі мен сырғанағы бар қауіпсіз саябақты табыңыз да, оның таза ауада еркін ойнауына мүмкіндік беріңіз.'),
  ('24023d7c-2bc9-4102-89e5-fd869c13910d', 'Бойы мен салмағы күрт өсті! 📏', 'Киіндірген кезде жейделерінің тарылып немесе аяқкиімінің қыса бастағанын байқадыңыз ба? Салмақ трекеріне қазіргі бойы мен өлшемдерін енгізіп, өсу қисығының қалай жоғарылағанын мақтанышпен бақылаңыз.'),
  ('af6b0980-8f3e-49f7-8539-9fc05967e656', 'Темір қорын тексеріңіз 🥩', 'Өңі бозарып немесе тез шаршай ма? Тамақтануды бақылау құралынан бүгін қанша темір қабылдағанын тексеріңіз. Темірдің жақсы сіңуі үшін етпен бірге міндетті түрде С дәруменіне бай тағамдар (лимон, қызанақ) беріңіз.'),
  ('f5e0ef2c-4838-48df-b45d-d158a473879a', 'Сізге де дос керек 👯‍♀️', 'Күні бойы тек бала тілінде сөйлесуден шаршадыңыз ба? Анаға қолайлы орындардан аналар жиі жиналатын балалар кафелерін тауып, өзіңізге де араласып, әңгімелесуге мүмкіндік жасаңыз.'),
  ('3046868d-cc9d-4ca4-8350-b813468ec4dd', 'Шұғыл керек заттар 🛒', 'Сусабын, жөргек немесе сұлы таусылды ма? Ойда сақтап жүрмей, сатып алу тізіміне жазып, жұбайыңызбен синхрондаңыз.'),
  ('437a3027-38a4-47b2-a62c-a24094b2e7eb', 'Қалағаны болмағанда жерге жата қалып, айқайлай ма?', 'Кішкентай балалардағы ашу ұстамалары әлі де жалғасуы мүмкін. Қасында сабырмен күтіңіз, тынышталған кезде құшақтаңыз.'),
  ('71700719-be0c-45bf-8d93-6cb51d48ed2d', 'Кітапқұмар 📖', 'Ең сүйікті ертегі кітабын әкеліп, бір бетті қайта-қайта оқыта ма? Қайталау — оның үйрену тәсілі. Сабырмен тағы бір рет оқып беріңіз.'),
  ('d6aaa644-5d8a-47cd-b998-227fc0b6f04b', 'Үй шаруасы күте тұрады 🛑', 'Еден жуылмай қалды ма? Қоя тұрыңыз. Лас үйді жинауға болады, ал әбден қажыған ананың қалпына келуіне көп уақыт қажет. Диванға жатып, тыныштықты тыңдаңыз.'),
  ('04312503-34be-494a-8896-38312d406a86', 'Қиялдағы шай жиынтығы 🫖', 'Сізді немесе ойыншықтарын қиялдағы кеселерден шай ішуге мәжбүрлей ме? Рөлдік ойындар — зияткерлік дамудың шарықтау шегі!'),
  ('149beadc-5c37-404b-8b3e-f6ce437629da', 'Ананың мойын ауруы 🧘‍♀️', 'Еденде ойнап, баланы көтере бергеннен мойныңыз бен беліңіз құрысып қалды ма? Пайдалы рецепттер бөліміндегі бұлшықетті босаңсытып, қабынуды басуға көмектесетін зімбір қосылған көк шайды демдеп, тынығып алыңыз.'),
  ('2daba5bf-3da2-43ab-bc87-fdc726c1aabb', 'Кереует астындағы құбыжық па? 👾', 'Қиялы дамыған сайын қорқыныштары да шынайы сезіле бастайды. Көлеңкелерден қорықса, жарықты бәсеңдетіп, Ақ шулар бөлімінен ана құрсағындағы дыбысты (жүрек соғысын) қосыңыз. Бұл оған бұрыннан таныс, толық қауіпсіздік сезімін сыйлайды.'),
  ('d0a47f18-7e98-462c-be4f-167fcf918411', 'Сырғанақтағы кезек дауы 🛑', 'Саябақта басқа балаларды күткісі келмей ме? 2.5 жасқа таяғанда кезек пен шыдам ұғымдарын қалай үйрету керегін Блогтар бөліміндегі әлеуметтену туралы мақалалардан міндетті түрде оқыңыз.'),
  ('dc66703c-31b3-4677-a6cd-dc09bb5b60cf', 'Өзіңізді кінәламаңыз 💖', 'Бүгін баланың қырсықтығы шыдамыңызды тауысып, даусыңызды көтеріп қойдыңыз ба? Ішіңіздегі мазасыз ойларды Көңіл күй күнделігіне жазыңыз. Сіз робот емессіз, мінсіз болуға міндетті де емессіз!'),
  ('f9ec5212-0b50-47f7-b50f-84f41a8701a2', 'Киімді теріс кию сәнге айналды! 👕', 'Шалбарын теріс, аяқкиімін ауыстырып киіп алып, шешкісі келмей ме? Оның бұл күлкілі дербестік әрекетіне араласпаңыз!'),
  ('46ca17b0-646f-46ee-9f74-a67a0f778d4f', 'Ертегі кейіпкері 🪄', 'Бүгін кешке Ақылды ертегілерде басты кейіпкері өз балаңыз болатын ерекше оқиға құрастырыңыз: Түнді жақсы көретін батыл балақай.'),
  ('44efc816-fa09-4bf6-a073-38bbffbb2693', '«Сені жақсы көремін» деген құшақ 🫂', 'Кенеттен жаныңызға келіп, мойныңыздан құшақтай ма немесе бетіңізден сипай ма? Ол енді сүйіспеншілігін қимылымен білдіре бастады. Осы сәттен ләззат алыңыз.'),
  ('764398f1-2f82-4a41-a767-bcf8004dd068', 'Заттарды орнына қою 🧸', 'Ойыншықты қорапқа салып, қайтадан шығара ма? Оның ішінде және сыртында деген ұғымдар туралы түсінігі қалыптасып келеді. Бұл танымдық дағдыны Даму бақылаушысына міндетті түрде белгілеңіз.'),
  ('850a613f-ecbc-4d9b-ab63-9701c3f268f9', 'Сұрағыңыз бар ма? 🤖', '2 жастан кейін баланың сөйлеу қабілеті қандай болуы керек? Интернеттен іздеп әуре болмаңыз, бірден Anacan AI-ға жазып, ғылыми негізделген жауап алыңыз.'),
  ('4fcc8b4e-e106-490a-a901-8c89be671af5', 'Ұзақ сөйлемдер басталды! 🗣️', 'Енді 4-5 сөзді біріктіріп, күлкілі оқиға айтып жүр ме? Сөздік қоры қарқынды өсіп келеді! Осы алтын сәтті жіберіп алмаңыз: дереу даусын Бөпе альбомына аудиожазба ретінде сақтап, дамуын белгілеңіз.'),
  ('569d530d-d6b9-4460-be46-292c62f656dd', 'Логиканы іздеу 🧩', 'Ол қарапайым екі-үш бөліктен тұратын пазлдарды жаттап алды. Ақыл-ойын одан әрі шыңдап, себеп-салдар байланысын қалыптастыратын күрделі ағаш ойыншықтарды Ұсынылатын өнімдер бөлімінен табыңыз.'),
  ('ce1a09c7-d2c5-485b-a920-bc02df41fb58', 'Жуынатын бөлмедегі дауыл 🛁', 'Судан шыққысы келмей, жылай ма? Шомылу рәсімін күйзеліссіз аяқтауға көмектесетін назарын басқаға аударатын ойыншықтар мен тиімді ауысу тәсілдері туралы дереу Anacan AI-дан сұраңыз.'),
  ('32be8503-ee3d-483e-baae-9b3b130b80cc', 'Сырғанақтағы кезек дауы 🛑', 'Саябақта басқа балаларды күткісі келмей ме? 2.5 жасқа таяғанда кезек күту және бөлісу ұғымдарын қалай үйретуге болатынын Блогтар бөліміндегі әлеуметтену туралы мақалалардан міндетті түрде оқып біліңіз.'),
  ('bbf3c14f-5832-4554-88a9-fc0b10c25324', 'Парақтар жанданады 📖', 'Ертегі оқығанда оқиғаның соңын бөпеңіз өзі ойлап таба ма? Қиялы шарықтайтын осындай тамаша сәттерді қолдайтын интерактивті оқу әдістерін Anacan AI арқылы ашыңыз.'),
  ('c3d03381-340f-4ce1-b075-de3e6584aed7', 'Сұйықтық ішу және іш қату 💩', 'Көп жүгіріп, аз су іше ме? Жөргегін ауыстырғанда (немесе түбекке отырғанда) үлкен дәретін бақылаңыз. Іш қату қаупі болса, оны қолданбаға белгілеп, бірден Тамақтануды бақылау құралы арқылы мәзірге қара өрік немесе сұлы қосыңыз.'),
  ('275e7b7b-377b-40f0-9e43-ab5886fc93b4', 'Тамақпен ойнайды 🥦', 'Макаронды жеудің орнына езіп, айналаға шаша ма? Бұл жаста тағам да ойыншықтың бір түрі. Қаншалықты жақсы тамақтанғанын Тамақтану жоспарына белгілеп, апталық теңгерімді бақылаңыз.'),
  ('7af19435-be8e-48dc-a066-aab689899f04', 'Таңғы сәнқой 🧦', 'Бүгін таңертең шұлығын қолына кигісі келді ме? Қырсықтықпен қатар жүретін осындай жаңалық ашу сәттеріне ашуланбаңыз. Біраз уақыт солай жүре берсін — бұл оның дербестігін сынап көруі.'),
  ('f13502d3-76f4-47c6-bfef-ed2cb1d9fcf7', 'Судың сиқырлы күші 🛀', 'Күні бойы жүгіріп, бөпеңіз де, Сіз де шаршадыңыз. Жылы ванна — жай ғана тазалық емес, оның жүйке жүйесін тыныштандыратын ең жақсы ем.'),
  ('1b2a22e9-6d73-4469-8535-2d773936acd1', 'Саябақтағы өзімшілдік 🧸', 'Құмда ойнағанда ыдысын ешкімге бермей ме? 27 ай шамасында бөлісу түсінігі әлі толық қалыптаспайды. Оны өзімшіл деп айыптамаңыз, жай ғана кезекпен ойнау тәртібін түсіндіріңіз.'),
  ('57e50587-fc65-4605-a4e9-bbde134adfea', 'Әкенің дауыс ырғағы 📖', 'Бүгін кешке бөлмеде өзгеше көңіл күй қалыптастырайық. Кітап оқу немесе ертегі айту міндетін әкесінің қоңыр әрі сенім ұялататын дауысына тапсырып, Сіз бір шетте демалыңыз.'),
  ('64f0ac54-c21f-4a4c-bcce-53662284a4f5', 'Керемет есте сақтау қабілеті 🧠', 'Кеше жасырған ойыншықтың орнын бүгін таңертең дәл тапты ма? Оның ұзақ мерзімді есте сақтау қабілеті таңғаларлықтай жақсы қалыптасқан.'),
  ('99e86be1-9932-47a0-b9a8-f6b98dc7dfcf', 'Ұйықтауға қарсылық 🥱', 'Түскі ұйқыға жатқысы келмей, қарсылық таныта ма? Кейбір балалар осы жаста күндізгі ұйқыны қоя бастайды. Дауласудың орнына «Тыныштық сағатын» жариялап, төсекте бірге кітап парақтаңыздар.'),
  ('f80a3604-81aa-4362-9508-4aa4c845b4bc', 'Бөлме акустикасы 🤫', 'Ұйықтай салысымен, сәл тықыр естілсе селк ете қала ма? Дыбыс өлшегішпен бөлменің акустикасын тексеріп, терезеден келетін дыбыстарды басу үшін ақ шуды қосыңыз.'),
  ('25092d10-5861-4eec-8fa9-86857d835418', 'Кішкентай көмекші 🧹', 'Сіз киім жинап немесе еден сүртіп жатқанда, қолыңыздан алуға тырыса ма? Ол өзін ересек сезінеді. Оған кішкентай шүберек беріп, көмектесуіне мүмкіндік беріңіз.'),
  ('739e50cd-5199-4e7e-9448-99a52d59a069', 'Жастықтан жасалған қамал 🏰', 'Бүгін кешке бөлмені ойын алаңына айналдырыңыз. Диван жастықтарынан кішкентай қамал жасап, ішіне бірге кіріңіздер. Аздап шашылып қалуы мүмкін, бірақ мұндай шат күлкі соған әбден тұрарлық.'),
  ('a9e6d37d-aa66-4119-abcb-6619dfc78256', 'Зейін сынағы 🧩', 'Бір ойыншықпен ойнау уақыты 10-15 минутқа жетті ме? Зейінін шоғырландыру ұзақтығы артып келеді.'),
  ('1a9b02d2-5d73-4e72-a7df-f4672edf0835', 'Әкесімен бірге ұйқыға дайындалу 👨‍🍼', 'Бүгін кешке баланы ұйқыға дайындауды, тісін тазалатуды және пижамасын кигізуді әкесіне тапсырып, өзіңіз тыныштықта шай ішіңіз.'),
  ('6c74968c-8cc0-4bee-8ae3-eae708b5b244', 'Мәзір машақаты 🍲', 'Бүгін не пісіретініңізді білмей тұрсыз ба? Интернетті ақтармай-ақ, Қосымшаның Блогтар бөліміндегі балалар тағамы туралы мақалалардан жаңа әрі оңай рецептілерді табыңыз.'),
  ('855cedcf-292a-4a61-b049-6fd355b3a599', 'Себеп пен салдарды зерттеу 🤔', '«Мынаны лақтырсам не болады?», «Бұл батырма не үшін керек?» деп, үнемі тәжірибе жасап көреді. Үйдің қауіпсіздігін тағы бір рет тексеріп шығыңыз.'),
  ('1fe350a6-fb9b-4b57-8832-dec2f74e4b97', 'Жүгіру марафоны 🏃‍♂️', 'Жай жүру оған енді қызық емес, ол тек жүгіргісі келеді! Бөлменің ортасындағы ұсақ кедергілерді алып тастап, оның сарқылмас энергиясын күлімсіреп бақылаңыз.'),
  ('a661f7cf-1a9f-46de-b66d-252b9874aa1c', 'Қараңғыдағы ойындар 🐰', 'Ұйықтағысы келмей, қараңғыдан қорқа ма? Бөлмені толық қараңғылап, қабырғада қолдарыңызбен көлеңкелі театр жасаңыз. Қорқынышты қызықты ойынға айналдырыңыз.'),
  ('a8a8e76c-4244-41ff-a34c-127f03070b5f', 'Ананың офлайн уақыты ☕', 'Бала өз әлеміне еніп, қуыршақтарымен сөйлесіп отырғанда бірден ыдыс жуғышқа асықпаңыз. Өзіңізге бір шыны кофе құйып, телефоныңызды да 15 минутқа шетке қойып, толықтай офлайн болыңыз.'),
  ('41bea9aa-47ca-48e8-8cd4-15b1a0a181a6', 'Алғашқы ұзақ сөйлемдер 🗣️', 'Анашым, машина ана жаққа кетті! Енді ол сөздерді бір-бірімен байланыстырып, мағыналы сөйлемдер құрайды. Осы тарихи сәттерді мұқият тыңдап, міндетті түрде Даму бақылағышына естелік ретінде жазып қойыңыз.'),
  ('69b61ce4-2f0a-419f-8ea0-47c763ae7f20', 'Блогқа үңілетін уақыт 📱', 'Түбекке үйретуді бастайтын уақыт келді ме? Күмәндансаңыз, Anacan қолданбасындағы блогтар бөліміне кіріп, мамандар жазған және педиатрлар мақұлдаған мақалаларды оқыңыз.'),
  ('8ba7811e-fc92-4ddc-b1e8-28de83aa7843', 'Күнді талдау 📝', 'Бүгін қиын күн болды ма? Көңіл күй күнделігіне бүгінгі бар күйзелісті жазып, ішіңіздегіні ақтарыңыз. Барлық аналар осындай ауыр дағдарыстарды бастан өткереді, Сіз жалғыз емессіз.'),
  ('3932254a-4956-424d-86dc-117f82815e3f', 'Су ішуден бас тарту 💧', 'Судың орнына үнемі тәтті сусындар сұрай ма? Оның тәуліктік су қажеттілігін есептеп, суды түрлі түсті, қызықты стақандармен ұсыныңыз.'),
  ('7f344552-48d5-4a0e-95d3-b9aa7199f33a', 'Ойдан шығарылған хикаялар 🎭', 'Қолындағы ойыншық қонжығын сөйлетіп, оған ойдан шығарылған хикаялар айтып бере ме? Қиялы шарықтап тұр! Оны сырттай бақылап, еш араласпаңыз.'),
  ('3e22553e-b182-4faa-9fc2-459fc9a92590', 'Қырсығып жылау ұстамалары 🛑', 'Дүкенде немесе саябақта аяқ астынан басталатын қырсығып жылауы Сізді ұялта ма? Есіңізде болсын, айналадағылардың не ойлайтыны емес, балаңыздың сол сәттегі эмоциясы маңызды. Көзіне қарап, тыныштандырыңыз.'),
  ('e37f9999-21b9-4b48-be42-d9cbbc3d9c55', 'Секіруге талпыныстар 🤸‍♂️', 'Диваннан еденге немесе тұрған орнында жоғары секіруге талпына ма? Ірі моторика дағдылары жетіліп келеді! Оны жігерлендіріңіз.'),
  ('ebbeae36-6d1a-428b-bb72-2ef8bd324080', 'Күн тәртібін толық талдайық ⏱️', 'Кешке ұйықтауы 40 минутқа созылды ма? Ұйқы таймерінің кестесін қараңыз. Күндізгі ұйқыны қысқартып, кешкі ұйқы уақытын ертерекке жылжытатын кез келген шығар.'),
  ('1240eee6-bdc5-4609-ba23-b9d212dcb809', 'Табиғатты зерттеу ⛅', 'Төрт қабырғада отыру Сізді жалықтырды ма? Ауа райы мен киім құралын ашып, ауа райына сай киіндіріңіз де, оны бірден саябаққа алып шығыңыз. Жапырақтар мен тастарды зерттесін.'),
  ('1e908b82-2f19-4ebe-b79e-40246a88bab7', 'Тыныштықтан ләззат алыңыз 🤫', 'Ол ақыры ұйықтап қалды. Енді үйдегі ең кішкентай дыбыстың өзі жүйкеңізге тиеді. Құлаққапты тағып, ештеңе тыңдамай-ақ, тыныштықтың қадірін сезініңіз.'),
  ('488aec04-c9ee-4eb7-9fb1-11c9a4093d08', 'Түстерді тану 🎨', 'Қызыл допты сұрағанда, дәл қызыл түсті көрсете ме? Ол түстерді ажырата бастады. Дамуды бақылау бөліміне осы жаңа танымдық кезеңді енгізіңіз.'),
  ('3be3de73-5fca-4eff-b43e-5882d476d692', '«Тойдым» деген сылтау 🥣', 'Екі қасық жеп, тойғанын айтып қашып кете ме? Оны мәжбүрлемеңіз. Аз мөлшерде, бірақ жиі тамақ беріп көріңіз.'),
  ('9e9231eb-622b-4591-8fb2-b2c0bedcc252', 'Дене мүшелерін тану 👀', '«Иығың қайда?» деп сұрағанда, саусағымен түртіп көрсете ме? Танымдық қабілеті қарқынды дамып келеді! Ойынды күрделірек дене мүшелерімен жалғастырыңыз.'),
  ('eda9b33e-46f7-44ed-b1db-b9ad146b53a3', 'Ертегісіз ұйықтамаймыз 🪄', 'Классикалық ертегілер енді балаңыздың назарын аудармай ма? Ақылды ертегілерде басты кейіпкері балаңыздың өзі болатын ерекше ертегі құрастырыңыз.'),
  ('67860791-a8d9-49e2-af36-c3429ea56929', 'Ретсіздік те әдемі 🌪️', 'Күн сайын бір ойыншықтарды қорапқа жинаудан шаршадыңыз ба? Бүгін жинамай-ақ қойыңыз! Үйдің шашылып жатуы дүниенің соңы емес, Сіздің психологиялық жайлылығыңыз маңыздырақ.'),
  ('a0432486-9631-45f3-ac61-64c5dc937b54', 'Оңаша 10 минут 🛀', 'Бөлме іші тым-тырыс болып қалды. Жұбайыңыздан үйдегі барлық істі өз қолына алуын өтініңіз. Ал өзіңіз жылы душ қабылдап, 10 минутты тек өзіңізге арнаңыз.'),
  ('fc396394-677d-4b99-a945-20af7aec5056', 'Кальций тек сүтте емес 🧀', 'Сүт ішуден бас тарта ма? Сүйектер үшін кальций өте қажет. Тамақтануды бақылау құралы арқылы бүгін жеген ірімшік, йогурт немесе брокколи мөлшерін есептеп, жетіспейтін кальцийдің орнын толтырыңыз.'),
  ('40c67b1f-86cb-4258-ae34-ac9f630e9bcd', 'Қолдау клубы 💬', 'Қатты шаршадыңыз ба әрі Сізді ешкім түсінбейді деп ойлайсыз ба? Дереу Anacan қауымдастығына жазыңыз. Онда дәл Сіз сияқты ұйқысы қанбай жүрген мыңдаған ана қолдау көрсетеді.'),
  ('5fa2d1b1-040b-4c74-81f7-5aaa581e81fc', 'Қисынсыз қырсықтық 🛑', 'Бүгін таңертең суды көк емес, қызыл стақанға құйып бергеніңіз үшін айғай-шу шығарды ма? Бұл еркелік емес, ол жай ғана әлемді басқара алатынын тексеріп жүр. Сабыр сақтаңыз.'),
  ('6555b02b-e564-49b7-b5ae-a0b3594560b0', 'Дәрумендер қоры 🥗', 'Балаңызды тойдыру үшін бәрін жасайсыз. Ал өзіңіз ше? Пайдалы рецептілердің ішінен 10 минутта дайындалатын, темір мен кальцийге бай түскі асты таңдап, күш-қуатыңызды қалпына келтіріңіз.'),
  ('74e20827-e129-489b-a3ba-b3145efc42b3', 'Айна алдында 👀', 'Айна алдында тұрып, түрлі бет қимылын жасап, өз-өзіне күле ме? Бұл — өзін жеке тұлға ретінде тани бастағанының тамаша белгісі. Оны білдірмей бақылап, осы күлкілі сәттерден ләззат алыңыз.'),
  ('df6798e4-19ad-45ba-b5f8-d0bab8fc0951', 'Қиял-ғажайып ертегілер 📖', 'Кітап оқудан жалықтыңыз ба? Жарықты өшіріп, Ақ шу ішінен жаңбыр дыбысын қосыңыз да, қараңғыда бірге қиялдан ертегі құрастырып, ұйықтап қалыңыздар.'),
  ('ebf1eb36-04dc-42ad-9b92-cfc852cf267d', 'Жемісті жаңалықтар 🍏', 'Ақуызды тағамнан немесе көкөністен бас тарта ма? Тамақтануды бақылау құралы арқылы бүгінгі нормасын есептеп, Бөпеге арналған рецептілерден жемісті йогурт секілді дәмді үйлесімдер дайындаңыз.'),
  ('14a13bdc-ca07-4dfa-9231-806da316a5bd', 'Саусақпен санау 🔢', 'Баспалдақпен көтерілгенде немесе ойыншық көліктерді тізгенде бір, екі, үш деп айтуға тырыса ма? Математикалық ойлаудың негізі қаланып жатыр. Онымен бірге бәрін дауыстап санаңыз.'),
  ('8bf6a243-dbba-488e-976d-ab76ac22fdef', 'Терең тыныс 🧘‍♀️', 'Күні бойы сұрақтарға жауап беріп, тамағыңыз құрғап кетті. Бөлме тыныштала салысымен ешқандай экранға қарамай, жай ғана терең тыныс алып, демалыңыз.'),
  ('c86b2cf3-2c86-4802-abd7-eac1fbe8e326', 'Ыстық шай мен тыныштық 🍵', 'Таймер тоқтады, бала ұйықтады. Үй шаруасына асықпаңыз! Пайдалы рецептілерден мелисса немесе түймедақ шайын демдеп, диванға жайғасып, тыныштықтан ғана ләззат алыңыз.'),
  ('37bdad79-de07-4752-a75a-2761546b1523', 'Бөлісу қиын 🧸', 'Бауырына немесе саябақтағы балаға қаталдық таныта ма? Бөлісу әзірге ол үшін абстрактілі ұғым. Жазаламаңыз, оның сезімдерін түсінетініңізді көрсетіңіз.'),
  ('966fb5ae-0b22-47d8-b524-7d0d8e3e8e61', 'Қиялдағы шай дастарқаны 🍵', 'Сізді де қиялындағы ойындарға қосып, бос кеседен шай ішуіңізді сұрай ма? Оның қиялының бір бөлігі болыңыз. Мұндай ойындар оның әлеуметтік зердесін қалыптастырады.'),
  ('cab52685-d8da-4cce-a78e-b76068863ea1', 'Әкенің әңгімесі 📖', 'Бүгін кешке дауыс желбезегіңізді тынықтырыңыз. Баланың сүйікті кітаптарын әртүрлі дауыс ырғағымен қызықты етіп оқу міндетін әкесі атқарсын.'),
  ('dfbc5f7d-d4f2-4480-8272-664e257700f7', 'Пижама үшін күрес 👕', 'Кешкісін киіну үлкен шайқасқа айнала ма? Таңдауды бөпеңізге қалдырыңыз: «Ақ пижаманы қалайсың ба, әлде көгін бе?» Бұл әдіс көбіне көмектеседі.'),
  ('437d195c-2ce7-46eb-a38c-e5ab8476f991', 'Басқаның ойыншығы 🧸', 'Бөпеңіз үйге келген қонақтың баласына өз ойыншығын бермей ме? Бұл өзімшілдік емес, жеке шекарасын қорғау. Бөлісуді мәжбүрлеу арқылы емес, өз үлгіңізбен үйретіңіз.'),
  ('49a7a4ab-0bbe-4e7b-ab8f-16aac2b2f875', 'Сөздердің айтылуы 🗣️', 'Кейбір сөздерді толық айтпай ма немесе өте күлкілі етіп айта ма? Күлмеңіз, тек миы дұрыс нұсқасын есте сақтауы үшін сөзді дұрыс екпінмен қайталап айтыңыз.'),
  ('d03e0dcf-56bb-436b-bb3e-19d3231b91eb', 'Түнгі қорқыныш болуы мүмкін 😭', 'Түн ортасында көзін ашпай жылап, еш тынышталмай ма? Даусын бірден Жылауды талдау қызметіне тыңдатыңыз. Кейде бұл жай ғана іштің кебуі емес, түнгі қорқыныш болуы мүмкін.'),
  ('42301ed7-ed5e-4c5a-a79b-59b5256decae', 'Таңғы мазасыздық ☁️', 'Көзін аша салысымен бәріне жылап, ештеңеге көңілі толмай ма? Бәлкім, бөпеңіз дәл қазір қарқынды өсу кезеңін бастан өткеріп жатқан болар. Оны көбірек құшақтап, өзін қауіпсіз сезінуіне көмектесіңіз.'),
  ('4611486b-3235-40ef-8f07-a9ac44bd4de8', 'Ластануына рұқсат етіңіз 🏖️', 'Саябақта балшықпен немесе құммен ойнағысы келе ме? Ластануына рұқсат етіңіз! Сенсорлық дамуды қолдайтын мұндай ойындарға арналған ең жақсы Анаға қолайлы орындарды қолданбадан табыңыз.'),
  ('b8751eb5-8b11-4040-9350-f54539cfefa1', 'Командалық рух 🥂', 'Қиын күнді артта қалдырдыңыздар. Бөпеңіз ұйықтаған соң серігіңізбен бірге шай ішіп, «Біз мұның бәрін шынымен жақсы атқарып жүрміз» деп бір-біріңізді мақтаңыздар.'),
  ('dc029c20-8f5d-4aa9-a173-be7d3be13a69', 'Өзіңізді қалай сезініп жүрсіз? 🩸', 'Күш-қуатыңыз кенет азайды ма немесе көңіл күйіңіз құбылып жүр ме? Қолданбадағы Етеккір трекеріне көз жүгіртіңіз. Цикліңізді бақылап, ағзаңыздың қажеттіліктеріне түсіністікпен қараңыз.'),
  ('e1b2a066-88e9-4a4f-9df5-3af6a5d26b79', 'Күндізгі ұйқыдан бас тарту 🥱', 'Тағы да ұйықтамады ма? Онымен күресіп, бөпеңізді де, өзіңізді де шаршатпаңыз. Бөлмеде тыныш қана кітап парақтау да ми үшін демалыстың бір түрі.'),
  ('17487e3f-403d-4b65-ab45-c514d335d8cb', 'Сезімдерді білдіру 📝', 'Бүгін әбден шаршадыңыз ба, әлде ол өте сүйкімді сөз айтты ма? Қай жағдайда да Көңіл күй күнделігін ашып, осы сәтті болашаққа естелік ретінде жазып қойыңыз.'),
  ('343623a3-2f2a-4afd-99aa-b377f0610f4c', 'Тіс тазалау тартысы 🦷', 'Тіс щеткасын аузына жақындатқызбай ма? Мұны міндетке емес, ойынға айналдырыңыз. Алдымен оған Сіздің тісіңізді тазалауға рұқсат беріңіз, содан кейін кезек Сізге келсін.'),
  ('7022b1d9-81c4-428f-be96-d38885bd2971', 'Еркін ойын 🧸', 'Оның әр минутын көңілді өткізуге міндетті емессіз. Баланың ішінің пысуы — шығармашылықтың бастауы. Бөлмеде өз бетінше бірдеңе зерттеп, жаңалық ашуына мүмкіндік беріңіз.'),
  ('561010fd-17de-4698-b582-1c91bc73389a', 'Жай ғана құшақтаңыз 🫂', 'Ешқандай құралдың, кітаптың немесе ертегінің қажеті жоқ. Бүгін кешке оны жай ғана кеудеңізге қысып, иісін құшырлана жұтыңыз да, қараңғыда оған сүйіспеншілігіңізді сыбырлаңыз.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('927b3990-20b2-4f48-94c1-3ea0663bfcd4'::uuid, 'Нық айтылған «Жоқ» 🛑', 'Біреу оны сүйгісі келгенде, алыстап, «жоқ» дей ме? Оның жеке шекараларын құрметтеңіз және басқалардан да соны талап етіңіз. Өзіне деген сенім осыдан басталады.'),
  ('f73f1d7d-92d7-412b-a0e4-c0f949786729', 'Блогтарды қарап шығыңыз 📱', '2 жастағы баланың ашу ұстамаларымен күресе алмай жүрсіз бе? Anacan қолданбасындағы психологиялық блогтарды оқыңыз. Сондай сәтте баланың миында не болып жатқанын түсіну әрекет етуді жеңілдетеді.'),
  ('7281bfed-2cc1-421c-942f-77684085a8cf', 'Ақылды ертегі уақыты 🪄', 'Бүгін кешке Ақылды ертегілерде оған арнайы шытырман оқиға құрастырыңыз: қорықпайтын батыл қоянның хикаясы. Қорқыныштарын ертегілер арқылы жеңуге көмектесіңіз.'),
  ('380a71ea-f755-4ca8-a25d-c156eefcd118', 'Құлағанда жыламау 🧗‍♂️', 'Жеңіл құлап қалғанда бірден жыламай, Сіздің реакцияңызға қарап, содан кейін не істеу керегін шешеді ме? Абыржымаңыз, күлімсіреп: «Ештеңе болған жоқ, сен мықтысың», — деңіз.'),
  ('77a38e1b-ddf2-4519-806e-48198f93ac3a', 'Қараңғыдан қорқа ма?  🌙', 'Кереуетінің жанына жылы түсті шағын түнгі шам қойыңыз. Ал мелатонин бөлінуі үшін бөлменің қалған бөлігін толық қараңғы күйде ұстаңыз.'),
  ('b3b925ae-8f35-4c41-918e-ce24c80daa1b', 'Көгөністермен жауласу 🥦', 'Сорпадағы көгөністердің бәрін шетке жинай ма? Тамақтану жоспарынан оған ұнайтын басқа баламаларды іздеңіз. Көгөністерді котлеттің ішіне жасыру — аналардың ежелден келе жатқан айласы.'),
  ('16c277b4-79fe-460a-b9a5-72a7e8683280', 'Мінсіз ана болмайды 💬', 'Бәріне бір уақытта үлгере алмағаныңыз үшін өзіңізді кінәлі сезінесіз бе? Дереу Anacan қауымдастығына қосылыңыз. Ондағы аналардың шынайы сырлары Сізге күш береді.'),
  ('2e1e3e82-a2d5-4c25-a5ab-d3b0a7f4df86', 'Шимайлауға құмарлық 🖍️', 'Қаламды ұстау тәсілі өзгеріп, қағазға мақсатты түрде сызықтар сала бастайды. Ұсақ моториканың осындай керемет ілгерілеуін даму трекерінде міндетті түрде белгілеңіз.'),
  ('72b641f0-637f-48cd-8a37-fcd8fc3414bf', 'Кофемен қуаттану ☕', 'Күндізгі қарбалас Сізді әбден шаршатты. Оны 15 минутқа қауіпсіз бір іспен (мысалы, сурет бояумен) айналысуға қалдырып, өзіңіз міндетті түрде кофе ішіп, қуаттанып алыңыз.'),
  ('35817a20-39d6-4243-8610-08e856df9e52', 'Дәл лақтырулар ⚾', 'Сіз лақтырған үлкен допты қолымен қағып алуға, тіпті кері лақтыруға тырыса ма? Көз бен қол үйлесімі қарқынды дамып келеді. Дәлізде бірге доп ойнаңыз.'),
  ('801c2145-44f5-4f5c-b680-cdaa0cf58a86', 'Музыкалық ауысу 🛀', 'Кешкі күн тәртібін орындау қиындады ма? Жылы суға шомылып жатқанда, жайлы фон ретінде тыныштандыратын классикалық музыка қосыңыз. Су мен музыканың үйлесімі тіпті ең қырсық баланы да сабасына түсіреді.'),
  ('e96ff0af-1a62-4cbe-8543-0ed5c9498c20', 'Үйдегі аласапыран 🌪️', 'Күнде жинайтын бөлме 5 минуттан кейін қайта шашылып қала ма? Ештеңе етпейді! Үй мұражай емес, тіршілік қайнап жатқан орын. Шашылған заттарға емес, балаңыздың қуанышына көңіл бөліңіз.'),
  ('fa5b66d9-39b4-43f8-b655-5b6b176b299f', 'Қорқыныштың оянуы 👻', 'Бұрын қатты дауысты шаңсорғыштан мүлде қорықпайтын балаңыз енді артыңызға тығыла ма? Қиялы дамыған сайын негізсіз қорқыныштар пайда болуы мүмкін. Оны еркелетіп, өзін қауіпсіз сезінуіне көмектесіңіз.'),
  ('7b50e55a-c023-4d17-aacb-ffa1852fdee2', 'Ұйқы қысқанда 🥱', 'Ұйқысы келіп тұрса да, төсекке барғысы келмей ме? Бүгін кешкі әдетті сәл өзгертіп көріңіз. Кітап оқудың орнына төсекте жатып, оған бүгін болған жақсы оқиғаларды еске түсіріңіз.'),
  ('a4e24e0d-5f22-40d2-b64c-109e7cec356e', 'Тасыған энергия ⛅', 'Балаңыз үйде қабырғаға өрмелеп жүр ме? Оған бойындағы энергиясын шығару қажет. Ауа райы мен киім бөліміне кіріп, оны дұрыс киіндіріңіз де, саябаққа апарып, шаршағанша жүгіруіне мүмкіндік беріңіз.'),
  ('a628c2a6-552d-4e1a-a37b-9ed947ed297d', 'Даусыңызды айнытпай салады 🗣️', 'Ойыншықтарына дәл Сіздің дауыс ырғағыңызбен, Сіз қолданатын сөздермен ақыл айтып жүр ме? Ол — Сіздің ең жақсы айнаңыз. Өзіңізге сырт көзбен қарау қызық болады.'),
  ('a5f509e7-b242-4ca9-b7c5-aa083ba7699a', 'Бойы мен салмағы күрт өсті! 📏', 'Киіндіргенде жейделерінің тарылғанын немесе аяқкиімінің қысатынын байқадыңыз ба? Даму трекеріне қазіргі бойы мен өлшемдерін енгізіп, даму қисығының қалай жоғарылағанын мақтанышпен бақылаңыз.'),
  ('a9ef3c95-4b55-4dd2-abe5-e4a54e6509df', 'Ана шаршағанда 🛑', 'Сіз робот емессіз. Бүгін тамақ пісіруге күшіңіз болмаса, дайын асқа тапсырыс беріңіз. Мінсіз ана болу — бәрін жалғыз істеу деген сөз емес.'),
  ('ce9a0c9c-c1ca-4fbc-ad47-53a33a6c199f', 'Жеңіс үшін тост 🥂', 'Қиындық пен қырсыққа толы тағы бір күнді аман-есен аяқтадыңыз. Жұбайыңызбен бетпе-бет отырып, шай құйылған кеселеріңізді соғыстырыңыз. Сіздер осы үлкен жауапкершілікті ойдағыдай атқарып жүрсіздер.'),
  ('805c93f2-e2d3-43ec-9e6f-4782049680cd', 'Бөлменің қараңғылығы 🌙', 'Тезірек ұйықтап кетуі үшін бөлмедегі барлық қосымша жарықты, әсіресе планшет экрандарын өшіріңіз. Мелатонин тек қараңғы ортада бөлінеді.'),
  ('ba544f24-4325-4cce-9fad-539f5e144287', 'Тамаққа қырсығу 🥣', 'Екі қасық жеп, тойдым дей ме? Оны мәжбүрлемеңіз. Тамақпен дұрыс қарым-қатынас қалыптастыру күштеп тамақтандырудан маңыздырақ. Тамақтану санын көбейтіп, мөлшерін азайтыңыз.'),
  ('0b8f75a4-5ddd-4527-a07d-f3a8b79df578', 'Қол соғу қуанышы 👏', 'Бір нәрсені істей алғанда (мысалы, мұнара құрастырғанда) өзіне-өзі қол соғып, мақтана ма? Ол Сіздің мақұлдауыңызды күтеді! Сіз де оның осы кішкентай жетістігін зор қуанышпен қошеметтеңіз.'),
  ('2ac10424-b1ee-4b11-b087-e5d8e74e2722', 'Тыныштық сағаты ☕', 'Күндіз ұйықтамаса, кемінде 1 сағаттық Тыныштық сағатын (quiet time) белгілеңіз. Ол өз төсегінде кітап парақтасын, ал Сіз шайыңызды ішіп, телефоныңызды қарап отырыңыз.'),
  ('2eea19a8-6377-4aff-9f02-8b899ec1a730', 'Екеуіңізге арналған үзіліс 🥂', 'Бала ұйықтап қалды. Енді телефондар мен үй шаруасын бір шетке қойыңыз. Жұбайыңызбен кемінде 20 минут балаға қатысы жоқ кез келген тақырыпта сөйлесіңіз. Сіздер ата-ана ғана емес, жұп та екендеріңізді ұмытпаңыздар.'),
  ('2102feb2-22f3-4c41-8de6-6f3e115e2d56', 'Ертегінің соңы 🪄', 'Классикалық ертегілер жалықтыруы мүмкін. Ал зеректікті дамытатын ертегілерде бұл жолы оқиғаның соңын балаңызға таңдатыңыз. «Қонжыққа кім көмектесті деп ойлайсың?» деп, оның қиялына ерік беріңіз.'),
  ('8df55e5c-cbbb-49b9-bd1a-b655d228f1d5', 'Шекараны тексеру ⚠️', '«Бұлай істеме» дегеніңізге қарамастан, көзіңізге қарап тұрып сол әрекетті жасай ма? Оның мақсаты — Сізді ашуландыру емес, қойған шекараларыңыздың қаншалықты берік екенін тексеру. Ұстанымыңыздан таймаңыз.'),
  ('aa89536f-3d4b-4a1e-9088-0384b755894e', 'Суреттерге реакциясы 📖', 'Кітаптағы жануарларды немесе балаларды көргенде оларға қолын тигізіп, дыбыс шығара ма? Оның көру арқылы қабылдауы керемет дамып келеді. Даму трекерінде осы жайтты белгілеңіз.'),
  ('fb38f47e-3f88-41bf-87e7-fb7f9b1c8e65', 'Дағдарыс сәті 🛒', 'Дүкенде қалаған ойыншығын алып бермегеніңіз үшін айқайлап жатыр. Сырттай бақылап тұрған «мінсіз» ата-аналардың көзқарасына мән бермеңіз. Сабырмен көзіне қарап, түсіндіріңіз.'),
  ('3a862b3f-38a2-4cda-8a77-17c531d3e5f5', 'Үй шаруасы күте тұрсын 🛑', 'Еден жуылмады, киімдер жиналмады ма? Қоя тұрыңыз. Үйдің кірін тазалауға болады, ал психологиялық тұрғыдан әбден қажыған ананың қалпына келуі ұзаққа созылады. Диванға жатып, демалыңыз.'),
  ('52c32776-811a-4d66-a0c4-6b1c34cdfc69', 'Ұйқысыздықты қабылдаңыз 😭', 'Бөпеңіз түн ортасында оянып, қайта ұйықтағысы келмей ме? Оған ашуланбаңыз. Дауысын Жылауды талдау мүмкіндігіне тыңдатып, себебін (ауырсыну, іш кебу, қорқыныш) анықтаңыз да, оны сабырмен құшақтаңыз.'),
  ('bc7db5e2-0eb7-4adc-85cd-1181aac8b268', 'Жаңа достар іздеу 👫', 'Саябақта өзімен жасты балалармен бірге жүгіріп, оларға жақындауға тырыса ма? Әлеуметтену ресми түрде басталды! Қауіпсіздігін алыстан қадағалап, осы сәтті мақтанышпен тамашалаңыз.'),
  ('100554ba-e336-4148-9dd0-9a0ceeecb04b', 'Блогтардан үйреніңіз 📱', 'Балаңыздың бәріне «жоқ» дей беруі Сізді шаршатты ма? Бұл — 2 жас дағдарысының классикалық белгісі. Қолданбадағы психологиялық блогтарды оқып, оның миында не болып жатқанын түсініңіз.'),
  ('19cce24b-ae51-482e-8dc7-6812a220483b', 'Өзіңізді кінәламаңыз 📝', 'Бүгін шыдамыңыз таусылып, даусыңызды көтеріп қойдыңыз ба? Бала ұйықтағанда, сезімдеріңізді Көңіл күй күнделігіне жазып, өзіңізді кешіріңіз. Сіз жай ғана шаршадыңыз, Сіз де адамсыз.'),
  ('1bc0b4db-b3a8-4a70-bfa5-eaa18f5fe1f5', 'Баспалдақпен өз бетінше көтерілу 🧗‍♂️', 'Қолыңыздан ұстап баспалдақпен көтерілуге, тіпті өзі шығуға ұмтыла ма? Ол өз денесінің мүмкіндіктерін сынап жүр. Қауіпсіздігін қадағалай отырып, оған міндетті түрде осындай еркіндік беріңіз.'),
  ('380af2db-ede8-491b-ab1a-6f695da10f42', 'Ажырасудан қорқу 🥺', 'Сіз тіпті дәретханаға кіргенде де, есіктің артында күтіп, жылай ма? Ажырасу мазасыздығы кейде күшейеді. Әр жолы оған даусыңызды естіртіп, осында екеніңізді және қайтып келетініңізді айтыңыз.'),
  ('7cad0a21-48df-4f84-89c3-bca4ef4e2b8a', 'Суды аз ішеді деп ойлайсыз ба?💧', 'Оған түрлі түсті, пішіні ерекше стақандар алып беріп, су ішуді көңілді әдетке айналдырыңыз.'),
  ('d2d72f62-94bd-4b00-9bc2-090ee3d937fa', 'Сыбырлап әңгімелесу 🌙', 'Бөлменің жарығын толығымен өшіріңіз. Жанына жатып, күні бойы болған оқиғаларды оған өте бәсең дауыспен, сыбырлап айтып беріңіз. Сыбырлау — миды ұйқыға дайындаудың ең жақсы тәсілдерінің бірі.'),
  ('df67b2d6-67a7-45d0-8784-314cb9888630', 'Таңдау еркіндігі 👗', 'Киімін өзі таңдағысы келеді, бірақ түстері мүлде үйлеспей ме? Ештеңе етпейді. Ерік-жігерін басып тастамау үшін оған тек 2 нұсқа ұсыныңыз: мынаны ма, әлде ананы ма?'),
  ('308209fb-08e0-4807-8fb4-5bc201b75466', 'Әкесінің қызық дыбыстары 🤡', 'Бөпені күлдірудің ең жылдам жолы — әкесінің қызық дыбыстар шығарып, түрлі мимика жасауы. Бүгін кешке оның шат күлкісін тыңдап, Сіз де сырттай жымиып отырыңыз.'),
  ('591ee14c-695d-499c-8f9b-1192b3fd9c23', 'Ішіңіздегіні ақтаратын уақыт 💬', 'Бүгін ол бәріне жылады, ал Сіздің әбден күшіңіз таусылды. Дереу Anacan қауымдастығына кіріп, «Бүгін өте қиын болды» деп жазыңыз. Жүздеген әйелдің дәл осындай сәтті бастан өткеріп жатқанын көресіз.'),
  ('7b870bcd-23ba-4647-a5da-35a4bde7db6f', 'Құрастыру шебері 🧱', 'Үлкен LEGO бөлшектерін бір-біріне жалғап, бірдеңе құрастыруға тырысып жүр ме? Ол геометрияны зерттеп жатыр. Даму трекеріне оның осы шағын инженерлік талпыныстарын қосыңыз.'),
  ('3cc5c04e-9600-46b6-86d4-dfe7f6d1b82d', 'Сөздерді қайталау 🗣️', 'Сіз айтқан әрбір жаңа сөзді тотықұс сияқты бірден қайталай ма? Оның сөздік қоры молайып келеді. Оның жанында айтатын сөздеріңіз бен білдіретін эмоцияларыңызға ерекше мән беріңіз.'),
  ('b4771ddf-ae8c-44a0-b4dd-2f61938d3c93', 'Түнгі әуен 🛀', 'Күні бойы жүгіріп, ол да, Сіз де әбден шаршадыңыздар. Жылы ванна мен фонда ойнап тұрған баяу, нәзік әуен оның жүйке жүйесін толық тыныштандырады.'),
  ('0f4c51cd-27d9-4064-9aec-69b37d8e0a6f', 'Таңғы би 🎶', 'Көзін аша сала энергиясы тасып тұра ма? Таңғы қарбаласты басу үшін көңілді балалар әнін қосып, бөлмеде бірнеше минут билеңіздер де, күнді күлімдеп бастаңыздар.'),
  ('3f35178a-8193-420a-abc5-0ec312dd4ef0', 'Қажетті заттар тізімі 🛒', 'Жөргек, сусабын немесе жеміс езбесі таусылды ма? Есте сақтауға тырысып әуре болмаңыз: бәрін бірден Сатып алу тізіміне жазып, жұбыңызбен бір рет басу арқылы синхрондаңыз.'),
  ('4ec6bcf9-c49a-4e82-9a6f-0ae618212221', 'Мүлгіген тыныштық 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — ең сезімтал кезең. Дыбыс өлшегішпен бөлмедегі децибел деңгейін тексеріп, теледидардың дауысын бәсеңдетіңіз де, үйге орнаған мүлгіген тыныштықтың рақатын көріңіз.'),
  ('79665648-b787-4a1e-b120-da8384605658', 'Темірдің құпиясы: C дәрумені 🍋', 'Өңі бозарып немесе тәбеті төмендеп кетті ме? Тамақтануды бақылау құралынан бүгін қанша темір қабылдағанын тексеріңіз. Темірдің жақсы сіңуі үшін етпен бірге міндетті түрде лимон шырыны мол салат беріңіз.'),
  ('a55553fe-9a49-45fa-b5bb-ccf86cdd6fc8', 'Түнде ояну 🌌', 'Түн ортасында жылап оянып, тыныштала алмай ма? Түнгі қорқыныш пен жаман түстің айырмашылығын түсініп, дұрыс психологиялық қолдау көрсету үшін Блогтар бөлімін қарап шығыңыз.'),
  ('f582b213-b9d3-463a-9b65-bba1181ecabf', 'Шеңбер сызу өнері! 🎨', 'Қарындашпен қағазға (немесе қабырғаға!) тұйық шеңберлер салуға тырысып жүр ме? Бұл — ұсақ моториканың дамуындағы керемет серпіліс.'),
  ('41c18ba7-5f94-4cf4-bbb5-a65eaf5e3cf9', 'Көк шөптен жасалған детокс 🌿', 'Ішіңіз кеуіп тұрғандай сезінесіз бе? Етеккір трекерінен цикліңізді тексеріп, Әйелдерге арналған пайдалы рецептілердің ішінен жасыл смузи дайындаңыз: ол ағзаңызды тазартып, күш-қуатыңызды қалпына келтіруге көмектеседі.'),
  ('99409d74-b463-47c8-b5a8-30d9e195253d', 'Сұйықтық ішу және іш қату 💩', 'Көп жүгіріп, суды аз іше ме? Жөргегін ауыстырғанда (немесе түбекке отырғанда) үлкен дәретін бақылаңыз. Іш қату қаупі болса, ас мәзіріне сұлы қосыңыз.'),
  ('ee2ef852-cac1-4c22-a029-d59cd40dbe5f', 'Құбыжық аулау! 👾', 'Төсектің астынан құбыжық іздей ме? Қиялдан туындайтын қорқыныштар күшейе түседі. Ақ шу ішінен желдеткіш дыбысын қосып, бөлмеде қауіпсіз әрі бірқалыпты орта қалыптастырыңыз да, оны тыныштандырыңыз.'),
  ('3389c70e-b510-475b-87c1-4f01743277cd', 'Төсектен қашу жоспары 🛌', 'Бесігінен өрмелеп шығуға тырыса ма? Үлкен балаларға арналған төсекке ауысатын уақыт жақындап қалды. Бөлменің қауіпсіздігін еден деңгейінен қайта тексеріңіз.'),
  ('92afc025-d2fe-4c60-9ebd-9366e19b0175', 'Анаға арналған үзіліс ☕', 'Балаңыз өз бетінше ойнап отырғанда, бірден үй шаруасына кіріспеңіз. Бөлменің шашылғаны ешқайда кетпейді, ал Сіздің күш-қуатыңыз таусылуы мүмкін. Отырып, ыстық кофеңізді ішіңіз.'),
  ('c522fcae-04de-4086-b6e1-764904ead448', '«Неге?» кезеңінің шарықтау шегі 🤔', 'Ол неге сонда?, Мен неге ұйықтаймын?... Оның миы губка секілді бәрін сіңіреді! Таусылмайтын сұрақтарына қысқа, бірақ қисынды жауап беріңіз. Ол әлемді Сіздің сөзіңіз арқылы танып-біледі.'),
  ('3a442f56-c411-4f3c-a16a-32453afe5f33', 'Саябақтағы қарым-қатынас 🌳', 'Басқа балалармен бірге ойнағаннан гөрі, олардың жанында өз бетінше ойнай ма? Қатар ойнау бұл жас үшін мүлде қалыпты. Ауа райы мен киімін ескеріп, оны құрдастары болатын ортаға жиі апарыңыз.'),
  ('5d66b2e6-45ec-4c26-ae59-9d0d0eba4b4d', 'Қиялдағы достар 🧸', 'Ойыншық қонжығына ертегі айтып немесе бос кеседен шай ішіп жүр ме? Символдық ойындар — дамудың нағыз жауһары. Дамуды бақылау бөлімінде осы когнитивті серпілісті мақтанышпен белгілеңіз.'),
  ('d4544a8c-8615-4a88-b7e6-c7dc2d3b805a', 'Тыныштық қажеттілігі 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — ең сезімтал уақыт. Дыбыс өлшегішпен бөлмедегі децибел деңгейін тексеріп, көрші бөлмедегі теледидардың дыбысын соған сай реттеңіз.'),
  ('32813c49-da9b-4dca-8d61-b20de94b9fae', 'Бәрін меншіктеп алғысы келе ме? 🛑', 'Бөлісу ұғымы әлі қалыптаспаған. Оны мәжбүрлемеңіз, оның орнына «Кезекпен ойнайық» ережесін біртіндеп енгізіңіз.'),
  ('493d7552-4aa4-42f1-ab76-65529b782f6d', 'Кішкентай инженер 🏗️', 'Мұнаралар құрастырып, оларды бұзғанды ұната ма? Зердесі мен қимыл-қозғалыс дағдыларын одан әрі дамытатын магнитті немесе ағаш текшелерді дәл қазір Ұсынылатын өнімдер бөлімінен табыңыз.'),
  ('96969038-76a5-48c3-b60c-aafe8839c46c', 'Терең тыныс алыңыз 🌬️', 'Бүгін оның соңынан жүгіремін деп әбден шаршадыңыз ба? Көңіл күй күнделігін ашып, шаршағаныңызды жазыңыз. Мінсіз ана болуға тырыспаңыз, Сіздің сезімдеріңіз де маңызды!'),
  ('3cbc904d-0d48-46fa-a264-4d48559d6b46', 'Күніңіз қиын өтті ме?', 'Көңіл күй күнделігіне бүгінгі күйзелісіңіз туралы жазып, ішіңіздегіні шығарыңыз. Мұндай дағдарыстарды барлық ана бастан өткереді, Сіз жалғыз емессіз.'),
  ('aabf621d-766b-4fe7-b19d-2316986fdc64', 'Анаға арналған ас 🥑', 'Оны тойдыру үшін бәрін жасайсыз. Ал өзіңіз ше? Пайдалы рецептілер арасынан Сізге күш беретін, темірге бай түскі ас таңдап, асықпай отырып тамақтаныңыз.'),
  ('c60bf17d-5d16-4967-881d-d808bb5c5b6e', 'Екі сөзден тұратын сөйлемдер 🗣️', '«Анашым, кел», «Допты лақтыр» – оның сөздік қоры күннен-күнге молайып келеді. Толық айтпаған сөздерін дұрыс дыбыстап қайталау арқылы сөйлеу қабілетінің дамуына қолдау көрсетіңіз.'),
  ('274e44c7-f2f2-4e14-a2db-692e3ab50d92', 'Дүкендегі қырсықтық 🛒', 'Дүкенде қалағанын алып бермегеніңіз үшін жерге жата қалып, ашуланды ма? Айналадағылардың көзқарасына мән бермеңіз. Оның көз деңгейіне дейін еңкейіп, сезімдерін түсінетініңізді айтыңыз.'),
  ('7ffa24e8-d5c5-47fa-bd56-46791566e3ed', 'Теріс киілген киімдер 👗', 'Аяқкиімін ауыстырып, жейдесін теріс киіп алып, шешкісі келмей ме? Солай жүре берсін! Бұл – оның өз даралығын көрсетудің ең зиянсыз тәсілі.'),
  ('90cdd9aa-f5c9-402b-8ee4-af9073e319ae', 'Музыка сыйлаған тыныштық 🎶', 'Кешкі мазасыздықты басудың ең оңай жолы – оның сүйікті әуенін қосып, құшақтап, бірге баяу билеу.'),
  ('c19b60f5-cbba-4300-8903-9c5cb8625ba7', 'Өзіңізді мақтан тұтыңыз 🌟', 'Оның күн сайын меңгерген жаңа дағдысы мен әрбір сенімді қадамы — Сіз бен серіктесіңіздің еңбегінің нәтижесі.'),
  ('e47a41a7-8601-4ce3-8c27-0c69ab445dad', 'Тәуелсіздік декларациясы 📜', 'Бәрін «Өзім істеймін!» деп, ісіңізді баяулата ма? Бұл шек білмейтін қырсықтықты дамуға бағыттау жолдарын дәл қазір Anacan AI-дан сұраңыз.'),
  ('e4b29fb1-70d1-4a56-b112-96966513c6eb', 'Кітаптағы ұсақ бөлшектер 📖', 'Кітапты парақтап, суреттегі ең ұсақ бөлшектерді саусағымен көрсете ме? Оның көру жады тамаша жұмыс істеп тұр. Онымен суреттегілер туралы әңгімелесіңіз.'),
  ('14b9dba6-d0f2-4f3d-a4e8-f737b507b018', 'Шимайлау шебері 🖍️', 'Қолына қарындаш түсе қалса, қабырғаға немесе қағазға шимай салады. Түрлі түстермен жұмыс істегенде оның ұсақ моторикасы дамиды.'),
  ('48cc1013-ae1c-4b86-9e80-78bd05d5745a', 'Түнгі тыныштық 🛀', 'Жылы ванна, жеңіл массаж және қараңғы бөлме. Ұйқыға дайындалу тәртібін ешқашан бұзбаңыз, өйткені бұл оның миына ұйықтайтын ең қолайлы уақыт келгенін білдіреді.'),
  ('a8d24ffb-d035-4c11-983e-8c2c2a9ad274', 'Аналардың сырласуы 💬', '«Менің балам неге сонша қырсық?» деген ой Сізді қажыта ма? Anacan қауымдастығына қосылсаңыз, әр баланың әртүрлі дағдарыс кезеңдерінен өтетінін көресіз.'),
  ('5ae62f81-7331-472c-9b48-c967d0615a5b', 'Кештің қаһарманы: Әке 🦸‍♂️', 'Бүгін кешкі ұйқыға дайындауды Серіктес функциясы арқылы жұбайыңызға тапсырыңыз. Ертегіні ол оқысын, ал Сіз өзіңізге жылы ванна дайындап, күндізгі күйзелістен арылыңыз.'),
  ('88d95f7d-2e98-41b0-8554-4115adfb31c5', 'Тамақ талғау 🥦', 'Кеше тәбетімен жеген тағамынан бүгін бас тарта ма? Тамақтануды бақылау құралы арқылы мәзірді талдап, Бөпеге арналған рецепттерден тағамды ұсынудың ерекше әрі қызықты тәсілдерін табыңыз.'),
  ('b1d18fda-3875-4aca-b436-4ecb52ef49a6', 'Ауырсынусыз күндер 🩸', 'Етеккіріңіз жақындап, түйілу басталды ма? Дәріге жүгінбес бұрын, Әйелдерге арналған пайдалы рецепттер бөлімінен магнийге бай құрма мен жаңғақтан тіскебасар дайындап, өзіңізге қамқорлық жасаңыз.'),
  ('55fa43db-2800-421e-b0f2-748c40c7ef07', 'Киімдер кішірейіп барады! 📏', 'Көйлектерінің жеңі тағы да қысқарып қалды ма? 29-шы айға қарай болатын өсу қарқынын анық көру үшін Салмақ трекеріне қазіргі өлшемдерін енгізіп, жоғарылаған графикті қараңыз.'),
  ('8a1a47bc-2d1d-4804-abb1-5b5294f326db', 'Кітап кейіпкері 📖', 'Бір ертегіні 100-ші рет оқып беруіңізді сұрай ма? Бір қарағанда жалықтыратын осы қайталаудың зияткерлік дамуындағы таңғажайып рөлі туралы Блогтардан оқып, сабырыңызды қайта шыңдаңыз.'),
  ('c88c6893-fe11-4ce0-bf2d-ed7f94e0770d', 'Алғашқы логикалық болжамдар 🤔', '«Мұны істесем, былай болады» деген сияқты сөйлемдер құра ма? Осы керемет танымдық серпілісті жіберіп алмай, дыбысы бар видео ретінде Бөпе альбомына қосып, мақтанышпен сақтаңыз.'),
  ('3469bb77-d2d2-406c-8c90-287cb3502fb6', 'Командалық кеңес 🥂', 'Бала ұйықтағаннан кейін күндізгі күйзелісті басу үшін серігіңізбен бірге шай ішіп, «Біз тамаша командамыз» деп бір-біріңізге ризашылық білдіріңіз.'),
  ('69a15994-f6a2-4e74-92d0-633dfea33b45', 'Анаға жайлы орын іздеу ☕', 'Үйдегі бірдей қабырғаларға қарай беру Сізді қажытты ма? Аналарға жайлы орындардан балаларға арналған ойын бұрышы бар кафе табыңыз. Бөпеңіз ойнасын, ал Сіз кофеңізден ләззат алыңыз.'),
  ('71af31e1-67cd-4bc6-a54d-505d0d3ed0af', 'Жануарлардың дауыстары 🐶', 'Мысықты көргенде «мияу», ал итті көргенде «ау-ау» деуге тырыса ма? Жануарлардың дауысын қайталау сөздік қорды керемет дамытады. Онымен бірге осы ойынды ойнаңыз.'),
  ('1fe665ee-e68e-4e2a-b81e-f697b1100d0d', 'Жедел педиатр 🤖', '2.5 жасқа жақындағанда ас үлесінің мөлшері қандай болуы керек? Күмәндансаңыз, Anacan AI-дан бірден нақты әрі ғылыми негізделген кесте сұраңыз.'),
  ('8139ee6f-daa0-4072-ad02-2be67ee8488d', 'Ертегі кейіпкері 🪄', 'Бүгін кешке Ақылды ертегілерде басты кейіпкері өз балаңыз болатын ерекше хикая құрастырыңыз: Тісін тазалағанды жақсы көретін батыл бөпе.'),
  ('9d6f4449-54d1-4585-9f63-6d19afec1bda', '«Жақсы көремін» құшағы 🫂', 'Кенеттен жүгіріп келіп, мойныңыздан құшақтай ма немесе бетіңізді сипай ма? Ол енді сүйіспеншілігін жанасу арқылы білдіреді. Осы сәт сыйлаған теңдессіз тыныштықтан ләззат алыңыз.'),
  ('c32b736c-41b6-4e37-ad3d-7f15cea8084a', 'Ұйқыға қарсылық 🥱', 'Күндіз ұйықтағысы келмей, жылай ма? Күреспеңіз. Оның орнына бөлмеде тыныш отырып, кітап қарайтын 30 минуттық Тыныштық сағатын жариялаңыз.'),
  ('c762e9b7-a5b4-4810-a642-39d1f9c28936', 'Кезек ауысымы 👨‍👧', 'Күні бойы «Неге?» деген сұрақтарға жауап беріп, миыңыз шаршады. Бүгін кешке пижама кигізіп, ұйықтату міндетін серігіңізге тапсырыңыз да, өзіңіз демалыңыз.'),
  ('dc54ef63-6d88-4c2f-9c5d-c431db5caf8b', 'Ерекше сән 👗', 'Қыстың ортасында жазғы шолақ шалбарын, ал шалбарын басына кигісі келе ме? Талғамына араласпаңыз. Бұл күлкілі тәжірибелер оның даралығын танытуына көмектеседі.'),
  ('37bfacdd-d6ce-4a16-96d7-85b70834ca41', 'Табақтағы зерттеу 🥦', 'Кеше ұнатқан тамағын бүгін еденге лақтырып жатыр ма? Тамақтану жоспары құралына кіріп, мамандар 2.5 жасқа арнап дайындаған алуан түрлі әрі түрлі түсті мәзір идеяларын пайдаланыңыз.'),
  ('6b5d8f34-e3e9-4e8b-8382-9b0f64e3f018', 'Күтпеген қорқыныштар 👻', 'Бөлменің қараңғылығынан немесе қиялындағы көлеңкелерден қорқа бастады ма? Қиялы дамыған сайын негізсіз қорқыныштар пайда болады. Оған сенімділік сыйлап, жанында екеніңізді сездіріңіз.'),
  ('b459387d-d414-446b-ac06-391ffb5af36c', 'Таусылмайтын қуат 🔋', 'Сіз әлі көзіңізді ашып үлгермедіңіз, ал ол кілем үстінде жүгіру марафонын бастап кетті. Өзіңізге үлкен кесе кофе құйып алыңыз, бүгін өте белсенді күн болмақ.'),
  ('fc8def68-9f4f-421f-a543-941a3d40a533', 'Жаңа сөздер 🧠', 'Бүгін ересек адам сияқты өзгеше, күрделі сөйлем құрады ма? Дереу Даму трекерін ашып, осы когнитивтік серпілісті кейін оқып шығу үшін естелік ретінде жазып қойыңыз.'),
  ('115c548f-9326-4a38-a159-3195407d360e', 'Жұптарға арналған үзіліс 🥂', 'Бөпе ұйықтап қалды. Енді үй шаруасын қоя тұрыңыз. Жұбайыңызбен кемінде 20 минут бөпеден басқа кез келген тақырыпта әңгімелесіңіз. Сіздер ата-ана ғана емес, жұп екендеріңізді де ұмытпаңыздар.'),
  ('91f7fb7e-2bab-481e-816b-6e91267f93ae', 'Әдейі еңбектеу 🐢', 'Жүре алса да, кейде көңіл көтеру үшін жылдам еңбектеп, Сізден қаша ма? Бөлмедегі қауіпті кедергілерді алып тастап, осы қуаласпақ ойынына Сіз де қосылыңыз.'),
  ('ca59c65d-2643-4f9a-b7e1-efbf69908275', 'Анаға арналған офлайн уақыт ☕', 'Бөпе өз әлеміне еніп, ойнап отырғанда бірден ыдыс жуғышқа асықпаңыз. Өзіңізге ыстық шай құйып, телефонды шетке қойыңыз да, 15 минут бойы ештеңе ойламай, офлайн демалыңыз.'),
  ('53f1873b-90e8-4dcd-884c-7bbec73835df', 'Сыбырлап сырласу 🌙', 'Бөлменің жарығын толығымен өшіріңіз. Жанына жатып, күні бойы болған оқиғаларды өте баяу дауыспен, сыбырлап айтып беріңіз. Сыбырлау — миды ұйқыға дайындаудың ең тыныштандыратын тәсілі.'),
  ('67fb000b-9452-4ae5-aa28-3a36f345f54a', 'Ауырсынусыз күндер 🩸', 'Етеккіріңіз жақындап, түйілу басталды ма? Бірден дәріге жүгінбей, «Пайдалы рецепттер» бөлімінен магнийге бай құрма мен жаңғақтан тіскебасар дайындап, өзіңізге күтім жасаңыз.'),
  ('f0ddb044-981f-4758-9737-12aa24392d50', 'Саусақпен санау 🔢', 'Баспалдақпен көтерілгенде немесе ойыншықтарын реттегенде бір, екі, үш деп айтуға тырыса ма? Математикалық ойлау қабілеті оянып келеді. Онымен бірге бөлмедегі заттарды дауыстап санаңыз.'),
  ('841fa22f-136a-48a1-b594-4a69eafbc030', 'Қуатыңызды қалпына келтіріңіз 🍲', 'Күнделікті қарбалас Сізді әбден қажытты. Аяқүсті жүріп тіскебасар жей салмай, өзіңізге тойымды, кальцийге бай арнайы ас әзірлеп, рақаттана жеңіз.'),
  ('5b291f89-d920-4ebd-a4e6-3d982c3f7c31', 'Өнерпаздың ізімен 🖍️', 'Қағаз таусылып, енді қабырға мен есікке кезек келді ме? Бояу арқылы оның ұсақ моторикасы дамиды. Бөлмеге үлкен картон жайып, суретті тек осында салуға болатынын айтыңыз.'),
  ('a9576738-56a5-42cd-a95f-6e85e5fb1189', 'Қисынсыз қырсықтық 🛑', 'Суды көк емес, қызыл стақанға құйып бергеніңіз үшін үлкен жанжал шықты ма? Бұл еркелік емес, ол жай ғана Сіздің шекараңызды және айналасындағы дүниені басқара алатынын тексеріп жүр. Сабырлы болыңыз.'),
  ('e5ef4a95-198d-48b4-a37a-8ba378115031', 'Судың емдік күші 🛀', 'Күні бойы жүгіріп, бөпеңіз де, Сіз де әбден шаршадыңыздар. Жылы ванна — жай ғана тазалық емес, оның ширыққан жүйке жүйесін тыныштандыратын ең жақсы табиғи тәсіл.'),
  ('891847ab-5f43-4ba4-a99f-cf7faceb076c', 'Шашылған заттарға сабырмен қарау 🌪️', 'Күн сайын бір ойыншықтарды қайта-қайта жинаудан шаршадыңыз ба? Бүгін жинамай-ақ қойыңыз! Үйдің шашылып жатуы — дүниенің соңы емес, Сіздің жан тыныштығыңыз бәрінен маңызды.'),
  ('9de03e77-6cb6-4585-9646-e7347bac18d6', 'Өзіңізді кінәлауды доғарыңыз 💬', 'Бүгін экран алдында ұзақ отырғаны үшін өзіңізді кінәлап жүрсіз бе? Anacan қауымдастығына кіріп, басқа аналардың да кейде дәл осылай сезінетінін оқып, көңіліңізді жұбатыңыз. Сіз жалғыз емессіз.'),
  ('f7d0d8f9-fd4d-4b19-b40e-907cdb2d4aea', 'Айнадағы тұлға 👀', 'Айна алдында түрлі бет қимылын жасап, өзімен-өзі сөйлесіп, күле ме? Бұл оның өзін-өзі тануы жақсы дамып келе жатқанын көрсетеді. Оны білдіртпей бақылап, осы күлкілі сәттерді мақтанышпен тамашалаңыз.'),
  ('765fd3c5-2a1b-4659-aa42-b76314ae48dc', 'Саябақтағы өзімшілдік 🧸', 'Құмда ойнап отырып, шелегін ешкімге бермей ме? Бұл өзімшілдік емес, өз шекарасын қорғау. Оны мәжбүрлемеңіз, оның орнына «Кезектесіп ойнайық» деген ережені жұмсақ тілмен үйретіңіз.'),
  ('8329858a-b5aa-4e88-a094-94baf4b4dff4', 'Қиялдағы ойындар 🧸', 'Ойыншық қонжығына немесе қуыршағына су ішкізіп, олармен сөйлесуге тырыса ма? Символдық ойындар — бала дамуының нағыз жауһары. Осы кішкентай сүйкімді режиссерді сырттай қызыға бақылаңыз.'),
  ('98be6947-c839-4cba-807a-2d0a7d2db4bd', 'Әкенің күлкілі түрі 🤡', 'Бөпені күлдірудің ең жылдам жолы — әкесінің оғаш дыбыстар шығарып, түрлі мимика жасауы. Бүгін кешкі шат күлкіні тыңдап, Сіз де сырттай жымиып отырыңыз.'),
  ('9c1b9283-eb25-42f4-8927-c54192637c35', 'Ананың таңғы энергиясы ⚡', 'Таңертең шаршап ояндыңыз ба? Тәттіге асықпаңыз. Пайдалы рецепттер арасынан 5 минутта дайындалатын ақуыз бен жеміс қосылған сұлы ботқасын тауып, күніңізді сергек бастаңыз.'),
  ('1868bb46-a550-4249-8524-2b40ecd9cad3', 'Әкенің қолдауы қажет 🫂', 'Етеккір трекерінде ПМС күндері басталып, өзіңізді сезімтал сезініп жүрсіз бе? Серіктес функциясы арқылы оған бүгін көбірек қолдау қажет екенін білдіріңіз.'),
  ('5efae0dc-5ddd-4ac1-9526-ddfa449ec612', 'Жастықтан жасалған қамал 🏰', 'Бүгін кешке бөлмені ойын алаңына айналдырыңыз. Диван жастықтарынан шағын қамал тұрғызып, ішіне кіріңіздер. Аздап шашылуы мүмкін, бірақ көңілді күлкіге әбден тұрарлық.'),
  ('e40e4ab0-cd42-4ed7-b968-edc0adab6461', 'Адвокаттай саудаласу 🗣️', '«Тағы біраз ойнайын, сосын киінемін» деп жүр ме? Ол Сізбен кәсіби келіссөз жүргізуге тырысып жүр. Сөйлеу қабілетінің дамуы керемет, бірақ шекараңызды сүйіспеншілікпен сақтауды ұмытпаңыз.'),
  ('f9854a88-373e-4d4d-91e8-4e24a9ea9cba', 'Табиғатты зерттеу 🌳', 'Төрт қабырғада отыру жалықтырды ма? Күн салқын болса да, оны жылы киіндіріп, саябаққа 20 минутқа шығыңыз. Жапырақтар мен тастарды зерттесін, таза ауа екеуіңізге де пайдалы болады.'),
  ('fb90f3c3-fde8-496d-b59b-6ba1236abd46', '«Таптым сені!» қуанышы 🙈', 'Жасырынбақ енді ең сүйікті ойынға айналды. Ол перденің артына жасырынып, Сіздің тауып алуыңызды күтеді. Бұл ойынды күнделікті әдеттеріңіздің ең көңілді бөлігіне айналдырыңыз.'),
  ('fce8d709-58cb-464d-bc50-7c2b9036555e', 'Қараңғылыққа үйрену 🌙', 'Тезірек ұйықтауы үшін бөлмедегі барлық экранды өшіріңіз. Теледидардың көк жарығы ұйқы гормонының бөлінуін баяулатады.'),
  ('1dc3a9e4-8c1a-46c9-b53c-b30058a99bb3', 'Батыл қадамдар 🧗‍♂️', 'Диванға немесе креслоға жармасып, жоғары өрмелеуге тырыса ма? Бұл оның тепе-теңдігі мен бұлшықет күші артып келе жатқанын білдіреді. Оны қауіптен қорғаңыз, бірақ кішкентай альпинистіңіздің мұндай талпыныстарына еш кедергі жасамаңыз.'),
  ('a7098097-ad7b-4ef2-ac70-151dc53814b4', 'Тамақтан бас тарту 🥣', 'Екі қасық жегеннен кейін тойдым дегендей қашып кете ме? Оны қинамаңыз. Баланың тамақпен дұрыс қарым-қатынасын қалыптастыру күштеп тамақтандырудан әлдеқайда маңызды.'),
  ('f8b30c93-8e49-4cb9-8db0-9b3082221d0d', 'Күнді қорытындылау 📝', 'Бүгін қатты шаршадыңыз ба, әлде ол өте сүйкімді бір сөз айтты ма? Қалай болғанда да, Көңіл күй күнделігін ашып, осы сәтті болашаққа естелік ретінде жазып қойыңыз әрі ішіңіздегіні ақтарып, жеңілдеп қалыңыз.'),
  ('18e35d56-8285-420a-adac-121643743cd2', 'Зейін сынағы 🧩', 'Бір ойыншықпен, мысалы, пазлмен ойнау ұзақтығы 10-15 минутқа жетті ме? Бұл оның зейінін ұзақ уақыт шоғырландыра алатынын білдіреді. Бөлменің бір шетінде үнсіз тұрып, оны бақылаңыз.'),
  ('87548d0a-d1fb-4a91-8d0e-f51d5f31d60e', 'Себеп пен салдарды іздеу 🤔', '«Мынаны лақтырсам, не болады?», «Бұл түйме не үшін керек?» Ол айналасындағы заттарды үнемі іс жүзінде сынап көреді. Үйдің қауіпсіздігін еден деңгейінен қарап, тағы бір рет тексеріп шығыңыз.'),
  ('f1a78ec7-6b62-43e2-8747-e4f8c033a5e7', 'Ертегісіз ұйықтамаймыз 🪄', 'Классикалық ертегілер енді оның назарын аудармай ма? Басты кейіпкері өзі болатын, табиғат дыбыстарымен сүйемелденген ерекше хикая ойлап тауып, оның қиял әлеміне еніңіз.'),
  ('becd06f2-3767-4d60-98af-e6ee50a40e21', 'Музыкаға билеу 🎶', 'Көңілді музыка ойнағанда бірден ырғаққа сай қимылдай ма? Есту қабілеті мен қимыл-қозғалысының үйлесімі тамаша қалыптасып келеді! Көңілді ән қосып, онымен бірге бөлмеде билеңіз.'),
  ('befcea5e-21fe-4c91-b025-35c7c94f17a1', 'Әкенің хикаясы 📖', 'Бүгін кешке дауысыңызды тынықтырыңыз. Баланың сүйікті кітаптарын әртүрлі дауыс ырғағымен қызықты етіп оқуды әкесіне тапсырыңыз.'),
  ('d245b047-0d4a-45c3-956c-817469ecd147', '«Неге?» аяқталып, «Қалай?» басталды 🤔', 'Қиялы мен логикасы жаңа деңгейге көтерілді! Енді бөпеңіз заттардың қалай жұмыс істейтінін де сұрайды. Anacan AI сарапшысынан мұндай сұрақтарға жасына сай әрі қызықты жауап беру тәсілдерін үйреніңіз.'),
  ('0d9edca6-9e16-4f20-b482-5f21d8925331', 'Ұйқысыздыққа көндігуге тура келеді 😭', 'Бөпеңіз түн ортасында оянып, қайта ұйықтағысы келмей ме? Оған ашуланбаңыз. Себебін (ауырсыну, ішінің кебуі, қорқыныш) анықтап, сабырмен құшақтап, өзін қауіпсіз сезінуіне көмектесіңіз.'),
  ('6fbdbe3b-91f8-4e0a-9823-628cb1856a3a', 'Кетпейтін дақтар 👗', 'Киімнің үнемі былғануы Сізді шаршатты ма? Бұған ашуланбаңыз. Бөпеңіз тағамдарды зерттеп жүр. Силикон алжапқыштарды пайдаланып, осы түрлі-түсті, былғаныш сәттерден ләззат алыңыз.'),
  ('9f08baf7-46d6-4ac6-b651-94901e800f6b', 'Сізге көмектесейін! 🧹', 'Сіз еден сүртіп немесе шаң тазалап жатқанда, қолыңыздағыны алуға тырыса ма? Ол өзін әлдеқашан ересек сезінеді. Оған кішкентай шүберек беріп, командаңызға қосылуына мүмкіндік беріңіз.'),
  ('40197a85-31e6-4141-9d38-df9b89843274', 'Денеңізді тыңдаңыз 🩸', 'Кенеттен тәттіге құмартып немесе шаршап жүрсіз бе? Етеккір бақылағышындағы күнтізбеге қараңыз. Егер етеккіріңіз жақындап қалса, Пайдалы рецептілерден магнийге бай тіскебасар таңдаңыз.'),
  ('4ca62724-362e-47af-b9dc-e138d57c7cbd', 'Бөлмедегі көлеңкелер 🌌', 'Бөпеңіз қараңғылықтан және қиялындағы құбыжықтардан қорқа ма? Бөлмені тас қараңғы етпеңіз және Ақ шулардан ана құрсағындағы дыбысты қосып, оған бұрыннан таныс мінсіз қауіпсіздік сезімін сыйлаңыз.'),
  ('f8e208a6-e2c2-4a88-b04c-adaeb10974b8', 'Ажырасу мазасыздығы 🥺', 'Сіз бөлмеден шыққанда, тіпті дәретханаға барғанда да артыңыздан жылай ма? Ол Сізді қайтып келмейді деп ойлайды. «Мен әрдайым осындамын, дауысымды естіп тұрсың ба?» деп, оны тыныштандырыңыз.'),
  ('216f95a1-f03e-48c4-8e9d-615f08aa0853', 'Сөзшең бөпеңіз 🗣️', 'Бөпеңіз 4-5 сөзді біріктіріп, күлкілі оқиғалар айтып жүр ме? Сөздік қоры қарқынды дамып келеді! Осы алтын сәтті жіберіп алмаңыз.'),
  ('41e28dbe-e3fb-4744-b4f1-9927a3802b24', 'Дыбыстарды сүзгіден өткізіңіз 🤫', 'Ұйықтап бара жатқанда сезімталдығы артады. Терезеден естілетін дыбыстарды бәсеңдету үшін бөлмеде ақырын ақ шу (white noise) құрылғысын немесе музыка қосыңыз.'),
  ('745737c8-7329-40d3-90c9-336ff2e4a2ae', 'Асүйде бірге 🧑‍🍳', 'Сізбен бірге асүйде бірдеңе істегісі келе ме? Ұн немесе су құйғанда көмектесуіне мүмкіндік беріңіз. Айналаның бәрі былғанса да, оның қуанышы мен үйренуге деген ынтасы соған тұрарлық.'),
  ('1938c0bd-ea98-478e-8da7-ef024a27ce71', 'Тізім жай керек емес, аса қажет 🛒', 'Ұйқының қанбауы есте сақтау қабілетіңізді әлсіретіп, дүкеннен алатын заттарды ұмытып жүрсіз бе? Миыңызды шаршатпаңыз. Бәрін қолданбадағы Сатып алу тізіміне жазыңыз.'),
  ('30a1934e-958b-40a0-9b32-c4894a70a798', 'Жай ғана құшақтаңыз 🫂', 'Ешқандай ойын да, кітап та қажет емес. Бүгін кешке оны жай ғана кеудеңізге қысып, иісін терең жұтыңыз да, қараңғыда оның Сіз үшін қаншалықты қымбат екенін сыбырлап айтыңыз.'),
  ('e00d8cce-8b3a-4ac6-ad35-5a22b01bd325', 'Конструктор шебері 🧱', 'Үлкен лего бөлшектерін бір-біріне қосып, әлдене құрастыруға тырысып жүр ме? Ол кеңістік пен геометрияны зерттеп жатыр. Даму трекерінде оның осы ерекше инженерлік талпынысын белгілеңіз.'),
  ('1a4b3925-7885-40fb-a56f-488e3358cee1', 'Жалғыз өзіңізге 10 минут 🛀', 'Бөлме тыныштала қалды. Жұбайыңыздан үйдегі барлық шаруаны өз қолына алуын өтініңіз. Ал өзіңіз жылы душ қабылдап, біраз уақытты оңаша өткізіңіз.'),
  ('505c8d78-0b81-4cb5-96f5-e5571e1fc049', '2 жас дағдарысы 📱', 'Балаңыздың бәріне «жоқ» дей беруі Сізді шаршатты ма? Блогтар бөліміндегі мақалаларды оқып, оның миында жүріп жатқан осы даму дауылының себептерін түсініңіз.'),
  ('5e96bc6a-ca0b-4e3c-9cde-441c31566ab3', 'Көкөністі жасыру операциясы 🥦', 'Көк шөпті немесе брокколиді тәрелкеден алып тастай ма? Бөпеге арналған рецепттерден көкөніс қосылған түрлі түсті үй кексін тауып, Тамақтануды бақылау құралында витамин нормасының орындалғанын оңай белгілеңіз.'),
  ('91db0bda-d980-4153-bb7d-0ed55ffcd626', 'Терең тыныс алыңыз 🧘‍♀️', 'Күні бойы сұрақтарға жауап беріп, тамағыңыз кеуіп кетті. Бөлме тыныштала қалғанда, ешқандай экранға қарамай, жай ғана терең тыныс алып, демалыңыз.'),
  ('de182c61-510f-445a-9f50-8ed2459f90cf', 'Сөздерді айту 🗣️', 'Кейбір сөздерді толық айтпай ма немесе тым күлкілі етіп айта ма? Күлмеңіз, оның миы дұрыс нұсқасын есте сақтауы үшін сөзді дұрыс екпінмен қайталап айтыңыз.'),
  ('f4bf03e5-dc33-4bfa-a875-42962b014227', 'Еркін ойын 🧸', 'Оның әр минутын көңілді етуге міндетті емессіз. Баланың ішінің пысуы — шығармашылықтың бастауы. Бөлмеде өз бетінше бір нәрсе зерттеп, жаңалық ашуына мүмкіндік беріңіз.'),
  ('3ead07a7-4417-4744-9277-6bedf5fa245b', 'Уақытты тоқтатар сәт 📸', 'Балаңыз ұйықтап жатқанда, оның бейкүнә жүзіне қараңыз. Күні бойы Сізді әбден шаршатса да, ұйықтап қалған сәтте оны сағынасыз, солай емес пе? Ана болудың парадоксы да осында.'),
  ('5f09ad8f-0fde-4f65-8032-dfe56e435a81', 'Су ішу әдеті 💧', 'Судың орнына үнемі тәтті шырын сұрай ма? Тамақтану жоспарындағы сұйықтық ішу тәртібін тексеріңіз. Суды түрлі түсті, арнайы түтікшесі бар стақандармен ұсынып, қызығушылығын оятыңыз.'),
  ('e8fd5bc0-a904-4768-8c61-d9259b243761', 'Қол соғайық 👏', 'Бір нәрсені істей алғанда, өзіне-өзі қол соғып, қуанышын білдіре ме? Осындай керемет сәтті көргенде, үйде кішкентай жеңіс биін билеп, оның қуанышына ортақтасыңыз!'),
  ('2a429f3f-0b1b-49c6-befd-28bf5cd2cf98', 'Ана шаршағанда 🛑', 'Сіз робот емессіз. Егер бүгін тамақ пісіруге күшіңіз болмаса, дайын асқа тапсырыс беріңіз. Мінсіз ана болу — бәрін жалғыз істеу деген сөз емес.'),
  ('5c059ccd-12dd-4a31-9da6-6e33ef79b1be', 'Нық «жоқ» 🛑', 'Біреу оны сүйгісі келгенде, алыстап, нық түрде «жоқ» дей ме? Оның жеке шекараларын құрметтеңіз. Рұқсатсыз қол тигізуге қарсылық білдіруі өте маңызды.'),
  ('127ac6bb-4f6e-424f-91fb-e2d406c68c2a', 'Төрт қабырғадан тыс ☕', 'Үйдегі күнделікті тірлік Сізді жалықтыра бастады. Бүгін бір өзгеріс жасаңыз. Жақын маңдағы тыныш дәмханаға барып, бөпеңізге жаңа орта көрсетіп, өзіңіз де кофеңізден ләззат алыңыз.'),
  ('1e376436-3f0d-4a14-a96b-e1c16c40c937', 'Ұйқының сезімталдығы 🤫', 'Ұйықтай салысымен болмашы дыбыстан селк ете ме? Бөлменің акустикасын тексеріп, терезеден келетін дыбыстарды бәсеңдету үшін ақ шуды қосыңыз.'),
  ('e0d7037f-df25-46a9-8fd2-5b2b39c1432d', 'Жиһазға өрмелеу 🧗‍♂️', 'Диваннан немесе орындықтан ұстап, жоғары өрмелеуге тырыса ма? Аяқ бұлшықеттері әртүрлі биіктіктерді игеріп жатыр. Қауіпсіздігін қадағалаңыз, бірақ кішкентай альпинистің бұл талпыныстарына кедергі жасамаңыз.'),
  ('458c2efd-1859-4a36-bc6c-218987ce42a4', 'Тәрелкедегі өнер туындысы 🥦', 'Тамағын жемей ме? Кейде мәселе дәмінде емес, сыртқы көрінісінде болады. Түрлі түсті көкөністерден күлкілі бет-бейнелер жасап, тәбетін ашуға тырысыңыз.'),
  ('6007d88c-cdbb-46d0-9b99-4e7bdd857418', 'Түнгі бесік жыры 🎶', 'Ешбір қолданба немесе дыбыс ана әлдиін алмастыра алмайды. Бүгін кешке оны бауырыңызға басып, ең жақсы көретін әрі өзін қауіпсіз сезіндіретін бесік жырын жай дауыспен айтып беріңіз.'),
  ('ade78fe2-3290-467b-9d4f-4aa0e7d81802', 'Түбектегі алғашқы жеңіс! 🚽', 'Түбекке өзі отырғысы келе ме? Бұл — 2.5 жастағы ең үлкен жеңістердің бірі! Жөргек/Түбек трекерінде осы жетістікті белгілеп, Блогтардан бұл кезеңге өтуді қалай жеңілдетуге болатынын оқыңыз.'),
  ('ca5c9545-5eb9-432c-acea-7e6fe2c5ab98', 'Тыныштық пен кофе 🤫', 'Ол ұйықтап қалды! Енді ыдыс жуғыш машинаны босатудың орнына, қараңғы бөлмеде отыра тұрыңыз. 15 минуттық тыныштықтың қадірін сезініп, демалыңыз.'),
  ('cc9ba302-22d8-43e5-a70d-2bed916f8d33', 'Төменге қараңыз! 👣', 'Ол аяқ саусақтарын ұстап, зерттей бастады ма, тіпті жалаңаяқ жүргенді ұната ма? Табанындағы жүйке ұштарын сезіну тепе-теңдікті дамыту үшін өте маңызды.'),
  ('0bcb845e-25a8-4c8a-b05c-67b7a3788c4a', 'Ауа райының тосынсыйы ⛅', 'Серуенге шыққанда ауа райына алданып, оны тоңдырып алмаңыз. Терезеден қарап қана шешім қабылдамай, сырттағы желдің жылдамдығы мен сезілетін температураны алдын ала тексеріңіз.'),
  ('1566736d-5f6a-420b-9aaa-9e37909efa16', 'Өз «Менін» танып жүр 👑', '«Менмін!», «Менікі!» деген сөздер аузынан түспей жүр. Бұл — эгоцентризм кезеңінің ең айқын шағы. Оның даралығын құрметпен қабылдаңыз, бұл — қалыпты даму кезеңі.'),
  ('7aba0d06-67c9-4fba-811b-47eacf1ff2d7', 'Әкенің жауапкершілігі 👨‍🍼', 'Күндізгі шаршаудың өзі Сізге жеткілікті. Кешке баланы ұйқыға дайындап, пижамасын кигізуді әкесіне тапсырыңыз да, өзіңіз сырттай бақылаңыз.'),
  ('2876fc5f-fac3-4af5-b718-9c2f0d9b5314', 'Қуат қорын толықтырыңыз 🍲', 'Шаршау сүйегіңізге дейін өтті ме? 10 минутта дайын болатын, әрі тойымды, әрі сергітетін ерекше салат әзірлеп, өзіңізді қуантыңыз.'),
  ('2b82cde7-2302-4ad2-96b7-ca1beedb8f4f', 'Тіс щеткасы үшін тартыс аяқталады 🪥', 'Тіс щеткасын көрген бойда аузын ашпай қоя ма? Бұл үдерісті жеңілдететін әуенді немесе айналмалы балалар щеткаларын Ұсынылатын өнімдер бөлімінен іздеп, тазалықты көңілді ойынға айналдырыңыз.'),
  ('c3b0f127-530e-4b11-9687-7c0bcb24de5f', 'Түнгі дауыл 😭', 'Түн ортасында еш себепсіз жылап оянды ма? Іші кебіп тұр ма, әлде бұл түнгі қорқыныш па? Оны жайлап құшақтап, дауысыңызды көтермей тыныштандырыңыз.'),
  ('79a825c4-e46e-4e7d-81f2-4387a7318ef2', 'Сыр бөлісу 💬', 'Қатты шаршадыңыз ба? Anacan қауымдастығына қосылыңыз. Мыңдаған ананың шынайы оқиғаларын оқып, жалғыз емес екеніңізді сезініп, күш жинаңыз.'),
  ('0048f15c-3ab2-4568-b3e6-cf763bd916d3', 'Көкөністерді жасырыңыз 🥦', 'Сорпадағы барлық көкөністі шетке ысырып қоя ма? Онымен күреспеңіз. Көкөністерді езбе жасап, тұздыққа немесе котлетке жасырып қосу — аналардың ежелден келе жатқан айласы.'),
  ('4d0d3015-35d0-4444-b757-3789d14e8ec4', 'Суреттерге реакциясы 📖', 'Кітаптағы жануарларды немесе әртүрлі заттарды көргенде оларға қолын тигізіп, дыбыс шығара ма? Оның көру арқылы қабылдауы таңғаларлық. Онымен кітаптағы кейіпкерлер туралы сөйлесіңіз.'),
  ('cfe51929-b2af-45a2-b23e-e670a8d3ebd8', 'Ұйқымен қуаласпақ 🏃‍♂️', 'Төсекке жатпау үшін қайта-қайта сылтау ойлап таба ма? Ұйқы таймерін қосып, белгіленген шекарадан таймаңыз және Ақ шудан жаңбыр дыбысын қосып, бөлмені тыныштандырыңыз.'),
  ('0727c4e7-7433-410a-9da5-27fff69d9877', 'Сұйықтық қабылдау және іш қату 💩', 'Көп жүгіріп, суды аз іше ме? Түбектегі немесе жөргектегі нәжісін бақылаңыз. Іш қату қаупі болса, оны қолданбаға белгілеп, бірден Тамақтануды бақылау құралы арқылы мәзірге сұлы немесе алмұрт қосыңыз.'),
  ('5730e69b-8e67-40bb-94c5-56cb9dd41a75', 'Жаңа достар іздеу 👫', 'Саябақта құрдастарымен бірге жүгіріп, оларға жақындауға тырыса ма? Әлеуметтену ресми түрде басталды! Қауіпсіздігін алыстан қадағалап, бұл әрекеттерін мақтанышпен бақылаңыз.'),
  ('a11a0d3a-a9c4-402b-9b3c-bc6d874fc9a7', 'Түнгі әуен 🛀', 'Күні бойы жүгіріп, бөпеңіз де, Сіз де әбден шаршадыңыз. Жылы ванна мен фонда ойнап тұрған баяу, нәзік әуен оның жүйке жүйесін толық тыныштандырады.'),
  ('100fc6ed-66a7-4e9e-939c-15af0683652e', 'Күндізгі ұйқыдан бас тарту 🥱', 'Тағы да ұйықтамады ма? Күресіп, оны да, өзіңізді де шаршатпаңыз. Бөлмеде ойыншықтармен тыныш ойнау да ми үшін демалыстың бір түрі.'),
  ('6c9cc94d-8363-4a16-b062-eb3e2640d824', 'Жадтың сыр беруі 🛒', 'Ұйқының қанбауы жадыңызды әлсіретіп, дүкеннен алатын заттарды ұмытып кетіп жүрсіз бе? Миыңызды шаршатпаңыз. Бәрін тізімге жазып қойыңыз, серігіңіз келгенде алып келсін.'),
  ('8f8c331b-379e-4898-a071-076982bfc0c2', 'Дипломатиялық келіссөздер 🤝', 'Саябақта ойыншығын бермей ме? 2.5 жастан кейін бөлісуді емес, кезектесіп ойнауды қалай үйрету керектігін Блогтар бөлімінен міндетті түрде оқыңыз.'),
  ('e1ad3771-efd0-4fef-8fce-2cfe9cc2174f', 'Түнде ояну 🌌', 'Түн ортасында жылап оянып, тыныштала алмай ма? Ұйқы таймерінің кестесін қараңыз. Түнгі үрей мен қорқынышты түстің айырмашылығын түсіну үшін дәл қазір Блогтар бөліміне кіріңіз.'),
  ('d3fd3ce0-fc06-4bdf-8472-041feda78c86', 'Қырсықтық ұстамалары 🛑', 'Әрбір «жоқ» деген сөзіңізге айқаймен жауап бере ме? Бақылауға келмейтін мұндай эмоциялық күйзелістерді сабырмен басқаруды және назарын басқаға аудару тәсілдерін үйрену үшін Anacan AI-мен сырласыңыз.'),
  ('de972116-bddf-48f9-bc08-9f55438a9ed7', 'Әкенің ертегі оқитын уақыты 📚', 'Бүгін кешке ұйқыға дайындау рәсімін серігіңізге тапсырыңыз! Қолданбадағы Серіктес режимін пайдаланып, ертегіні ол оқысын, ал Сіз асықпай шайыңызды ішіңіз.'),
  ('fd7112b4-d166-4f5f-ab2b-5f43c5c75632', 'Тәжірибе бөлісу 💬', 'Баланың жаңа бір әрекеті Сізді қорқытты ма? Интернеттен үрейлі мақалалар іздемеңіз. Anacan қауымдастығындағы тәжірибелі аналардың кеңестерін пайдаланыңыз.'),
  ('0b033378-5688-4baf-b5a5-b23c33fde967', 'Темірдің құпиясы: C дәрумені 🍋', 'Өңі бозарып немесе тәбеті төмендеп кетті ме? Тамақтануды бақылау құралынан бүгін қанша темір қабылдағанын тексеріңіз және темірдің сіңуін арттыру үшін етпен бірге міндетті түрде лимоны мол салат беріңіз.'),
  ('69b9bded-4194-4499-ad7b-42407cdd5970', 'Тек құрғақ тағамдар ма? 🍞', 'Бөпеңіз езбе мен сұйық тағамдардан бас тартып, тек нан мен печенье сұрай ма? Бұл — тағам текстурасын талғау. Тамақтануды бақылау құралы арқылы мәзірін талдап, Бөпеге арналған рецепттерден пайдалы баламаларды табыңыз.'),
  ('a97ba33c-1ca8-42a6-b9a0-1eac5f5ba6a9', 'Денеңізді тыңдаңыз 🩸', 'Кенеттен тәттіге қатты құмартып, ашуланшақ болып жүрсіз бе? Етеккір күнтізбесін тексеріңіз. Егер бұл етеккір кезеңі болса, Әйелдерге арналған пайдалы рецепттерден магнийге бай құрма мен жаңғақтан тіскебасар дайындаңыз.'),
  ('16180139-d7b3-4c7d-9723-1b1d28274883', 'Табиғат зерттеушісі 🔍', 'Үйдегі заттардың бәрін шашып жүр ме? Үлкейткіш әйнекті алып, далаға шығыңыз! Анаға қолайлы орындардан жасыл желекті саябақ тауып, жәндіктер мен жапырақтарды бірге зерттеу арқылы оның энергиясын табиғатқа бағыттаңыз.'),
  ('1e0561d7-2e98-4811-8aaf-2ee6c5e76ef8', 'Кешкі дағды қиындап кетті ме?🛀', 'Жылы ваннаға шомылдырып жатқанда, жайлы әуен қосыңыз. Су мен әуеннің үйлесімі тіпті ең қырсық баланың өзін тыныштандырады.'),
  ('39972a4c-ff8f-4f23-abf0-aefe71b44bb9', 'Үйдегі бейберекет 🌪️', 'Бөлменің іші ойыншыққа толып кетті ме? Үй жинағаннан гөрі, балаңызбен көңілді өткізген 10 минутыңыз маңыздырақ. Ойыншықтар ертең де орнында болады, өзіңізді шаршатпаңыз.'),
  ('15d607dd-13ee-4b91-b920-e762edd4acd3', 'Толық тыныштықты сезіну 🛋️', 'Бала ұйықтай салысымен ыдыс жуғыш машинаны босатуға асықпаңыз! Диванға жатып, көзіңізді жұмыңыз да, 15 минут бойы үйдегі сол бір сирек кездесетін толық тыныштықтан ләззат алыңыз.'),
  ('6417fc2a-8680-4b6d-9b78-5b97074e6a4c', 'Қараңғылыққа үйрену 🌙', 'Тезірек ұйықтауы үшін бөлмедегі барлық артық жарық пен экрандарды өшіріңіз. Мелатонин гормонының бөлінуі тыныш әрі қараңғы ортада ғана жылдамдайды.'),
  ('986722e4-1562-4f18-a164-dd6f65efe855', 'Сені естіп тұрмын 🗣️', 'Сізді мұқият тыңдап, ұқсас сөйлемдер құрауға тырыса ма? Ол Сізбен сөйлесіп жатыр! Оған күлімсіреп, жиі жауап беріңіз және осылай қарым-қатынас жасауға ынталандырыңыз.'),
  ('2eb3f64d-4f32-4bfb-81ca-c75ffc798fd6', 'Серуендейтін уақыт 🌳', 'Төрт қабырғада отыру Сізді қажытып жіберді. Бөпеңізді арбасына отырғызып, небәрі 20 минутқа болса да таза ауаға шығыңыз. Табиғаттың тыныштығы бөпеңізге де, Сіздің көңіл күйіңізге де керемет әсер етеді.'),
  ('48fd17bd-f8c5-4be3-9778-ec599f5cc5b0', 'Төменге қараңыз! 👣', 'Ол жалаңаяқ жүріп, табанымен әртүрлі құрылымды сезінгенді ұната ма? Табанындағы жүйке ұштарын осылай ынталандыру тепе-теңдік сақтау қабілетінің дамуы үшін өте маңызды.'),
  ('e607fc1e-dfa8-4735-b945-f39209fa5d8a', 'Ертегінің сиқырлы әлемі 🪄', 'Бүгін кешке мүлде жаңа нәрсені байқап көріңіз: аспанды зерттеген кішкентай бұлт туралы ертегі айтып беріңіз. Дауыс ырғағыңызды оқиға желісіне сай өзгертіп отырыңыз.'),
  ('4434b892-1b9a-48ea-bd05-6295b7705bc1', 'Кешкі дағдыдағы тыныштық 🌬️', 'Ол күні бойы жүгіріп, енді тыныштала алмай жүр ме? Ұйқы таймерін қосып, Ақ шудан мұхит толқындарының дыбысын таңдаңыз. Бөлмені тыныш ұйқы мекеніне айналдырып, оның күш-қуатын қалпына келтіріңіз.'),
  ('a8561422-a7d3-4164-876d-1471ce35f23d', 'Әкенің асүйдегі күні 👨‍🍳', 'Серіктес режимін іске қосыңыз. Бүгін түскі ас дайындап, бөпені тамақтандыру — әкенің міндеті! Ал Сіз бұл уақытты кітап оқуға немесе демалуға арнап, өзіңізге көңіл бөліңіз.'),
  ('f2202a7a-5edc-4209-b790-4083df0975d2', 'Мақсатты еңбектеу 🐢', 'Ол енді жүре алса да, кейде көңіл көтеру үшін тез еңбектеп, Сізден қашып кете ме? Бөлмедегі қауіпті кедергілерді алып тастап, осы қуаласпақ ойынға Сіз де қосылыңыз.'),
  ('9f77c4af-512a-49b9-8cbf-0c7c57609122', 'Сүйектерге арналған D дәрумені ☀️', 'Кальцийдің сіңуі үшін D дәрумені міндетті түрде қажет! Тамақтануды бақылау құралы арқылы бүгінгі ас мәзірін тексеріп, Ұсынылатын өнімдер бөліміндегі дәрігерлер кеңес берген тамшыларды қарап шығыңыз.'),
  ('a85116cf-7f79-486c-8e28-8b90c93cfb63', 'Кешігу дағдарысы 🛑', 'Үйден шығуыңыз керек, бірақ ол бәрін баяу жасап, асығар емес пе? Бұл жаста балаларда уақыт туралы түсінік әлі қалыптаспаған! Оны асықтырудың орнына, бір әрекеттен екіншісіне ауысуды қалай жеңілдетуге болатынын Anacan AI сарапшысынан біліңіз.'),
  ('956585f5-6347-4c88-b6a3-3638bd223889', 'Сіздің кофе ішетін уақытыңыз ☕', 'Үнемі үйде отырудан шаршадыңыз ба? «Анаға қолайлы орындар» бөлімінен аналар жиі жиналатын балалар кафелерін тауып, өзіңізге де араласатын жаңа орта қалыптастырыңыз.'),
  ('96e63d94-22cd-4a99-8350-f721e6ade562', 'Кезек күтуді үйрену 🧸', 'Саябақта басқа баланың сырғанақтан түсуін күткісі келмей ме? 2.5 жастан кейін балаға шыдамдылық пен кезекпен ойнауды қалай үйретуге болатынын «Блогтар» бөлімінен міндетті түрде оқыңыз.'),
  ('1cf87075-900c-4f1c-a89d-b12b8314ac9b', 'Темір қорының тексерісі 🥩', 'Өңі бозарып немесе тәбеті төмендеп кетті ме? Тамақтануды бақылау құралынан бүгін қанша темір қабылдағанын тексеріңіз. Темірдің сіңуін жақсарту үшін етпен бірге лимон шырыны мол салат беріңіз.'),
  ('9c0be1cd-f5f7-43c2-bf11-199a917727ea', 'Әкенің массажы 💆‍♀️', 'Күні бойы баланың соңынан жүгіріп, беліңіз құрысып қалды ма? «Серіктес» функциясы арқылы оған бүгін кешке баланы ұйықтатқаннан кейін Сіздің иығыңызға қысқа массаж жасайтын уақыт келгенін білдіріңіз.'),
  ('fcd8e598-c584-4111-a575-0192c20a2ba3', 'Су ішуді ойынға айналдырыңыз 💧', 'Көп жүгіріп, аз су іше ме? Іш қату қаупі артады. Үлкен дәретін қолданбаға белгілеп, тамақтануды бақылау құралы арқылы мәзіріне бірден сұлы қосыңыз және «Ұсынылатын өнімдер» бөлімінен балаларға арналған түрлі түсті су құтыларын тапсырыс беріңіз.'),
  ('819da396-26ce-4c11-baf2-c21f3a1ad406', 'Тамақты талғап жеу 🍝', 'Тек макарон жегісі келе ме? Тамақтануды бақылау құралы арқылы апталық теңгерімді тексеріңіз. Бір күн үшін уайымдап, өзіңізді қинамаңыз.'),
  ('f0c36b67-8799-4202-8ab4-a072283a2c59', 'Шаршаудан төгілген жас 💧', 'Сіздің де жылағыңыз келе ме? Бұл — қалыпты жағдай. Сезімдеріңізді «Көңіл күй күнделігіне» жазып, өзіңізді кінәлауды доғарыңыз.'),
  ('f35164ca-a4af-42c5-8f5c-d2b4e2de79f4', 'Сандарды тани ма? 🔢', 'Баспалдақпен көтерілгенде немесе ойыншықтарын жинағанда бірдеңелерді санап көруге тырыса ма? Математикалық дамудың осы алғашқы нышандарын дыбысы бар видео түрінде бірден «Бөпе альбомына» қосып, өмірлік естелікке айналдырыңыз.'),
  ('02944013-1945-43f5-a622-bb7657b42970', 'Көкөністерді жасырыңыз 🥦', 'Көк шөпті немесе брокколиді тәрелкеден алып тастай ма? Бөпеге арналған рецепттерден түрлі түсті, көкөніс қосылған үй кексін тауып, Тамақтануды бақылау құралында дәрумендердің күнделікті мөлшерін оңай толықтырыңыз.'),
  ('45019ac4-08ed-4d8b-8186-060ceb70601a', 'Сіздер — тамаша командасыздар 🌟', 'Оның күн сайын үйренген жаңа дағдысы мен әрбір нық қадамы — Сіз бен серігіңіздің еңбегі. Көңіл күй күнделігін ашып, бүгін команда ретінде өздеріңізге тік тұрып қол соғыңыздар!'),
  ('5613e3d7-d67b-4e9a-b92f-7ce15054b42e', 'Бойы мен салмағы күрт өсті! 📏', 'Киіндіргенде жейделерінің тарылып немесе аяқ киімінің қысып қалғанын байқадыңыз ба? Салмақ трекеріне қазіргі бойы мен өлшемдерін енгізіп, өсу қисығының қалай жоғарылағанын мақтанышпен бақылаңыз.'),
  ('3a871deb-8d4f-4409-84bd-a7fdcb6e8f4e', 'Әкенің ертегі оқитын уақыты 📚', 'Бүгін кешке бөпені ұйықтату кезегі серігіңізде. Ертегіні ол оқысын, ал Сіз өзіңізге берілген осы қысқа үзілістің рақатын көріңіз.'),
  ('751db3a1-bc4d-4599-b35d-5aadaed3cfca', '«Неге?» деген сұрақтар 🤔', 'Ол әлемді түсінгісі келеді. Оның таусылмайтын сұрақтарына қалай сабырмен жауап беруге болатынын Блогтардан біліңіз. Сіздің сабырыңыз — оның дамуына қосқан үлесіңіз.'),
  ('ce6fd7ba-57bf-4c85-bfa6-c9b4b3713d0c', 'Төрт қабырға қысып кетті ме? 🌳', 'Үйде бәрі астан-кестен болып жатыр ма? Аналарға қолайлы орындардан жақын маңдағы саябақты табыңыз. Таза ауа оған да, Сізге де — ең жақсы ем.'),
  ('034073b2-a550-46ff-9473-8411c49fc4ec', 'Темір мен күш-қуат 🥩', 'Өңі бозарып жүр ме? Тамақтануды бақылау құралында темірдің жеткілікті мөлшерде қабылданып жатқанын тексеріңіз. Етпен бірге лимон қосылған салат беріп, темірдің сіңуін жақсартыңыз.'),
  ('3e853511-fee0-4626-9f71-c751f4b255ca', 'Тіс щеткасымен күрес 🪥', 'Щетканы көргенде қашып кете ме? Ұсынылатын өнімдерден әуенді щеткаларды қараңыз. Тазалықты мәжбүрлікке емес, ойынға айналдырыңыз.'),
  ('b222d604-2c4a-4c8d-9eda-efff14884581', 'Мінсіз ана болуға ұмтылу 💖', 'Бүгін шыдамыңыз таусылып, дауысыңызды көтеріп қойдыңыз ба? Өзіңізді кінәламаңыз. Балаңыз ұйықтағаннан кейін Көңіл күй күнделігіне ішкі толғаныстарыңызды жазып, жеңілдеп қалыңыз.'),
  ('259a4698-04af-4cc3-93e9-91599ab8a275', 'Күндізгі ұйқыдан бас тартатын кез келді ме? ⏱️', 'Балаңыз күндіз ұйықтаудан үзілді-кесілді бас тартып, ал кешке қатты шаршай ма? Ұйқы таймерінің статистикасын талдап, күндізгі ұйқыны толығымен тыныш уақыт (quiet time) режиміне ауыстырып көріңіз.'),
  ('278f2f23-c655-4241-807c-401148d291e5', 'Ананың ПМС кезіндегі күйзелісі 🍫', 'Етеккір қарсаңында қуатыңыз азая ма? Дәріге жүгінбес бұрын Әйелдерге арналған пайдалы рецепттер бөлімінен табиғи қантқа бай жидек смузиін дайындап, бойыңызға бірден күш жинаңыз.'),
  ('af74ff56-7d79-46b1-8bf0-e27bd2c06fed', 'Өзім кесемін! ✂️', 'Асүйде бананды немесе ермексазды өзі кескісі келе ме? Бұл — ұсақ моториканы дамытатын тамаша талпыныс! Ұсынылатын өнімдер бөлімінен балаларға арналған қауіпсіз, өткір емес пышақтар мен қайшыларды қазір қарап шығыңыз.'),
  ('04970a72-c396-466c-9613-3a82e661e79f', 'Неге жылағанын өзі де білмейді 😭', 'Стақаны көк емес, қызыл болғаны үшін үлкен айқай-шу басталды ма? Шын мәнінде, бұған шаршау немесе эмоциялық шамадан тыс жүктеме себеп болуы мүмкін. Мұндай бақылауға келмейтін эмоциялық жарылыстарды сабырмен басқару үшін Anacan AI-мен сырласыңыз.'),
  ('c150e539-1698-44fc-be7c-18e8beb9b566', 'Бөлмедегі бөгде дыбыстар 🌌', 'Бөлмедегі толық тыныштық немесе көршіден естілген болмашы тықыр оны оятып жібере ме? Ақ шулар бөлімінен желдеткіш дыбысын қосып, оның ұйықтайтын ортаны бөгде дыбыстардан қалай тамаша оқшаулайтынын байқаңыз.'),
  ('f0684802-cf6d-4a4b-96a5-44c5cabd2832', 'Үйді бірге тазалайық 🧹', 'Үйді жинау керек пе? Серіктес режимін іске қосыңыз! Өзіңіз, әкесі және балақайыңыз (қолына кішкентай шүберек беріп) үй жинауды қалай көңілді отбасылық ойынға айналдыра алатыныңызды біліңіз.'),
  ('20745776-36d1-4511-abf0-1fafb63ced1d', 'Экранның орнына ойын 📱', 'Кешке қарай мультфильм көргісі келіп, жылай ма? Экран уақытын күйзеліссіз шектеуді және оның назарын бірден басқа ойынға аударуды Anacan AI-дан үйреніңіз.'),
  ('d32651ed-78b7-4090-bd14-46fc6e60d9a7', 'Экранға талас 📱', 'Телефонды алып қойсаңыз, айғай-шу бастала ма? Экран уақытын күйзеліссіз шектеудің шынымен көмектесетін психологиялық тәсілдерін Anacan AI-дан сұраңыз.'),
  ('49972eb0-ce9d-4cba-ad0b-3cc84b80e743', 'Түнгі үрейлер 🤖', 'Түн ортасында айғайлап оянып, Сізді танымай қала ма? Мұндайда не істеу керектігін және оның қорқынышты түстен айырмашылығын Блогтар бөліміндегі мақалалардан бірден біліңіз.'),
  ('4efefe1c-c867-4006-9142-0718a80c34db', 'Сіздің де досыңыз бар ☕', 'Тек баламен сөйлесу шаршатады. Анаға қолайлы орындардан балалар кафелерін тауып, бір шыны кофе ішіп, басқа аналармен араласыңыз.'),
  ('a185d77d-1385-43cb-bec6-87f42c458382', 'Таңғы дағдарыстар 🛑', 'Әр «жоқ» деген сөзіңізге жылай ма? Эмоциялық күйзелістерді сабырмен басқару және назарын басқаға аудару үшін Anacan AI-ға ішіңіздегіні айтыңыз.'),
  ('1d63f653-1008-4746-a730-0e985e6ca79c', 'Ластануға рұқсат 🏖️', 'Балшықпен ойнағысы келе ме? Ластана берсін! Сенсорлық дамуды қолдайтын ең жақсы құралдарды Ұсынылатын өнімдерден табыңыз.'),
  ('ab5b74cd-5dbb-4df0-aad8-f7ce58bb43e4', 'Бойдың күрт өсуі 📏', 'Көйлектері қысқарып қалды ма? Бөпеңіз өсіп жатыр! Салмақ бақылағышына қазіргі өлшемдерін енгізіп, даму қисығының қалай жоғарылағанын мақтанышпен бақылаңыз.'),
  ('cd4b46fb-6caf-421b-9a9e-22b85cfd2d73', 'Ыстық шай мен тыныштық 🍵', 'Таймер тоқтады, бала ұйықтады. Үй шаруасын ұмытыңыз! Пайдалы рецепттерден мелисса шайын демдеп, тыныштықтан ләззат алыңыз.'),
  ('3e08f834-ae99-412b-94f4-fcb284f337ca', 'Күн тәртібін талдау ⏱️', 'Кешке ұйықтау тым ұзаққа созыла ма? Ұйқы таймерінің кестесіне қараңыз. Бәлкім, күндізгі ұйқыны едәуір қысқартатын уақыт келген шығар.'),
  ('6c779bea-dc2a-41ad-8ebb-96d5620eee3b', 'Кальций қалқаны 🦴', 'Сүт ішпей ме? Сүйектер үшін кальций өте қажет. Тамақтануды бақылау құралы арқылы йогурт немесе брокколи мөлшерін есептеп, жетіспегенін толықтырыңыз.'),
  ('9550715f-5ff1-4a49-8dae-33944b52477f', 'Ұзақ сөйлемдер 🗣️', 'Бөпеңіз күлкілі оқиғаларды айтып жүр ме? Сөздік қоры қарқынды дамып келеді! Осы бір алтын сәтті жіберіп алмай, Бөпе альбомына дауысын жазып қойыңыз.'),
  ('2d4c6405-93aa-4a22-9aae-af7a8dcd04fc', 'Ерте ояну 🌅', 'Күн шықпай тұрып оянып, бойы энергияға толып жүр ме? Ал Сіздің әбден шаршағаныңыз сезіледі. Бұл режимді қалай реттеуге болатынын Anacan AI-дан сұраңыз. Ұйқысыздық мәңгілік емес.'),
  ('49091c89-e2f8-4ecf-a7b6-b705116efa46', 'Әкенің ертегісі 📚', 'Серіктес режимін қосыңыз. Бүгін кешке ертегі кейіпкері — әке! Ол оқысын, ал Сіз кофеңізді құйып алып, бөлмеден тыс жерде тыныштықтың рақатын көріңіз.'),
  ('865b1ef2-1722-47cc-bf4d-3108a098404b', 'Бөліскісі келмейді 🧸', 'Ойыншығын ешкімге бермей ме? Бұл өзімшілдік емес, жасына сай даму кезеңі. Блогтардан кезекпен ойнауды қалай үйретуге болатынын біліңіз.'),
  ('983d85d9-b1dc-40ec-a012-9c7aba93c4d9', 'Көз жасы — қалыпты 💧', 'Шаршадыңыз ба, тек жылағыңыз келе ме? Мықты ана болу — кейде әлсіздігіңізді мойындай білу.'),
  ('ee623f8b-a47a-4ef6-96d3-5754f3e3cd43', 'Күш-қуаттың төмендеуі ⚡', 'Түсте тұрып-ақ қалғып кетесіз бе? Кофеинге емес, ақуызға жүгініңіз! Пайдалы рецептілерден бірден күш беретін жержаңғақ пастасы қосылған смузи дайындап, сергіп алыңыз.'),
  ('fe3bdaaa-fafd-445d-b4e7-84a8026c6168', 'Кенеттен айқайлау 🛑', 'Еш себепсіз өзін жерге тастай ма? Мұндай ұстамаларды сабырмен басқару және айналадағылардың көзқарасына мән бермеу үшін Anacan AI-мен сырласыңыз.'),
  ('59dde031-61d1-4132-874a-bbebe2bc223a', 'Сынған печенье қасіреті 🍪', 'Печеньесі екіге бөлініп қалғаны үшін ақырзаман орнағандай болды ма? 2.5 жастағы классикалық дағдарыстарға қош келдіңіз. Бұдан қисын іздемеңіз, оған тек осы үлкен қайғысын түсінетініңізді айтыңыз.'),
  ('5e26eff6-747b-42a4-909a-13e90be41e9d', 'Сүзгісіз шындық 🛑', 'Әлеуметтік желідегі тыныш әрі тап-таза балалардың видеоларын көріп, өзіңізді кінәлап жүрсіз бе? Олар небәрі 15 секундтық елес. Сіздің шашылған, у-шулы шынайы өміріңіз бәрінен де әдемі.'),
  ('db6eccad-9548-4b17-8f6b-0466160ee8dc', 'Пижамаға қарсылық 👕', 'Киінгісі келмей, үйдің ішінде қашып жүр ме? Бұл күресті ойынға айналдырыңыз. Кім тезірек киінеді екен? Бәсекелестік көбіне қырсықтықты жеңудің ең жақсы тәсілі.'),
  ('118d8e02-86c1-4716-8dfd-287849e960b7', 'Кішкентай диктофон іске қосылды 🎙️', 'Аузыңыздан шыққан кез келген сөзді бірден қайталай ма? Ол — Сіздің жанды айнаңыз. Бұл жаста сөздік қоры қарқынды дамиды, жаңа сөздерді Даму трекеріне жазып отырыңыз.'),
  ('4ffb5f4c-fcb6-4d97-8d29-5662777e74bb', 'Жылдам қамдану 🛒', 'Ұйқысыздық зейініңізді шашыратып жіберді ме? Не сатып алу керегін үнемі ұмытып жүрсіз. Бәрін бірден Сатып алу тізіміне қосыңыз да, дүкенге бару міндетін жұбайыңызға толық тапсырыңыз.'),
  ('8658617d-87c3-40a0-a148-d3af3d34503e', 'Әкенің ертегі театры 📖', 'Күні бойы «жоқ» дей бергеннен дауысыңыз қарлығып кетті. Бүгін кешкі ертегі уақытын әкесіне тапсырыңыз. Ол дауысын құбылтып, күлкілі оқиғалар айтып берсін, ал Сіз демалыңыз.'),
  ('5d60ba67-a127-4fbd-bd24-40125cd3bcc8', 'Суретшінің жаңа кенебі 🖍️', 'Қағаз таусылып, енді қабырғаға немесе есікке сурет салғысы келе ме? Ол жай шимайлап жатқан жоқ, ұсақ моторикасы арқылы әлемді танып-біліп жүр. Оған үлкен қатырма қағаз беріп, сурет салатын шекараны белгілеңіз.'),
  ('b27a302e-b37e-4606-900b-22135e770f9b', 'Тыныштықты сезіну 🤫', 'Үйдегі қарбалас ақыры басылып, бөпеңіз ұйықтап қалды. Дыбыс өлшегішті қосып, бөлмедегі тыныштық деңгейін көріңіз де, 15 минут бойы ешбір экранға қарамай, осы тыныштықтан ләззат алыңыз.'),
  ('65dda26f-c428-4285-904a-5e44f932685c', 'Бірге еңсереміз 🥂', 'Бөпе ұйықтағаннан кейін жұбайыңызбен бетпе-бет отырыңыз. Бөпе туралы сөйлесудің орнына, «Бүгін де аман қалдық» деп бір-біріңізге жымиып, бір команда екендеріңізді сезініңіз.'),
  ('68aff420-6957-4fb3-8fd3-172910f79641', 'Далаға шығу керек ⛅', 'Төрт қабырғада отырудан шаршадыңыз. Ауа райы мен киім құралынан сырттағы нақты температураны тексеріп, көп ойланбастан саябаққа шығыңыз. Таза ауа тіпті ең ауыр дағдарыстың өзін бірден басады.'),
  ('70cc8a60-04a1-4e4e-b5c3-986f74563498', 'Аяқкиімге 20 минут 👟', 'Аяқкиімін өзі кигісі келіп, үйден шығу кешігіп жатыр ма? Сабыр сақтаңыз.'),
  ('e2414d34-11c4-4990-9c63-38d30534a147', 'Сөйлемдері ұзарып келеді 🗣️', 'Енді ол сөздерді бір-бірімен байланыстырып, қызықты әрі өз қисынына толық сай сөйлемдер құрайды. Бұл сәттерді жіберіп алмаңыз: «Бөпенің фотосессиясы» арқылы оның осындай сүйкімді әңгімелерін видеоға түсіріп алыңыз.'),
  ('ef8a1fe8-6bb2-49b8-bcbe-cb005f42d12f', 'Қараңғыдағы ойындар 🐰', 'Жарық сөнгенде қорқа ма? Бөлмені толық қараңғылап, қолшаммен қабырғаға көлеңке түсіріп ойнаңыз. Қорқынышты көңілді ойынға айналдырып, оның қараңғылыққа үйренуіне көмектесіңіз.'),
  ('005f91e2-a696-4de0-bf24-bb840b614746', 'Бой мен салмақтың күрт өсуі 📏', 'Шалбарының балағы тағы қысқарып қалды ма? Ол тез өсіп келеді! Даму трекеріне қазіргі өлшемдерін енгізіп, ұйқысыз түндеріңіздің жемісі болған жоғары өрлеп келе жатқан даму қисығына мақтанышпен қараңыз.'),
  ('4d0ac53a-0a7d-40d8-a958-4dd99382d977', 'Себепсіз ояну 😭', 'Түн ортасында айғайлап оянды. Абыржымаңыз. Жылауды талдау құралы арқылы мұның өсу кезіндегі ауырсыну ма, әлде түнгі үрей ме екенін тексеріп, оны сабырмен құшақтаңыз.'),
  ('7a36ad44-2dba-4854-82a6-8b3c27a56c6f', 'Мұздай кофе ☕', 'Кофе құйып алып, оны 3 сағаттан кейін ішу — ана болудың ресми түрде жазылмаған заңы. Бүгін бұл әдетті өзгертіңіз. Оны ойыншықтарымен өз бетінше ойнауға қалдырып, кофеңізді 10 минут ішінде ыстық күйінде ішіп алыңыз!'),
  ('d7ebaa5c-a836-4c14-8fc7-8ddab08162c6', 'Көкөністі жасыру тәсілі 🥦', 'Тәрелкедегі жасыл түсті тағамның бәрін шетке ысырып қоя ма? Бұл жаста тамақ талғау шегіне жетеді. Тамақтану жоспары бөлімінен көкөністерді езіп, котлеттің ішіне жасыруға болатын айлакер рецептілерді табыңыз.'),
  ('2461cdb3-c847-4528-8c72-5b1258b6ff1d', 'Саябақтағы шекаралар 🧸', 'Құм алаңында шелегін ешкімге бермей ме? Бұл өзімшілдік емес, меншік ұғымының қалыптасуы. Бөлісуді мәжбүрлеу арқылы емес, кезекпен ойнау арқылы үйретіңіз: Қазір оның кезегі.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('b0edd680-c98e-4626-b7fa-18383befe832'::uuid, 'Қиялдағы қонақтар келді ☕', 'Бөлмеде жалғыз отырып, көзге көрінбейтін достарымен сөйлесіп, оларға шай құя ма? Бұл — қиял дамуының шарықтау шегі! Осы керемет сценаристі сырттай мақтанышпен бақылаңыз.'),
  ('dea0086a-894a-4d43-a110-0948ee956740', 'Сиқыр тізгіні баланың қолында 🪄', 'Классикалық ертегілерден жалығып кетті ме? Ақылды ертегілерде бұл жолы кейіпкерді өзі таңдауына мүмкіндік беріңіз. Ұшатын ит немесе Сөйлейтін ағаш – қиялына ерік беріңіз.'),
  ('0a08658d-8354-4bb5-9ba8-b4c528e517fc', 'Өз ережелерін орнатады 🛑', 'Бәріне «өзім!» дей ме? Аяқкиімін теріс, жейдесін дұрыс кимесе де, алған бетінен қайтпайды. Еш зияны жоқ, дербестікке деген ұмтылыс сыртқы көріністен маңыздырақ, оған мүмкіндік беріңіз.'),
  ('411275c3-b6bc-4218-a886-bbf3ee4ba697', 'Су терапиясы 🛀', 'Күні бойы жүгіріп, оның да, Сіздің де жүйкеңіз жұқарды. Жылы ванна тек тазалық үшін емес, судың бойдағы ширығуды басатын ғажайып күшін пайдалану үшін де қажет.'),
  ('d5a4b327-9717-431f-8c67-ec44df34af85', 'Қажу сезімі 🔋', 'Бәріне айқайлағыңыз келе ме? Бұл — эмоциялық қажу. Дереу Anacan қауымдастығына қосылып, Сізбен бірдей кезеңді бастан өткеріп жүрген аналардың жан сырын оқып, қолдау алыңыз.'),
  ('38c563a6-395b-403a-8ffd-c4d46a16b207', 'Асүйдегі тосын әрекет 🧑‍🍳', 'Сіз тамақ әзірлеп жатқанда, ол қазандармен концерт қоя ма? Ол да топтың бір мүшесі болғысы келеді. Қолына кішкене қамыр беріп, оның да ас әзірлеуіне мүмкіндік беріңіз.'),
  ('1e03f3e4-2305-4ae5-883c-39581f248697', 'Сандарды танып-біледі 🔢', 'Баспалдақпен көтерілгенде немесе ойыншықтарын тізгенде бір, екі, үш деп санауға тырысады. Онымен бірге санап, танымдық дамуының осы математикалық кезеңін қолдаңыз.'),
  ('2e1f0716-93b5-4be3-9000-fdb28349534d', 'Әкенің құпия қаруы 🤡', 'Сіздің айла-тәсілдеріңіз көмектеспей қалғанда, әкесінің оғаш дыбыстары мен күлкілі қылықтары жағдайды әп-сәтте құтқарады. Кешкі мазасыздық кезінде кезекті бірден әкесіне беріңіз.'),
  ('b24ba903-09d2-4243-a80b-995524b45caf', 'Күндізгі ұйқыға қарсылық 🥱', 'Төсекке жатқысы мүлде келмей ме? 2.5 жаста кейбір балалар күндізгі ұйқыдан бас тарта бастайды. Ұйықтауға мәжбүрлемей, оның орнына 30 минуттық тыныш кітап оқу уақытын ұйымдастырыңыз.'),
  ('54501d8f-f370-4895-a96c-448bca275b4e', 'Аяқ астыңызда не бар? 👣', 'Жалаңаяқ жүргенді, әртүрлі беттерді (құм, кілем, тас) басып сезінгенді ерекше ұнатады. Аяқ табанындағы жүйке ұштарының белсенділенуі оның неврологиялық дамуы үшін өте маңызды.'),
  ('7212233e-c5da-4c83-bd8d-a74e469e3fcc', 'Жарықты бәсеңдетіңіз 🌙', 'Ұйықтардан 1 сағат бұрын үйдегі барлық жарық шамдар мен көк жарық шығаратын экрандарды өшіріңіз. Мелатонин гормоны бөлінуі үшін үйде кешкі алакөлеңке орта қалыптастырыңыз.'),
  ('efc5b454-d92c-49c6-a2a5-9e995c6d9a84', 'Дәрігерге қатысты алаңдаушылық 🤖', '2.5 жаста қажет екпелер немесе дәрумендер туралы күмәніңіз бар ма? Интернеттегі үрейлі форумдардан жауап іздеп адаспай, бірден Anacan AI-дан нақты жауап алыңыз.'),
  ('235bf352-67d4-4056-94d7-5429271d340f', 'Шағын пікірталастар 🗣️', 'Жоқ, мен өстім, өзім білемін! Енді ол өз уәждерін айтып, Сізбен келіспеуге тырысады. Даусыңызды көтермей, онымен тең дәрежеде, бірақ нық сөйлесіңіз.'),
  ('ae99921f-bf29-40ac-a251-a633a4741d07', 'Өзіңізге уақыт бөлу — кінә емес 💆‍♀️', '«Баламен аз уақыт өткіземін» деген сезім әр ананы мазалайды. Бірақ әбден қалжыраған ананың балаға берер күші қалмайтынын ұмытпаңыз. Күндіз өзіңізге 20 минуттық тынығу үзілісін жасаңыз.'),
  ('ead40251-f5fc-4b01-b344-4b041fbbf0eb', 'Ең тәтті жүк 🫂', 'Күні бойы Сізді әбден әуреге салып, әр нәрсеге жылады. Бірақ кешке ұйықтарда кеудеңізге тығылған сол жылы, кішкентай дененің иісі... Міне, осы — әлемдегі ең керемет сезім.'),
  ('41765791-323c-438b-b416-30b7105b9c01', 'Аналарға арналған орын ☕', 'Күн сайын бір саябаққа бара беруден жалықтыңыз ба? Аналарға қолайлы орындардан балалар да емін-еркін ойнай алатын, тыныш әрі өзгеше бір дәмхана тауып, бүгін өзіңізді еркелетіңіз.'),
  ('dc90d262-2720-4f19-9f2a-dcf90cd5da80', 'Пішін мен кеңістікті түсіну 🧩', 'Бөпеңіз пазл бөлшектері мен түрлі пішіндерді сәйкес саңылауларға салуға бар ынтасымен тырысады. Қателессе де, араласпаңыз. Ол мәселені шешу дағдысын дәл осы сынап көру және қателесу арқылы үйренеді.'),
  ('e0925ec9-2283-4167-888a-ee7948c21d0f', 'Табиғи ақ шу 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — мидың ең белсенді кезі. Бөлмедегі дыбыс деңгейін шу өлшегішпен реттеңіз. Кейде жай ғана сіркіреп жауған жаңбырдың дыбысы бөпеңізді терең ұйқыға батыруы мүмкін.'),
  ('28ff0d8a-2265-4669-8253-5aac2bfb80da', 'Өзіңізге рақмет айтыңыз 🎈', 'Түнде ұйқысыздық, күндіз тынымсыз қарбалас... Бірақ Сіз бәрін еңсердіңіз. Бүгін оны дауыс көтермей өсіріп жатқаныңыз үшін өзіңізге «Жарайсыз!» деңіз.'),
  ('95ffd69a-c8c2-4b14-b98e-76c322f02229', 'Тізімсіз дүкенге бару? Ешқашан! 🛒', 'Жадыңызға сеніп дүкенге барасыз да, үйге ең қажет затты алмай қайтасыз. Бұл әдеттен арылыңыз. Үйде таусылған әр затты бірден Сатып алу тізіміне жазып жүруді әдетке айналдырыңыз.'),
  ('ec24c154-30dc-40d8-8aed-20579933d8fb', 'Сезімдеріңізге ерік беріңіз 📝', 'Сізді ешкім түсінбейтіндей ме? Шаршағаныңызды ешкім байқамай ма? Көңіл күй күнделігі — ең сенімді сырлас. Оған бүкіл күйзелісіңізді, жан қиналысыңыз бен жалғыздық сезіміңізді жазыңыз. Сонда жаныңыздың қалай жеңілдегенін байқайсыз.'),
  ('093d545f-b52d-4160-be2f-88e5e1b53427', 'Көкөніспен күрес әлі жалғасуда 🥦', 'Бөпеңіз сорпадағы кішкентай сәбізді тағы да байқап қалып, тамақтан бас тартты ма? Порцияны кішірейтіп, тағамның пішінін өзгертіңіз. Шығармашылық — ананың ең мықты қаруы.'),
  ('0e43d226-9cd6-4c62-b9a7-e0206f0830ca', 'Таптым сені! тосынсыйы 🙈', 'Жасырынбақ ойынының ережелері өзгерді. Енді ол өзі жасырынып, «Мен осындамын!» деп айқайлап шығады. Ойын ережелерін өзі ойлап табуына мүмкіндік беріп, бірге мәз болып күліңіздер.'),
  ('39e6032f-d2bf-40b5-98db-1f2ab3a5a379', 'Түнгі тыныштық 🛀', 'Егер кеш өте қырсық әрі мазасыз өтіп жатса, оны жылы суға шомылдырыңыз. Ваннада жай ғана сумен ойнауы және судың емдік әсері оның бойындағы барлық жағымсыз энергияны шайып әкетеді.'),
  ('2c4fbb59-42cd-4340-ba93-aee620d9df26', 'Әнді ыңылдап айту 🎶', 'Ойын кезінде өздігінен түсініксіз сөздермен ән айтады. Бұл сөйлеу қабілеті мен есту қабілетінің дамып келе жатқанының белгісі. Осы жаңа кезеңді Даму трекеріне міндетті түрде енгізіңіз.'),
  ('491d12b8-51d5-4984-8dda-d40fbb4e95c8', 'Әкенің кітап оқу сағаты 📖', 'Бүгін кешке бөлмеде өзгеше атмосфера қалыптастырайық. Кітап оқуды әкесінің қоңыр әрі сенімді дауысына тапсырып, өзіңіз бір шетте тыныштықтың рақатын көріңіз.'),
  ('c32299af-eeac-42f3-ab67-01688b0d4551', 'Аналарды қолдау тобы 💬', 'Күрделі шешім қабылдауыңыз керек пе? (Балабақша, түбекке үйрету, ұйқы). Anacan қауымдастығындағы тәжірибелі аналардың кеңестері — ешбір кітапта жазылмаған ең шынайы шешімдер.'),
  ('1c02ca47-65ab-4daa-8468-3f801795414a', 'Үй шашылып жата берсін 🌪️', 'Күн сайын кешке бір ойыншықтарды қайта-қайта қорапқа жинаудан шаршадыңыз ба? Бүгін жинамаңыз! Үй — мұражай емес, тіршілік қайнап жатқан, кішкентай зерттеуші өсіп келе жатқан мекен.'),
  ('890c1216-15b7-4852-b1cb-42e4a141e897', 'Нысанаға лақтыру және қағып алу ⚾', 'Енді ол Сіз лақтырған үлкен допты жай ғана өткізіп жібермей, қағып алуға тырысады. Көз бен қол үйлесімі қарқынды дамып келеді. Дәлізде бір-біріңізге доп лақтырып, шағын спорттық ойындар ойнаңыздар.'),
  ('a764d770-048d-4a17-b477-fc4f761c3c2d', 'Ертегісіз ұйықтамаймыз 🪄', 'Бөлменің жарығын толығымен өшіріңіз. Ақылды ертегілерде фонға тек табиғат дыбыстарын (жел, орман) қойып, сөзсіз әрі тыныштандыратын орта қалыптастырыңыз және ұйықтауын жеңілдетіңіз.'),
  ('1c8d40ed-ce45-4ab5-a646-af121febdc6b', 'Командалық мақтаныш 🥂', 'Қиын күнді артта қалдырдыңыздар. Бөпе ұйықтағаннан кейін серігіңізбен бірге шай ішіп, «Біз мұның бәрін шынымен керемет атқарып жүрміз» деп бір-біріңізді жігерлендіріңіздер.'),
  ('b19556d6-123c-4633-b806-8552c2789139', 'Ауа райы құбылмалы ⛅', 'Серуенге шыққанда ауа райына алданып, бөпені тоңдырып алмаңыз. Терезеден қарап қана шешім қабылдамай, Ауа райы және киім көмекшісі арқылы дала жағдайына барынша сай киім үйлесімін таңдаңыз.'),
  ('d7f16071-fb32-41c6-bf73-3b61867ff844', 'Батыл секірулер 🧗‍♂️', 'Ол диваннан жастықтардың үстіне секіреді. Осылайша тартылыс күшін және өз батылдығын сынап жүр. Тыйым салудың орнына бөлмеде қауіпсіз секіруге арналған орын жасаңыз.'),
  ('3c7fed9f-b2da-420c-b7cb-afa7c5dc9f37', 'Ұйқысыздықты қабылдаңыз 😭', 'Ол түн ортасында оянып, қайта ұйықтағысы келмейді. Оған ашуланбаңыз. Себебін анықтап, жай ғана жанында екеніңізді сездіре отырып, мейірлене сипаңыз.'),
  ('904ee771-1822-4dbc-a79d-be6697d8f129', 'Қиын сәттегі сабыр 🛒', 'Дүкенде қалаған ойыншығын алып бермегеніңіз үшін айқайлап жатыр. Айналадағы «мінсіз» ата-аналардың көзқарасына мән бермеңіз. Сабырмен көзіне қарап түсіндіріңіз және шешіміңізден таймаңыз.'),
  ('c5b71abf-d92a-46da-8996-4282a02052e4', '31-ші айға қадам!  🎉', 'Ол қазір балалық шақтың ақыл-ойы қарқынды дамитын әрі ең күрделі кезеңінде. Оның әрбір сөйлемі мен әрбір сұрағы — Сіз үшін үлкен жаңалық.'),
  ('0f2d9f90-69e8-4777-adab-24eab59b69a5', 'Ас мәзіріне қатысты қиындықтар 🥣', 'Екі қасық жеп алып, «тойдым» деп қашып кете ме? Оны мәжбүрлемеңіз. Тағаммен дұрыс қарым-қатынас қалыптастыру тәрелкені тауысып жеуден әлдеқайда маңызды.'),
  ('1b92930f-874b-4bdc-b9d4-44b2ec744469', 'Уақытты тоқтатқан сәт 📸', 'Ол бөлмеде сүйкімді болып ойнап жүргенде, бірден Бөпе фотосессиясын ашыңыз. Оның өзгерген, есейген жүзін және жарқыраған көздерін ешқандай сүзгісіз түсіріп, болашаққа естелік етіп сақтаңыз.'),
  ('1beec453-866b-4504-9a19-59d21f2305e4', 'Айырылу үрейі қайтадан басталды ма? 🥺', 'Тіпті дәретханаға кірсеңіз де, есіктің ар жағында Сізді күтіп, жылайды. Айырылу үрейі кейде қайта оралады. Оған әр жолы дауыстап, осында екеніңізді және міндетті түрде қайтып келетініңізді, тіпті басқа бөлмеден болса да, айтып отырыңыз.'),
  ('01e5d997-771c-4149-81ec-cf5e1b89ede9', 'Энергиясын шығаруы маңызды 🌳', 'Төрт қабырға арасында отыру оны ашушаң етеді. Оны арбасына отырғызыңыз немесе қолынан ұстап, таза ауаға шығыңыз. Табиғаттың тыныштығы бөпеге де, Сіздің көңіл күйіңізге де тамаша әсер етеді.'),
  ('149c401f-2cba-4bc8-b3fb-54e3507ca6f5', 'Қараңғылыққа үйрену 🌙', 'Тезірек ұйықтап кетуі үшін бөлмедегі барлық қосымша жарықты және планшет экрандарын өшіріңіз. Мелатонин тыныш әрі қараңғы ортада ғана жылдам бөлінеді.'),
  ('1d84618d-c436-422f-bb3e-95d3ae0487d6', '«Бұл не?» сұрақтарының тасқыны ☝️', 'Барлығын саусағымен көрсетіп, атауын сұрай ма? Ол Сізден айналасындағы дүниені атап беруді қалайды. Бұл — тілдесудегі үлкен серпіліс! Ол көрсеткен әр заттың атауын шыдамдылықпен қайталап айтыңыз.'),
  ('0d2ab4f6-8a9d-4fb2-978b-635299c5c2d2', 'Қол соғудың қуанышы 👏', 'Бір нәрсені істей алғанда, өзіне-өзі қол соғып, мақтана ма? Ол Сіздің мақұлдауыңызды қалайды! Сіз де оның осы кішкентай жетістігіне зор қуанышпен қол соғып, жігерлендіріңіз.'),
  ('25c7776c-5416-4926-9ebf-f1fff97f3809', 'Сұрағыңыз бар ма? 🤖', '2.5 жастан кейін баланың бойы мен салмағының графигі Сізді алаңдата ма? Интернеттен қорқынышты мақалалар оқығанша, Anacan AI-дан нақты әрі ғылыми негізделген ақпарат алыңыз.'),
  ('8ca38ffe-27aa-42ae-a1e8-03b42c6c25c2', 'Әкенің оғаш дыбыстары 🤡', 'Сіздің әрекеттеріңіз көмектеспей қалғанда, әкенің оғаш дыбыстары жағдайды құтқарады. Кешкі мазасыздық кезінде кезекті бірден оған беріп, сырттай жымиып қарап отырыңыз.'),
  ('186e8c82-10c6-4dcc-8ae8-517e2888e663', 'Түнгі әуен 🛀', 'Күні бойы жүгіріп, бөпеңіз де, Сіз де әбден шаршадыңыз. Жылы ванна мен жаймен ойнап тұрған баяу, нәзік әуен оның жүйке жүйесін толық тыныштандырады.'),
  ('34a5aff2-1b83-44f1-acd3-59c942a78f84', 'Суреттерге мән береді 📖', 'Кітаптағы жануарларды немесе балаларды көргенде, оларды түртіп, «Бұл не істеп жатыр?» деп сұрайды. Оның көру арқылы қабылдауы таңғажайып деңгейде. Онымен кейіпкерлер туралы мазмұнды оқиғалар құрып, әңгімелесіңіз.'),
  ('638fb01b-1266-441c-a6a2-ad8bcb0172d8', 'Анаға арналған уақыт 🥑', 'Күнделікті қарбаласта түскі асты жүріп бара жатып ішпеңіз. Пайдалы рецептілерден қуат беретін тіскебасар таңдап, кем дегенде 10 минут диванға жайғасып, дұрыс тамақтануды бірінші орынға қойыңыз.'),
  ('543664cd-6c89-4ffd-ac7b-d08edd1101b7', 'Сыбырлап сырласу 🌙', 'Бөлменің жарығын толығымен өшіріңіз. Жанына жатып, күні бойы болған оқиғаларды өте баяу дауыспен, сыбырлап айтып беріңіз. Сыбырлау — миды ұйқыға дайындаудың ең жақсы тәсілдерінің бірі.'),
  ('93186474-3eab-43ed-a284-f876b4f1b709', 'Темір және күш 🥩', 'Өңі бозарып немесе тез шаршай ма? Етпен бірге лимон немесе қызанақ қосылған салат беріп, темірдің ағзаға сіңуін арттырыңыз.'),
  ('fd977b6d-8463-4d3e-998c-e4dea887a555', 'Тізімдердің күші 🛒', 'Дүкенге барғанда міндетті түрде бір нәрсені ұмытып кетесіз бе? Қолданбада сатып алу тізімі Сізді күтіп тұр. Қажетті заттарды сол жерге жазып қойыңыз, сонда жұбайыңыз жұмыстан қайтарда бәрін тізім бойынша алып келеді.'),
  ('7c36b46e-089a-4d1a-adf7-c6f69476bd88', 'Сезімдеріңізді жазыңыз 📝', 'Сізді ешкім түсінбейтіндей көріне ме? Шаршағаныңызды ешкім байқамай ма? Көңіл күй күнделігі — ең сенімді сырлас. Барлық күйзелісті, жан ауыртқан сезімдер мен жалғыздықты соған жазыңыз. Ішіңіздің қаншалықты тез жеңілдегенін байқайсыз.'),
  ('b5b01983-be53-446e-a05f-8de98770b472', 'Бұл менікі 🧸', 'Үйге келген қонақтың баласына өз ойыншығын бермей ме? Бұл өзімшілдік емес, өзінің жеке шекарасын қорғау. Бөлісуді мәжбүрлеу арқылы емес, өзіңіз үлгі көрсету арқылы үйретіңіз.'),
  ('b791e063-932d-483a-b56e-e710cf0815c9', 'Еркін ойын 🧸', 'Оны әр минут сайын көңілдендіріп, ойын ойлап табуға міндетті емессіз. Ішінің пысуы — балалар шығармашылығының бастауы. Бөлмеде өз бетінше бір нәрсе зерттеп, жаңалық ашуына мүмкіндік беріңіз.'),
  ('78cdd6a4-a9f3-4cd8-8b42-3de0066371e3', 'Ластануға толық рұқсат 🏖️', 'Балшықпен немесе сумен ойнағысы келе ме? Ластана берсін! Сенсорлық дамуды қолдайтын осындай ойындарға арналған оңай тазаланатын керек-жарақтарды Ұсынылатын өнімдерден таба аласыз.'),
  ('a54926e2-dcf2-4ae7-b48f-de76a56a8b5a', 'Дыбыстарды бәсеңдетіңіз 🤫', 'Ұйықтап бара жатқанда оның сезімталдығы артады. Терезеден келетін дыбыстарды басу үшін бөлмеде ақ шу (white noise) құрылғысын қосыңыз немесе табиғат әуендерін ойнатыңыз.'),
  ('b1b0d666-c61e-4108-b645-d26f43bbe56c', 'Төменге қараңызшы, ол нені зерттеп жүр? 👣', 'Ол енді жалаңаяқ жүріп, кілемді немесе бөлмедегі еден тақтайшаларын табанымен сезінгенді ұнатады. Табанындағы жүйке ұштарының белсенді болуы оның тепе-теңдігі мен қимыл-қозғалысының дамуы үшін өте маңызды.'),
  ('07396f85-0dfe-4998-a9ea-d36af8bc97dd', 'Жай ғана құшақтаңыз 🫂', 'Ешқандай ойынның, кітаптың немесе ертегінің қажеті жоқ. Бүгін кешке оны жай ғана бауырыңызға басып, иісін құшырлана жұтыңыз да, қараңғыда оның Сіз үшін қаншалықты қымбат екенін сыбырлап айтыңыз.'),
  ('0c781594-9b76-4258-9f91-7171c6608a1a', 'Тәжірибе бөлісу 💬', 'Баланың бәріне қасарысуы Сізді қорқытты ма? Интернеттен үрейлі мақалалар іздемеңіз. Anacan қауымдастығындағы тәжірибелі аналардың шынайы тәжірибесіне сүйеніңіз.'),
  ('598525b6-1a5f-4877-944f-c79292ee0167', 'Мақсатты жүгіру 🐢', 'Енді оған жай жүру аздық етеді: ол жылдам жүгіріп, Сізден тығылады. Бөлмедегі қауіпті кедергілерді алып тастап, бұл қуаласпақ ойынына Сіз де бар күшіңізбен қосылыңыз.'),
  ('01e01b8e-03c9-4797-b794-5c6f68c813f6', 'Әкенің ертегісі 📖', 'Бүгін кешке даусыңызды тынықтырыңыз. Баланың сүйікті кітаптарын әртүрлі дауыс ырғағымен қызықты әрі күлкілі етіп оқуды әкесіне тапсырыңыз.'),
  ('687bbb3b-79db-41d1-81e9-02d82200fd25', 'Нық «жоқ» деу басталады 🛑', 'Біреу оны сүйгісі келгенде, ол алыстап, нық түрде «жоқ» дей ме? Оның жеке шекараларын құрметтеңіз. Рұқсатсыз жанасуға қарсылық білдіруі болашақта өзіне сенімді болуы үшін өте маңызды.'),
  ('cb9d6b16-c52e-4770-b96a-4ab41dd866dc', 'Ана шаршағанда 🛑', 'Сіз темірден жаралмағансыз. Егер бүгін тамақ пісіруге шамаңыз болмаса, макарон қайнатыңыз немесе дайын асқа тапсырыс беріңіз. Мінсіз ана болу — бәрін жалғыз атқару емес.'),
  ('438805fb-6787-4d0d-b1d5-b2a1a747c30c', 'Іш қату белгісі 💩', 'Көп жүгіріп, су ішуді ұмытып кете ме? Түбекке отырған кезде нәжісін бақылаңыз. Мәзіріне міндетті түрде талшыққа бай сұлы мен қара өрік қосыңыз.'),
  ('6e0e2948-0156-4f7e-a4e9-342d621f5670', 'Төсектегі бітпейтін шоу 🛌', 'Ұйықтаудың орнына төсекте секіріп, жүгіре ме? Ұйқы таймерін қосып, шекараны сүйіспеншілікпен сақтаңыз. Ақ шу ішіндегі орман дыбысын қосып, бөлмені тыныш ұйқы аймағына айналдырыңыз.'),
  ('c7ebe08f-c601-4b91-b115-456e094665de', 'Кальций қалқаны 🦴', 'Сүт ішпей ме? Сүйек үшін кальций өте қажет. Тамақтануды бақылау құралы арқылы бүгін қанша ірімшік, йогурт немесе брокколи жегенін есептеп, жетіспеген мөлшерін толықтырыңыз.'),
  ('54448f6d-1a3b-4d93-a54d-a52f199ed706', 'Жастықтан жасалған қамал 🏰', 'Бүгін кешке бөлмені ойын алаңына айналдырыңыз. Диван жастықтарынан кішкентай қамал жасап, ішіне бірге кіріңіз. Бөлме сәл шашылады, бірақ көңілді күлкі үшін бұл соған тұрарлық.'),
  ('71cd2e71-d81c-477a-9842-72269b236716', 'Өзім жеймін деген қырсықтық 🥄', 'Қасықты қолына алып, айналаның бәрін былғай ма? Тамақтану таймерін қосыңыз. Шашылған тамаққа емес, оның өз бетінше әрекет етуге үйреніп, өзіне деген сенімі артып жатқанына қарап мақтаныңыз.'),
  ('a40edf39-5245-44c1-a544-58bd483fee61', 'Таңғы қырсықтық ☁️', 'Көзін аша сала бәріне жылап, ештеңеге көңілі толмай ма? Бәлкім, дәл қазір қарқынды өсу кезеңін бастан өткеріп жүрген шығар. Оны құшақтап, қауіпсіздікте екенін сезіндіру арқылы күнді жайлы өткізіңіз.'),
  ('08e4a521-2f7a-4298-b56b-2d48b11d0ee9', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Күндізгі шаршаудың өзі Сізге жеткілікті. Кешке баланы ұйқыға дайындап, пижамасын кигізуді әкесіне тапсырып, өзіңіз сырттай ғана бақылаңыз.'),
  ('352c5750-18d9-48a8-a40c-2d51006fd988', 'Сөздерді қайталау 🗣️', 'Сіздің аузыңыздан шыққан әрбір жаңа сөзді тотықұс сияқты бірден қайталай ма? Оның сөздік қоры молайып келеді. Қасында айтатын сөздеріңіз бен білдіретін эмоцияларыңызға ерекше мән беріңіз, өйткені ол бәрін қайталайды.'),
  ('3f0547e8-7e6b-4c78-bdaf-b78aab3ce2fa', 'Көкөністерді жасырыңыз 🥦', 'Көжедегі кішкентай сәбізді тағы да байқап қалып, тамақтан бас тартты ма? Тамақтану жоспарына сай көкөністерді езіп, котлетке жасырып қосу — аналардың бұрыннан келе жатқан әрі пайдалы айласы.'),
  ('b0e5435a-23a4-401e-a5a2-1b672694e080', 'Ауа райының тосынсыйы ⛅', 'Серуенге шыққанда ауа райына алданып, оны тоңдырып алмаңыз. Терезеден қарап қана шешім қабылдамаңыз: Ауа райы және киім көмекшісі арқылы сырттағы жағдайға сай ең қолайлы киім үйлесімін таңдап, содан кейін үйден шығыңыз.'),
  ('c7c50614-edd2-448c-a9f6-e76579ba2f11', 'Түнгі мазасыздық 😭', 'Түн ортасында еш себепсіз жылап оянды ма? Іші кеуіп тұр ма, әлде бұл жай ғана түнгі қорқыныш па? Оны сабырмен құшақтап, дауысыңызды көтермей тыныштандырып, қайта ұйықтатыңыз.'),
  ('ccc01a90-d6a0-43fa-b96b-7ed5976f5309', 'Ажырасудан қорқу 🥺', 'Сіз тіпті дәретханаға кіргенде де, есіктің артында күтіп тұрып жылайды. Ажырасу мазасыздығы кейде күшейе түседі. Әр жолы дауыстап, осында екеніңізді және қазір қайтып келетініңізді айтыңыз.'),
  ('1f77c97d-063c-457e-9c51-eaecc473dae1', 'Жаңа дос іздеу 👫', 'Саябақта өзімен жасты балалармен жүгіріп, оларға жақындауға тырыса ма? Әлеуметтену кезеңі ресми түрде басталды! Қауіпсіздігін алыстан қадағалап, осы алғашқы талпыныстарын мақтанышпен бақылаңыз.'),
  ('3eccfd90-7490-4750-87b2-6db63c387fc8', 'Пижама үшін күрес 👕', 'Кешкісін киіну үлкен шайқасқа айнала ма? Таңдауды өзіне қалдырыңыз: қызыл пижаманы қалайсың ба, әлде көгін бе? Осы кішкентай айла оған шешімді өзі қабылдағандай сезім сыйлайды.'),
  ('a9a77950-254b-44a6-a42a-1aaac4de986d', 'Тыныштық сағаты ☕', 'Күндіз ұйықтамаса, кем дегенде 1 сағаттық Тыныштық сағатын (quiet time) белгілеңіз. Ол өз төсегінде кітап парақтасын, ал Сіз шайыңызды ішіп, ойыңызды тынықтырыңыз.'),
  ('f3bd302c-47f2-4428-b12d-4062c2445dfe', 'Айнадағы дос 👀', 'Оны айнаның алдына апарыңыз. Өз бейнесіне таңырқай қарап, әртүрлі мимика жасағанын бақылаңыз. Бұл — оның өзін-өзі тануына көмектесетін тамаша әрекет.'),
  ('30560050-23fa-4905-9bfc-f3082838579d', 'Музыкамен ұйқыға дайындық 🛀', 'Кешкі әдеттерді орындау қиындап кетті ме? Жылы ванна қабылдап жатқанда, баяу тыныштандыратын музыка қосыңыз. Су мен әуеннің үйлесімі тіпті ең қырсық баланы да тыныштандырады.'),
  ('a805f1c5-c4c1-4bb3-8f2d-828f16d9efaf', 'Тіс тазалау тартысы 🦷', 'Тіс щеткасын аузына жақындатуға мүмкіндік бермей ме? Мұны міндетке емес, ойынға айналдырыңыз. Алдымен оған Сіздің тісіңізді тазалауға рұқсат беріңіз, содан кейін кезек Сізге келсін.'),
  ('c0129df7-df96-4659-882d-c3fd4d3c25e7', 'Тамаққа қырсығу 🥣', 'Екі қасық жеп, тойдым дегендей қашып кете ме? Оны мәжбүрлемеңіз. Тамақпен дұрыс қарым-қатынас қалыптастыру күштеп тамақтандырудан маңыздырақ. Тамақтану санын көбейтіп, мөлшерін азайтыңыз.'),
  ('2f4c11d8-739d-4bb0-9942-69a623d77f66', 'Гормондар дауылы 🩸', 'Кенеттен тәтті жегіңіз келіп, ашуланшақ болып жүрсіз бе? Етеккір күнтізбесін тексеріңіз. Мүмкін, бұл ПМС шығар. Өзіңізді кінәламаңыз, Пайдалы рецепттерден магнийге бай құрма тіскебасарын тауып, ағзаңызға қолдау көрсетіңіз.'),
  ('b69b6089-ef94-4c8e-8537-ca4464897520', 'Себепсіз таңғы дағдарыстар 🛑', 'Көзін аша салысымен бәріне айқайлап, жылай ма? Эмоциялық жүктемені бастан өткеріп жатқан балаңызды сабырмен қалай тыныштандыру керегін Anacan AI сарапшысымен сөйлесіп, бірден біліңіз.'),
  ('c01d73b8-c3b9-41a9-ae94-2f63ced9cfc4', 'Ертегінің соңын өзі айтсын 📖', 'Бүгін кешке ертегі оқығанда, сөйлемдерді аяқтамай тоқтаңыз да, жалғасын оған айтқызыңыз! Тілінің дамуын керемет қолдайтын осындай диалог тәсілдері туралы Anacan AI-дан сұраңыз.'),
  ('0b9c3636-088f-48ec-88e8-94ea05f16477', 'Ластануға толық рұқсат 🏖️', 'Балшықпен немесе сумен ойнағысы келе ме? Ластана берсін! Сенсорлық дамуды қолдайтын осындай ойындарға арналған оңай тазаланатын құралдарды Ұсынылатын өнімдерден табыңыз.'),
  ('28f1c509-c643-44be-b37c-9bbbdb368b42', 'Күн тәртібін талдау ⏱️', 'Кешке ұйықтату 1 сағатқа созыла ма? Ұйқы таймерінің кестесіне қараңыз. Бәлкім, күндізгі ұйқыны қысқартып, кешкі ұйқы уақытын ертерекке жылжытатын кез әлдеқашан келген шығар.'),
  ('e4b4940d-8946-4ebd-8a09-0e41f12848e2', 'Бірге үй жинау 🧹', 'Үйді жинау керек пе? Сіз бөлмені сыпырып жүргенде, бөпеңіз де шүберекпен сүртіп, көмектессін. Үй жинауды көңілді ойынға қалай айналдыруға болатынын Блогтардан оқыңыз.'),
  ('08a08f0f-d89f-412b-a0e0-06835ec16be6', 'Түн ортасындағы айқай 🤖', 'Түн ортасында айқайлап оянып, Сізді танымай қала ма? Бұл түнгі үрей болуы мүмкін. Мұндай жағдайда не істеу керегін және неліктен оны оятпау маңызды екенін дәл қазір Anacan AI-дан сұраңыз.'),
  ('0b568eaa-4297-4b84-983b-14d42c18fb06', '«Неге?» бітпейді 🤔', 'Ол әлемді түсініп, бәрінің себебін білгісі келеді. Оның толассыз сұрақтарына жалықпай, сабырмен жауап берудің жолдарын Anacan AI-дан біліңіз. Сіздің сабырыңыз – оның болашағы.'),
  ('e029b1ab-4432-4819-9a9e-c44e5506a20c', 'Кофені ыстық күйінде ішуге құқығыңыз бар ☕', 'Бөлме шашылып жатыр ма? Жата берсін. Өзіңізге 10 минут бөліп, сол кофені ақыры ыстық күйінде ішіңіз. Сіз мінсіз болуға міндетті емессіз.'),
  ('7d7930a8-9ab0-45ba-bbf4-3a10238d3d72', 'Тығылып жеген шоколад 🍫', 'Асүйге кіріп, одан тығылып тұрып тәтті жеп алдыңыз ба? Өзіңізді кінәламаңыз. Күнделікті у-шуға төтеп беру үшін ананың қандағы қант деңгейін көтеріп алуға толық құқығы бар.'),
  ('946cf6ed-b93e-4326-a1b8-4af737be38ff', 'Сахна енді әкеде 🎭', 'Сіздің «Тамағыңды тауысып же» деген сөзіңіз енді әсер етпей ме? Кезекті әкесіне беріңіз. Ол қасықты ұшаққа айналдырғанда, қырсықтық та ғажайып түрде ғайып болады. Демалып, тамашалаңыз.'),
  ('c17a59df-f595-4941-acce-8426080226bf', 'Қасықтың түсіне байланысты дағдарыс 🥄', 'Тамақты жасыл емес, сары қасықпен бергеніңіз үшін ақырзаман орнағандай болды ма? Терең тыныс алыңыз. Бұл жерден қисын іздемеңіз: ол тек әлемді басқара алатынын тексеріп жүр. Қасықты ауыстырып, жымиыңыз.'),
  ('193d109c-1b4e-4ffc-b28d-b0ef379e189f', 'Қараңғыдағы құбыжық 🌌', 'Жарықты өшіргенде көлеңкелерден қорқа ма? Қиялы дамыған сайын қорқыныштары да шынайы сезіледі. Ақ шу ішінен ана құрсағындағы дыбысты қосып, оған қажет ежелден таныс қауіпсіздік сезімін сыйлаңыз.'),
  ('52e4f8ee-826b-476b-b87c-2f51c60ddd09', 'Кенеттен төгілген жас 😭', 'Көзін аша сала себепсіз жылай ма? Сезімдері шамадан тыс ширыққан балаңызды сабырмен қалай тыныштандыруға болатынын Anacan AI сарапшысымен сырласа отырып біліңіз.'),
  ('9a65afbd-9f9f-42c0-ae08-4e58e8bf0c14', 'Таза ауа қажет 🌳', 'Үйдің төрт қабырғасы балаңызды да, Сізді де қажыта ма? Шыдамдарыңыз таусылмай тұрғанда, Анаға қолайлы орындардан жақын маңдағы саябақты табыңыз. Таза ауа екеуіңіз үшін де ең жақсы ем.'),
  ('51ad8bab-02f3-44e2-b4ec-e672c59c18fa', 'Сізге көмектесейін! 🧹', 'Сіз еден жуып немесе шаң сүртіп жатқанда, қолыңыздағыны алуға тырыса ма? Ол өзін қазірдің өзінде ересек сезінеді. Оған кішкентай шүберек беріп, командаңызға қосылуына мүмкіндік беріңіз — осылайша ол дами түседі.'),
  ('aa639fbc-fe83-44f4-b9ac-8b3bd199a951', 'Энергиясын шығару қажет 🌳', 'Үйдің төрт қабырғасында отыру оны ашушаң етеді. Оны арбасына отырғызыңыз немесе қолынан ұстап, таза ауаға шығыңыз. Табиғаттың тыныштығы бөпеге де, Сіздің көңіл күйіңізге де жақсы әсер етеді.'),
  ('d88a96c2-0998-4bcd-a181-952127acf518', 'Қараңғылыққа үйрену 🌙', 'Тезірек ұйықтауы үшін бөлмедегі барлық артық жарықты, әсіресе планшет экрандарын өшіріңіз. Мелатонин тек қараңғы ортада бөлінеді.'),
  ('5d05da29-b0e2-435e-9e14-f523b38e966b', 'Ұйқысыздықпен ымыраласу 😭', 'Түн ортасында оянып, қайта ұйықтағысы келмей ме? Оған ашуланбаңыз. Себебін (ауырсыну, іштің кебуі, қорқыныш) анықтап, құшақтап, қайта ұйықтауын сабырмен күтіңіз.'),
  ('7d1bf85e-e587-4da1-8ee8-b719514d8f71', 'Кетпейтін дақтар 👗', 'Киімдерінің үнемі былғануы Сізді шаршата ма? Бұған ашуланбаңыз. Ол тағамдарды танып-біліп жүр. Силиконды алжапқыштарды қолданыңыз және осы түрлі-түсті, былғаныш сәттерден жай ғана ләззат алыңыз.'),
  ('202cf19c-e94a-473d-b9ba-56a3c22509c2', 'Сізге көмектесейін 🧽', 'Сіз шаң сүртіп жатқанда, қолыңыздағы шүберекті тартып ала ма? Ол өзін ересек сезінгісі келеді. Оған кішкентай дымқыл шүберек беріңіз. Тазалағаннан гөрі көбірек былғайды, есесіне өзіне деген сенімі артады.'),
  ('4f32f07a-4c87-40d2-83db-3d4785cda04f', 'Үйдің акустикасы 🤫', 'Күндізгі ұйқыға әрең жатты. Енді үйдегі болмашы тықырдың өзі Сізді ашуландыруы мүмкін. Дереу Дыбыс өлшегішті қосып, терезелерді жабыңыз да, осы мүлгіген тыныштықтан ләззат алыңыз.'),
  ('f750ae50-4664-4363-8c07-389c3fa0e9cb', 'Аяқ киім кию майданы 👟', 'Оң аяқ киімді сол аяғына киіп алып, шешкісі келмей ме? Солай жүре берсін. Қазір сыртқы көрініс пен дұрыстықтан гөрі оның еркіндік сезімі маңыздырақ.'),
  ('bcbba6df-cc6d-45d3-b424-d121d2ee2ecb', 'Қараңғылықпен достасу 🌙', 'Бөлменің жарығын толық өшіріңіз. Жанына жатып, күні бойы болған оқиғаларды оған өте бәсең дауыспен, сыбырлап айтып беріңіз. Сыбырлау — миды ұйқыға дайындайтын ең табиғи тәсіл.'),
  ('db4f7065-c5e8-4316-a750-ff341f726db5', 'Кішкентай суретші 🎨', 'Қарындашпен қабырғаға немесе қағазға дөңгелектер салып жүр ме? Бұл — ірі моториканың дамуындағы үлкен серпіліс.'),
  ('eacddbb3-0cac-4a07-a3b8-0e2751f215e2', 'Балабақша іздейтін уақыт келді ме? 🏫', '3 жасқа таяғанда балабақша туралы ой маза бермей жүр ме? Мұны жалғыз ойлаудан шаршасаңыз, Anacan қауымдастығына қосылып, басқа аналардан тәжірибесі мен кеңестері туралы сұраңыз.'),
  ('37d0e7fb-1a1f-4126-b2cd-6303007be080', 'Қиялдағы шай дастарханы ☕', 'Бос кесені Сізге ұсынып, Шай іш дейді ме? Символдық ойындар — бала дамуының нағыз жауһары. Сол кеседегі бөлме температурасындағы қиялдағы шайды ерекше сүйсініп ішіңіз.'),
  ('aaf79d19-89d8-4b33-8891-ceb716e86559', 'Киімдерінің бәрі дақ 🎨', 'Пижамасына тамақ төгіліп, үсті-басы бояу болып жүр ме? Балалар тап-таза болып өспеуі керек, олар әлемді зерттеп жүріп кірлеуі керек. Силикон алжапқыштарды қолданыңыз, ал қалғанын кір жуғыш машинаға тапсырыңыз.'),
  ('d6cb9a79-b32c-4069-9d3c-ac4297c600b6', '15 минуттық қашу 🛀', 'Дәретханаға кіріп, есікті жауып алып, жай ғана телефон қарап отырсыз ба? Иә, бұл — аналардың бәрінен қашып, тынығуының ең танымал тәсілі. Ешкімге есеп бермей, сол тыныштықта біраз отырыңыз.'),
  ('0db2d13e-0a0c-45f3-a6f3-c4bf73384a78', '«Мені сүйме!» деген батылдық 🛑', 'Туыстардың бірі сүйгісі келгенде, бөпеңіз бетін бұрып, оны итере ме? Оның жеке шекарасын бұзбаңыз! Рұқсатсыз жанасуға қарсылық білдіруі — оның қауіпсіз әрі дені сау болашағы үшін маңызды.'),
  ('aaaf42f2-3e96-489f-b1d3-e331bf487627', 'Түнгі үрейдің шындығы 😭', 'Түн ортасында көзі жұмулы күйде жылап оянып, ешкімді естімей ме? Бұл — түнгі үрей ұстамасы. Оны сілкілемеңіз және оятуға тырыспаңыз. Тек жанында болып, өзін қауіпсіз сезінуіне көмектесіңіз.'),
  ('be944652-2efc-45de-a928-8d34a23e4645', 'Табиғат аясында сергіп қайту қажет 🌳', 'Бүгін үйдегі бейберекетке шыдау мүмкін болмай кетті ме? Дереу «Ауа райы және киім» құралын қарап, лайықты киініп, ең жақын саябаққа шығыңыз. Таза ауа — баланы тыныштандырудың ең жақсы тәсілі.'),
  ('09900d01-e715-436d-95eb-cb7b3165dfb1', 'Сөздердің жаңа нұсқасы 🗣️', '«Су» деудің орнына «шу», «үлкен» деудің орнына «үккен» дей ме? Сондай сүйкімді естілгендіктен, күлмеу қиын. Дегенмен миы дұрыс нұсқасын есте сақтауы үшін әр жолы сөзді дұрыс әрі мейіріммен қайталап айтыңыз.'),
  ('9853e360-5dcb-4105-84a8-77759e13bdcd', 'Ертегінің соңын өзі жазсын 🪄', 'Классикалық кітаптардан екеуіңіз де жалықтыңыздар ма? Бұл жолы «Ақылды ертегілерде» оқиғаның соңын балаңызға таңдатыңыз. «Қалай ойлайсың, кейіпкерге кім көмектесті?» деп сұрап, қиялына ерік беріңіз.'),
  ('d5f06496-2705-48a5-8325-2f0c28ac0a0f', 'Қуатыңыз таусылғанда 🔋', 'Бүгін ештеңеге шамаңыз жоқ па? «Пайдалы рецепттерден» 5 минутта дайындалатын, блендермен араластырылған, темір мен дәрумендерге бай смузи жасап, жүре ішіңіз. Өзіңізге қамқор болыңыз.'),
  ('42bb5c65-e45f-45b5-8da0-322b9acd1ab4', 'Дүкен тізімі — құтқарушы 🛒', 'Жадыңызға сеніп, дүкенге барып, бала жөргегін ұмытып қайттыңыз ба? Ондай да болады. Барлық қажетті затты «Сатып алу тізіміне» жазуды әдетке айналдырыңыз, Сіздің орныңызға қолданба еске салсын.'),
  ('8f5ba264-bfbc-4e71-b81e-4cbb2fe23c54', 'Екеуіңізге арналған тосын уақыт 🥂', 'Балаңыз күтпеген жерден ерте ұйықтап қалды! Осындай сирек сәтті үй жинауға жұмсамаңыз. Жұбайыңызбен бетпе-бет отырып, теледидарды өшіріңіз де, жай ғана бір-біріңізден күндеріңіздің қалай өткенін сұраңыз.'),
  ('92ad5bcb-5fa6-44a6-8e27-05fc8347c1e3', 'Пазл құрастыру шеберлігі 🧩', 'Пішіндерді сәйкес тесіктерге салуға барын салып жүр. Қателессе де, ашуланса да, бірден көмектеспеңіз. Ол мәселені шешу дағдысын дәл осы байқап көру мен қателесу арқылы үйренеді.'),
  ('2fb64a2b-9948-4425-9837-80add71d4e54', 'Әкемен саябақты зерттеу 👨‍👧', 'Ана болу — 24/7 кезекшілік ету емес! Бүгінгі серуенді әкесіне тапсырыңыз. Екеуі бірге балшық кешіп ойнасын, ал Сіз диванға жайғасып, тыныштықтан ләззат алыңыз.'),
  ('9928c8dc-9b21-49a6-b0c4-fd4704041409', 'Бой мен салмақтың күрт өсуі 📏', 'Шалбарының балағы тағы да қысқарып қалды ма? Ол күн сайын көз алдыңызда өсіп келеді! Даму трекеріне қазіргі өлшемдерін енгізіп, ұйқысыз түндеріңіздің жемісі болған өсу қисығына мақтанышпен қараңыз.'),
  ('ed4eff7e-2e68-4d65-af30-186f1086a150', 'Классикалық музыканың кереметі 🎶', 'Кешкісін себепсіз мазасызданып, ашулана бастады ма? Теледидарды өшіріп, жарықты бәсеңдетіңіз де, бөлмеде классикалық музыканы өте баяу қосыңыз. Су мен музыканың үйлесімі үйдегі көңіл күйді өзгертеді.'),
  ('331370dc-1940-499c-abdb-15eb6fc3307a', 'Сорпадағы жасырын агенттер 🥦', 'Жасыл түсті тағамның бәріне бойкот жариялады ма? Уайымдамаңыз. Тамақтану жоспарын пайдаланып, көкөністерді езбе күйіне келтіріп, котлет пен тұздықтарға жасыру — аналардың ежелден келе жатқан пайдалы айласы.'),
  ('a9d400f1-6a44-4584-a532-eeed75cc3207', 'Ойдан шығарылған әндер 🎤', 'Ойыншықтарын реттеп жүріп, ешбір тілде жоқ сөздермен өздігінен ән айтып жүр. Оның сөздік қоры мен ырғақты сезіну қабілеті қатар дамып келеді. Даму трекеріне осы жаңа музыкалық кезеңді міндетті түрде енгізіңіз.'),
  ('e7308375-84bd-4b4e-9322-163dcd46ff8e', 'Қырсық пижама 👕', 'Киіну үлкен шайқасқа айналды ма? Таңдауды өзіне қалдырыңыз: Қызыл пижаманы киесің бе, әлде көгін бе? Бұл кішкентай айла оған шешімді өзі қабылдағандай сезім сыйлап, қарсылығын тоқтатады.'),
  ('346ca24f-e8f9-47c9-9cc2-dc1b86281214', 'Ажырасу мазасыздығы 🥺', 'Бөлмеден бір сәтке шығып кетсеңіз де, артыңыздан жылайды. Ажырасу мазасыздығы кейде қайта пайда болады. Әр жолы дауысыңызды естіртіп, «Мен осындамын», «Асүйдемін», «Қазір келемін» деп, алыстан-ақ оған сенімділік сыйлаңыз.'),
  ('afa94b0b-8399-4813-8b1a-8a243185fcf4', 'Мінсіз болуға деген қысым 🛑', 'Басқа балалар түстерді атап жүр, ал Сіздің балаңыз әлі қаламай ма? Салыстыруды дереу тоқтатыңыз! Әр баланың даму қарқыны әртүрлі. Сіздің балаңыз өз қарқынымен дамып келеді және бұл — қалыпты жағдай.'),
  ('d5610b5c-f92a-4668-b551-ccf2ba5bd9e4', 'Әкенің құпия тәсілі 👨‍🍼', 'Күндізгі шаршаудың өзі Сізге жеткілікті. Кешке баланы ұйқыға дайындау мен тісін тазалату үдерісін әкесінің ойын түріндегі тәсілдеріне тапсырып, өзіңіз бір шетте тыныш қана шайыңызды ішіңіз.'),
  ('47b60c96-b788-4cad-9b79-643917c1b944', 'Педиатриялық күмәндар 🤖', '32 айлық баланың бойы мен салмағының графигі Сізді кенеттен алаңдатты ма? Интернет форумдарынан қорқынышты ауруларды іздемей, Anacan AI-дан нақты әрі ғылыми негізделген ақпарат алыңыз.'),
  ('7f82c861-b627-4e20-b2ed-f2fb9f45756b', 'Ұйқыға жайлы табиғи орта 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — мидың ең сезімтал кезі. Терезеден келетін дыбыстарды бәсеңдету үшін бөлмеде ақырын ақ шу шығаратын құрылғыны (мысалы, жаңбыр дыбысын) қосыңыз.'),
  ('9bea836b-e06e-49f0-af98-259fe4009523', 'Саған түсіндіріп берейін! ☝️', 'Ол бәрін саусағымен көрсетіп, бірінен соң бірі сұрақ қояды. Ол Сізден айналасындағы заттардың атауын білгісі келеді. Бұл — қарым-қатынас дамуындағы үлкен серпіліс! Шаршасаңыз да, сол заттардың атауын сабырмен қайталаңыз.'),
  ('68ebc7a3-cb63-4696-9089-9b8d5bd20d47', 'Жай ғана құшақтаңыз 🫂', 'Ешқандай ойынның, кітаптың немесе ертегінің қажеті жоқ. Бүгін кешке оны жай ғана кеудеңізге қысып, жұпар иісін терең жұтыңыз да, қараңғыда оның Сіз үшін қаншалықты қымбат екенін сыбырлап айтыңыз.'),
  ('e7127e7f-2c80-4b8e-aba6-2bcc0bbe7513', 'Бірге тазалайық 🧹', 'Үйді жинау керек пе? Бөлмені сыпырып жатқанда, ол да шүберекпен сүртіп, Сізге көмектессін. Үй жинауды командалық жұмыс пен көңілді іске айналдыру жолдарын Блогтардан оқыңыз.'),
  ('f0084bbf-ef12-44c3-80b2-42b0bd99f526', 'Мен қатты шаршадым 🔋', 'Барлығы Сізден күш-қуат күтеді, ал Сіздің қуатыңыз таусылған. Бүгін тамақ әзірлемей-ақ, тапсырыс беріңіз. Мінсіз ана болу — бәрін жалғыз істеу керек деген сөз емес. Өзіңізге демалуға рұқсат етіңіз.'),
  ('001946c3-28e7-4dd7-a8dd-6edeeb1c5013', 'Шеңберден пішінге 🎨', 'Қарындашпен қабырғаға немесе қағазға шеңберлер салып жүр ме? Бұл тентектік сияқты көрінгенімен, шын мәнінде ұсақ моториканың дамуындағы үлкен серпіліс.'),
  ('447f446e-b226-43bb-8269-02d7d4965189', 'Судың үйлесімі 🛀', 'Күні бойы жүгіріп, бөпеңіз де, Сіз де әбден шаршадыңыздар. Жылы ванна қабылдаған кезде баяу табиғат дыбыстарын қосыңыз. Судың үйлесімі тіпті ең қырсық баланы да ұйқыға дайындайды.'),
  ('706c71ad-a073-4d24-bc8e-9dc899c5ba4e', 'Дүкендегі ашу ұстамасы 🛒', 'Касса алдында тәтті сұрап, айқайлап жатыр ма? Айналадағылардың «тәрбиесіз бала» дегендей көзқарасына мүлде мән бермеңіз. Сабырмен көзіне қарап, ережені түсіндіріңіз және шешіміңізден таймаңыз.'),
  ('4144a3ff-720b-4a72-a2d5-5866dd12fa04', 'Күн тәртібі бұзылып жүр ме? ⏱️', 'Кешке ұйықтауына 1 сағаттан көп уақыт кете ме? Ұйқы таймерінің кестесін қараңыз. Бәлкім, күндізгі ұйқыны едәуір қысқартып, кешкі ұйқы уақытын ертерек жылжытатын кез әлдеқашан келген шығар.'),
  ('556e8775-c182-4e9f-b2c6-f0cf109ff616', 'Жануарларға еліктеу 🐶', 'Тек дыбысын салып қана қоймай, ит сияқты еңбектеп, мысық сияқты еркелей ме? Дене қимылы мен қиялы ұштасып жатыр. Сіз де онымен бірге кілем үстіндегі осы ойынға бар күш-жігеріңізбен қосылыңыз.'),
  ('b521243e-fc9e-4c87-849b-f17e742b8529', 'Күндізгі ұйқы дағдарысы 🥱', 'Төсекке жатқысы келмей, жылай ма? 3 жасқа қарай кейбір балалар күндізгі ұйқыдан бас тарта бастайды. Күресудің орнына, «Тыныштық сағатын» жариялап, төсекте ойыншықтармен үнсіз ойнауды ұсыныңыз.'),
  ('9d29683b-c9aa-4b14-81df-782b8e1da8f5', 'Ұйықтағысы келмей, қараңғыдан қорқа ма?', 'Бөлмені толық қараңғылап, қабырғаға қолыңызбен құс пен иттің көлеңкесін түсіріңіз. Қорқынышты ойынға айналдырып, оның қараңғылықпен достасуына көмектесіңіз.'),
  ('a452ae82-775c-477d-b99f-ddd24ddd54fa', 'Тамақтану белгілері 🥣', 'Екі қасық жеп, тойғанын білдіріп, орындықтан қашып кете ме? Оны мәжбүрлемеңіз. Тамақпен дұрыс қарым-қатынас қалыптастыру тәрелкені міндетті түрде тауысып жеуден әлдеқайда маңызды. Қарны ашқанда өзі сұрайды.'),
  ('aa995666-2118-43a4-9171-858348f38b54', 'Суретті оқиғалар 📖', 'Кітаптағы жануарларды немесе балаларды көргенде оларды түртіп, «Бұл не істеп жатыр?» деп сұрай ма? Оның көру арқылы қабылдауы таңғаларлық деңгейде дамып келеді. Онымен бірге кейіпкерлер туралы қызықты әрі күлкілі оқиғалар ойлап табыңыз.'),
  ('076945c8-0a00-4e34-b0d0-2a0bb6a70d19', 'Ұйқы кестесі өзгеріп жатыр ма? 😭', 'Түн ортасында оянып, қайта ұйықтағысы келмей ме? Оған ашуланбаңыз. Себебін анықтап, жай ғана жанында екеніңізді сездіріп, ақырын сипаңыз да, ұйықтап кеткенін күтіңіз.'),
  ('3d9ffa52-2fa2-4130-82de-58bdbc77e7b6', 'Ауа райының тосынсыйы ⛅', 'Серуенге шыққанда ауа райына алданып, оны тоңдырып алмаңыз. Терезеден қарап қана шешім қабылдамаңыз: Ауа райы және киім көмекшісі арқылы даладағы желге сай киім үйлесімін таңдап, үйден алаңсыз шығыңыз.'),
  ('50a3f6bc-f0a4-4606-972d-9c8a2cc70695', 'Еркін ойынның пайдасы 🧸', 'Оны әр минут сайын көңілдендіріп, үнемі жаңа ойын ойлап табуға міндетті емессіз. Баланың зерігуі — шығармашылыққа бастайтын алғашқы қадам. Бөлмеде өз бетінше бірдеңе зерттеп, жаңалық ашуына мүмкіндік беріңіз.'),
  ('0e8938b3-51a2-479f-a598-94b98e255136', 'Дүкен тізімінде ұмыт қалғандар 🛒', 'Дүкенге барғанда ең маңызды затты ұмытып кете бересіз бе? Сатып алу тізімі қолданбада Сізді күтіп тұр. Қажет заттарды сонда жазып қойыңыз, жұбайыңыз жұмыстан қайтарда бәрін тізім бойынша алып келеді.'),
  ('2b8de8fb-82bc-4b54-a795-1fffd716ddd5', 'Дене тілі арқылы қарым-қатынас 🗣️', '«Жүрейік пе?» дегенде қолдарын көтере ме немесе бір нәрсені қаламаса, басын қатты шайқай ма? Оның түсіну қабілеті ғажап қарқынмен дамып келеді! Оған түсінгеніңізді білдіретін жылы сөздермен жиі жауап беріңіз.'),
  ('db645804-58ab-429b-bd1f-cae1d65c9e1e', 'Музыкамен ұйқыға дайындалу 🎶', 'Кешке қарай себепсіз басталатын мазасыздықты жеңіл классикалық музыкамен басып көріңіз. Көбіне осы қарапайым, бірақ тиімді тәсіл үйде нағыз ғажайып жасап, бөлмеге тыныштық сыйлайды.'),
  ('f865873b-dd5e-4259-93bf-a8d4ef0dc1b0', 'Жасыл түске қарсылық 🥦', 'Көк шөпті тәрелкеден алып тастай ма? Дастарқанды ұрыс алаңына айналдырмаңыз. Пайдалы рецепттерден көкөніс жасырылған үй кекстерін тауып, қажетті дәрумен мөлшерін білдірмей-ақ толықтырыңыз.'),
  ('00bb1bab-f1b2-408a-929e-869ffd6367c6', 'Сыбырдың сиқыры 🌙', 'Бөлменің жарығын толығымен өшіріңіз. Жанына жатып, күні бойы болған оқиғаларды өте бәсең дауыспен құлағына сыбырлап айтып беріңіз. Сыбырлау — миды ұйқыға дайындайтын ең табиғи әрі тыныштандыратын әдіс.'),
  ('6948f738-9261-43c8-87d9-90b884505db8', 'Брокколи детективі 🥦', 'Тәрелкедегі жасыл көкөністерді байқап, шетке ысырып қоя ма? Ендеше жасыру өнеріне көшіңіз. Пайдалы рецепттер бөлімінен көкөністерді езбе түріне келтіріп, дәмді котлеттердің ішіне жасыруға көмектесетін айлакер рецепттерді табыңыз.'),
  ('c7ff87eb-a94f-4bb4-85c6-085ae172efe9', 'Сазгердің алғашқы концерті 🎤', 'Ойыншықтарын реттеп жүріп, ешбір сөздікте жоқ сөздермен, бірақ ерекше ырғақпен ән айта ма? Бұл зияткерлік серпілісті тоқтатпаңыз, оны Даму трекеріне бөпеңіздің алғашқы туындысы ретінде тіркеп қойыңыз.'),
  ('331b6c40-0fb5-4851-9134-928632566339', 'Табиғатқа шығу жоспары ⛅', 'Төрт қабырға бөпеңізді де, Сізді де ашуландырып жіберді. Ауа райы мен киім құралын тексеріп, тез жиналыңыз да, саябаққа шығыңыз. Таза ауа бүлдіршіннің ең қатты қыңырлығын да тез басады.'),
  ('56824801-bf77-4597-b1ce-5aa469fe1db9', 'Алтын тыныштық 🤫', 'Үйдегі қарбалас ақыры басылып, бөпеңіз терең ұйқыға кетті. Дыбыс өлшегішті қосып, бөлмедегі тыныштық деңгейін (децибелін) көріңіз де, 15 минут бойы ешбір экранға қарамай, осы алтын тыныштықтан ләззат алыңыз.'),
  ('7614704a-6622-4005-bcc5-442f422f2e2c', 'Авангард сән 👗', 'Шалбарын басына киіп алып, бөлмеде паңдана жүр ме? Араспаңыз. Мұндай күлкілі тәжірибелер — оның еркіндік пен даралыққа ұмтылысы. Иә, оғаш көрінеді, бірақ бұл сәттер сондай сүйкімді.'),
  ('45e0f5b4-5219-47b6-9a9e-bcadb9ed774d', 'Дүкенде бәрін ұмыту 🛒', 'Жадыңызға сеніп дүкенге барып, ең қажет затты ұмытып қайттыңыз ба? Барлық керекті затты қолданбадағы Сатып алу тізіміне жазуды әдетке айналдырыңыз — цифрлық жадыңыз Сізді құтқарсын.'),
  ('295a4c1e-3bba-40c5-820d-04095aefe60e', 'Үй шаруасын кім істейді? 🌪️', 'Үй шаруасы жиналып қалды ма? Қала берсін. Бүгін серігіңізден үй шаруасын өз мойнына алуын сұраңыз. Сіз демалыңыз, өйткені бұл үйдегі ең маңызды әрі күш-қуатқа мұқтаж жан — Сіз.'),
  ('546e217e-8060-4a89-877d-29e71165dae1', 'Командалық қолдау 🥂', 'Қиын күнді артта қалдырдыңыздар. Бөпе ұйықтағаннан кейін серігіңізбен бірге шай құйып, «Біз мұның бәрін шынымен керемет атқарып жүрміз» деп бір-біріңізді жігерлендіріңіздер.'),
  ('f23e5345-9d7c-4e2d-871d-a259a849da6f', 'Суреттердің мағынасын түсінеді 📖', 'Кітаптағы кейіпкерлерді көргенде оларға қолын тигізіп, «Мынау не істеп жатыр?» деп сұрай ма? Оның көру арқылы қабылдауы таңғаларлық деңгейде дамып келеді. Бірге оқыған кітаптарыңызға мүлде жаңа, ойдан шығарылған соңын құрастырыңыздар.'),
  ('3edbcdb0-49d0-4dd6-973b-d76b6099a642', 'Тазалық синдромы 🌪️', 'Үйді жинап, тазалап шықтыңыз, бірақ 10 минуттан кейін бәрі қайтадан жарылыс болған жердей көріне ме? Бүгін шашылған заттарға мән бермей-ақ қойыңыз. Диванға жайғасып, кофеңізді ішіп болғанша орныңыздан тұрмаңыз.'),
  ('3eea40c1-536e-46c3-bd20-2051d2e3ccae', 'Әкесінің дипломатиялық шешімі 👨‍👧', 'Сіздің «Тамағыңды тауысып же» деген сөзіңіз енді әсер етпей ме? Кезекті әкесіне беріңіз. Ол қасықты ұшатын ғарыш кемесіне айналдырғанда, қырсықтық та ғажайып түрде жоғалып кетеді. Сіз демалып, осы көріністі тамашалаңыз.'),
  ('ac669cdb-bbf4-4741-8460-56b46118bbec', 'Таңғы адвокат іске кірісті 💼', '«Бұл жейдені емес, басқасын киемін!» Енді бөлмеде жай бала емес, Сізбен кәсіби келіссөз жүргізіп отырған кішкентай адвокат бар. Дауласпаңыз, оған тек 2 нұсқа ұсынып, шешімді өзі қабылдағандай әсер қалдырыңыз.'),
  ('8805c85d-beba-4d76-905f-2991bc6002f2', 'Түбекке үйренудегі жеңіс 🚽', 'Дәретінің келгенін сезіп, түбекке өзі жүгіре ме? Бұл — үлкен жеңіс!'),
  ('9a0661d6-3164-4575-bc05-58b2efdd3f26', 'Ертегіні өзі ойлап тапсын 📖', 'Бүгін кешке кітапты бір шетке қойыңыз. Оқиғаны өзі айтып берсін! Оның таңғажайып қиялын дамытуға көмектесетін диалог тәсілдерін Anacan AI-дан сұраңыз.'),
  ('8cab638c-2941-4e59-9d14-fa8e3dd46600', 'Көрінбейтін қонақтар 👻', 'Дивандағы бос орынға қарап, әлдене айтып, тіпті көрінбейтін досына шай құйып жүр ме? Қиялдағы достар кезеңі қызған шақ! Бөпеңіз енді өз әлемінің сценарисіне айналды. Бұл қойылымды күлімсіреп тамашалаңыз.'),
  ('d368c6ed-7184-4b38-b97e-6f9c7890966b', 'Судың жанды сергітер күші 🛀', 'Күні бойы жүгіріп, бөпеңіздің де, Сіздің де жүйкеңіз жұқарды. Жылы ванна — жай ғана тазалық үшін емес, судың бойдағы ширығуды басып, күннің жағымсыз әсерін шайып әкететін тылсым күшін сезіну үшін де қажет.'),
  ('37a646c6-efce-4c74-8923-488fc7f72713', 'Асүйдегі әкенің кезегі 👨‍🍳', 'Ана болу — жалғыз жүгіріп өтетін марафон емес. Демалыс күнгі түскі асты әкесі дайындап, бөпені тамақтандырсын, ал Сіз диванға жайғасып, бағалы үзілістің рақатын көріңіз.'),
  ('38899b21-6787-484d-901a-76cdc0b3deb6', 'Осындай жалғыз мен бе? 💬', 'Қатты шаршадыңыз ба және Сізді ешкім түсінбейтіндей көріне ме? Бірден Anacan қауымдастығына жазыңыз. Онда дәл Сіз сияқты ұйқысыз жүрген мыңдаған ананың «мен де сен сияқтымын» деген хабарламалары Сізге күш береді.'),
  ('c34613c3-022a-46ef-a284-68eea41b09f7', 'Сценарийді өзі жазсын 🪄', 'Классикалық кітаптардан екеуіңіз де жалықтыңыздар ма? Бұл жолы интерактивті ертегінің соңын балаңызға таңдауға мүмкіндік беріңіз. «Қалай ойлайсың, кейіпкерге кім көмектесті?» деп сұрап, ұйықтар алдында оның қиялын оятыңыз.'),
  ('29d7734b-e03c-4396-8939-93b0dfe516dc', 'Анаға қажетті нәрлі ас 🥗', 'Оны тойдыру үшін 3 түрлі мәзір ойлап таптыңыз, ал өзіңіз жүре тамақтанып алдыңыз ба? Пайдалы рецепттердің ішінен 10 минутта дайындалатын, дәруменге бай салатты таңдап, өзіңізге де қамқорлық жасаңыз.'),
  ('bdf82e6a-e184-465d-ab37-a709d395d1d4', 'Әкенің ым-ишара театры 🤡', 'Сіздің күлдіруге тырысқаныңыз әсер етпей қалғанда, әкесінің оғаш дыбыстары жағдайды бірден құтқарады. Кешкі мазасыздық кезінде кезекті оған беріп, көңілді күлкіні сырттай тамашалаңыз.'),
  ('f6962d3f-b694-40e4-9faf-0cd32b36de3d', 'Кішкентай көмекші 🧽', 'Сіз шаң сүртіп жатқанда, қолыңыздағы шүберекті тартып ала ма? Ол өзін ересек әрі команданың бір мүшесі ретінде сезінгісі келеді. Оған дымқыл шүберек беріңіз. Тазалағаннан гөрі көбірек былғайды, есесіне өзін маңызды сезінеді.'),
  ('7794de7c-0d82-4deb-b825-a11099a42226', 'Ұйқысыздық жарияланды 🥱', 'Төсекке жатқысы келмей, қырсығып жүр ме? Кейбір балалар осы кезеңде күндізгі ұйқыдан бас тартады. Онымен күресудің орнына «Тыныштық сағатын» жариялап, төсекте ойыншықтарымен үнсіз ойнауды ұсыныңыз.'),
  ('a2143b10-3a17-415c-a09b-d16e4c9ace11', 'Түнгі қорқыныштың құпиясы 😭', 'Түн ортасында көзін ашпастан жылап оянып, ешкімді естімей ме? Даусын «Жылауды талдау» құралына тыңдатыңыз. Егер бұл түнгі қорқыныш болса, оны оятуға тырыспаңыз. Тек жанында болып, өзін қауіпсіз сезінуіне көмектесіңіз.'),
  ('df260082-4554-4a41-9637-0bed22c395ae', 'Тамақ талғау дағдарысы 🍝', 'Кеше сүйсініп жеген тағамынан бүгін бас тартып отыр ма? Дастарқанды шайқас алаңына айналдырмаңыз. «Тамақтануды бақылау» құралы арқылы апталық теңгерімді тексеріп, «Пайдалы рецепттер» бөлімінен тағамды ұсынудың ерекше әрі қызықты тәсілдерін табыңыз.'),
  ('181acf25-f33b-4b1f-a3df-4084c1837a73', 'Жараланған қонжықтың дәрігері 🩺', 'Ойыншығы құлап қалса, оны сипап, «Жылама» дей ме? Бөпеңізде таңғажайып жанашырлық сезімі қалыптасып келеді! Тұлға дамуының осы бір алтын кезеңін дереу «Дамуды бақылау» бөліміне жазып қойыңыз.'),
  ('41b6bff2-f792-4d2c-a887-2fbdd7ee533a', 'Мелатонинге шақыру 🌙', 'Тезірек ұйықтауы үшін бөлмедегі барлық артық жарықты өшіріп, көгілдір экрандарды алып тастаңыз. Ұйқы гормоны (мелатонин) қараңғы әрі технологиясыз ортада ғана жылдам бөлінеді.'),
  ('afdd5971-fffc-43af-9956-3bc9d2687359', 'Құм алаңындағы саясат 🧸', 'Саябақта шелегін ешкімге бермей ме? Бұл өзімшілдік емес, балаңыз жеке меншік ұғымын енді танып жатыр. Оны ұялтпай, кезекпен ойнауды ұсыныңыз да, дипломатиялық дағдарысты шешіңіз.'),
  ('0574f644-1505-478c-8228-ceb707400249', 'Көзбен байланыс маңызды 🥂', 'Балаңыз күтпеген жерден ерте ұйықтап қалды! Осындай сирек сәтті үй жинауға жұмсамаңыз. Жұбайыңызбен бетпе-бет отырып, теледидарды өшіріңіз де, бір-біріңіздің көзіңізге қарап, күннің қалай өткенін сұраңыз.'),
  ('091c7303-14ec-4220-83cd-0ec1c91a3ce2', 'Жанды диктофон 🎙️', 'Аузыңыздан шыққан кез келген сөзді тотықұс сияқты бірден қайталай ма? Ол — Сіздің жанды айнаңыз. Оның жанында айтатын сөздеріңіз бен білдіретін эмоцияларыңызға екі есе мұқият болыңыз, өйткені ол бәрін қайталайды.'),
  ('32681963-7779-41a7-9090-772ca76143b7', 'Шашып тастауға рұқсат 🌪️', 'Күн сайын бір ойыншықтарды қорапқа жинаудан шаршадыңыз ба? Бүгін жинамай-ақ қойыңыз! Үй — мұражай емес, тіршілік қайнап жатқан орын. Шашылған заттарға емес, балаңыздың жаңалық ашудан алатын қуанышына назар аударыңыз.'),
  ('500b7216-41e0-45a9-a2b9-20687055dfdc', 'Кезек әкеде 👨‍🍼', 'Күндізгі шаршаудың өзі де жеткілікті. Кешке баланы ұйқыға дайындауды, тісін тазалатуды және пижамасын кигізуді әкесіне тапсырып, өзіңіз оңаша отырып, тыныштықта шайыңызды ішіңіз.'),
  ('be6a944e-f3ba-401c-9b99-70457d5df68b', 'Анашым, маған қарашы! 👀', 'Сіз телефонға немесе басқа нәрсеге қарап отырғанда, ол келіп бетіңізді өзіне қарай бұра ма? Оған Сіздің бар назарыңыз қажет. Көзіне қарап тыңдау арқылы оның маңызды екенін сездіріңіз.'),
  ('e95e1a48-e2fe-47ab-898a-2c6c20ef5f3c', 'Сөйлемдер ертегіге айналады 🗣️', 'Бөпеңіз сөздерді біріктіріп, күлкілі, қиял-ғажайып оқиғалар айтып жүр ме? Сөздік қоры қарқынды өсіп жатыр!'),
  ('13a8c002-9f52-4112-970b-14cac50a9b5c', 'Бөлме акустикасы 🤫', 'Ұйықтап бара жатқан сәтте дыбыстарға сезімталдығы артады. Терезеден келетін дыбыстарды бейтараптандыру үшін Дыбыс өлшегішті тексеріп, бөлмеде бәсең ақ шу (white noise) құрылғысын қосыңыз.'),
  ('4892459c-b0fb-4a8c-89d7-1bb93e680c5b', 'Кішкентай инженер 🤔', 'Мұны лақтырсам не болады?, Бұл батырма не үшін керек? Ол үнемі физикалық тәжірибелер жасап көреді. Осылай үйреніп жүр! Үйдің қауіпсіздігін баланың бойы деңгейінен тағы бір рет тексеріп шығыңыз.'),
  ('ee52c904-b97d-4a34-b7fb-b60ab86aadcd', 'Ананың энергия батончигі 🥑', 'Күнделікті қарбаласта түскі асты жүріп бара жатып ішпеңіз. Пайдалы рецептілердің ішінен қуат беретін тіскебасар таңдап, кем дегенде 10 минут диванда жатып, өзіңіздің дұрыс тамақтануыңызға басымдық беріңіз.'),
  ('51decf20-cf70-4c72-beb9-3712b300a999', 'Қуаласпақ марафоны 🏃‍♂️', 'Енді жай жүрумен шектелмейді: Сіз шақырғанда, жүгіріп барып тығылады. Бөлмедегі қауіпті кедергілерді алып тастап, осы көңілді қуаласпаққа Сіз де қосылыңыз.'),
  ('aff77c93-ed92-44bc-9afd-e64eb6ce5292', 'Психологияны танып біліңіз 📱', 'Балаңыздың бәріне «жоқ» дей беруі Сізді шаршатты ма? Қолданбадағы психологиялық блогтарды оқып, оның миында жүріп жатқан осы даму дауылының терең себептерін түсініңіз.'),
  ('e18b761a-6fd6-438d-896c-ec7bd458b9c2', 'Қараңғылықтың күші 🌙', 'Тезірек ұйықтауы үшін бөлмедегі барлық қосымша жарықты өшіріп, планшет экрандарын сөндіріңіз. Мелатонин қараңғы әрі технологиясыз ортада ғана жылдам бөлінеді.'),
  ('0953ad75-dec1-4dc2-9d50-5eb074aad008', 'Жай ғана құшақтаңыз 🫂', 'Ешқандай ойынның, кітаптың немесе ертегінің қажеті жоқ. Бүгін кешке оны жай ғана бауырыңызға басып, жұпар иісін терең жұтыңыз да, қараңғыда оның Сіз үшін қаншалықты қымбат екенін сыбырлап айтыңыз.'),
  ('4df5b42c-f87e-4fa7-b1d2-b3aa6d779c67', '«Бұл не?» кезеңі ☝️', 'Бәрін саусағымен көрсетіп, атын сұрай ма? Ол Сізден айналасындағы дүниелерді атап беруді сұрап жүр. Бұл — қарым-қатынас дағдыларындағы үлкен серпіліс! Шаршасаңыз да, заттардың атауын сабырмен қайталай беріңіз.'),
  ('fb8b7427-667b-4244-909c-df4ca467d79e', 'Сіз де адамсыз 🛑', 'Бүгін ештеңе жоспар бойынша болмады ма? Өзіңізді кінәламаңыз. Сіз — әлеуметтік желідегі сүзгіден өткен елес емес, шынайы анасыз. Балаңызға керегі — тек Сіз.'),
  ('e60389be-4932-49bf-9ebd-d4caa963b145', 'Суық кофенің шындығы ☕', 'Кофені демдеп, 3 сағаттан кейін мұздай күйінде ішу — аналықтың жазылмаған заңы. Бүгін басқаша жасап көріңіз! Бөпеңізді ойыншықтарымен аз уақытқа өз бетінше ойнатып, кофеңізді 10 минут ішінде ыстық күйінде ішіп алыңыз. Сіз бұған лайықсыз.'),
  ('28610640-860d-43af-8a5a-381f751b562e', 'Ананың жасырын дауылы 🩸', 'Кенеттен шаршап, себепсіз жылағыңыз келе ме? Етеккір бақылағышын ашыңыз. Бәлкім, Сізде ПМС кезеңі болар. Өзіңізді кінәламаңыз: Пайдалы рецепттерден магнийге бай тіскебасар дайындап, денеңізге құлақ түріңіз.'),
  ('51272fb1-4e13-49cf-9f74-cdaa0749b5ed', 'Цифрлық педиатр 🤖', '33 айлық балаңыздың бойы мен салмағының графигі Сізді кенет алаңдатты ма? Интернет форумдарынан қорқынышты ауруларды іздемеңіз, Anacan AI көмегімен нақты, жедел әрі ғылыми негізделген ақпарат алыңыз.'),
  ('b5429001-8d63-464c-9e9d-56aab19950f8', 'Моцарт әсері 🎶', 'Кешкісін себепсіз ашулана бастады ма? Теледидарды өшіріп, жарықты бәсеңдетіңіз де, бөлмеге өте баяу классикалық музыка қойыңыз. Су мен музыканың үйлесімі атмосфераны сиқырлы түрде өзгертеді.'),
  ('8510671a-e1a9-4df3-abde-5ad11cb9aee4', 'Ұшу сынақтары 🧗‍♂️', 'Диваннан жастықтардың үстіне секіре ме? Ол тартылыс күшін және өз батылдығын сынап жүр. Тыйым салудың орнына, бөлмеде қауіпсіз секіру аймағын жасап, энергиясын шығаруына мүмкіндік беріңіз.'),
  ('8f7f72ec-9698-4ef9-a7b6-a44bc3f231c0', 'Түнгі жылаудың құпиясы 😭', 'Себебін таба алмайтын жылау ұстамалары әбден қажытады. Болжай бермей, Жылауды талдау құралы арқылы дауыстың астарындағы жасырын хабарды (ауырсыну, шаршау) түсініп, бөпеңізді тыныштандыруға тырысыңыз.'),
  ('a4f7c95b-7fff-41b8-a6d4-80ab1d481977', 'Бүркемелеу шебері 🥦', 'Сорпадағы көкөністерді микроскоппен іздегендей шетке теріп қоя ма? Пайдалы рецепттерден көкөністерді байқатпайтын тұздық рецептілерін табыңыз. Шығармашылық — ананың ең мықты құпия қаруы.'),
  ('30d43616-cc93-4cce-b2c3-cdd876b6c9e5', 'Тіс щеткасы үшін шайқас 🦷', 'Тіс щеткасын аузына жақындатпай, өзі тазалағысы келе ме? Мұны мәжбүрлеуге емес, ойынға айналдырыңыз. Алдымен ол Сіздің тістеріңізді тазаласын, содан кейін кезек Сізге келсін.'),
  ('dc8c6058-0791-46ab-b5d1-2637ff0b924e', 'Терезеге сенбеңіз ⛅', 'Серуенге шығарда терезеден қарап, ауа райына алданып қалмаңыз. Ауа райы және киім көмекшісі арқылы даладағы нақты жел мен температураға сай киім үйлесімін таңдап, үйден алаңсыз шығыңыз.'),
  ('7325d8d6-eeac-417b-abca-d32163dd16b4', 'Дүкендегі құтқарушы 🛒', 'Дүкенге барғанда ең қажетті затты үнемі ұмытып кетесіз бе? Қолданбада Сізді сатып алу тізімі күтіп тұр. Қажет заттарды сонда жазып қойыңыз, жұбайыңыз жұмыстан қайтарда бәрін тізім бойынша алып келеді.'),
  ('d7e75209-c901-4086-8f01-b71b4374f127', 'Су терапиясы 🛀', 'Күні бойы жүгіріп, ол да, Сіз де әбден шаршадыңыздар. Жылы ванна қабылдап жатқанда, жайлы фон ретінде тыныштандыратын табиғат дыбыстарын қосыңыз. Судың үйлесімі тіпті ең қырсық баланы да ұйқыға дайындайды.'),
  ('f55edde1-4803-4d20-96d6-d40197fda19c', 'Нық айтылған «Жоқ!» 🛑', 'Біреу оны сүйгісі келгенде, алыстап, нық түрде «жоқ» дей ме? Оның жеке дене шекараларын құрметтеңіз. Рұқсатсыз жанасуға қарсылық білдіре алуы — оның психологиялық саулығы үшін маңызды.'),
  ('a279684f-8916-4183-8bdf-0b058193de01', 'Әкенің дауыс ырғағы 📖', 'Бүгін кешке дауыс желбезегіңізді тынықтырыңыз. Баланың сүйікті кітаптарын әртүрлі дауыс ырғағымен, қиял қосып, көңілді етіп оқу міндетін әкесі атқарсын.'),
  ('acb821ae-037d-451e-905f-fae976b254b3', 'Жеке меншік 🧸', 'Балаңыз үйге келген қонақтың баласына өз ойыншығын бермей ме? Бұл өзімшілдік емес, жеке шекарасын қорғау. Бөлісуді мәжбүрлеу арқылы емес, өз үлгіңізбен үйретіңіз.'),
  ('5a4437a7-7519-4a4e-9c66-e797d5e763f5', 'Режиссер іске кірісті 🎭', 'Суретті кітаптағы кейіпкерлерге қарап, өзі ойдан шығарған оқиғаларды айтып бере ме? Қиялы шарықтап тұр! Оның ерекше хикаяларын бөлмей, мақтанышпен тыңдаңыз.'),
  ('932de885-b10a-4cc0-af8a-8db540c3d060', 'Ыстық шай мен тыныштық 🍵', 'Үй шаруасын ұмыта тұрыңыз, бәрі де күте алады. Пайдалы рецептілердің бірін қолданып, мелисса шайын демдеңіз де, өзіңізбен оңаша қалудың рақатын сезініңіз.'),
  ('ba3e9de9-b98f-4d3a-93a0-ef5b3f06f424', 'Саябақ терапиясы 🌳', 'Төрт қабырға қысып барады. Күн салқын болса да, оны жылы киіндіріп, саябаққа 20 минутқа шығып қайтыңыз. Жапырақтар мен тастарды зерттесін, ал таза ауа оның миын оттегімен қамтамасыз етеді.'),
  ('12d65ca5-dc2d-4959-8af5-51ab64abb6bf', 'Тәрелкедегі өнер 🥦', 'Ол тамақты жемей ме? Кейде мәселе дәмінде емес, сыртқы көрінісінде болады. Түрлі түсті көкөністерден күлкілі бейнелер жасап, тәбетін ашуға және тамақтануды ойынға айналдыруға тырысыңыз.'),
  ('27428d92-902e-4e8b-a566-975a32a7bf6a', 'Көңілді күлкі 🤡', 'Сіздің амалдарыңыз көмектеспегенде, әкесінің оғаш дыбыстары жағдайды құтқарады. Кешкі мазасыздық басталғанда, тізгінді бірден оған беріп, сырттай жымиып бақылаңыз.'),
  ('71ce1c15-b947-45d9-8c0e-c8a77ece4ef7', 'Жабайы табиғат үйде 🐶', 'Ол дыбыс шығарып қана қоймай, ит сияқты еңбектеп, мысық сияқты еркелей ме? Дене қимылы мен қиялы таңғажайып үйлесім тапқан. Кілем үстінде онымен бірге осы ойынға Сіз де қосылыңыз.'),
  ('418dbea1-2468-4df0-ad94-f76ab3c14a42', 'Мелатонин фабрикасы 🌙', 'Тезірек ұйықтауы үшін бөлмедегі барлық қосымша жарықты және планшет экрандарын өшіріңіз. Мелатонин тек қараңғы әрі технологиялық құрылғылар жоқ ортада жылдам бөлінеді.'),
  ('dcb96656-d377-4147-b075-f440d05b3b54', 'Әдептілік ережелері 👋', 'Біреу есіктен шығып бара жатқанда, бөпеңіз өздігінен қол бұлғап қоштасады! Бұл әлеуметтік зерде мен эмпатияның қалыптасып келе жатқанын білдіреді. Оның осындай әдепті әрекеттерін үнемі қолдап, мадақтаңыз.'),
  ('32e0ad68-9613-493b-b8b0-dc5729e770dd', 'Бірге тазалайық 🧹', 'Үйді жинау керек пе? Бөлмені сыпырып жатқанда, оған да шүберек беріп, Сізге көмектесуіне мүмкіндік беріңіз. Үй жинауды командалық жұмыс пен қызықты ойынға айналдыру жолдарын Блогтардан оқыңыз.'),
  ('a3a1222f-3b9a-40aa-a53c-50cc656ba7c7', 'Күн тәртібі бұзылып жүр ме? ⏱️', 'Кешке ұйықтауы тым ұзаққа созыла ма? Ұйқы таймерінің кестесін қараңыз. Бәлкім, күндізгі ұйқыны едәуір қысқартып, кешкі ұйқы уақытын ертерек жылжытатын кез әлдеқашан келген шығар.'),
  ('ee3cf122-8fc4-43ea-906b-ef2165dd428d', '«Мен үлкенмін!» деген қырсықтық 🛑', 'Барлығына араласқысы келіп, істі баяулата ма? Осы бір қызық дербестік күресінде оған бірнеше қарапайым таңдау ұсыныңыз.'),
  ('98562e83-4876-4c00-8dbc-2ad2897e54b5', '1000 күндік ғажайып! 👑', 'ҚҰТТЫҚТАЙМЫЗ! Сіз осы дауылды, шаршататын, бірақ әлемдегі ең қымбат жолмен тура 1000 күн жүріп өттіңіз! Осы ерекше жеңіс күнін дәл қазір тойлап, қуанышыңызды Anacan қауымдастығында мақтанышпен бөлісіңіз!'),
  ('c186b66b-55e3-4f3f-9de6-a20601b6d88b', 'Команданың жеңіс биі 🥂', 'Осы кеште 1000 күннің шаршауын, көз жасы мен қуанышын жұбайыңызбен бірге атап өтіңіз. Дастарқанға бір шам жағып, мызғымас командаңыздың жеңісін зор қуанышпен тойлаңыздар!'),
  ('f26096f7-035d-44ff-ad7c-b1f1eaade001', 'Сіз мұны істей алдыңыз! 📈', 'Балаңыз қандай ұзақ жолдан өтті! Алғашқы күндердегі нәзік қорқыныштың орнын енді зор сенім басты. Сіз осы 1000 күнді үлкен мақтанышпен еңсердіңіз! Сіз шынымен кереметсіз!'),
  ('d50eb553-5709-43ce-81ea-ce5014437b1a', 'Мақтаныш парағы 📝', 'Осындай ұзақ әрі ойлы-қырлы жолда Сіздің ең үлкен күшіңіз — бөпеңізге деген махаббатыңыз. Көңіл күй күнделігін ашып, оған болашақта оқитын шағын әрі мақтанышқа толы хат жазыңыз.'),
  ('20a1ef6d-4573-433a-a2b7-db48ed6c1114', 'Кішкентай көмекші 🧸', '«Аяқкиімді әкелші» дегенде, шынымен барып әкеле ме? Сөздік қоры мен түсіну қабілеті шарықтау шегінде! Оны үйдегі шағын істерге қатыстырып, өзіне деген сенімін арттырыңыз.'),
  ('9b33bb20-6873-451a-abe7-084cc34eff93', 'Нағыз команда — сіздер 🌟', 'Әрбір нық қадам — Сіз бен серігіңіздің ортақ еңбегінің жемісі.'),
  ('9d370453-5ab2-46ed-b11b-b4f3648ebe3e', 'Үй шашылып жатса да, ана көңілді 🌪', 'Киімдер тау болып үйіліп, ыдыс жуғыш машина толып тұр ма? Қоя тұрыңыз. Бүгін үй шаруасын өз мойнына алуын серігіңізден сұраңыз. Демалып алыңыз, өйткені Сіз — осы үйдің басты тірегісіз.'),
  ('32252794-61c5-419d-b7e8-539bc9987fc9', 'Анатомия сабағы 👀', '«Иығың қайда?» деп сұрағанда, саусағымен көрсетеді ме? Танымдық қабілеті шарықтау шегінде! Ойынды күрделірек дене мүшелерімен жалғастырып, сөздік қорын байытыңыз.'),
  ('520e2a70-086b-4229-864f-4de7f51683ae', 'Судың құдіреті 🛀', 'Күні бойы жүгіріп, бөпеңіз де, Сіз де шаршадыңыз. Жылы ванна қабылдағанда, жайландыратын табиғат дыбыстарын қосыңыз. Судың үйлесімді үні тіпті ең қырсық баланы да ұйқыға дайындайды.'),
  ('8083b651-9df8-40f8-a78a-23401da54600', 'Ананың ыдысындағы дәм 🥣', 'Өз тәрелкесін шетке ысырып қойып, Сіздің асыңызға қол соза ма? Балалар әрдайым ата-анасының таңдауына көбірек сенеді. Пайдалы рецепттердің ішінен екеуіңіз де бірге жей алатын тағамдарды таңдаңыз.'),
  ('23868e91-8f1b-41db-955e-cd3d4e20a70a', 'Серуен тактикасы ⛅', 'Серуенге шыққанда, күн райына алданып, оны тоңдырып алмаңыз. Терезеден қарап қана шешім қабылдамаңыз: Ауа райы және киім көмекшісі арқылы даладағы желге сай киім үйлесімін таңдап, үйден алаңсыз шығыңыз.'),
  ('5cf4179d-ca05-4825-ae51-8ae8bda4be3e', 'Күнделікке есеп жазу 📝', 'Бала ұйықтағаннан кейін Көңіл күй күнделігін ашыңыз. Бүгін Сізді ең көп не шаршатты, не күлдірді? Сезімдеріңізге толық ерік беріп, ішіңіздегіні ақтарыңыз.'),
  ('f9781f63-e578-4e40-8665-b3d4fa014824', 'Жеңістен кейінгі шынайы өмір 🚀', 'Кешегі мерейтойдан кейін бүгін таңертең тағы да шашылған ойыншықтар мен «Қаламаймын!» деген сөздерге ояндық! Өмір жалғасуда. Терең тыныс алыңыз, Сіз бұл бейберекеттіктің ең керемет басқарушысысыз.'),
  ('fde949fd-c8a2-4b0b-a364-0d008da67880', 'Күндізгі ұйқы дағдарысы 🥱', 'Төсекке жатқысы келмей, жылай ма? 3 жасқа қарай кейбір балалар күндізгі ұйқыдан бас тарта бастайды. Күресудің орнына «Тыныштық сағатын» жариялап, төсекте жай ғана кітап парақтауды ұсыныңыз.'),
  ('092fe7ca-f54f-4986-9a3f-884d05ff6c27', 'Кереуеттен қашу жоспары 🛌', 'Бесігінен өрмелеп шығуға тырыса ма? Қауіпсіздік үшін бөлмені қайта тексеріңіз. Үлкен балаларға арналған кереуетке ауысатын уақыт жақындап келеді.'),
  ('9fdf76d2-ea34-465e-99e8-537978d670c9', '«Қалай?» деген сұрақтар басталады 🤔', '«Неге?» деген сұрақтардың орнын «Бұл қалай жұмыс істейді?» деген сұрақтар басады. Ол механизмдердің қалай жұмыс істейтінін түсінуге тырысады. Сабыр сақтап, оған қысқа әрі қисынды түсініктемелер беріңіз.'),
  ('c9428152-a130-431b-ac89-26275023d613', 'Анаға арналған үзіліс ☕', 'Бала өздігінен ойнап отырғанда, бірден үй шаруасына кірісіп кетпеңіз. Бөлмедегі шашылған заттар ешқайда қашпайды, ал Сіздің күш-қуатыңыз таусылуы мүмкін. Отырып, ыстық кофеңізді ішіңіз.'),
  ('b69e774e-9d7b-4da5-9fb4-5b192b81f712', 'Қиялдағы көріністер 🧸', 'Ойыншық қонжығына ертегі айтып немесе бос кеседен шай ішіп отыр ма? Символдық ойындар — бала дамуының нағыз жауһары. Оған кедергі жасамай, осы кішкентай режиссерді сырттай бақылаңыз.'),
  ('c131d97d-34fe-4f0d-ab19-20860829451c', 'Тыныштық қажет болатын сәт 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — ең сезімтал уақыт. Шу өлшегішпен бөлмедегі децибел деңгейін тексеріп, көрші бөлмедегі теледидардың дыбысын реттеңіз.'),
  ('c0f3d36a-8d02-476e-a6a5-3dfb6c2aa133', 'Жалаңаяқ жүру 👣', 'Ол жалаңаяқ жүргенді, әртүрлі беттерді басып сезінгенді ерекше ұнатады. Табанындағы жүйке ұштарының қозуы оның неврологиялық дамуы үшін өте маңызды, сондықтан оған шұлықсыз жүруге рұқсат етіңіз.'),
  ('c3c4fb6d-e99b-442f-b18d-4a0a69488a0a', 'Цифрлық жад 🛒', 'Дүкенге барғанда міндетті түрде бір нәрсені ұмытып кетесіз бе? Қосымшада сатып алу тізімі Сізді күтіп тұр. Қажетті заттарды сол жерге жазып қойыңыз, жұбайыңыз жұмыстан қайтарда бәрін тізім бойынша алып келсін.'),
  ('cb069764-7f58-461b-a159-7d553277ecda', 'Дыбысты қиял 🪄', 'Бүгін кешке ақылды ертегілерде оған арнап ерекше хикая құрастырыңыз: шаңсорғыштан қорықпайтын батыл қоян туралы оқиға. Қорқынышты ертегілердің көмегімен жеңу әлдеқайда оңай.'),
  ('62149695-6298-4aba-847f-c8ce0b1eb19a', 'Жараланған эго 🛑', '«Өзім істеймін!» деп, кез келген көмектен бас тартады. Аяқ киімін теріс кисе де, араласпаңыз. Аяқ киімнің дұрыс киілгенінен гөрі, баланың өзіне деген сенімінің сақталғаны маңыздырақ.'),
  ('86650154-88a4-4c7d-ab75-32f1a232aa9d', 'Күмәнді сейілтіңіз 🤖', 'Баланың мінез-құлқындағы кенет өзгерістер Сізді алаңдатты ма? Интернет форумдарынан қорқынышты ауруларды іздемеңіз, Anacan AI-дан нақты, жедел әрі ғылыми негізделген ақпарат алыңыз.'),
  ('d8fdf53e-3f50-42fc-a36a-84c2b2cbfbee', 'Ұйқы күзетшісі 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — мидың ең белсенді кезі. Дыбыс өлшегіштің көмегімен бөлмедегі дыбыс деңгейін реттеңіз. Кейде жай ғана себелеген жаңбырдың дыбысы оны терең ұйқыға батыруы мүмкін.'),
  ('5820d5b6-2a79-44ac-a012-46235cfe81f4', '1000 күнге небәрі 5 күн қалды! 🎈', 'Кері санақ аяқталуға жақын! Сіз тура 1000 күнге созылған үлкен әрі аңызға бергісіз жолды еңсергелі тұрсыз. Күлімдеңіз, мерейтойға дайындық пен көңілді тақырыптарды қазірден бастап жоспарлаңыз!'),
  ('7ac49f38-01ad-4503-8e74-f0a0bf7621d8', 'Тыныш кітап сағаты 🥱', 'Төсекке жатқысы келмей, қырсығып жүр ме? Кейбір балалар осы кезеңде күндізгі ұйқыдан бас тартады. Күресудің орнына «Тыныштық сағатын» жариялап, төсекте жай ғана кітап парақтауды ұсыныңыз.'),
  ('e0133a48-f7ee-4d9e-9e82-8b0c0ba8095b', 'Саябақтағы қарым-қатынас 🌳', 'Басқа балалармен бірге ойнағаннан гөрі, олардың жанында өз бетінше ойнай ма? Қатар ойнау бұл жас үшін мүлде қалыпты. Ауа райына сай киіндіріп, оны саябаққа алып шығыңыз.'),
  ('88b776b7-0d43-49f1-b31c-da27294feb6f', 'Жедел педиатр 🤖', 'Түбекке үйрету кезінде кері кету байқалды ма? Өзіңізді қинамаңыз, осы психологиялық үдерісті жеңілдету жолдарын Anacan AI-дан сұраңыз.'),
  ('92aa3f00-711e-43bd-a2d7-1f3bfbc7744d', '«Менікі!» деген қырсықтық 🛑', 'Бәрін өзінікі еткісі келе ме? Бөлісу ұғымы әлі толық қалыптаспаған. Оны мәжбүрлемеңіз, оның орнына «Кезекпен ойнайық» қағидасын біртіндеп енгізіңіз.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('adf1cd9b-1322-48c3-a05b-72b8aa90f9cc'::uuid, 'Сиқырлы түнгі көрініс 🪄', 'Ұйықтап кетуі қиын ба? Ақылды ертегілерде арнайы ертегі құрастырып, жаңа әдеттерді қызықты оқиғаға айналдырыңыз.'),
  ('269b7d14-00d0-4c42-84b9-6759e61b0baa', 'Тағамның түріне байланысты дағдарыс 🥦', 'Нанның шетін немесе қияр тілімін көріксіз болғаны үшін жемей ме? Тағам талғампаздығы кейде осындай тосын сипат алады. Тамақтану жоспарынан көкөністерді езбе түрінде білдіртпей ұсынудың ең шебер тәсілдерін табыңыз.'),
  ('3619cb9e-e29f-4149-9f97-e65685c72f61', 'Таңғы концерт басталды 🎤', 'Ояна сала бар даусымен бірдеңе айтып, әндете бастай ма? Оның қуаты таңғы 7-де-ақ толық толып тұрады. Көзіңізді уқалап, осы кішкентай поп-жұлдыздың өнерін күлімсіреп тамашалаңыз.'),
  ('4e5a485c-972c-4f14-b15e-6d0c1f1b8961', 'Жуынатын бөлмедегі тасқын 🛀', 'Сумен ойнаудың мақсаты тазалану емес, бөлмені аквапаркке айналдыру сияқты. Су шашырай берсін. Жылы су мен көңілді ойын оның күні бойы жиналған бар қырсықтығын шайып әкетеді.'),
  ('22cad895-d987-4916-ac97-672fe0a05ac0', '«Тағы біреу» деген айла 📖', 'Төсекке жатқысы келмей, тағы бір ертегі сұрап, уақыт соза ма? Классикалық кітаптарды қоя тұрыңыз. Ақылды ертегілерде оның өзі ойлап тапқан кейіпкерлермен қысқа ұйқы ертегісін құрастырып, кешкі рәсімді аяқтаңыз.'),
  ('4aedb3f8-6caf-4ec5-a8d3-5b5f77908beb', 'Жасырын шоколад үзілісі 🍫', 'Асүй шкафының тасасында тұрып, жасырын тәтті жеп тұрған ана, біз Сізді көріп тұрмыз! Өзіңізді кінәламаңыз. У-шуға төзу үшін глюкозаны осылай көтеруге толық қақыңыз бар.'),
  ('c5c0175d-de40-45a7-97f9-43392b324696', 'Үйдің кішкентай диктаторы 👑', 'Ол жерге емес, мұнда отыр!, Мұны сен емес, мен істеймін! Ол үйді өзі басқарғысы келеді. Оның жігерін күрт жаншымай, Сен мұнда отыр, ал мен ана жерге отырамын деп тепе-теңдікті сақтаңыз.'),
  ('2f5f6f47-30c9-4601-933d-5baa445585db', 'Әкенің массаж сеансы 💆‍♂️', 'Бүгін көп уақыт тік тұрып қалдыңыз, оның соңынан жүгіріп, беліңіз үзіліп барады. Бөпе ұйықтаған бойда жұбайыңыздан иығыңызға 10 минут массаж жасап беруін сұраңыз. Сіз — үйдің тірегісіз, ал тірекке де демалыс қажет.'),
  ('e70841e8-9af5-471e-9ff6-b28774448a7f', 'Араласпаңыз 🧦', 'Шұлығының өкшесі үстіне қарап тұр, бірақ өзі кигеніне әлемдегі ең мақтанышты адамдай мәз болып жүр. Мүлде араласпаңыз. Дербестік сезімі киімді дұрыс киюден маңыздырақ.'),
  ('f3fc49f1-990c-4271-ab6c-21a94434e4c2', 'Қауымдастықта бір демалу 💬', 'Қатты шаршадыңыз ба және өзіңізді әлемдегі ең шыдамсыз анадай сезініп жүрсіз бе? Дереу Anacan қауымдастығын ашыңыз. Басқа аналардың да дәл осындай дағдарыстарды бастан өткеретінін оқу — ең үлкен психологиялық қолдау.'),
  ('3bcabb18-ba8e-4729-bb3a-959b28fdcaeb', 'Бұлттарды тап ойыны ⛅', 'Төрт қабырға қысып кетті ме? Ауа райына сай киініп, саябаққа шығыңыз. Жай ғана отырып, аспандағы бұлттардың неге ұқсайтынын табыңыз. Бұл баяу ойын миды әрі тынықтырады, әрі дамытады.'),
  ('8fab2e02-e35e-45f0-a10f-554adfe7c2c6', 'Үйдегі бейберекет ақыры аяқталды.', 'Терезеден келетін дыбыстарды басу үшін lofi музыкасын қосып, жаныңызды тынықтырыңыз.'),
  ('9de02d84-1ac6-4478-a817-67045fcd6af5', 'Алғашқы сүйкімді өтіріктер ме? 🤥', 'Суды мен төккен жоқпын, қонжығым төкті. Назар аударыңыз! Оның қиялы соншалық дамыған, тіпті оқиғаларды өз пайдасына қарай ойдан құрастыра алады. Оны өтірік айтты деп айыптамаңыз, Қонжығыңа енді қайтып төкпесін деп айт деп күлімсіреңіз.'),
  ('3af3aa71-d08b-4f87-af96-9527f5f91ec1', 'Таңғы жаттығу 🤸‍♂️', 'Сіз әлі оянған жоқсыз, ал ол төсекте үстіңізге секіріп жүр. Дүниедегі ең шулы, бірақ ең сүйкімді оятқыш! Күніңізді оның сарқылмас энергиясына күле отырып бастаңыз.'),
  ('8c84402b-2c57-4668-ad1d-96d138e6ba29', 'Тізімсіз дүкенге барудың машақаты 🛒', 'Дүкенге барып, ең керекті затты алмай қайттыңыз ба? Аналардың есте сақтау қабілеті осындай. Жадыңызға сенбей, қажет болған әрбір ұсақ-түйекті бірден Сатып алу тізіміне жазуды әдетке айналдырыңыз.'),
  ('90c41ad8-7de7-4c6d-ba3d-cf1aad328939', 'Майшам жарығындағы шай 🕯️', 'Бала ұйықтап қалды. Жарықты өшіріп, үстелге бір майшам жағыңыз. Бұл романтика үшін емес, күні бойы шаршаған жүйкеңіз бен көзіңізді тынықтыру үшін ғана.'),
  ('4390f43b-f533-4c56-8aa2-5901fd06c8f5', 'Жасанды интеллект, нақты көмек 🤖', 'Баланың бәріне қасарысуының психологиялық себебі неде? Интернеттен қорқынышты мақалалар іздемеңіз. Anacan AI-дан 33 айлық балалардың дағдарысы туралы ғылыми әрі қысқаша түсініктеме сұраңыз.'),
  ('70560836-1d71-42c8-8235-1ad990694b3b', 'Күн тәртібінің бұзылуы ⏱️', 'Кешке ұйықтату 1 сағаттан ұзаққа созыла ма? Ұйқы таймерінің кестесін қараңыз. Мүмкін, күндізгі ұйқыны едәуір қысқартып, кешкі ұйқы уақытын ертерекке ауыстыратын кез әлдеқашан келген шығар.'),
  ('dfed41fd-982b-4955-b70f-6d43247a4468', 'Шаш тарау машақаты 🪮', 'Шашын тарағанда немесе қол тигізгенде, әлемдегі ең ауыр азапты көргендей айқайлай ма? Күресті тоқтатыңыз. Алдымен тарақты оған беріп, шашыңызды тарауына мүмкіндік беріңіз, содан кейін кезек Сізге келсін.'),
  ('5b72c8ce-753e-4283-9bd2-18995d662a91', 'Темір қоры 🥩', 'Өңі бозарып немесе тәбеті нашарлап жүр ме? Тамақтануды бақылау құралынан темірдің жеткілікті мөлшерде қабылданып жатқанын тексеріңіз. Етпен бірге міндетті түрде лимон қосылған салат беріңіз — бұл темірдің сіңуін бірден арттырады.'),
  ('b0a26358-dcc7-4a57-8694-6e91e9d4baaa', 'Ойыншықпен бөлісу сабағы 🧸', 'Саябаққа бармас бұрын: «Бүгін ойыншықтарымызды кезекпен ойнаймыз», — деп түсіндіріңіз. Иә, ол тағы да бөліспеуі мүмкін, бірақ бұл дерексіз ережені қайта-қайта естуі қажет.'),
  ('c1d1533f-3d3f-4fb5-a549-d74668c72b3d', 'Әкенің ұйықтату тәсілі 👨‍🍼', 'Кешке пижамасын кигісі келмей, қашып жүр ме? Бұл істі әкесіне тапсырыңыз. Әкесі киіну процесін күреске немесе күлкілі ойынға айналдырса, бала пижамасын қалай киіп қойғанын өзі де байқамай қалады.'),
  ('3aee856b-a30f-48de-84ad-3c91f83ed092', 'Табиғат жұмбағы 🍁', 'Саябақта жай серуендемей, оны ойынға айналдырыңыз: «Кәне, ең үлкен сары жапырақты табайық!» Табиғат — бала үшін ең үлкен әрі интерактивті мектеп.'),
  ('746f5afe-3705-4073-a3c0-ff69e92f5a25', 'Кір жуғыш машинаға қызығу 🧺', 'Кір жуғыш машинаның алдында отырып, айналып жатқан киімдерге қадала қарап жүр ме? Бұл — мүлде тегін әрі ойды тыныштандыратын қызық. Оған кедергі жасамаңыз, өзіңіз де осы мүмкіндікті пайдаланып, демалып алыңыз.'),
  ('8da8a36e-5d67-4dd0-ac14-245b62a8846a', 'Көңіл күй күнделігіндегі сыр 📝', 'Телефоныңызды қолыңызға алыңыз. Әлеуметтік желіні парақтаудың орнына, Көңіл күй күнделігін ашып, бүгін ашуыңызға тигеннің бәрін ішіңіз босағанша жазыңыз. Цифрлық терапия көмектеседі.'),
  ('71f7d0fb-698f-4308-ad55-a95583a3469b', 'Мелатонин уақыты 🌙', 'Ұйқы гормоны бөлінуі үшін ұйықтардан кемінде 1 сағат бұрын теледидар, планшет сияқты көк жарық көздерін толық өшіріңіз. Қараңғылық пен тыныштық — ең жақсы ұйықтататын құрал.'),
  ('9d1de334-e45a-491d-8075-45ce379df7ad', '«Мен анамын!» ойыны 🎭', 'Қуыршағына саусағын шошайтып, Сіздің дауыс ырғағыңызбен ұрсып жүр ме? Бөлмеде Сіздің кішкентай көшірмеңіз жүргендей. Өзіңізге сырт көзбен қарау әрі күлкілі, әрі мінез-құлқыңызға назар аудару керегін білдіретін белгі.'),
  ('fc7921b2-eab6-4a37-aad0-63611df47ad7', 'Күндізгі ұйқыдан бас тарту 🥱', 'Төсекке жатқысы келмейді, бірақ көзі ілініп бара ма? 3 жасқа қарай мұндай қарсылық жиі кездеседі. Мәжбүрлемеңіз, бөлменің жарығын бәсеңдетіп, «Кітапты тыныш парақтау сағатын» жариялаңыз.'),
  ('2a74e43d-d2e3-45ad-8762-627a59c365b2', 'Таңғы қырсықтықтың түсі 🔴', 'Тамағын жасыл тәрелкеге салып беруді сұрап, әкелгеніңізде «Мен қызыл дегенмін» деп жылап жатыр ма? Бұдан қисын іздеуді доғарыңыз. Тамағын қызыл тәрелкеге салып беріп, жүйкеңізді сақтаңыз.'),
  ('8ac94a1b-a693-498b-9e54-d59e3331d567', 'Кәсіби биші 🎶', 'Алғаш естіген ырғағына-ақ, мейлі ол жарнама әуені болсын, мейлі көлік сигналы болсын, билей жөнеледі. Өмірге бөпеңіз сияқты көңілді қараңыз! Бөлмеде оған қосылып, бірнеше минут еркін билеп алыңыз.'),
  ('540ed6cc-ab45-42f3-bbdf-f7d1a37e6094', 'Әкенің құпия тәсілі 👨‍🍼', 'Күндізгі шаршаудың өзі Сізге жеткілікті. Кешке баланы ұйқыға дайындау мен тісін тазалату үдерісін әкесінің ойындарына тапсырып, өзіңіз оңаша тыныш демалыңыз.'),
  ('75bb1e03-07ff-448a-b132-6eec4abf1a2d', 'Жиналатын да, шашылатын да киімдер 👗', 'Сіз бар ынтаңызбен киімдерді жинап қоясыз, ал ол келіп, әп-сәтте бәрін шашып тастайды. Ашуланудың орнына мұны ойынға айналдырыңыз: Қане, мына жейдені кім алысырақ лақтырады екен?'),
  ('ca77a3ff-10f8-4690-8926-270fe161b3d5', 'Өз бетімен тамақтануға деген қырсықтық 🥄', 'Қасықты алып, айналаның бәрін былғай ма? Тамақтану таймерін қосыңыз. Шашылған тамаққа емес, оның бойында қалыптасып келе жатқан дербестікке қарап қуаныңыз.'),
  ('25c4de30-89c3-4f45-952f-3b21fb85b41e', 'Жалаңаяқ зерттеуші 👣', 'Шұлық кигісі келмей, қашып тығыла ма? Біраз уақыт жалаңаяқ жүріп, еденді, кілемді, салқын тақташаны сезінуіне мүмкіндік беріңіз. Табандағы жүйке ұштарының дамуы оның тепе-теңдікті сақтау қабілеті үшін өте маңызды.'),
  ('a0e0a012-48a8-4169-b4f6-62857311b266', 'Жарықты өшірсеңіз, ұйқы келеді 🌙', 'Тезірек ұйықтауы үшін бөлмедегі барлық қосымша жарықты және планшет экрандарын өшіріңіз. Мелатонин тек қараңғы әрі технологиялық құрылғылар жоқ ортада бөлінеді.'),
  ('ac0003df-1b37-4e86-98c2-561682149d03', 'Табиғатты зерттеу 🍁', 'Ауа райына сай киініп, далаға шығыңыз. Саябақта әртүрлі тастар мен түрлі түсті жапырақтарды іздеу ойынын ойнаңыз. Бұл жаста табиғат — ол үшін ең үлкен әрі интерактивті ойыншық.'),
  ('85540a77-8c0c-40d1-bec5-6ddc93f07354', 'Дүкендегі ұмытшақтық 🛒', 'Жадыңызға сеніп дүкенге барып, ең маңызды затты ұмытып қайттыңыз ба? Қажет нәрсенің бәрін бірден Сатып алу тізіміне жазуды әдетке айналдырыңыз, Сіздің орныңызға қолданба еске салсын.'),
  ('43d613a7-90fe-4d48-880a-a0dadfb94dab', 'Жасырын көкөніс операциясы 🥦', 'Сорпадағы көкөністерді микроскоппен іздегендей шетке теріп қоя ма? Пайдалы рецептерден көкөністерді байқатпайтын тұздықтардың рецептерін табыңыз. Тапқырлық — ананың ең мықты қаруы.'),
  ('6fd78011-ad7d-48f0-9941-25d07912808e', 'Төменге қараңызшы, ол нені зерттеп жүр? 👣', 'Жалаңаяқ жүруден, әртүрлі беттерді басып көруден ерекше ләззат алады. Табандағы жүйке ұштарының қозуы оның тепе-теңдікті сақтау қабілеті үшін маңызды, сондықтан шұлықсыз жүруіне рұқсат етіңіз.'),
  ('dcc98b1b-6e09-41d3-9be6-78333aecdab4', 'Түнгі қорғаушылар 🧸', 'Қараңғыдан қорқа ма? Сүйікті қонжықтары мен ойыншықтарын төсегінің айналасына қойып, «Олар сені таң атқанша қорғайды» деп айтыңыз. Мұндай көрнекі сенім тәсілі өте жақсы көмектеседі.'),
  ('3d8d4230-c58c-4f55-bb5e-c5c92f713201', 'Тыныштықтың растауы 🤫', 'У-шу күннен кейін бала ұйықтағанда, дыбыс деңгейін өлшейтін құрылғымен бөлмедегі тыныштықты өлшеңіз. Нөлге жақындаған сандарды көрудің өзі ананың миына терапиядай әсер етеді.'),
  ('53046b7a-695e-4d17-9dda-231255060141', 'Таңғы «Жоқ!» 🛑', 'Көзін ашып үлгермей жатып бірдеңе ұсынсаңыз, «Жоқ!» дейді. 3 жасқа таяғанда сұрақ қоймай, бірден әрекетке көшіңіз. «Жүр, беті-қолымызды жуайық па?» демей, «Беті-қолды жуатын уақыт келді!» деңіз.'),
  ('e5f27372-8ce2-40d6-acbc-12281fab28bb', 'Өзіңізге де уақыт бөліңіз 🥑', 'Күнделікті қарбалас Сізді әбден қажытты. Аяқ үстінде жүріп асығыс тамақтанудың орнына, пайдалы рецептерден тойымды әрі дәруменге бай ерекше ас дайындап, асықпай рақаттанып жеңіз. Сізге энергия міндетті түрде қажет.'),
  ('096e15b3-74ca-4180-ab20-07ce9b214b2a', 'Сыбырлап сырласу 🌙', 'Бөлменің жарығын толық өшіріңіз. Жанына жатып, күні бойы болған оқиғаларды оған өте баяу дауыспен, сыбырлап айтып беріңіз. Сыбырлау — миды ұйқыға дайындайтын ең жақсы тәсілдердің бірі.'),
  ('41df7f7d-e272-4737-8498-6c866ab9545a', 'Тәжірибе алмасу 💬', 'Баланың бәріне қасарыса беруі Сізді қорқытты ма? Интернеттен үрейлі мақалалар іздемеңіз. Anacan қауымдастығындағы тәжірибелі аналардың шынайы оқиғаларынан қолдау тауып, күлімдеңіз.'),
  ('541b84ef-a3ed-43ff-8a33-aa153668c840', 'Түнгі дауыл 😭', 'Түн ортасында еш себепсіз жылап оянды ма? Іші кебіп жүр ме, әлде бұл түнгі қорқыныш па? Болжай бермей, Жылауды талдау арқылы себебін анықтаңыз да, бөпеңізді бауырыңызға басып, тыныштандырыңыз.'),
  ('60323c41-a0d6-4029-8b71-994315dcb0cf', 'Түбекке қатысты оқиғалар 🚽', 'Түбекке үйретіп жүргенде кілемге тағы да кіші дәретін жіберіп қойды ма? Терең тыныс алыңыз. Ашулансаңыз, ол кейін шегінуі мүмкін. Тазалап алуға болатын нәрсе үшін өзіңізді қинамаңыз, бұл — үйрену үдерісінің бір бөлігі ғана.'),
  ('1a8259f8-8cae-4f18-b5c2-ee44aa10346d', 'Саябақтағы адвокат 🗣️', '«Тағы біраз ойнайыншы, небәрі 5 минут!» деп уақытты созады. Уақыт туралы түсінігі жоқ, бірақ саудаласуға келгенде алдына жан салмайды. Таймер қойып, ережелерді көңіліне тимей, ойын арқылы еске салыңыз.'),
  ('bf1a9cee-65ab-4eac-ad90-70c1631bbc46', 'Бойдың күрт өсуі 📏', 'Шалбары қысқарып қалды ма? Ол тез өсіп келеді! Даму трекеріне қазіргі өлшемдерін енгізіп, ұйқысыз түндеріңіздің жемісіне мақтанышпен қараңыз.'),
  ('cff0599d-3a80-4d02-94df-22f42e5f09f2', 'Екеуіңізге арналған үзіліс 🥂', 'Бала ұйықтады. Енді телефондар мен үй шаруасын бір шетке қойыңыз. Жұбайыңызбен кемінде 20 минут бала мен төлемдерден басқа кез келген тақырыпта сөйлесіңіз.'),
  ('5130988b-06fa-4ca0-8477-7c4e5105998f', 'Ертегінің сиқырлы әлемі 🪄', 'Бүгін кешке Ақылды ертегілерден мүлде өзгеше бір нәрсені байқап көріңіз: Аспанды зерттеген кішкентай бұлттың хикаясы. Дауыс ырғағыңызды ертегінің ырғағына сәйкестендіріп, бөпеңізді ұйқыға жетелеңіз.'),
  ('632fc2f4-f865-49e5-8a30-eef5c63d0d4a', '«Маған қара!» соққысы 👀', 'Сіз телефонға қарап отырғанда, ол келіп қолыңызды қағады немесе құрылғыны тартып алады. Бұл жерде оның айтқаны дұрыс. Ол дәл қазір бар назарыңыздың өзінде болғанын қалайды. Көзіне қарап, оны тыңдап отырғаныңызды сездіріңіз.'),
  ('df191a16-4b37-4a90-bbd4-c8972ecc1670', 'Кетпейтін дақтар, еркін зерттеулер 🎨', 'Пижамасы тамақ, ал үсті-басы бояу дақтары болып кетті ме? Балалар тап-таза болып өспеуі керек, олар айналасын зерттеп жүріп кірлейді. Шашылған заттар мен дақтар — оның шығармашылығының қолтаңбасы, уайымдамаңыз.'),
  ('9c87f5af-e2e2-4310-ab2c-98ff6d5521d4', 'Тыныш режимге ауысу 🤫', 'Ұйықтап бара жатқанда сезімталдығы артады. Тыныштық сақтаңыз.'),
  ('af1711a8-2ca3-45c1-ae35-556b3b0e2d67', 'Әкенің ұйқы дуэті 📖', 'Бүгін кешке бөлмеде өзгеше көңіл күй қалыптастырайық. Кітап оқудың орнына, әкесімен бірге ақырын әрі ырғақты ән айтып, бөпеңіздің ұйықтап кетуіне жағдай жасаңыз.'),
  ('b2328024-7846-4b25-a276-980c22ebcd52', 'Анашым, өзіңіз де тойып тамақтаныңыз 🥑', 'Күнделікті қарбаласта түскі асты жүрдім-бардым ішпеңіз. Отырып, темір мен кальцийге бай ерекше салат дайындап, асықпай әрі сүйсініп жеңіз. Сіздің қуатыңыз — осы үйдің қозғалтқышы.'),
  ('e037ab2c-d2a8-49ed-a1df-aac78a584118', 'Достыққа алғашқы қадамдар 👫', 'Саябақта алғаш рет өз қалауымен ойыншығын басқа баламен бөлісті ме? Бұл — дамудағы үлкен жетістік! Эгоцентризм әлсіреп, эмпатия қалыптасып келеді. Оны зор қуанышпен қолпаштаңыз.'),
  ('1f9d373c-817c-4a86-9cb9-a9b3d9fac797', 'Шам жарығындағы 10 минут 🕯️', 'Бала ұйықтады, үйдегі қарбалас басылды. Жарықты өшіріп, қараңғылыққа немесе бір шамның жарығына қарап, 10 минут бойы миыңыз бен ойыңызды толық тынықтырыңыз.'),
  ('7ca4e4fb-3ef6-4d7f-b7a1-18d9264ed8c8', 'Қауымдастықтан медет табу 💬', '«Мен енді ешқашан бұрынғы қалпыма оралмаймын» деген ой Сізді тұншықтыра ма? Осы өткінші, бірақ өте ауыр сезімді Anacan қауымдастығындағы аналармен бөлісіп, олардан қолдау алыңыз.'),
  ('d270bdfa-5a84-42b7-8b44-3231febd32b3', 'Қырсық шаштар 🪮', 'Шашын жинауға да, тарауға да мүлде жол бермей ме? Таласуды доғарыңыз. Айнаның алдына барып, алдымен өз шашыңызды ол қалағандай тараңыз, содан кейін кезекті оған беріңіз.'),
  ('b155d377-4b41-487e-b8ee-74a365226635', 'Күндізгі ұйқы үшін күрес 🥱', 'Ұйықтаудан бас тартса, мәжбүрлемеңіз. Оны қайта-қайта ұйықтатуға тырысып, жүйкеңізді жұқартқанша, бөлмеде ойыншықтарымен тыныш ойнайтын уақыт ұйымдастырыңыз.'),
  ('181a440f-5684-4f29-a861-16adef184628', 'Уақыт зымырап өтіп жатыр!', 'Өткенге көз жүгіртіп, қаншалықты көп нәрсе үйренгеніңізді байқаңыз. Бұл кішкентай келіссөз шебері енді Сізбен кез келген тақырыпта саудаласа алады. Оны да, өзіңізді де мақтан тұтыңыз.'),
  ('31d8e844-a068-4aa5-8b2c-23a9d11616c4', 'Ертегі кейіпкері 🪄', 'Классикалық кітаптардан екеуіңіз де жалықтыңыздар. Ақылды ертегілерде оны ғарышкерге айналдырып, жұлдыздарға ұшырыңыз немесе теңіз тұңғиығына түсіріңіз. Ұйықтар алдында қиялға ерік беріңіз.'),
  ('4280853d-50c1-4092-8d31-3279f5e3d68a', 'Тыныштық уақыты міндетті ☕', 'Егер ол күндіз ұйықтаудан үзілді-кесілді бас тартса, мәжбүрлемеңіз. Бірақ 30 минуттық Тыныштық уақытын (quiet time) белгілеңіз. Ол төсегінде кітаптарымен оңаша қалсын, ал Сіз басқа бөлмеде тынығып алыңыз.'),
  ('10fd3d36-ea93-4f52-8bc2-486b88206869', 'Көңіл күй күнделігі 📝', 'Телефоныңызды қолыңызға алыңыз. Әлеуметтік желіні парақтаудың орнына, Көңіл күй күнделігін ашып, оның бүгін жасаған ең күлкілі, Сізді ерекше күлдірген сәтін болашаққа естелік ретінде жазып қойыңыз.'),
  ('502d3376-0322-4c07-aee1-71c209315c6b', 'Жасырын көкөністер операциясы 🥦', 'Сорпадағы көкөністерді теріп алып тастай ма? Онымен күреспеңіз. Тамақтану жоспарынан көкөністерді езіп, тұздықтарға жасырудың ерекше әрі айлакер тәсілдерін табыңыз.'),
  ('ad687f75-6bde-4ad1-8992-78906bd61fd5', '«Анашым, маған қарашы!» деген қырсықтық 👀', 'Сіз телефонға қарап немесе жұмыс істеп отырғанда, ол келіп қолыңызды қаға ма? Оның талабы орынды: ол бар назарыңыздың өзінде болғанын қалайды. Көзіне қарап, 5 минутты тек соған арнасаңыз, ол тынышталады.'),
  ('22e7c65d-25fb-4bbe-aa34-29a2d5e5e3ea', 'Бөлмеден қашу ойыны 🏃‍♂️', 'Сіз оған пижама немесе жейде кигізгіңіз келгенде, ол күліп бөлмеден қаша ма? Ашуланбай, мұны ойынға айналдырыңыз. Қуаласпақ ойнап жүріп киіндіру әлдеқайда оңай.'),
  ('322a385d-8940-4d2a-9d21-4777e2660139', 'Ауа райы туралы ескерту ⛅', 'Серуенге шығарда терезеден қарап қана шешім қабылдамаңыз. Ауа райы және киім көмекшісі арқылы даладағы нақты жел мен температураға сай келетін киім үйлесімін таңдап, содан кейін үйден шығыңыз.'),
  ('b7283d95-1357-4ff9-9423-db4159e19c31', 'Командалық жеңіс 🥂', 'Тағы бір қиын күнді артта қалдырдыңыздар. Жұбайыңызбен бетпе-бет отырып, бір шыныаяқ шаймен қағыстырыңыздар: Біз шынымен де керемет командамыз және бәрін тамаша атқарып жүрміз!'),
  ('c932a08e-a484-4595-8fa6-e57165ffaf96', 'Бөлісудің машақаты 🧸', 'Ойыншығын ешкімге бермей ме? Бұл өзімшілдік емес, дамудың бір кезеңі. 3 жасқа қарай бөлісуді емес, кезекпен ойнауды қалай үйретуге болатынын Anacan AI-дан біліңіз.'),
  ('23137ca6-6246-4dc7-b692-cdcd36eeac0f', 'Үш дөңгелекті велосипед 🚴‍♂️', 'Педальды басып, велосипед тебуге тырысып жүр ме? Аяқ бұлшықеттері мен қимыл үйлесімі дамудың жаңа кезеңіне өтті! Оны қауіпсіз жерлерде ынталандырыңыз.'),
  ('b44d4b2a-f3eb-4e26-aa50-0105efb5648c', 'Анаға арналған дәрумен 🥑', 'Оны тойдыру үшін қолыңыздан келгеннің бәрін жасайсыз. Ал өзіңіз ше? Пайдалы рецепттер бөлімінен темір мен кальцийге бай жеңіл түскі ас таңдаңыз.'),
  ('f62c402c-4ba9-489a-b6de-dde4e1aa3aae', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Түнде оянудың бар ауыртпалығын жалғыз көтермеңіз. Жұбайыңызды да оятыңыз: команда болу — жауапкершілікті тең бөлісу.'),
  ('10872122-03c1-4660-aabc-490c724034c9', 'Қалта толы қазына 🍁', 'Саябақтан қайтып келгенде, оның қалтасынан 3 тас, 1 қураған жапырақ пен бір бұтақ шықты ма? Ол үшін бұлардың бәрі — бағалы қазына. Сіз оларды үйге шашып үлгермей тұрып, жай ғана қауіпсіз жерге алып қоюға тырысыңыз.'),
  ('8f84e032-e8dd-4d1f-b3c6-5d57937006dd', 'Логика іздемеңіз 👑', 'Таңғы асқа балмұздақ немесе кешегі жасымық сорпасын талап ете ме? Үйде жаңа диктатор пайда болды. Оған таңдау құқығын беріп (Мысалы: Алма жейсің бе, әлде банан ба?), назарын дереу басқаға аударыңыз.'),
  ('907a5bc5-4a7e-48ec-977c-d9c5440faba0', 'Төсектен қашудың сылтаулары 🏃‍♂️', 'Су ішкісі келеді, дәретханаға барғысы келеді, бөлмедегі пердені сүйгісі келеді... Ұйықтамау үшін миы жаңа сылтаулар ойлап табады. Шектеу қойыңыз: Тек 1 стақан су — болды. Шешіміңізден қайтпаңыз.'),
  ('bd0902bb-9be1-40b5-8e41-73f85b835f0e', 'Таңғы көмекші 🧑‍🍳', 'Таңғы ас дайындауға көмектескісі келеді. Ұнды төгеді, суды шашады, асүйдің астан-кестеңін шығарады... Бірақ осындай ұсақ моторика жаттығулары арқылы ол дамып келеді. Сабырлы болыңыз.'),
  ('c929f83e-5e59-4728-8c79-df0502607758', 'Сиқыршы әкенің шоуы 🤡', 'Сіздің айла-тәсілдеріңіз әсер етпей қалғанда, әкесінің шығаратын оғаш дыбыстары жағдайды бірден құтқарады. Кешкі мазасыздық кезінде кезекті оған беріп, көңілді күлкіні сырттай тамашалаңыз.'),
  ('61f1a424-1da9-48ab-b336-92c9137ef39e', 'Жылы ванна терапиясы 🛀', 'Күні бойы жүгіріп, балаңыз да, Сіз де әбден шаршадыңыздар. Жылы ванна қабылдап жатқанда, жайлы табиғат дыбыстарын қосыңыз. Судың үйлесімді сылдыры тіпті ең қырсық баланы да ұйқыға дайындайды.'),
  ('8ae2c146-2d4a-4919-80fe-7f15c41cdc0e', 'Өзі құйғысы келеді 💧', 'Суды стақанға міндетті түрде өзі құйғысы келеді. Сүртетін шүберектерді дайындап қойыңыз, оның дербестікке деген ұмтылысын баспаңыз. Әрине, төгіп алады, бірақ бірнеше әрекеттен кейін стақанды қаншалықты ұқыпты толтыратынына таңғаласыз.'),
  ('c8458955-5810-4609-a23d-82b155bf6112', 'Қажып кету сезімі 🔋', 'Өзіңізді жеткіліксіз сезінесіз бе? Бәріне үлгере алмай жүрмін деп ойлайсыз ба? Қауымдастықтағы жазбаларды қарап шығыңыз: Сіз жалғыз емессіз әрі жеткіліксіз де емессіз. Сіз — осы баланың бүкіл әлемісіз.'),
  ('87267db7-ab44-41b2-82ed-1d12fea90f71', 'Ерекше грамматика 🗣️', '«Менің қарным ашылдым», «Ол кетіп бара жатып келді» деген сияқты мүлде жаңа, өзіндік грамматикалық құрылымдар ойлап табады. Оны қатаң түзетпеңіз, жауап бергенде сөйлемнің дұрыс нұсқасын жай ғана қайталаңыз.'),
  ('9a6f7d87-06ae-42b3-a4d0-b7eff2923976', 'Anacan AI кеңесі 🤖', 'Балаңыздың саябақта басқа балалармен араласуы туралы сұрағыңыз бар ма? Интернеттен сағаттап жауап іздемеңіз, Anacan AI-дан сұрап, баланың даму кезеңіне сай әрі педиатрлар мақұлдаған кеңесті бірден алыңыз.'),
  ('a3b7ecf2-9668-46df-b331-9c7487819a32', 'Түнгі қорқыныш туралы ескерту 😭', 'Балаңыз кенет жылап, көзін ашпай айқайласа, Жылауды талдау арқылы тексеріңіз. Егер бұл түнгі қорқыныш болса, оны оятуға тырыспай, тек жанында болып, үнсіз жұбатыңыз.'),
  ('4ab501ea-956f-4adc-a27e-2e2bc99f59c6', 'Денедегі тату-суреттер 🖍️', 'Бірнеше секундтық тыныштық кейде қауіпті. Бөлмеге кіріп, оның қолдарына фломастермен тату-сурет салып жатқанын көрдіңіз бе? Терең тыныс алыңыз. Ұсақ моторикасы дамып жатыр, ал терідегі бояу бәрібір жуылып кетеді.'),
  ('93712bd1-e114-4739-841f-9d8901785feb', 'Әке — Сіздің серіктесіңіз 👨‍👧', 'Кешке қарай күш-қуатыңыз таусылды ма? «Мен бұл ойыннан шығамын» деп, баланы әкесіне тапсырыңыз. Олардың бірге шашқан бөлмесін жинау баламен жалғыз арпалысқаннан оңайырақ.'),
  ('9a4e49fa-28ce-4422-86d1-9b77699fd24c', 'Талшыққа қажеттілік 💩', 'Көп жүгіреді, бірақ су ішуді ұмытады. Түбекке отырғанда нәжісін бақылаңыз. Іш қату қаупі болса, ас мәзіріне сұлы мен қара өрік қосыңыз.'),
  ('2743b373-11c6-4a72-a371-988483c30fb4', 'Көлеңкемен жауласу 👻', 'Көшеде немесе бөлмеде кенеттен жылай бастады ма? Оған соңынан қалмай келе жатқан көлеңкесі себеп болуы мүмкін! 3 жасқа таяғанда қиялы өзгеше сипат ала бастайды. Оны құшақтап, көлеңкесімен күлімдеп таныстырыңыз.'),
  ('344cf14d-0511-4f06-86bb-38e1e79297c3', 'Тағам хирургі 🥦', 'Тамағын жемей, ішіндегі ұсақ күріш түйірлерін немесе жасыл дәмдеуіштерді хирургтің дәлдігімен теріп алып отыр ма? Тамақтану жоспарына кіріп, көкөністерді езбе түрінде ұсыну жолдарын қарастырыңыз.'),
  ('85bf1b2b-8bd2-41a8-8e81-bd414469ff03', 'Барлығымен қоштасу 🧸', 'Ұйықтар алдында бөлмедегі ойыншық мәшинеге, орындыққа, тіпті есіктің тұтқасына да «қайырлы түн» айтқысы келеді. Бұл — оның ұйқыға дайындалу үшін меңгерген жаңа рәсімдерінің бірі. Оны асықтырмаңыз.'),
  ('4699f7a7-a05a-4fb5-bcc3-1031cc990173', 'Қиялдағы іскерлік қоңыраулар 🍌', 'Қолына банан немесе теледидар пультін алып, ойдан шығарылған тілде телефонмен маңызды кейіпте сөйлесіп жүр ме? Ол Сіздің дене қимылдарыңызды айнытпай қайталап жүр. Видеоға түсіріп, болашаққа сақтап қойыңыз — кейін әбден күлесіз.'),
  ('77b18a3d-16c2-454b-9fe4-daea00f5a342', 'Күн тәртібі өзгеріп кетті ме? ⏱️', 'Кешке ұйықтатуға 1 сағаттан артық уақыт кете ме? Ұйқы таймерінің кестесін қараңыз. Мүмкін, күндізгі ұйқыны толығымен тоқтатып, кешкі ұйқы уақытын ертерек жылжытатын кез келген шығар.'),
  ('9ed1ae4d-be3f-4fb2-a1fd-f7b060b22469', 'Тіс щеткасымен айқас 🪥', 'Тіс щеткасын көргенде аузын ашпай қоя ма? Тазалықты айқасқа айналдырмаңыз. Ұсынылатын өнімдерден музыкалық щеткаларды қарап, осы азапты күнделікті істі көңілді ойынға айналдырыңыз.'),
  ('3d5dc682-22fb-45d2-8bc6-6a1ae9873a3a', '«Аяғым жүрмей қалды» деген қырсықтық 🛑', 'Саябақтан қайтып келе жатқанда кенет жерге отыра қалып, «аяғым жүрмей қалды» деп құшаққа сұрана ма? Бұл шаршау емес, айла. «Қане, үйге дейін қоян сияқты секіріп жете аласың ба?» деп, жағдайды ойынға айналдырыңыз.'),
  ('b948ea64-f471-4d36-958a-85e04a0250f1', 'Түбекпен жасырынбақ 🚽', 'Дәретке отырғысы келгенде перденің артына немесе диванның жанына тығыла ма? Блогтар бөліміне өтіп, түбекке үйретуді бастаудың ғылыми негізделген қадамдарын оқитын нағыз уақыт келді.'),
  ('b9e8fff7-f7f2-410b-a103-f4cd6c6231f8', 'Күнделікке ашуды төгу 📝', 'Біреу Сізге «Үйде отырсаң да, несіне шаршайсың?» деді ме? Дереу Көңіл күй күнделігін ашып, бүкіл ашуыңызды саусақтарыңызбен экранға төгіңіз. Жасанды жымиғаннан гөрі, шынайы сезімдеріңізді жазған әлдеқайда жақсы.'),
  ('0de1aee1-4ccd-4daa-b9f3-ed4d6ab70bfc', 'Әкенің ертегі шоуы 📖', 'Бүгін кешке бөлмеде Сіздің емес, әкесінің дауысы естілсін. Ертегіні сол оқып, кейіпкерлердің дауысын бірде жуандатып, бірде жіңішкертіп, күлкілі етсін. Ал Сіз шетте тұрып, күлкілерін тыңдаңыз.'),
  ('2fc731d4-47df-4b97-8f67-c7df6aabac96', 'Ананың жасырын шоколады 🍫', 'Бөпе теріс қараған сәтте аузына бір тілім шоколад салып, тез шайнап үлгеретін ана, бұл глюкоза — Сіздің табиғи құқығыңыз. Күні бойы сол қарқынға төтеп беру үшін қуат жинауыңыз керек.'),
  ('edb08c0a-b151-4f7a-9713-c903f3f5c584', 'Ерекше жан досы 🥄', 'Қаншама қымбат ойыншығы бола тұра, асүйден силикон қалақша тауып алып, күні бойы сонымен жүріп, тіпті ұйықтата ма? Бөпенің қиялы ғажап. Кедергі жасамаңыз, қалақшасын жақсы көре берсін.'),
  ('36ebb286-2e4d-4e44-a91d-6c026199737c', 'Табиғатты зерттеу ⛅', 'Төрт қабырға миыңызды тұмандатып жіберді. Ауа райына қарап, соған сай ең қолайлы киімді таңдаңыз. Далаға шығып, сары жапырақ іздеу тапсырмасын орындаңыз: бөпе энергиясын жұмсасын, ал Сіз таза ауамен тыныстаңыз.'),
  ('4b98ee52-d8a1-4d7a-9183-64cdd8482ef0', 'Тыйым салынған сөздер 🤐', 'Бір жерден естіген жаман сөзді күліп тұрып Сізге қайталап, реакцияңызды күте ме? Ең мықты қаруыңыз — еш реакция білдірмеу. Күлмеңіз, ашуланбаңыз, жай ғана елемеңіз. Ұмытып кетеді.'),
  ('c2b89303-d5b8-4b81-97cd-3a091f15bb05', 'Алтын тыныштықтың өлшемі 🤫', 'Ақыры ұйықтап қалды! Дыбыс өлшегішті қосып, бөлмедегі абсолютті дыбыс деңгейін (0-10 децибел) экраннан бақылаңыз. Бұл сандарды көру — шаршаған ананың миына жасалған ең жақсы массаж.'),
  ('45a51286-f051-4f99-a23c-39a189481dfa', 'Қырсық пижама 👗', 'Таңнан кешке дейін киіп, кірлетіп, дақ түсірген пижамасын шешкісі келмей ме? 3 жаста эстетика маңызды емес. Тоңбаса, тағы бірнеше сағат солай жүре берсін.'),
  ('4c871abf-c886-4fbd-909f-95e344736fa3', 'Ақылды ертегідегі мен 🪄', 'Классикалық кітаптарды жатқа білесіз. Ақылды ертегілерді ашып, басты кейіпкерді балаңыз, ал бағындыратын мекенді оның бөлмесі етіп құрастырыңыз да, ерекше ұйқы алдындағы сәт жасаңыз.'),
  ('9f3be00e-0091-4500-91da-22dc9ba62d93', 'Мультфильм сыншысы 📺', 'Көрген мультфильмін Сізге өз грамматикасымен айтып, кімнің қайда барғанын байыппен түсіндіреді. Оны мұқият әрі таңғалғандай тыңдаңыз. Өзін әлемдегі ең ақылды жан сезінсін.'),
  ('89c52f3b-2e4b-4c88-b0bc-f1bbe0891bb8', 'Күннен бұрын оянатындар 🌅', 'Ол таңғы сағат 6-да тұрып алды, ал Сіздің әбден шаршадыңыз ба? Бұл режимді қалай реттеуге болатынын Anacan AI-дан сұраңыз. Есіңізде болсын, ұйқысыздық мәңгі емес, бәрі де өтеді.'),
  ('e229522e-360b-4392-8cfc-620f6326286c', 'Екеуіңізге арналған шампан 🥂', 'Бала ұйықтап қалды. Шампан болмаса да, стақандарға ыстық шай құйып, жұбайыңызбен «Осы қиын күнді де аман-есен аяқтадық» деп стақан түйістіріңіз. Сіздер — керемет серіктессіздер.'),
  ('f802a634-da9b-44e2-a965-9f94ea543fd1', 'Тізімдегі тосынсый 🛒', 'Дүкенге барар алдында «Сатып алу тізімін» аштыңыз, ал ол артыңыздан келіп, телефон экранын басып, тізімге шоколад қосып қойғанын көрдіңіз. Иә, олар технологияны Сізден жақсы біледі!'),
  ('0d0524d6-a4ad-4051-b779-b554d981748f', 'Ваннада бүріскен саусақтар 🛀', 'Сумен ойнау сондай қызық: саусақтары бүрісіп қалса да, ваннадан шыққысы келмейді. Оған 5 минут бұрын ескертіп, таймер қойыңыз. «Қоңырау соғылғанда шығамыз» деген ереже көбіне көмектеседі.'),
  ('1460be31-c5b7-4f0f-9a6b-7ff5c2085c36', 'Шаш тарау тартысы 🪮', 'Таңертең оянғанда шашы тоқ соққандай тікірейіп тұрады. Ал тарақты көре сала қаша жөнеледі. Тараудың орнына шашын қолыңызбен сулап, жатқызыңыз да, тартысты тоқтатыңыз.'),
  ('fc5667d9-2c85-42d4-a92c-e90c3b994a0f', 'Жасанды интеллекттің пікірі 🤖', 'Балаңызда бір оғаш әдет пайда болды ма (мысалы, тырнағын тістеу) және интернеттегі мақалалар Сізді қорқытып жіберді ме? Тоқтаңыз. Anacan AI-дан оның педиатрлар растаған нақты себебін сұрап, көңіліңізді тыныштандырыңыз.'),
  ('01349acb-919c-490a-bfce-f75e04518130', 'Дәрігер қасыңызда 🩺', 'Ойыншық стетоскопын алып, кеудеңізге қояды да, дем алыңыз дейді. Сіз — науқассыз, ал ол — бас дәрігер. Осы ойынды ойнаңыз: жатып, ем қабылдап жатқанда тым болмаса 5 минут көзіңізді жұмып, демалып алыңыз.'),
  ('d58d064b-a397-425d-9d57-3f6068e31cf1', 'Энергия тасқыны 🏃‍♂️', 'Үйдің ішінде қабырғаларға өрмелеп жүр. Ауа райын тексеріп, лайықты киім кигізіп, міндетті түрде далаға шығыңыз. Таза ауада 30 минут жүгіріп ойнау — оның кешке жақсы ұйықтауының ең сенімді кепілі.'),
  ('d96fbe0f-26f7-4473-9f0b-34109da6a744', 'Сыбырдың сиқыры 🌙', 'Бөлменің жарығын толығымен өшіріңіз. Жанына жатып, күні бойы болған оқиғаларды оған өте бәсең дауыспен, сыбырлап айтып беріңіз. Сыбырлау — миды ұйқыға дайындайтын ең табиғи әрі тыныштандыратын тәсіл.'),
  ('2521dffb-415b-4bec-81f4-b18ee93644d8', 'Қараңғылыққа үйрену 🌙', 'Тезірек ұйықтауы үшін бөлмедегі барлық қосымша жарықты және планшет экрандарын өшіріңіз. Мелатонин гормонының бөлінуі тек тыныш әрі қараңғы ортада жылдамдайды.'),
  ('8ca17d8b-45e4-4184-b598-9b59778d5b0c', 'Ананың қуат жинайтын уақыты 🔋', 'Ол өздігінен пазл құрастырып, 10 минуттан бері тыныш отыр. Ал Сіз осы сәтті үй жинауға жұмсамақсыз. Жоқ! Диванға барып жатыңыз. Кешке дейін күшіңіз жетуі үшін Сіздің де қуатыңыз толуы керек.'),
  ('c145c120-a19a-477b-922c-6f3ffc430787', 'Ойдан шығарылған грамматика 🗣️', '«Мен бардымдым», «Ол келіпті еді» сияқты қызық әрі күлкілі шақ формаларын ойлап тауып жүр. Сөздік қоры дамып келеді! Оны күліп тұрып түзетпеңіз, жай ғана дұрыс сөйлемді қайталап, ойын растаңыз.'),
  ('6e5eaf14-24e1-4f23-8d49-63a035b843ff', 'Көңіл күй күнделігін паналау 📝', 'Сіздің осыншалықты шаршағаныңызды ешкім байқамай жүр ме? Қолданбадағы Көңіл күй күнделігі Сізді тыңдауға әрдайым дайын. Бүгін жүйкеңізге тиген барлық ұсақ-түйекті сонда жазып, ойыңызды сергітіңіз.'),
  ('b83f22c8-15c6-43cf-9689-94f8a790e4b9', 'Тамаққа қатысты сынақтар 🥣', 'Кеше ғана жеген тағамдарының бәрін бүгін түкіріп тастайды. Тісіне байланысты мәселе болмаса, бұл жай ғана Сіздің төзіміңізді сынау. Пайдалы рецепттер бөлімінен көкөністер жасырылған дәмді әрі түрлі түсті котлеттердің рецепттерін байқап көріңіз.'),
  ('fe01f44d-664a-4a34-8ce6-39e87f7fdab2', '5 минут елесі ⏱️', '«Тағы 5 минут қана қараймын» дейді, бірақ оның санасында 5 минут деген ұғым әлі жоқ. Телефон таймерін орнатып, дыбыс естілгенде уақыттың біткенін түсіндіріңіз. Кінәлі Сіз емес, технология болсын.'),
  ('1fc309f5-659f-4b2e-bf6f-e17296d830ff', 'Әкенің арқасындағы ат ойыны 🐴', 'Күш-қуатын толық жұмсай алмай, ұйықтағысы келмей жүр ме? Әкесінің арқасына мініп, үй ішінде ат шапқандай ойнау және мәз болып күлу — сол энергияны жұмсаудың ең жылдам әрі көңілді жолы. Ендігі кезек әкеде.'),
  ('69846205-68bb-4476-a7e0-45d4e68fae26', 'Ананың тыныштыққа мұқтаждығы 🩸', 'Әрбір дыбыс жүйкеңізге тиіп жүр ме? Етеккір трекерін тексеріңіз. Денеңізге демалыс қажет. Пайдалы рецепттер бөлімінен магнийге бай тіскебасар дайындап, өзіңізге уақыт бөліңіз.'),
  ('c6dcd330-d5df-4d87-b7a0-d8ab33a73063', 'Себепсіз айқайлау 😭', 'Көзін аша сала себепсіз жылай ма? Бұл еркелік емес, эмоциялық шамадан тыс жүктеме. Осындай күйзеліс кезінде не істеу керектігін Anacan AI сарапшысымен сырласа отырып біліңіз.'),
  ('6ac257ab-47ac-4e61-a9e4-2b538df0a8dc', 'Әкенің асүйдегі кезекшілігі 👨‍🍳', 'Бүгін түскі ас дайындап, бөпені тамақтандыру — әкенің міндеті! Ал Сіз бұл уақытты жай ғана жатып немесе тынығып, өзіңізге арнаңыз.'),
  ('0cd42656-20ce-4f47-aca2-4978ae93880d', 'Дәретке баруда кері қадам? 🚽', 'Түбекке баруды үйреніп еді, енді қайтадан үлгермей жүр ме? Бұл — қалыпты уақытша кері кету. Қысым жасамаңыз, осы психологиялық кедергіден күйзеліссіз өту жолдарын Anacan AI-дан сұраңыз.'),
  ('3164bc6c-fe7e-4273-94e8-6750bee50d0a', 'Блогтардан шабыт алу 📱', '35 айға таяған баланың дамуында қандай серпілістер болады? Ол нені істей алуы керек? Қосымшадағы даму туралы блогтарды қарап шығып, балаңыздың қаншалықты жақсы дамып келе жатқанына қуаныңыз.'),
  ('4d45db57-1817-4fc6-ad71-f2aeb4cd1050', 'Мерекеге дайындық 💆‍♂️', 'Бала ұйықтағаннан кейін жұбайыңызбен ертеңгі маңызды белесті атап өтіп, бір-біріңіздің иығыңызға жеңіл массаж жасаңыздар. Мерекелік күнге күш жинау үшін екеуіңіз де жақсылап демалуларыңыз керек.'),
  ('41e90866-d00f-459e-8936-e28d83f9d539', 'Ұйықтар алдындағы қашып-пысу 🏃‍♂️', 'Ұйықтаудың орнына диванда секіріп жүр ме? Біресе су сұрап, сылтауы таусылмай ма? Ұйқы таймерін қосып, белгіленген шекарадан таймаңыз.'),
  ('4f9eced2-7736-4f35-ad7d-6205edaad1e4', 'Әкенің ойнайтын кезегі 👨‍👧', 'Ана болу — бітпейтін марафон емес. Бүгін баланың энергиясын саябақта әкесі шығарсын, ал Сіз диванда оңаша демалудың рақатын көріңіз.'),
  ('e18107ed-4459-4f40-b466-2d79ae0ff98c', 'Жазда қысқы бас киім кию 🧢', 'Ауа райына мүлде сай келмейтін киім кигісі келе ме? Дербестікке ұмтылған кезінде оған бірнеше қарапайым таңдау ұсыныңыз.'),
  ('37ca7eb9-999f-4245-9a90-94f0e28e6df4', 'Таусылмайтын сұрақтар 🤔', '«Неге?», «Қалай?» деген сұрақтардан басыңыз қатып жүр ме? Оның білуге деген құштарлығын жалықпай қолдап, қисынды жауап беру жолдарын Anacan AI-дан біліңіз. Сіздің сабырыңыз — оның дамуына қосқан үлесіңіз.'),
  ('70e9f70c-b53f-462f-9274-badc9beebd25', 'Тыныштық күнделігі 📝', 'Үйдегі құйын ақыры ұйықтады. Енді телефонды қолыңызға алып, Көңіл күй күнделігіне бүгінгі күннен аман өткеніңіз үшін өзіңізге алғыс хат жазыңыз. Сіздің қолыңыздан келеді.'),
  ('ba525880-dd70-46d8-9c0c-f0fb9b49240c', 'Табиғат дыбыстарымен ұйықтау 🪄', 'Классикалық музыка көмектеспей ме? Ақылды ертегілерде ертегіні өшіріп, тек жаңбырдың немесе орманның дыбыстары бар фонға ауысыңыз. Бірқалыпты табиғат дыбыстары баланы сиқырлағандай ұйықтатады.'),
  ('ba82984e-ccd6-40f9-b991-bf586ff48b9d', 'Үлкендерше күрсіну 😔', 'Диванда отырып, кенет үлкендер сияқты терең дем алып, күрсінеді. Сізді айнытпай қайталайды! Оның осындай әсерлі мимикаларын сырттай жымиып қана бақылаңыз.'),
  ('268f32e3-3ad0-45c0-aef4-aba7ce610179', 'Асүйдегі қызықтар 🧑‍🍳', 'Тамақ пісіріп жатқанда міндетті түрде пештің жанында Сізге көмектесіп, тұз салғысы келеді. Рұқсат етсеңіз, тамақ бүлінеді, рұқсат етпесеңіз, жылайды. Оған бос ыдыс пен су беріп: «Сен өз сорпаңды пісір», — деңіз.'),
  ('e612b840-bcec-4199-920b-e4d2f37aa7cb', 'Тізімді тексеру 🛒', 'Мерейтойға қажет нәрсенің бәрін Сатып алу тізіміне қостыңыз ба? Шарлар мен шағын тосынсыйлардың да тізімде бар екеніне көз жеткізіңіз. Жұбайыңызға қолданба арқылы соңғы еске салуды жіберіңіз.'),
  ('eb50f918-4009-4323-94a0-e8fd1ccc9f1d', 'Жарықты бақылау 🤫', 'Ұйықтап кеткеннен кейінгі алғашқы жарты сағат — мидың ең белсенді болатын уақыты. Дыбыс өлшегіштің көмегімен бөлмедегі жағдайды реттеңіз. Терезеден естілетін дыбыстарды бәсеңдетіп, барынша тыныш әрі қараңғы орта жасаңыз.'),
  ('0cde3d33-fabc-43f7-bcba-b8c6c307e26e', 'Оқиғаның режиссері 🪄', 'Ақылды ертегілерді қосып, бүгін кешке оқиғаны баланың өзі бағыттауына мүмкіндік беріңіз. «Енді кейіпкер қайда барсын?» — деп сұраңыз. Өзі ойлап тапқан қисынсыз аяқталумен бірге ұйықтап қалсын.'),
  ('60a51ebc-ca29-4910-bc60-cd0880a0539a', 'Себепсіз көз жасы 🐶', 'Көшеде көрген ит оған қарамады деп 15 минут өксіп жылады ма? Бұдан қисын іздемеңіз. Бала үшін бұл шынымен де үлкен қайғы. «Білемін, сен оның саған қарағанын қаладың», — деп, сезімін қабылдайтыныңызды көрсетіңіз.'),
  ('e0a781fd-ff93-41bb-aced-df42a4ca9525', 'Үйдегі бейберекетті қабылдау 🌪️', 'Бөлменің іші ойыншыққа толып кетті ме? Тазалық емес, балаңызбен бірге өткізген осы көңілді сәттер маңызды. Ойыншықтар ертең де орнында болады, өзіңізді шаршатпаңыз. Кейде бейберекетке мән бермеу — ең жақсы демалыс.'),
  ('cac1efaa-10e1-4f19-b586-507cb8610102', '«Өзім істеймін» кезеңі 🛑', 'Аяқкиімінің бауын өзі байлағысы келіп, оған 10 минут уақытыңыз кетіп жатыр ма? Асықтырмай, оған уақыт беріңіз. Талаптанып көруі мен қателесуі — болашақта мәселені шешу дағдысының негізі.'),
  ('078ff563-48f3-4bd6-81ac-93fc21a3bab7', 'Кофе және медитация ☕', 'Бөлменің астаң-кестеңін шығарды ма? Жинауды қоя тұрыңыз. Бала өзімен-өзі ойнап отырғанда, диванға жайғасып, ыстық кофеңізді ішіңіз де, қабырғаға қарап отырып, 10 минут миыңызды тынықтырыңыз.'),
  ('710f54a9-baa0-4889-a361-f7615894b552', 'Мамандықтарға еліктеу 🩺', 'Ойыншық қонжығын емдеп немесе мәшинелерін жөндеп жүр ме? Символдық ойындар (рөлдік ойындар) нағыз қызған шағына жетті.'),
  ('9f105ce0-5653-4d0b-8d96-2ed9abdc7e4a', 'Көлеңке ойыны 🐰', 'Ұйықтағысы келмей ме? Бөлмені толық қараңғылап, қабырғаға қолдарыңызбен көлеңке театрын жасаңыз. Бұл — қараңғыдан қорқуды жеңудің ең қызықты жолы.'),
  ('3a84b553-313a-486c-95e8-2a799895283c', 'Сен жыламашы 🫂', 'Саябақта жылап тұрған басқа баланы көргенде, қасына барып жұбата ма? Жанашырлық сезімі іске қосылды! Оның осындай керемет мейірімділігін сырттай мақтанышпен бақылаңыз.'),
  ('77ff1ffc-86a7-418d-bad4-4d026f199772', 'Үлкен кереуетке ауысатын кез келді ме? 🛏️', 'Бесігінен өрмелеп түсуге тырыса ма? Мүмкін, үлкен кереуетке ауыстыруды ойлап жүрген боларсыз. Anacan AI-дан үлкен балалар кереуетіне ауысудың қауіпсіздік ережелері мен ең қолайлы уақытын сұраңыз.'),
  ('e176efcb-aafc-4480-93eb-e1978282a880', 'Әкенің кітап оқу сағаты 📖', 'Бүгін кешке дауысыңызды тынықтырыңыз. Баланың сүйікті кітаптарын әртүрлі дауыс ырғағымен оқуды әкесіне тапсырыңыз.'),
  ('65edab42-e5b4-4da3-8b99-8e271dd3fc16', 'Жеке шекарасын белгілеп жүр ✋', 'Біреу оны сүйгісі келгенде, шегініп немесе «жоқ» дей ме? Оның дене шекарасына құрметпен қарап, өзгелерден де соны талап етіңіз. Өзіне деген сенім дәл осыдан басталады.'),
  ('c46434f8-d6b6-4038-89e7-8bc38a5332c2', 'Ақылды ертегінің сиқыры 🪄', 'Классикалық ертегілерден жалықтыңыз ба? Ақылды ертегіге ерекше тақырып ұсыныңыз: көкөніс жегенді ұнататын сиқырлы динозаврдың шытырман оқиғалары.'),
  ('d941dd67-309a-49cb-833c-78b38c4762e7', 'Киім дипломатиясы 👗', 'Қыстың ортасында жазғы шалбар кигісі келе ме? Бірден Ауа райы және киім құралын ашып, экрандағы көрнекіліктер арқылы оған далада күн суық екенін қисынды түрде түсіндіріңіз.'),
  ('0ff4754d-26cd-4a0c-9aad-d8a1cbe8e5a6', 'Тыныштықтың қадірі 🤫', 'Ол ақыры ұйықтап қалды. Енді үйдегі ең кішкентай дыбыстың өзі жүйкеңізге тиеді. Дыбыс өлшегішпен бөлмедегі шу шегін белгілеп, артқы фонға үздіксіз ақ шу қосыңыз.'),
  ('bf9527d0-d7b0-4cb8-8523-c499e2e95693', 'Санауды бастаймыз 🔢', 'Баспалдақпен көтерілгенде немесе ойыншықтарын реттегенде бір, екі, үш деп айтуға тырыса ма? Математикалық ойлаудың негізі қаланып жатыр. Онымен бірге бөлмедегі заттарды дауыстап санаңыз.'),
  ('ebcc858d-cfdb-4af6-a7c6-c1e46f778ba5', 'Эмоциялық күйіп кету синдромы 🔋', 'Бәріне айқайлағыңыз келе ме? Сіз эмоциялық күйіп кетуді бастан өткеріп жүрсіз. Anacan қауымдастығына кіріп, Мен қатты шаршадым деп жазыңыз. Сол сәтте мыңдаған әйелдің Сізбен тілектес екенін көресіз.'),
  ('405360f8-7a97-471c-825c-355eafed365d', 'Күндізгі ұйқыдан бас тарту 🥱', 'Күндіз мүлде ұйықтағысы келмей, қарсылық көрсете ме? 3 жасқа қарай кейбір балалар күндізгі ұйқыны қояды. Күн тәртібіндегі ұйқыны Тыныштық сағатымен (ұйқысыз тыныш уақыт) алмастырып көріңіз.'),
  ('6740b19e-f070-42e2-9b6e-76434890c90f', 'Естеліктер оянады 🧠', 'Кеше әжеміздің үйіне бардық деген сияқты өткен шаққа қатысты сөйлемдер құрай ма? Уақыт туралы түсінігі мен ұзақмерзімді жады қалыптасып келеді. Оның естеліктерін қызығушылықпен тыңдап, сұрақтар қойыңыз.'),
  ('f0257b2e-d5f4-40d8-9701-488c186af81f', 'Түн ортасында көзін жұмған күйі айқайлап жылай ма?', 'Оны оятуға тырыспаңыз. Даусын Жылауды талдау құралына тыңдатып, бұл жай ғана түнгі қорқыныш екеніне көз жеткізіңіз де, қасында тыныш қана отырыңыз.'),
  ('f7c61cc4-7a2d-48d0-bf89-ec947a89cd75', 'Әкенің жауапкершілігі 👨‍🍼', 'Барлығын өзіңіз істеуге міндетті емессіз. Бүгін кешке тіс тазалау мен пижама кигізуді толығымен әкесіне тапсырып, сырттай бақылаңыз.'),
  ('07c7c2cb-58bb-47db-ac0e-f81bd01e602b', 'Ана дауысының құдіреті 🎶', 'Бүгін кешке ешқандай құрылғы қолданбаңыз. Оны жай ғана кеудеңізге қысып, ең жақсы көретін бесік жырын құлағына сыбырлап айтыңыз. Сіздің даусыңыз — оның ең сенімді айлағы.'),
  ('1acb826a-9b73-413f-b0af-4614a74084bd', 'Жедел педиатриялық қолдау 🤖', '3 жасқа таяған балаңыздың бойы мен салмағының өсу кестесі Сізді алаңдата ма? Интернеттен сағаттап іздемей-ақ, нақты әрі педиатрлар мақұлдаған көрсеткіштерді Anacan AI-дан бірден біліңіз.'),
  ('5bb344ff-e859-413b-93f7-4f25386f0835', 'Өз аты мен жасын біледі 🎂', '«Жасың нешеде?» деп сұрағанда, саусақтарымен көрсетуге тырыса ма? Бұл — өзін-өзі тануының тамаша дамып келе жатқанының белгісі. Даму трекеріне осы зияткерлік серпілісті белгілеңіз.'),
  ('2c139fbd-2360-47be-8201-67957bcf1684', 'Айна алдындағы режиссер 🎭', 'Айна алдында тұрып, әртүрлі бет қимылдарын жасап, өзімен-өзі сөйлесе ме? Ол түрлі рөлдерді байқап көріп жүр. Оны білдірмей бақылап, осы күлкілі сәттерден ләззат алыңыз.'),
  ('42026a5f-2788-45b9-acb9-1e97ccc1366b', 'Қуат қорын толықтыру керек 🍲', 'Күн бойы жүгіріп, әбден шаршадыңыз. Пайдалы рецепттер бөлімінен өзіңізге де, балаңызға да ұнайтын, темір мен ақуызға бай ерекше түскі ас таңдаңыз.'),
  ('f413f7f2-f85e-4bd1-a054-6b9d46b4d341', 'Күнді қорытындылау 📝', 'Бала ұйықтаған соң, жұбайыңызбен бірге Көңіл күй күнделігін ашыңыз. Балаңыздың бүгін жасаған ең күлкілі әрекетін жазып, бірге күлімдеп, күйзелістен арылыңыз.'),
  ('59d23d62-6dca-4962-aec7-eb093810797b', 'Әуенмен ұйқыға дайындалу 🛀', 'Кешкі ұйқыға дайындау қиындап кетті ме? Жылы ванна қабылдап жатқанда, баяу классикалық музыка қосыңыз. Су мен музыканың үйлесімі тіпті ең қырсық баланың өзін тыныштандырады.'),
  ('895f4348-4fb2-4124-9532-acf7d07409f6', 'Әкенің әдістері 👨‍🍼', 'Балалардың әкелерімен бірге жасайтын ерекше әдеттері болады. Бүгін кешкі ұйықтату рәсімін әкесінің көңілді ережелеріне тапсырып, бөлменің сыртында тыныш қана шайыңызды ішіңіз.'),
  ('aca7ae85-535e-4175-ab27-d1ca390e78cb', 'Түстерді танып-білу 🎨', '«Бұл қызыл, ал бұл көк» деп, түстерді дұрыс топтастыра ма? Бұл — когнитивті дамудағы үлкен ілгерілеу! Даму трекерінде осы жетістікті мақтанышпен белгілеңіз.'),
  ('b6ee83b4-0d5f-4791-8483-ed7d1d3aa649', 'Асүйде бірге 🧑‍🍳', 'Сізбен бірге бірдеңе жасағысы келе ме? Пайдалы рецептілердің ішінен оңай кекс таңдап, ұн немесе су қосуға көмектесуіне мүмкіндік беріңіз. Айнала былғанса да, көңілді уақыт өткізуге кепілдік бар.'),
  ('2009290a-99c2-4bf0-a2b6-174daa69d49d', 'Түнгі децибелдер 🤫', 'Көшеден естілетін дыбыстар оның терең ұйқыға кетуіне кедергі келтіре ме? Бөлмедегі дыбыс деңгейін дыбыс өлшегішпен тексеріңіз.'),
  ('2a0f6e31-8cdc-436b-8432-73cf4dad5b5c', 'Суретші жұмыс үстінде 🖍️', 'Қабырғалар мен есіктер кейде оның сурет тақтасына айналады. Ашуланудың орнына үлкен қатырма қағаз тауып, еденге жайыңыз да: «Бұл — сенің орның», — деңіз. Оның ерік-жігерін дұрыс арнаға бағыттаңыз.'),
  ('7750d70c-df5b-48b0-9b2f-522c15391059', 'Сұрақтар тасқыны 🤖', 'Бөпеңіз 3 жасқа таяғанда, оның мінез-құлқы туралы сұрақтарыңыз көбейе түсті ме? Anacan AI — Сіз үшін 7/24 қолжетімді цифрлық педиатр әрі психолог. Сұрағыңызды жазып, бірден жауап алыңыз.'),
  ('2859fc00-366b-44b7-ba24-815b9b659125', 'Сезімдеріңізді еркін жіберіңіз 📝', 'Өзіңізді тым жалғыз әрі ешкім түсінбейтіндей сезінесіз бе? Бұл — қалыпты сезім. Көңіл күй күнделігіне сезімдеріңізді шынайы жазып отырыңыз.'),
  ('4f59cf22-ccfa-43b9-8a30-62365a911312', 'Өз «Менін» танып жүр 👑', '«Мен!», «Менікі!» деген сөздерді аузынан тастамайды. Бұл — эгоцентризм кезеңінің ең айқын шағы. Оның даралығын құрметпен қабылдаңыз, бұл — даму кезеңдерінің бірі.'),
  ('605d2ada-99ba-4138-bd88-c091a6c53e2b', 'Сені таптым деген қуаныш 🙈', 'Тығылмақ енді оның ең сүйікті ойынына айналды. Перденің артына тығылып, Сіздің оны тапқаныңызды күтеді. Заттардың көзден таса болса да бар екенін түсінуі осы жаста ойын арқылы нығая түседі.'),
  ('c0738cb9-5d1f-47d6-821c-55b543c58b28', 'Қырсығу сәттерін басқару 🛑', 'Дүкенде немесе саябақта баланың аяқ астынан қырсығуы Сізді ұялта ма? Есіңізде болсын, айналадағы адамдардың не ойлайтыны емес, балаңыздың сол сәттегі сезімі маңызды. Оны сабырмен құшақтаңыз.'),
  ('244e81e4-ef8a-4010-a428-229aabe2c4b0', 'Серігіңізден көмек сұраңыз 🛒', 'Дүкен аралауға уақытыңыз жоқ па? Сатып алатын заттар тізімін ашып, үйде жетіспейтін нәрсенің бәрін белгілеңіз де, бір рет басып, серігіңізге жіберіңіз. Міндеттерді бөлісу өте маңызды.'),
  ('e5509d0f-428a-4a25-9b61-f825746504ad', 'Үнсіз кітап оқу 📖', 'Бүгін кешке бөлмеде тек кітап беттерінің сыбдыры естілсін. Екеуіңіз де төсекке жатыңыздар: ол суретті кітабын қарасын, ал Сіз тыныштықта демалыңыз.'),
  ('f568dd40-0374-40d2-8f34-9a863c9b7158', 'Қауіпті секірулер 🧗‍♂️', 'Диванның үстінен еденге секірмек бола ма? Ол өзінің қимыл-қозғалыс дағдыларына тым сенімді. Тыйым салудың орнына, еденге жұмсақ жастықтар төсеп, қауіпсіз секіру аймағын жасаңыз.'),
  ('1222929d-ba35-40ba-92f4-2c3b29988e2e', 'Ережені бұзып тексеру ⚠️', '«Бұлай жасама» дегеніңізге қарамастан, көзіңізге қарап тұрып сол әрекетті қайталай ма? Оның мақсаты Сізді ашуландыру емес, белгілеген шекараларыңыздың қаншалықты тұрақты екенін тексеру. Ережелеріңізден айнымаңыз.'),
  ('60d686a6-8001-479b-9d53-bcd85bcdffdb', 'Үй жиналмай-ақ қойсын 🌪️', 'Күн сайын бір ойыншықтарды қайта-қайта жинаудан шаршадыңыз ба? Бүгін жинамаңыз! Үйдің шашылып жатуы дүниенің соңы емес, ал ананың психологиялық күйзеліске ұшырауы — маңызды мәселе.'),
  ('e7bfaacc-c0cc-4b36-8687-477371b3bc3d', 'Бүгінгі ақылды ертегі 🪄', 'Ақылды ертегіге ерекше тақырып беріңіз: ойыншықтарын жинағанды жақсы көретін сиқырлы қонжық. Бәлкім, бұл оқиға ертең үй жинағанда Сізге көмектесер!'),
  ('1da71143-b8dd-434a-bf23-b7f16a2d4a80', 'Еркіндік сарқырамасы 🥛', 'Суды немесе сүтті стақанға міндетті түрде өзі құйғысы келе ме? Нәтижесінде айналаның бәрі көлшікке айналады. Терең тыныс алыңыз. Бұл бейберекеттік — оның қол-көз үйлесімі мен өзіне деген сенімін дамытудың өтеуі. Оған да шүберек беріп, еш реніш білдірмей бірге тазалаңыз.'),
  ('7f1b27a1-aff6-4522-ba4e-76bb08fa648e', 'Шудан демалу 🎧', '«Анашым, анашым, анашым!» деген дауыстар миыңызда жаңғырып тұр ма? Өзіңізге шағын үзіліс жариялаңыз. Оны 15 минутқа қауіпсіз бір іспен айналысуға қалдырып, кофеңізді толық тыныштықта ішіңіз. Сіздің де қуатыңыз толуы керек.'),
  ('9ebeb631-4aa4-4310-b78e-47bee6920a4e', 'Шомылуға қарсылықты жеңу 🛁', 'Жуынғысы келмей, еденге жатып алып қарсылық білдіре ме? «Жүр, сені жуындырайын» деудің орнына, «Жүр, сүйікті мәшинелеріңді (немесе қуыршақтарыңды) шомылдырайық» деңіз. Ойынға айналған кез келген міндетке бала әлдеқайда оңай көнеді.'),
  ('5188ae48-9680-4372-a0c2-b6a14d87d513', 'Үйдегі аяқкиім дағдарысы 👟', 'Далаға киетін аяқкиімін үйде киіп, мүлде шешкісі келмей жылай ма? Бұл үшін күресудің қажеті жоқ. Табанын дымқыл шүберекпен сүртіп, бөлмеде бірнеше сағат бойы мақтанышпен жүре беруіне рұқсат етіңіз. Кейбір шайқаста әдейі жеңілу — шын мәнінде ананың ең үлкен жеңісі.'),
  ('a80b1c35-a6ce-48dc-a430-2268378d43f5', 'Кезек әкеде 👨‍🍼', 'Күні бойы «жоқ» деуден, ереже орнатудан шаршадыңыз. Бүгін кешке пижама кигізу мен тіс тазалату міндетін әкесіне тапсырыңыз. Бөлменің есігін жауып, Көңіл күй күнделігіне бүгінгі сезімдеріңізді ғана жазып, уақытты толығымен өзіңізге арнаңыз.'),
  ('f6d030df-f5ef-4ef7-84fc-04dd7126bef2', 'Қауымдастықтағы күлкі 💬', 'Бүгін оның қырсықтығы сізді әбден қажытты ма? Дереу Anacan қауымдастығын ашып, басқа аналардың үйінде болған осыған ұқсас, тіпті одан да күлкілі дағдарыстар туралы оқиғаларды оқыңыз. Бірдей жолдан өтіп жатқаныңызды және жалғыз емес екеніңізді білу — ең жақсы психологиялық қолдау.'),
  ('16b69d4c-feb3-42d5-b458-329c2a13a823', 'Жаңа достар іздеу 👫', 'Саябақта құрдастарымен бірге жүгіріп, олардың ойынына қосылуға тырыса ма? Әлеуметтену ресми түрде басталды! Оны жігерлендіріп, балалармен қалай амандасу керегін үйретіңіз.'),
  ('db813abc-1129-479f-a1e4-e6beaeb2ec95', 'Анаға арналған табиғат терапиясы 🌳', 'Үйдің төрт қабырғасы жаныңызды қысып жүр ме? Балаңызды алып, ең жақын саябаққа асығыңыз. Таза ауа баланың ғана емес, Сіздің де қажыған жүйкеңізге жасалған ең жақсы массаж болады.'),
  ('eddd6a67-3ce9-4446-ba23-dba7c167dca2', 'Ауа райы құбылмалы ⛅', 'Серуенге шыққыңыз келеді, бірақ даладағы ауа райы алдамшы ма? Ауа райы және киім құралын ашып, бөпені терлетпей, жайсыз ауа райынан қорғайтын ең қолайлы киім үйлесімін таңдаңыз.'),
  ('009a8d5c-9bba-4789-a6ee-e59d4c647832', 'Командалық мақтаныш 🥂', 'Қиын аптаны артқа тастадыңыздар. Жұбайыңызбен бетпе-бет отырып, «Біз бұл баланы шынымен жақсы тәрбиелеп жүрміз» деп, бір-біріңізге қолдау көрсетіңіздер.'),
  ('d0adf273-d83c-415a-88b8-6fa5f74c5f51', 'Сөйлем құрап, ертегі айтады 🗣️', 'Суретті кітапқа қарап, өздігінен сөйлемдер құрап, ертегі ойлап таба ма? Қиялы мен сөйлеу қабілеті қатар дамып келеді! Оны мұқият тыңдап, қол соғып қолдаңыз.'),
  ('ff22b088-7f8b-4366-a32b-7bd8cd1aa92f', 'Аналар ынтымақтастығы 💬', 'Potty training (түбекке үйрету) Сізді күйзеліске түсірді ме? Дереу Anacan қауымдастығына кіріңіз. Ондағы басқа аналардың жетістіктері мен сәтсіздіктері туралы оқиғалар Сізге күш береді.'),
  ('1c47434b-8f04-4342-a73a-e77c7a63eb48', 'Қараңғыдан қорқу 🌙', 'Бөлменің қараңғылығынан қорқа ма? Кереуетінің жанына кішкентай түнгі шам қойыңыз, бірақ мелатонин бөлінуі үшін бөлменің жеткілікті түрде қараңғы екеніне көз жеткізіңіз.'),
  ('77a1ab3f-8086-4334-93ed-03dab08fb152', 'Киімін өзі таңдағысы келеді 👗', 'Шкафты ашып, бір-біріне үйлеспейтін түстер мен әр маусымға арналған киімдерді үйлестіргісі келе ме? Дербестігін қолдаңыз, бірақ жағдайды бақылауда ұстау үшін оған тек 2 нұсқа ұсыныңыз.'),
  ('b22d0c31-c528-4596-b176-4f64d3f5be5d', 'Кофемен қуаттану ☕', 'Күндізгі ұйқысы тоқтап, енді күні бойы демала алмай жүрсіз бе? Оны 15 минутқа қауіпсіз бір іспен айналысуға қалдырып, өзіңіз міндетті түрде кофе ішіп, күш жинап алыңыз.'),
  ('9787e3a9-8592-4bb2-8463-c4e695682c99', 'Ауыр жүк, қайсар жүрек 🛒', 'Серуеннен қайтқанда ең ауыр затты немесе сөмкені міндетті түрде өзі көтергісі келе ме? Тіпті орнынан қозғалта алмаса да, Сіздің көмегіңізден үзілді-кесілді бас тартады. Біраз әуреленіп, өз күшін сынап көрсін.'),
  ('bdc2ddcb-448f-4cfa-b4a5-c5e56bf2b001', 'Кішкентай философ 🤔', 'Көзі енді жұмыла бергенде, кенет басын көтеріп: «Анашым, күн ұйықтауға қайда кетеді?» дегендей философиялық сұрақ қойды ма? Оның миы тіпті ұйқыға кетер сәтте де айналадағы әлемді танып-білуді жалғастырады. Тым тереңге бармай, қысқа әрі ертегіге ұқсас жауап беріңіз.'),
  ('c2525bad-5158-49a7-81ce-247259a08d2e', 'Ғажайыпқа толы талаптар 🪄', 'Бүгін таңертең ояна сала, туралған алманы қайтадан бүтін етіп беруіңізді айқайлап талап етті ме? Иә, 3 жасқа таяғанда олардың логикасы физика заңдарына бағынбайды.'),
  ('1e3f3fa1-dbbc-4651-aa40-6590038f46b0', 'Жануарларға еліктеу 🐶', 'Ол жануарлардың дауысын салып қана қоймай, ит сияқты еңбектеп, мысықтай пырылдай ма? Бұл — дене қимылы мен қиялдың тоғысуы. Сіз де оған қосылып, кілем үстінде бірге ойнаңыз.'),
  ('4ac97d09-8bce-44ef-922e-5286afc49815', 'Тамақ талғау 2.0 🥣', 'Кеше ғана сүйіп жеген сорпасынан бүгін бас тартып отыр ма? Мәжбүрлемеңіз. Пайдалы рецептілер бөлімінен көкөністерді байқатпай қосуға болатын өзгеше балама тағамдарды табыңыз.'),
  ('d8f03ef9-1ea4-48a4-a43d-dc4f633f2d60', 'Сиқырлы ұйқы ертегісі 🪄', 'Ақылды ертегілерде үш жасқа толғалы тұрған батыл кейіпкер туралы хикая құрып, оған өсіп, күшейіп келе жатқанын сезінуге көмектесіңіз.'),
  ('2a9575e0-ee4f-4f27-86a9-25def022748e', 'Сізді іздеп жүрмін! 👀', 'Сіз бөлмеден шыға салысымен, ол қайтадан жылай бастай ма? Ажырасу мазасыздығы кейде қайта пайда болады. Даусыңызбен алыстан-ақ оған сенімділік беріңіз, бірақ үнемі көз алдында болуға міндетті емессіз.'),
  ('89de8241-ec59-4180-ba30-e03291e0f208', 'Ертегінің соңын өзі айтсын 📖', 'Бүгін кешке ертегі оқығанда сөйлемдерді аяқтамай тоқтаңыз да, жалғасын өзі айтсын! Оның ғажайып қиялын дамытуға көмектесетін диалог тәсілдерін Anacan AI-дан сұраңыз.'),
  ('ca321f21-1031-4b14-96c8-69fa4c4201da', 'Тізім міндетті түрде керек 🛒', 'Туған күнге қажетті заттар ұмыт қалмасын! Ойыңызды артық нәрсемен шаршатпай, бәрін бірден Сатып алу тізіміне жазып, жұбайыңызбен синхрондаңыз.'),
  ('565fda98-0d2c-40b4-8230-13c64e585700', 'Шұлық тігісінің қасіреті 🧦', 'Бүгін таңертең үлкен дағдарыспен ояндық: шұлықтың ішіндегі тігіс башпайына тиіп тұр! 3 жасқа таяғанда эмоциялық сезімталдық шегіне жетеді. Бұдан қисын іздемеңіз, шұлықты теріс айналдырып кигізіңіз де, осы қисынсыз дағдарыстың 10 секундта қалай аяқталатынын бақылаңыз.'),
  ('acd26d8c-d24f-4082-9973-a1110aefb638', 'Шалшық аулаушы 🌧️', 'Жаңбырдан кейін далаға шыққанда, ол бірден лай шалшыққа секірді ме? Үсті-басы былғанды, бірақ оның көзіндегі жаңалық ашқандай жарқылды қараңызшы. Ауа райын ескеріп, алдын ала резеңке етік кигізуді жоспарлаңыз, балалық шағын еркін өткізсін.'),
  ('b17158eb-f894-42c6-8d84-cab6d30d297a', 'Ойыншықтарға қайырлы түн 🧸', 'Ұйықтайтын уақыт келді, бірақ ол бөлмедегі әрбір мәшине және қонжықпен бір-бірлеп қоштасып жүр. Бұл — ұйқыны кейінге қалдыру өнерінің нағыз жауһары. Таймер қойып, 3 минуттан кейін бәрімен бір мезетте қоштасамыз деген ережені қолданыңыз.'),
  ('3b1d044a-5917-48bd-b4f3-847b5ba6d5db', 'Ең оғаш зат 🥄', 'Қаншама қымбат ойыншық тұрса да, ол асүйден бір ожау тауып алып, кеш бойы соны көтеріп жүріп, тіпті ұйықтатады. Бала миының кейбір заттарға неге ерекше әуес болатынын түсіндіру мүмкін емес. Кедергі жасамаңыз, сол ожауға мейірімін төге берсін.'),
  ('498b3498-4fee-4a00-9b62-ebe43844ae53', 'Сорпа ішіндегі хирург 🥣', 'Тамақты жемей, ішіндегі ұсақ пияз немесе күріш түйірлерін хирургтің дәлдігімен бір шетке теріп отыр. Көкөністерді езбе жасап, көзге көрінбейтіндей ететін уақыт келді. Пайдалы тағамдар бөлімінен аналардың көкөніс жасырылған ең креативті рецептерін қарап көріңіз.'),
  ('a13e9959-a476-4e99-9da8-13f5bff68864', 'Шкафты өзім ашамын! 🚪', 'Таңертең шкафтың есігін Сіз ашып қойғаныңыз үшін жылап, оны қайта жапқызып, өзі ашты ма? Иә, бәрі толығымен оның бақылауында болуы керек. «Өзім істеймін» деген осы аңғал талпыныстарына жымиып қараңыз, ол өз ерік-жігерін сынап жүр.'),
  ('0a4a5638-968e-4cce-9213-12c0072354c4', 'Тыныштықтың цифрлық өлшемі 🤫', 'Ол ақыры ұйықтап қалды! Үйге орнаған тыныштыққа сене алар емессіз. Дыбыс өлшегішті қосып, экрандағы 0-10 децибел көрсеткішіне қарап отырып, миыңыздың біртіндеп тынығып, қуаттанып жатқанын сезініңіз.'),
  ('b5cfbb8a-14cd-4f76-bc5c-26b6d0b9418a', '«Сен жаман анасың!» деген соққы 💔', 'Қалаған кәмпитін бермегеніңіз үшін Сізге «сен жамансың» деді ме? Көңіліңізге алмаңыз. Ол әлі сезімдерін дұрыс сөздермен жеткізе алмайды, шын мәнінде «мен қатты ашулымын» дегісі келеді. Көзіне қарап, оның сезімін қабылдаңыз.'),
  ('fabd170d-dc89-4100-b9c1-3acf59e32a5c', 'Көрінбейтін құмырсқамен әңгіме 🐜', 'Балконда немесе саябақта жердегі құмырсқаға еңкейіп, онымен өте байсалды түрде сөйлесіп жүр ме? Бұл кезде қиялы мен жанашырлығы қатар жұмыс істейді. Осы керемет сәтті бірден Бөпе фотосессиясына түсіріп, мұрағатыңыздың ең сүйкімді бұрышына сақтап қойыңыз.'),
  ('a860534c-7167-4781-b298-8321127fd089', 'Әкенің ұшу режимі ✈️', 'Үйде бойындағы энергиясын шығара алмай, ұйықтағысы келмей жүр ме? Әкесін көмекке шақырыңыз. Әкесі оны жоғары көтеріп, ұшақ болып ойнатқанда, бөлме шат күлкіге толып, жиналған бүкіл физикалық ширығу санаулы секундта жоғалады.'),
  ('e0e56f8d-3c51-4c46-90f2-dbfa90060519', 'Еденде аунау еркіндігі 🌪️', 'Дүкеннің ортасында жерге жата кетті ме? Оны бірден тұрғызуға немесе айналадағыларға түсініктеме беруге тырыспаңыз. Терең тыныс алыңыз. Anacan қауымдастығына кіргенде, мыңдаған ананың дәл осындай ыңғайсыз, бірақ табиғи сәтті бастан өткеретінін көресіз.'),
  ('e9ba4911-0212-43aa-9a51-c6bf942facb9', '«Маған қарама!» деген қырсықтық 🙈', 'Сіз оған қарап жымиғаныңыз үшін «Маған қарама!» деп жылап жатыр. Қисынсыз ойдың шыңы! Бетіңізді басқа жаққа бұрып, осы күлкілі қылығының басылғанын күтіңіз. Кейде олар өздері де не қалайтынын білмейді.'),
  ('3b9f5253-06a7-4aef-bfdf-bb0daf30818e', 'Жарықтың сиқыры 🌙', 'Қараңғыдан қорқа бастады ма? Бөлмені толық қараңғылап, кішкентай қолшаммен төбеге жарық түсіріп ойнаңыз. Ол қорқатын қараңғылықты көңілді ойынға, ұйқы алдындағы шағын зерттеуге айналдырыңыз.'),
  ('5d1a2a49-e134-453a-a974-f4cff4de0952', 'Пижамаға деген махаббат 👗', 'Таңертең оянып, үстіндегі дақ түскен пижамасын шешуден үзілді-кесілді бас тартып жатыр ма? Егер үйден шықпайтын болсаңыздар, тартысты тоқтатыңыз. Кейде ананың жан тыныштығы баланың ұқыпты көрінуінен әлдеқайда маңызды.'),
  ('c8ffca51-c2fa-4f5a-8090-6c144b596f9c', 'Қалтадан шыққан қазыналар 🍁', 'Саябақтан оралдыңыздар, ал оның қалтасынан 3 тас, 1 кепкен жапырақ және бір шыбық шықты. Сіз үшін бұл қоқыс, ал ол үшін — қазына. Оларды үйге шашып тастамас үшін арнайы коллекция қорабын жасап, бәрін сонда жинауына рұқсат етіңіз.'),
  ('176265d3-ef2f-4ec4-923c-4308870e611f', 'Эмоциялық жүкті жеңілдету 📝', 'Үйіңіздегілердің ешқайсысы Сіздің қаншалықты шаршағаныңызды байқамай жүр ме? Көңіл күй күнделігі — ең үнсіз сырласыңыз. Бүгін Сізді ашуландырған барлық ұсақ-түйекті сонда жазып, ойыңыздың қалай жеңілдегенін байқаңыз.'),
  ('94fce04c-73e9-47bd-8d9d-3bd3da19122a', 'Өзім жүремін! 🚶‍♂️', 'Көшеде қолыңыздан ұстаудан үзілді-кесілді бас тартып, еркіндік талап ете ме? Қауіпсіз жерлерде оған осындай еркіндік беріңіз. Көзден таса қылмай, әлемді өз қадамдарымен танып-білуіне мүмкіндік беріңіз.'),
  ('b24a452c-9588-4b0c-923f-9c455be6d1e2', 'Асүйдегі кішкентай аспаз 🧑‍🍳', 'Сіз қамыр жайып жатқанда, міндетті түрде жаныңызға орындық қойып, іске араласа ма? Қолына кішкентай қамыр беріңіз. Айналаның бәрі ұн болады, бірақ оның байсалды әрі іскер кейпі кейінгі тазалыққа тұрарлық.'),
  ('09711673-d0fa-42b5-be98-012bd4b1ed8b', 'Экрансыз үзілістің қиындығы 📺', 'Бүгін жұмыстарыңызға байланысты оған мультфильмді әдеттегіден көбірек қосып беріп, өзіңізді кінәлі сезініп жүрсіз бе? Өзіңізді жазғырмаңыз. Күн сайын мінсіз ана болу мүмкін емес. Кейде цифрлық күтуші Сізді эмоциялық күйзелістен құтқарады.'),
  ('8649e4ca-170c-4117-8af8-b0d7e819e84f', 'Жанды диктофон 🎙️', 'Кеше жұбайыңызбен сөйлескенде байқамай айтып қалған сөзіңізді бүгін таңертең ойыншығына айтып отыр ма? Оның сөздік қоры таңғаларлық жылдамдықпен кеңейіп келеді және ол Сізді толығымен қайталайды. Оған үлгі екеніңізді ұмытпаңыз.'),
  ('c0faa467-b596-4471-bbba-6d91e0e37db1', 'Сыбырлау тәсілі 🤫', 'Төсекте тыным таппай, ұйықтамай жүр ме? Дауысыңызды көтерудің орнына, кенет бәсеңдетіп, сыбырлап сөйлеңіз. Бала Сізді есту үшін зейінін шоғырландырғанда, оның миы автоматты түрде ұйқы режиміне ауысады.'),
  ('48263ed0-f236-440c-a83e-807da51bd86f', 'Оттегі қажет ⛅', 'Төрт қабырға миыңызды тұмандандырып, үйде ашу ұстамалары жиілеп кетті ме? Ауа райына сай киім таңдап, далаға шығыңыз. Сыртта жай ғана жүгіріп ойнау оның артық энергиясын шығаруға көмектеседі, ал Сізге жаңа тыныс береді.'),
  ('8fed0a18-52ae-4688-8137-532b6b55726c', 'Ертегі тізгіні оның қолында 🪄', 'Классикалық кітаптардан екеуіңіз де жалықтыңыздар ма? Қиялыңызды қосып, басты кейіпкерді балаңыз, ал құтқарылатын жерді оның бөлмесі етіңіз. Осылайша ерекше, тыныш әрі еркін ұйқы алдындағы ертегі сәтін ұйымдастыра аласыз.'),
  ('c7c388a1-a255-4a7c-a615-22236406e4e2', 'Авангард өнері 🖍️', 'Бірнеше секундтық тыныштықтың соңы тосын жағдайға ұласты. Бөлмеге кіріп, оның қолына немесе ішіне фломастермен татуировка салып тастағанын көрдіңіз. Терең тыныс алыңыз. Оның ұсақ моторикасы дамып жатыр, ал терідегі бояу бәрібір жуылады.'),
  ('15f19421-c415-4b7b-ad4d-54211e4ccb3a', 'Су, барлық жерде су! 💧', 'Суды стақанға міндетті түрде өзі құйғысы келді. Төгіп алып, айналаның бәрін су қылды. Бірақ сүрткішті алып, сол жерді тазалауға тырысқан кішкентай қолдарына қараңызшы. Ол қателесу арқылы жауапкершілікті үйреніп жүр, ашуланбаңыз.'),
  ('6d2f1d1e-d7d7-41c3-b906-1e286aab1a51', 'Әкенің кезегі 👨‍👧', 'Ана болу — бітпейтін марафон емес. Бүгін бөпемен саябаққа әкесі барсын, ал Сіз диванда оңаша демалудың рақатын көріңіз.'),
  ('cf9e0ee2-2f17-4a55-933b-735bc0754d7e', 'Командалық массаж 💆‍♂️', 'Бала ұйықтағаннан кейін күндізгі күйзелістен арылу үшін серігіңізбен бір-біріңіздің иығыңызға массаж жасаңыздар. Сіздер жай ғана ата-ана емессіздер, осы шаңырақтың және бір-біріңіздің ең үлкен тірегісіздер.'),
  ('2caa3c21-d2d3-4566-921a-e08cdbce1397', 'Мен шаршадым... 🔋', 'Бәрі Сізден күш-қуат күтеді, ал қуатыңыз таусылып қалды. Бүгін ештеңе пісірмей-ақ қойыңыз: сырттан тапсырыс беріңіз немесе ең оңай макаронды қайната салыңыз. Суперқаһарман болу — бәрін жалғыз істеу керек деген сөз емес.'),
  ('48299b62-1108-44e9-af43-b48460ffdfa2', 'Ваннадағы тыныштық 🛀', 'Күні бойы «қаламаймын» деумен өтті. Жылы ванна тек тазалық үшін емес, оның ширыққан жүйке жүйесін тыныштандыру үшін де қажет. Судың дыбысын тыңдаңыз, бөлменің атмосферасы бірден өзгереді.'),
  ('ab5bd705-a57d-40d7-b0a0-86107e824b4d', 'Баспалдақпен өз бетімен көтерілу 🧗', 'Баспалдақпен сүйенішсіз көтерілуге тырысып жүр ме? Қимыл-қозғалыс дағдылары қарқынды дамып келеді! Сырттай бақылаңыз, араласпаңыз. Осы дербес қадамын Бөпе фотосессиясы арқылы мәңгі есте қалдырыңыз.'),
  ('33979ce6-ea09-4adc-ab85-0cf386a73156', 'Қораптың сиқырлы тартымдылығы 📦', 'Оған сонша қымбат, дыбысы бар ойыншық сатып әпердіңіз, ал ол ойыншықтың қорабымен 1 сағаттан бері ойнап отыр. Баланың миы дайын құрылымдарды емес, қиялына ерік беретін қарапайым заттарды ұнатады. Бақылаңыз және үйреніңіз.'),
  ('5b89452a-e411-4130-87b7-6e1e33b0701e', 'Табиғи ақ шу 🤫', 'Ұйықтап бара жатқан сәтте сезімталдығы артады. Көшеден келетін дыбыстарды бейтараптандыру үшін бөлмеде Дыбыс өлшегіштің фондық дыбысын қосып, жайлы әрі тұрақты тыныштық орнатыңыз.'),
  ('a09d0a7b-0632-4bcf-8833-28f5ef0f9d93', 'Өтірік жылау 🎭', 'Қалағанын алу үшін көз жасын төкпей-ақ, дауысын дірілдетіп, өтірік жылай ма? Ол Сізді манипуляциялауды үйреніп жүр. Күліп жібермеуге тырысыңыз, бірақ айтқанына көне салмаңыз. Шекараларыңыз анық болсын.'),
  ('20e8cb8e-6d52-4362-bb7b-a45ecbfa2cce', 'Кенеттен айтылған «Сені жақсы көремін» 💖', 'Бөлменің ортасында ойнап жүріп, кенет Сізге қарап: «Сені қатты жақсы көремін!» — деді ме? Барлық ұйқысыз түн мен шаршауға тұрарлық сәт! Осы мезет сыйлаған терең әрі ерекше жан тыныштығынан ләззат алыңыз.'),
  ('22b5d836-6305-422c-8cf7-c30a523392f2', 'Әкенің көңілді биі 🕺', 'Кешкі мазасыздықты кейде тек әке ғана баса алады. Музыканы барынша қатты қойып, баламен бірге бөлмеде секіріп билесін. Ал Сіз осы көңілді көріністі сырттай мақтанышпен тамашалаңыз.'),
  ('909bc50f-85b7-40ab-a524-0abbcb0fac9f', 'Өзіңізге арналған 10 минут ☕', 'Ол мультфильмге беріліп отырғанда, ыдыс жуғыш машинаны толтыруға асықпаңыз! Диванға жантайыңыз. Кофеңізді ақыры ыстық күйінде ішіп, 10 минутқа ана рөлінен шығып, жай ғана өзіңіз болыңыз.'),
  ('028ed2b5-737d-4edf-81c1-5a9151e5fbf0', 'Дүкендегі шоколад тосынсыйы 🛒', 'Дүкенге барар алдында «Сатып алу тізімін» ашқанда, оның артыңыздан келіп, телефон экранын басып, тізімге әлденелерді шимайлап қойғанын көрдіңіз бе? Иә, ол Сіздің цифрлық өміріңізді де қайталап жүр!'),
  ('098cd94b-6989-48a8-9fdc-160a2f819cb0', 'Ойдан шығарылған грамматиканың қызығы 🗣️', '«Мен бардымдым», «Ол келіптіді» деген сияқты оғаш, бірақ сондай сүйкімді шақ формаларын ойлап тапты ма? Сөздік қоры құйын секілді дамып келеді! Даму трекеріне оның осы ерекше тілін естелік ретінде жазып қойыңыз.'),
  ('50dce5d9-294a-44b8-b1c9-316b84d5df14', 'Кереуеттің астында не бар? 👻', 'Қараңғыда құбыжықтар бар деп сене ме? Ішіне жай ғана су құйылған бөтелкені алып, оны «Қорқынышты қуатын спрей» деп бөлмеге бүркіңіз. Қиялын қиялмен жеңіңіз.'),
  ('2cd29d0d-0cf1-403e-806d-35f84215b2df', 'Таңғы 5-те сауық басталды! ⏰', 'Күн әлі шыққан жоқ, ал ол кереуетте секіріп, күнін бастап кетті. Сіз әлі ұйқылы болсаңыз да, ол әлемді бағындыруға дайын. Оған қосылып, осы тасыған энергияның Сізді де оятуына мүмкіндік беріңіз.'),
  ('48550c10-c030-428e-9c25-ccd73ca09c55', 'Балабақша іздеп жүрсіз бе? 🏫', 'Бөпеңіз 3 жасқа таяғанда балабақша туралы ой маза бермей, бірақ шешім қабылдай алмай жүрсіз бе? Жалғыз ойлана беруден шаршасаңыз, Anacan қауымдастығына қосылып, басқа аналардың балабақшаға қатысты шынайы тәжірибесін оқыңыз.'),
  ('df1cf1ea-2772-44a6-8cb7-33857989fedf', 'Сезімдерді жазып жүру 📝', 'Біреу Сізге «Үйде отырсаңыз да, неден шаршайсыз?» деді ме? Дереу Көңіл күй күнделігін ашып, бар ашуыңызды саусақтарыңызбен экранға төгіңіз. Жасанды жымиғаннан гөрі, шынайы сезімдеріңізді жазу — нағыз терапия.'),
  ('3deb7e49-2093-4c39-a51d-8dd6fd44d138', 'Көгөністермен күрес жалғасуда 🥦', 'Бөпеңіз сорпадағы кішкентай сәбізді тағы да байқап қалып, тамақтан бас тартты ма? Тамақтану жоспары арқылы көгөністерді езбе жасап, котлеттің ішіне жасыру — аналардың ежелден келе жатқан әрі пайдалы айласы. Қолданып көріңіз!'),
  ('9dd6923c-7dc5-4341-8507-b21e0f3c9ee4', 'Кішкентай дәрігер Сізді тексеріп жатыр 🩺', 'Ойыншық стетоскопын алып, кеудеңізге қойып, тыныс алуыңызды сұрайды. Сіз — науқассыз, ал ол — бас дәрігер. Осы ойынды ойнаңыз: жатып, емделіп жатқанда тым болмаса 5 минутқа көзіңізді жұмып, демалып алыңыз.'),
  ('ebf71c8a-d8a3-4875-8021-e3145bf8ae06', 'Дыбысқа шектеу 🌙', 'Ол ақыры ұйықтап қалды. Енді үйдегі болмашы дыбыстың өзі Сізді алаңдатады. Жарықты бәсеңдетіп, теледидарды өшіріңіз де, қараңғылық құшағында сирек болатын сол тыныштықтан рақат алыңыз.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('19419b9a-b627-43ae-9610-e43b875264b1'::uuid, 'Мақсатты еңбектеу мен жүгіру 🐢', 'Енді ол жай жүруді азсынып, жүгіріп барып Сізден жасырынады, есіктің артынан сығалайды. Бөлмедегі кедергілерді алып тастап, осы қуаласпақ ойынына Сіз де баладай күш-жігермен қосылыңыз.'),
  ('20d0afb1-a487-43f5-b6f3-0f8cd2bca864', 'Жарықты өшірсеңіз, ұйқы келеді 🌙', 'Бөпеңіздің тезірек ұйықтауы үшін бөлмедегі барлық артық жарық пен көк жарық шығаратын экрандарды өшіріңіз. Ұйқы гормоны (мелатонин) тек қараңғы әрі технологиясыз ортада жылдам бөлінеді.'),
  ('c8f7bf43-25ab-4e4d-96d4-6f6b9ab81f33', 'Жасанды интеллект, шынайы жауап 🤖', 'Балаңызда біртүрлі әдет пайда болып (мысалы, тырнақ тістеу), интернеттегі форумдар Сізді қорқытып жіберді ме? Тоқтаңыз. Anacan AI-дан оның педиатр растаған шынайы себебін сұрап, көңіліңізді тыныштандырыңыз.'),
  ('1bbd92c6-a12a-4c26-a63f-0946e226b656', 'Өзіңізді ұмытуға болмайды! 🥗', 'Оны тойдыру үшін 3 түрлі мәзір ойластырдыңыз, ал өзіңіз тағы да аш қалдыңыз ба? Пайдалы рецептілердің ішінен 10 минутта дайындалатын, темір мен кальцийге бай түскі асты таңдап, өзіңізге қамқорлық танытыңыз.'),
  ('31e8c246-42c7-4bad-8ff1-c08af53874b1', 'Кенеттен ашуға булығу 💥', 'Ойнап отырып, кенет ашуланып, ойыншықтарын лақтырып жіберді ме? Ол әлі сезімдерін басқара алмайды. Айқайлаудың орнына, Ашуланып тұрғаныңды көріп тұрмын, кел, бірге терең тыныс алайық деп, түсіністік танытыңыз.'),
  ('96327d67-c216-46e6-b768-6cd8fce23852', 'Екеуіңізге арналған шампан 🥂', 'Бала ұйықтады. Шампан болмаса да, стақандарға ыстық шай құйып, жұбайыңызбен Осы қиын күнді де аман-есен аяқтадық деп стақан соғыстырыңыз. Сіздер — отбасының ең мықты қолбасшыларысыздар.'),
  ('3b764723-4ccb-4ab8-a1ed-3b072c5f8a25', '3 жасқа дейін соңғы 5 күн! 🚀', 'Сенгісіз! Үлкен белес — 3 жасқа толуына небәрі 5 күн қалды. Үйде өз ережесін орнататын осы кішкентай тұлғаны Сіз өсірдіңіз. Anacan-нан тортқа дәл қазір тапсырыс беріп, дайындықты бастаңыз.'),
  ('b8850dac-f142-4e24-bc24-56bb7962ebf6', 'Әкенің ұшу режимі ✈️', 'Үйде энергиясын шығара алмай, ұйықтағысы келмей жүр. Әкесін көмекке шақырыңыз. Әкесі оны әуеге көтеріп, ұшақ болып ойнатқанда, бөлме сыңғырлаған күлкіге толып, бойындағы ширығу санаулы секундта басылады.'),
  ('ee7e813c-5a12-4710-b655-7b294f1ff478', 'Ананың үзілісі ☕', 'Баланың тілінде сөйлей беруден шаршадыңыз ба? Анаға жайлы орындардың ішінен балалар бұрышы бар кафе тауып, кофе ішіңіз, басқа аналармен сырласып, бір сергіп алыңыз.'),
  ('20794d75-b46f-481d-baa5-2b85b8516d4e', 'Саябақтағы еркіндік 🌳', 'Төрт қабырға оны ашушаң етеді. Оны саябаққа алып шығыңыз: құмға аунасын, жүгіріп жүріп құласын, тас жинасын. Табиғат аясындағы осы еркіндік — оның миының дамуына ең жақсы әсер ететін дәрі.'),
  ('3d4fe78e-9d18-4fa4-b11f-ee7836615ee7', 'Мелатонин фабрикасы 🌙', 'Тезірек ұйықтауы үшін бөлмедегі барлық қосымша жарықты және планшет экрандарын өшіріңіз. Мелатонин тек тыныш, жарығы бәсең әрі экрансыз ортада жылдам бөлінеді.'),
  ('2d61ffa4-9df3-4b29-acca-6b87ebc82745', 'Аналарды қолдау тобы 💬', 'Күніңіз қиын өтіп, бәрі тым күрделі болып көріне ме? Anacan қауымдастығындағы тәжірибелі аналардың кеңестері — ешбір кітапта жазылмаған, өмірден алынған ең шынайы шешімдер. Солардан шабыт алыңыз.'),
  ('dd4c2432-4936-49e7-844c-aec9116027b4', '3 жасқа толар сәт! 🎂', 'Ертең — ерекше күн! Бөпеңіз ішіңізде алғаш рет тепкен күннен бері қаншама жолдан өттіңіз. Бүгін оған ұзақ қарап, киімдерін таңдаңыз және ертеңгі бөпе фотосессиясына телефоныңыздың жадын дайындап қойыңыз.'),
  ('36c78cd2-37d5-4665-84a1-551e9c9c2557', 'Серігіңізбен бірге атап өтіңіз 🥂', 'Осы 3 жылдың шаршауын, көз жасын және қуанышын бүгін кешке жұбайыңызбен бірге атап өтіңіз. Үстелге бір шам қойып, мызғымас командаңыздың жеңісін зор қуанышпен, күлімдей отырып тойлаңыздар!'),
  ('6148534d-dac4-4ca6-9b42-87f0242f8cdb', 'Керемет 3 жас! 👑🎉', 'Құттықтаймыз! Ол енді 3 жаста! Осы дауылды, шаршататын, бірақ әлемдегі ең тәтті жолмен келе жатқаныңызға тура 1095 күн болды! Бұл ерекше күнді дәл қазір мерекеге айналдырып, қуанышыңызды барлығымен бөлісіңіз!'),
  ('94dba968-6bd5-4b01-b8ef-b33b80729320', 'Сіз мінсізсіз! 📈', 'Балаңыз қандай үлкен жолдан өтті! Алғашқы күндердегі нәзік қорқыныштың орнын бүгінде зор сенім мен білім басты. Сіз осы 3 жылды үлкен мақтанышпен өткердіңіз! Сіз шынымен де керемет анасыз!'),
  ('278a6dcf-b4d5-435f-bebd-984362b1ec54', 'Мерекеден кейінгі шынайы өмір 🚀', 'Кешегі үлкен мерекеден кейін бүгін таңертең қайтадан шашылған ойыншықтар мен Киінгім келмейді! деген қарсылықты көрдік. Өмір өз ырғағына қайта оралды. Терең тыныс алыңыз, Сіз — осы бейберекеттіктің ең керемет басқарушысысыз.'),
  ('5242afc1-567f-496d-81cf-522c0271690e', 'Ертегі тізгіні оның қолында 🪄', 'Классикалық кітаптардан екеуіңіз де жалықтыңыздар. Ақылды ертегілерді ашып, басты кейіпкерді балаңыз, ал құтқарылатын орынды оның бөлмесі етіңіз де, ерекше, тыныш әрі еркін ұйықтау рәсімін жасаңыз.'),
  ('d5e65c0a-6f82-4fee-945e-ee1f72e84c4a', 'Мұны өзім істеймін деген қарсылық 🛑', 'Аяқкиімінің бауын өзі байлағысы келіп, оған 10 минутыңыз кетіп жатыр ма? Асықпаңыз, оған уақыт беріңіз. Әрекет жасап, қателесуі — оның болашақта мәселе шешу қабілетінің негізі.'),
  ('58d0ef6e-2eed-490f-85f9-8fd8f899a9bd', 'Үйдегі ретсіздікпен келісу 🌪️', 'Бөлменің іші ойыншыққа толып кетті ме? Тазалықтан гөрі, бөпеңізбен бірге өткізген осы тентек сәттер маңызды. Ойыншықтар ертең де орнында болады, өзіңізді шаршатпаңыз. Кейде ретсіздікке мән бермеу — ең жақсы демалыс.'),
  ('d52a333c-1a4b-40fd-a11c-b3544628c6df', 'Әкенің құпия тәсілі 👨‍🍼', 'Күндізгі шаршаудың өзі Сізге жеткілікті. Кешке баланы ұйқыға дайындау мен тісін тазалату үдерісін әкесінің ойындарына тапсырып, өзіңіз тыныш жерде демалып алыңыз.'),
  ('dbff772c-4b84-4bcd-8132-9e03a5a6d600', 'Ерекше жан досы 🥄', 'Қаншама қымбат ойыншығы бола тұра, асүйден силикон қалақша тауып алып, күні бойы соны қолынан тастамай, тіпті ұйықтатып жүр ме? Баланың қиялы ғажап. Кедергі жасамаңыз, қалақшасын жақсы көре берсін.'),
  ('5e23814c-ef4e-4708-8223-e1ab2ac7daa9', 'Сыбырмен ұйықтату 🌙', 'Бөлменің жарығын толық өшіріңіз. Жанына жатып, күні бойы болған оқиғаларды өте бәсең дауыспен құлағына сыбырлап айтып беріңіз. Сыбырлау — миды ұйқыға дайындап, айналадағы шуды ұмыттыратын ең табиғи әрі әсерлі тәсіл.'),
  ('e3d2e3a9-22c5-44f1-a54d-89fc427e1f7c', 'Тізімдегі тосынсый 🛒', 'Дүкенге барар алдында сатып алу тізімін ашқанда, балаңыздың артыңыздан келіп, телефон экранын басып, тізімге шоколад қосқанын көрдіңіз. Иә, олар технологияны Сізден де жақсы біледі!'),
  ('fc07a24b-5d02-4f37-9d95-b46ab5b5f190', 'Мақсатты қирату 🧱', 'Бар ынтасымен мұнара құрып, кейін оны бір соққымен құлатып, күледі. Осылайша ол физиканы және себеп-салдар байланысын танып-біледі. Ашуланбаңыз, құлаған мұнаралар — оның миында қалыптасып жатқан жаңа нейрондық байланыстар.'),
  ('aa798243-c44e-4178-957c-647030916048', 'Ауа райы туралы ескерту ⛅', 'Серуенге шығарда терезеден қарап қана шешім қабылдамаңыз. Ауа райы және киім көмекшісі арқылы даладағы нақты жел мен температураға сай киім үйлесімін таңдап, үйден алаңсыз әрі толық дайындықпен шығыңыз.'),
  ('b3ff48b4-aa5c-406e-999b-73655dca1c90', 'Мультфильм сыншысы 📺', 'Көрген мультфильмін өзінше әңгімелеп, кімнің қайда барғанын байыппен түсіндіреді. Оны таңғалғандай кейіппен мұқият тыңдаңыз. Өзін әлемдегі ең ақылды баладай сезінсін.'),
  ('5e21d0fb-8027-46a5-b7ea-7b3a58d0cd11', 'Қиялдағы қонақтар келді ☕', 'Бөлмеде жалғыз өзі көрінбейтін достарымен сөйлесіп, оларға шай құйып жүр ме? Бұл — қиял дамуының шарықтау шегі! Осы ғажап сценаристі сырттай мақтанышпен бақылаңыз, ол тұтас бір әлем құрып жатыр.'),
  ('19c93357-3662-4a7d-bd13-a71d938dc00a', 'Сізге түсіндіріп берейін! ☝️', 'Сіз білетін нәрсені бөпеңіз байсалды әрі ақылды кейіппен өзіңізге түсіндіріп береді. Осылайша ол өз білімін тексеріп жүр. Күлмеуге әрең шыдап тұрсаңыз да, оны барынша байыппен тыңдаңыз.'),
  ('6ab81ee1-daa9-4300-97cb-c7dad69d9baf', 'Көңіл күй күнделігіндегі сыр 📝', 'Телефоныңызды қолыңызға алыңыз. Әлеуметтік желіде өзгелердің өмірін парақтаудың орнына, Көңіл күй күнделігін ашып, оның бүгінгі ең күлкілі сәтін болашаққа естелік ретінде жазып қойыңыз. Цифрлық терапия шынымен көмектеседі.'),
  ('ee467fcc-7c51-4e6a-ba68-1e6466be7d10', 'Күндізгі ұйқыға қарсылық 🥱', 'Төсекке жатқысы мүлде келмей ме? 3 жасқа таяғанда мұндай қарсылық жиі кездеседі. Мәжбүрлемеңіз, жылатпаңыз. Бөлменің жарығын бәсеңдетіп, Кітапты үнсіз парақтау сағатын жариялау арқылы күн тәртібін өзгертіңіз.'),
  ('3a35865f-054d-413c-b3ad-81c68c171c47', 'Қайтадан айырылу мазасыздығы ма? 🥺', 'Бөлмеден бір сәтке шығып кетсеңіз де, артыңыздан жылай ма? 3 жас шамасында айырылу мазасыздығы кейде қайта оралады. Әр жолы оған дауыстап, осында екеніңізді, асүйде екеніңізді және қазір келетініңізді айтып, алыстан-ақ сенімділік сыйлаңыз.'),
  ('96b4e611-59a4-4d8b-a157-87f9d477e265', 'Тыныштықтың дәлелі 🤫', 'Шулы күннен кейін бала ұйықтағанда, Дыбыс өлшегішпен бөлмедегі тыныштық деңгейін өлшеңіз. Нөлге жақындаған сандарды көрудің өзі ананың миына ең жақсы визуалды массаждай әсер етеді.'),
  ('c1d1539d-38e2-40da-9e66-eb22e0cbbd09', 'Мінсіз болу қысымы 🛑', 'Басқа балалар түстерді атап жүр, ал Сіздің балаңыз мұны қаламай ма? Салыстыруды дереу тоқтатыңыз! Әр баланың даму қарқыны әртүрлі. Сіздің балаңыз өз ырғағымен дамып келеді және бұл — мүлде қалыпты жағдай.'),
  ('08d5ac7d-b540-46e7-9f43-7f771edfd887', 'Жеңіске дайындық 💆‍♂️', 'Бала ұйықтағаннан кейін күндізгі күйзелістен арылу үшін серігіңізбен бір-біріңіздің иығыңызға массаж жасаңыз. Ертеңгі 3 жас мерейтойы мен қарбаласқа екеуіңіз де міндетті түрде тың болуыңыз керек!'),
  ('c83099cc-b126-47d8-b334-d8faf9b45dde', 'Қараңғылықтың күші 🌙', 'Тезірек ұйықтап кетуі үшін бөлмедегі барлық артық жарықты өшіріп, планшет экрандарын сөндіріңіз. Мелатонин тек қараңғы әрі технологиясыз ортада жылдам бөлінеді.'),
  ('9f30d9e0-ccc5-4b30-b84e-6fc58af9aa3b', 'Талғампаз гурмандар 🥦', 'Кеше сүйіп жеген тағамынан бүгін бас тартып отыр ма? 3 жаста тамақ талғау — қалыпты жағдай. Пайдалы тағамдарды көңілді, түрлі түсті әрі ерекше етіп ұсынудың жолдарын табыңыз.'),
  ('b755d54c-d2cb-47a2-92bb-44a36d855874', 'Қиялға қанат бітті 🚀', 'Ол енді жай ғана ойнамайды, тұтас оқиғалар құрастырады! Картон қорап әп-сәтте ғарыш кемесіне айналады. Даму күнделігіне осы танымдық серпілісті мақтанышпен белгілеп, оның ойынына қосылыңыз.'),
  ('ef6fe3c1-b830-477f-93ee-842f8b450ab9', 'Күнді қорытындылау 🌙', 'Ұйықтар алдында жарықты бәсеңдетіп, бүгін неге қатты күлгендеріңізді бірге талқылаңыз. Ұйқы алдындағы осындай шағын әңгімелер оның ойын жеткізу қабілетін дамытады.'),
  ('00481a1e-da97-4621-84c5-0bde2c4df340', 'Көрінбейтін аңдушы 👻', 'Қабырғадағы көлеңкесінен қорқып, жылай бастады ма? Көлеңкемен арпалысу — 3 жасқа тән ең қызық кезеңдердің бірі. Жарықты өшіріп, қолшамды жағыңыз да, көлеңкелерді билетіп, бұл қорқынышты көңілді ұйқы рәсіміне айналдырыңыз.'),
  ('81f8ee8c-8ca4-4260-b2ea-e74f425fe201', 'Киім тауынан жасалған шатыр ⛺', 'Жаңа ғана бүктеген таза киімдеріңізді шашып, өзіне шатыр жасап алды ма? Ашуланбас бұрын сол шатырдың ішіне үңіліп көріңіз. Ондағы қиял әлемі мен баланың қуанышы киім бүктеуге жұмсаған еңбегіңізден де қымбат.'),
  ('c4bb77ab-6874-45a4-8118-c089a7246538', 'Заттаңба дағдарысы 🏷️', 'Мойнымды қышытады! Жейденің артындағы кішкентай заттаңба — бүгінгі таңның ең үлкен жауы. 3 жаста сенсорлық сезімталдық шегіне жетеді. Дауласпай-ақ қойыңыз, заттаңбаны қиып тастап, күннің тыныш басталуына мүмкіндік беріңіз.'),
  ('04cb5d8f-0591-4ccc-8e31-0cf6555eb83a', 'Ваннада батып бара жатқан кемелер 🛀', 'Сумен ойнау үшін ваннаға кірдіңіз, ал ол батпайтын ойыншықтарды суға батыруға тырысып жатыр. Ол физика заңдарын зерттеуде! Су жан-жаққа шашырай берсін — судың қуаты оның күні бойы жиналған қарсылығын да өзімен бірге алып кетеді.'),
  ('123c0368-cc37-47f7-bb36-f227dd4d9131', 'Қиялдағы үй жануары 🐕', 'Бөлмеде жоқ итті немесе мысықты сипап, оған ат қоя ма? Демек, қиялы физикалық шекарадан асып кеткен. Бөлменің бір бұрышына көрінбейтін су ыдысын қойып, осы сүйкімді қиялға Сіз де қосылыңыз.'),
  ('ecca6ba2-c00d-4fde-a20b-1268d23c90e0', 'Мұз қалыпшасындағы дәмді ас 🧊', 'Не істесеңіз де, көкөністерді жемей ме? Ұсыну тәсілін түбегейлі өзгертіңіз. Пайдалы тіскебасарларды мұз қатыратын қалыптың (ice cube tray) кішкентай ұяшықтарына бөліп салыңыз. Ерекше ұсыну тәсілі әрдайым тәбетті ашады.'),
  ('56159a04-f4fe-4e35-a3dd-8bcc4853f3c9', 'Әкенің ұшу режимі ✈️', 'Үйде жүгіріп жүріп, төсекке жатудан бас тарта ма? Әкесін көмекке шақырыңыз. Ол баланы жоғары көтеріп, ұшақ болып ұшқанда, бөлме күлкіге толады, ал бойына жиналған бар күш-қуаты бірнеше секундта термен бірге шығып кетеді.'),
  ('69ac9098-fc9c-4474-aa9d-090c0c3f7cdf', 'Таңғы 6-дағы режиссура 🎬', 'Сіз әлі ұйықтап жатырсыз, ал ол басыңызда тұрып: «Сен аю бол, мен қоян боламын!» — дейді. Ұйқылы-ояу күйде қорсылдаған дыбыстар шығарып, осы қызық театрдағы рөліңізді ойнаңыз. Ана болу кейде асқан актерлік шеберлікті талап етеді.'),
  ('aa6e4c45-6848-4e91-8836-f55617de9313', 'Қауымдастықпен сырласу 💬', 'Қатты шаршадыңыз және ешкімге ештеңе түсіндіргіңіз келмейді. Anacan қауымдастығына кіріп, жай ғана оқырман болыңыз. Басқа аналардың да дәл осылай шаршайтынын көру «мен жалғыз емеспін» деген сезім сыйлап, ең жақсы терапияға айналады.'),
  ('7b3c2751-f23f-4467-abdf-9463831a86cb', 'Тыныштықтың цифрлық рақаты 🤫', 'Ақыры ұйықтап қалды! Үйді жайлаған тыныштықтың тереңдігі сонша, құлағыңыз тұнып қалғандай болады. Дыбыс өлшегішті қосып, экрандағы 0-10 децибел көрсеткішіне қарап, миыңыздың біртіндеп қалай қалпына келіп жатқанын көзбен сезініңіз.'),
  ('7d093b24-909b-4f92-b3df-fe627f2322c0', 'Дүкенде «Мен жүргіземін!» 🛒', 'Дүкен арбасын міндетті түрде өзі жүргізгісі келіп, ақырында сөрелерге соғыласыздар. Оның жігерін жасытпау үшін арбаны бірге жүргізіңіздер. Ал ештеңені ұмытпау үшін қолданбадағы Сатып алу тізімін ашық ұстаңыз.'),
  ('803c4a83-8bb9-4a65-a6e0-a757e4e816cf', 'Аяқталмаған сөйлемдерді толықтыр 🗣️', 'Бір сөзді ұмытып қалғанда, қолымен ымдап, Сіздің тауып беруіңізді күте ме? «А-а, допты айтып тұрсың ба?» — дегеніңіздегі оның жеңілдеп қалған сәтін бақылаңыз. Сөздік қоры өсіп келеді, тек миы тілінен жылдамырақ жұмыс істейді.'),
  ('5625eb93-64b3-45e9-9346-29a2c6af885f', 'Табиғат детоксы міндетті 🌳', 'Төрт қабырғаның арасында оның энергиясы агрессияға айналады. Ауа райы қандай болса да, лайықты киіндіріп, оны міндетті түрде далаға шығарыңыз. Топырақты ұстау, жапырақ жинау оның жүйке жүйесін бірден тыныштандырады.'),
  ('d33d70dc-19c8-4087-8ed8-270685911bfd', 'Сыбырдың тылсым күші 🌙', 'Ертегі оқудан дауыс желбезегіңіз шаршады. Бөлменің жарығын толық өшіріңіз. Жанына жатып, күні бойы болған оқиғаларды өте бәсең дауыспен құлағына сыбырлап айтып беріңіз. Сыбырлау — миды ұйқыға дайындайтын ең тыныштандырушы тәсіл.'),
  ('e578603f-02ec-4734-b19f-2d0ca949a8e2', 'Таңғажайып жаратылыс 🎈', 'Осындай ұзақ жолда таңғалатын нәрсе көп. Мысалы, кеше үйренген сөзін бүгін философиялық сөйлемде қолдануы! Бұл күндер енді қайталанбайды.'),
  ('0cdb7f22-d990-414a-b36e-54d6d47e1b4f', 'Жасырын шоколад үзілісі 🍫', 'Асүй шкафының тасасында одан жасырынып шоколад жеп тұрған ана, сол глюкозаға Сіздің де хақыңыз бар. Өзіңізді кінәламаңыз! Оның ессіз энергиясына төтеп беру үшін Сізге де қуат жинау қажет. Терең тыныстап, шоколадты жей беріңіз.'),
  ('62a2e4b7-b7ef-4d46-a134-22e1f4da5625', 'Ақылды ертегінің кейіпкері — өзі 🪄', 'Бүгін кешке Ақылды ертегілердегі басты кейіпкерге балаңыздың атын беріңіз. Ертегідегі кейіпкердің де тісін тазаламай, кейін өкінгенін айтып, маңызды құндылықтарды жанама түрде үйретіңіз.'),
  ('ce8759a7-ff69-4b27-a788-668b48e71999', 'Дәретхана қағазының инженері 🧻', 'Бірнеше минуттық тыныштық... Бөлмеге кірсеңіз, дәретхана қағазының түгел тарқатылып, үйдің ішіне жайылып жатқанын көресіз! Ашуланудың орнына, сол қағаздарды жинап, бірге аққала жасаңыз. Хаосты шығармашылықпен жеңіңіз.'),
  ('1f94fede-7afb-4d0a-8e39-07ab7d2da0c4', 'Сен бала бол, мен ана болайын 👩‍👧', 'Рөл алмасу ойыны басталды! Ол Сізге «бері кел, тамағыңды же» деп нұсқау береді. Оның көшбасшы болу тәжірибесін қуана қабылдап, еш қарсылықсыз оның баласының рөлін ойнаңыз.'),
  ('77330b1b-94b4-4438-9dd4-9ea117490b54', 'Жасанды интеллект, нақты шешім 🤖', 'Неліктен 3 жастағы бала кенеттен тырнағын тістей бастайды? Интернеттегі қорқынышты, жанға жара салатын мақалаларды ұмытыңыз. Anacan AI-дан мұның жай ғана уақытша күйзеліс реакциясы болуы мүмкін екенін сұрап, ғылыми негізделген жауап алыңыз.'),
  ('c30ee50d-9665-4368-af0d-6578c2cc302b', 'Денеңізді тыңдаңыз 🩸', 'Себепсіз шаршап, жылағыңыз келе ме? Етеккір трекерін ашыңыз. Денеңіз белгі беріп тұр. Пайдалы рецептілерден магнийге бай тіскебасар дайындап, өзіңізге қамқорлық танытыңыз.'),
  ('c49b057e-0774-42da-aec0-ee5fcc238471', 'Тамақ талғау 🍝', 'Бөпеңіз тек өзі жақсы көретін 2-3 тағамды ғана жей ме? Уайымдамаңыз. Тамақтануды бақылау құралы арқылы апталық теңгерімді тексеріп, дастарқан басында қысым жасамауға тырысыңыз.'),
  ('462a51f8-d8f0-4c41-8551-81fbd18e8c62', 'Ертегінің соңын өзі ойлап тапсын 🪄', 'Классикалық кітаптардан екеуіңіз де жалықтыңыздар ма? Ақылды ертегілерді ашып, бүгін кешке оқиғаны бөпеңіздің өзі бағыттауына мүмкіндік беріңіз. «Енді көлік қайда барсын?» деп сұраңыз да, өзі ойлап тапқан қызық әрі қисынсыз аяқталуымен ұйықтап қалсын.'),
  ('a8ffc7b0-9821-4b11-9ed7-be3302b5f4fb', 'Мінсіз ана туралы мифтер 🛑', 'Әлеуметтік желідегі балалар өлеңді жатқа айтып жүр, ал Сіздің бөпеңіз әлі де сөздерді шатастыра ма? Салыстыруды дереу тоқтатыңыз! Әр баланың даму қарқыны ерекше әрі әртүрлі. Ол өз қарқынымен мінсіз дамып келеді.'),
  ('fca7853a-0c3e-4553-8c15-c32fa7564774', 'Аяқ киім кию олимпиадасы 👟', 'Оң аяқ киімін сол аяғына киіп алып, оны шешкісі келмей ме? Солай жүре берсін. Еркіндік сезімі мен «өзім істедім» деген мақтаныш аяқ киімді дұрыс киюден маңыздырақ. Бұл болашақта мәселені шешу қабілетінің де негізін қалайды.'),
  ('344d14b0-cfc9-4ff3-af6f-44e0148ab198', 'Көзге көрінбейтін қоқыс қасіреті 🗑️', 'Өзі лақтырып кеткен, ал Сіз қоқысқа тастаған әлгі керексіз қағаз қиындысын іздеп жылап жүр ме? 3 жастағы баланың логикасы дәл осындай. Оны қайтара алмайтындықтан, назарын бірден жарқырағырақ нәрсеге аударыңыз.'),
  ('be71bad2-041d-4cb4-a658-89cb36e8a738', 'Анаға қуат жинайтын уақыт 🔋', 'Бөпеңіз өз бетінше пазл құрастырып, 10 минуттан бері тыныш отыр. Ал Сіз осы сәтті үй жинауға жұмсағыңыз келеді. Жоқ! Диванға жатыңыз. Кешке дейін осы қарқынға төтеп беру үшін Сіздің де қуатыңыз толуы керек.'),
  ('d2f93631-6ef4-4ba4-9cac-259dafd2fb22', 'Қараңғылыққа үйрену 🌙', 'Жатын бөлмедегі жарық сөнгенде мазасыздана ма? Бөлменің бір бұрышына жылы түсті (сары немесе қызғылт сары) шағын түнгі шам қойыңыз. Ал бөлменің қалған бөлігі терең ұйқы үшін тас қараңғы болып қалуы керек.'),
  ('e7437e5e-38bf-45b1-8db0-74786f20b535', 'Екеуіңізге арналған үзіліс 🥂', 'Бөпе ұйықтап қалды. Енді телефондар мен үй шаруасын бір шетке қоя тұрыңыз. Жұбайыңызбен бетпе-бет отырып, небәрі 20 минут төлемдер мен баладан басқа тақырыпта сөйлесіңіз. Сіздер ата-ана ғана емес, жұпсыздар!'),
  ('3a4c5cc8-5f54-4aef-b016-9394a079ec83', 'Қалтадан шыққан қазыналар 🪨', 'Шалбарын жуарда қалтасынан көлемі әртүрлі 3 тас пен талшын қабығы шықты ма? Ол үшін бұлар — әлемдегі ең құнды жинақ. Оларды тастамай, кішкентай қорапқа жинап, қазына сандығын жасаңыз.'),
  ('68c1a1ff-c119-4521-aae1-9a7a984caad7', 'Жарықты өшірсеңіз, ұйқы келеді 🌙', 'Тезірек ұйықтауы үшін жатардан 1 сағат бұрын бөлмедегі барлық қосымша жарықты өшіріп, планшет экрандарын сөндіріңіз. Мелатонин (ұйқы гормоны) қараңғы әрі гаджетсіз ортада ғана жылдам бөлінеді.'),
  ('9021ef15-5cf5-4f9d-8592-aab7e32c65a0', 'Эмоциялық қажу сезімі 🔋', 'Бәріне айқайлағыңыз келе ме? Шу миыңызды тесіп бара жатқандай ма? Бұл — нағыз эмоциялық қажу. Оны дереу қауіпсіз жерге орналастырып (немесе әкесіне беріп), басқа бөлмеге өтіңіз де, Көңіл-күй күнделігіне бүкіл күйзелісіңізді еш сүзгісіз жазып шығыңыз.'),
  ('a5815a11-4b6f-4f3d-a6ff-4d587c286a65', 'Музыкамен ояну 🎶', 'Күн әлі толық шыққан жоқ, ал ол төсекте секіріп, ырғақты дыбыстар шығарып жатыр. Әлемдегі ең шулы, бірақ ең сүйкімді оятқыш! Күніңізді оның сарқылмас қуатына күлімсіреуден бастаңыз.'),
  ('afb9fd4f-60e2-4547-87e2-d867963a1345', 'Сезімдерді жазып қою 📝', 'Бөпе ұйықтағаннан кейін Көңіл-күй күнделігін ашыңыз. Бүгін оның жасаған ең күлкілі, Сізді қатты күлдірген сол бір оғаш сәтін болашақ үшін жазып қойыңыз. Жылдар өткен соң оқығанда көзіңізге жас келеді.'),
  ('db2d884d-1367-4ebc-a61b-9a450673d64d', 'Тыныштық сағаты тәжірибесі 🥱', 'Күндіз ұйықтағысы келмейді, бірақ көзі ілініп бара ма? 3 жастағы қарсылық — қалыпты құбылыс. Мәжбүрлемеңіз: бөлмедегі жарықты бәсеңдетіп, Кітапты үнсіз парақтау сағатын жариялау арқылы жаңа әдет қалыптастырыңыз.'),
  ('0f647bd8-9749-4a55-969b-bfc85ddb7152', 'Әкенің құпия қаруы 🤡', 'Сіз жасағанның бәрі әсер етпей қалғанда, әкесінің оғаш дыбыстары мен күлкілі қылықтары жағдайды бірден құтқарады. Кешкі дағдарыс кезінде кезекті бірден оған беріп, өзіңіз шетте тынығып, бақылаңыз.'),
  ('5407f02f-f40a-48e1-b4f8-80cd1fc9345c', 'Таңғы кішкентай әмірші іске кірісті 👑', 'Ол жерге сен отырма, қонжығым отырады! Таңғы ас кезінде бүкіл үстелге сол басшылық етеді. Оның еркін бірден басып тастамай, «Жақсы, қонжығың сонда отырсын, ал мен мұнда отырайын» деп тепе-теңдікті сақтаңыз.'),
  ('a1a50d57-7314-4042-848d-a89f6c8fc209', 'Табиғат аясына шығыңыз ⛅', 'Төрт қабырға бөпеңізді де, Сізді де ашуландырып жіберді. Ауа райы мен киім құралын тексеріп, бірден саябаққа шығыңыз. Таза ауада жүгіру мен еркіндік бүлдіршіннің ең ауыр дағдарысының өзін пышақпен кескендей сап тыйып жібереді.'),
  ('e61af62b-257c-41ec-8846-9d470f2646d9', 'Кешкі мамыражай сәттер 🛀', 'Күні бойы «қаламаймын» деумен өтті. Жылы ванна тек тазалық үшін емес, оның ширыққан жүйке жүйесін тыныштандыру үшін де қажет. Судың сылдыры мен жылуы бүкіл қырсықтығын жуып-шайып әкетеді.'),
  ('8169372c-8d17-46fc-bfc3-eda3a929eaa6', 'Дүкендегі ұмытшақтық 🛒', 'Жадыңызға сеніп, дүкенге барып, бөпенің жөргегін алуды ұмытып кеттіңіз бе? Ондай да болады. Барлық қажет затты бірден Сатып алу тізіміне жазуды әдетке айналдырыңыз. Қолданба Сіздің цифрлық жадыңыз болсын.'),
  ('a15765ea-b7ce-42a7-91ae-209256ee1beb', 'Анашым, маған қарашы! 👀', 'Сіз телефонға қарап немесе жұмыс істеп отырғанда, ол келіп қолыңызды қағады не алдыңызды бөгейді. Оның талабы орынды: ол Сіздің бар назарыңызды өзіне аударғысы келеді. Бар болғаны 5 минут бойы көзіне қарап, ештеңеге алаңдамай бірге ойнасаңыз, ол тынышталады.'),
  ('de1347cd-769b-44d4-8aff-75ce2b7d2f0c', 'Тыныштықтың дәлелі 🤫', 'Шулы күннен кейін бөпе ұйықтағанда, Дыбыс өлшегішпен бөлмедегі тыныштық деңгейін өлшеңіз. Нөлге жақындаған сандарды көру — сол көзге көрінетін тыныштық ананың миына жасалған ең жағымды массаждай әсер етеді.'),
  ('0ff315d9-2ad1-4c8c-9187-ea4c26042a66', 'Уақыт неткен жылдам!', 'Ол қазірдің өзінде өз шешімдері бар жеке тұлға. Оның осындай қайсар мінезі болашақта Сізді талай рет мақтан тұтқызады. Бұл күндер енді қайталанбайды, оны мейіріммен құшақтаңыз.'),
  ('e4430813-5ad7-446e-9502-6e658d83eddd', 'Көкөніс хирургі 🥦', 'Сорпадағы көкөністерді микроскоппен іздегендей теріп, шетке жинай ма? Күреспеңіз. Пайдалы тағам рецептерінен көкөністерді езіп, тұздықтарға жасырудың алуан түрлі әрі дәмді тәсілдерін табыңыз.'),
  ('e44cdd54-2858-49fa-8fd7-06dc369d29b6', 'Әкенің массаж сеансы 💆‍♂️', 'Бүгін көп уақыт аяғыңыздан тік тұрып, бөпеңіздің соңынан жүгіріп, беліңіз ауырып кетті. Бөпе ұйықтаған бойда жұбайыңыздан иығыңызға 10 минут массаж жасап беруін сұраңыз. Сіз — отбасының тірегісіз, ал тірек те міндетті түрде қалпына келуі керек.'),
  ('9c8523f0-548b-4581-bde4-2a8295db3639', 'Қараңғылыққа шақыру 🌙', 'Тезірек ұйықтауы үшін бөлмедегі барлық артық жарықты өшіріп, планшеттердің экрандарын сөндіріңіз. Қараңғы әрі гаджеттер жоқ ортада мелатонин жақсы бөлініп, ұйықтауды жеңілдетеді.'),
  ('b7c3f40e-e406-412b-86a2-1c33a12692d8', 'Балабақша туралы ойлар 🏫', 'Оған енді көбірек әлеуметтену қажет екенін сезіп жүрсіз бе? Балабақшаға баратын уақыт келді ме? Anacan Қауымдастығына қосылып, басқа аналардың бейімделу туралы шынайы тәжірибесін оқыңыз — бұл шешім қабылдауыңызды жеңілдетеді.'),
  ('d8d022ce-8e44-42aa-972f-aa293c4341c8', 'Сізге көмектесейін! 🧽', 'Сіз ыдыс жуғанда, жаныңызға орындық қойып, сумен ойнағысы келе ме? Шын мәнінде, ол көмектескісі келгеннен емес, әрекеттің бел ортасында болғысы келгендіктен осылай істейді. Оған кішкентай пластик ыдыс беріп, сабындауына мүмкіндік беріңіз.'),
  ('63dc600c-4255-41f7-8695-78dd689a1998', 'Сыбырлап айтылатын ертегілер 🪄', 'Бөлменің жарығын толық өшіріңіз. Жанына жатып, Ақылды ертегілердің бірінен қысқа оқиғаны өте бәсең дауыспен құлағына сыбырлап айтып беріңіз. Сыбырлау — миды ұйқыға дайындайтын ең табиғи әрі тыныштандыратын тәсілдердің бірі.'),
  ('76d2443b-1074-45cd-a82d-59ba223792bb', 'Жанды диктофон 🎙️', 'Кеше телефонмен құрбыңызға айтқан әлгі эмоцияға толы немесе оғаш сөйлемді бүгін ол ойыншығына айтып отыр! Сөздік қоры таңғаларлық жылдамдықпен кеңейіп келеді және ол Сізге еліктейді. Енді айтатын сөздеріңізге екі есе мұқият болыңыз.'),
  ('a624ef08-9c66-462b-82e4-a4aa90f5b17b', 'Өзіңізді бағалаңыз 🥗', 'Оны тамақтандыру үшін жұмыртқаны 4 түрлі тәсілмен дайындадыңыз, ал өзіңіз не жедіңіз? Пайдалы рецептілердің ішінен 5 минутта дайын болатын, темір мен кальцийге бай арнайы ас әзірлеп, өзіңізді қуантыңыз.'),
  ('0f7458af-fb58-4fe6-9907-6a5b773bca96', 'Ақ шудың көмегі 🤫', 'Ұйықтап бара жатқанда бөпе дыбыстарға ерекше сезімтал болады. Терезеден естілетін дыбыстарды бәсеңдету үшін бөлмеде Дыбыс өлшегіштің фондық дыбысын қосып, жайлы әрі тыныш орта қалыптастырыңыз.'),
  ('143f9431-42d8-41e6-9983-ce9dde347219', 'Киімнің бәрі дақ 🎨', 'Пижамасына тамақ төгіліп, үсті-басы бояу болып жүр ме? Балалар тап-таза болып өспеуі керек: олар әлемді зерттеп жүріп кірлейді. Силикон алжапқыштарды пайдаланыңыз, ал қалғанын кір жуғыш машинаға тапсырыңыз.'),
  ('6aecb8fd-7228-4ba7-9f34-65a8f0cda801', 'Жиһазға өрмелеу 🧗‍♂️', 'Диванға не креслоға жармасып, жоғары өрмелеуге тырыса ма? Бұл оның тепе-теңдігі мен бұлшықет күші артып келе жатқанын білдіреді. Қауіпсіздігін қадағалаңыз, бірақ кішкентай альпинистің мұндай талпыныстарына және физика заңдарын зерттеуіне кедергі жасамаңыз.'),
  ('0db41c26-c87d-4bd7-8650-e9fd07449904', 'Аналардың сырласуы 💬', '«Бұл бала ешқашан тынышталмайды» деген ой Сізді қажытып жүр ме? Anacan Қауымдастығына қосылыңыз. Әр баланың 3 жасқа қарай осындай аласапыран дағдарыстардан өтетінін көріп, терең тыныстайсыз.'),
  ('448fd3b8-143f-4fee-a40b-1b20e42ebbba', 'Бір, екі, үш... он! 🔢', 'Саусақтарын немесе ойыншықтарын санауға тырыса ма? Оның математикалық ойлауы оянып келеді. Ғажайып жылдамдықпен дамып жатқан осындай кішкентай талпыныстарын назардан тыс қалдырмаңыз.'),
  ('5a020277-4aac-4623-8f46-93168c2f54e5', 'Әкенің түнгі кезекшілігі 👨‍🍼', 'Түнде ояну мен ұйықтату міндетін жалғыз өзіңіз арқаламаңыз. Жұбайыңызды да оятыңыз: бір команда болу — жауапкершілікті тең бөлісу. Бүгін бөпені ұйықтату толығымен оның міндеті.'),
  ('026f00f3-6e56-4ac5-a91b-bd5bd82cd187', 'Тыныштық сағатын байқап көру 🥱', 'Күндіз ұйықтағысы келмей, жылай ма? Мәжбүрлемеңіз. Бөлменің жарығын бәсеңдетіп, «Кітапты үнсіз парақтау сағатын» жариялаңыз. Осылайша екеуіңізге де жайлы жаңа әдет қалыптастырасыз.'),
  ('53b445aa-e1d7-4c46-9d5a-07132c91031c', 'Қараңғылықтағы елестер 🌌', 'Жарық сөнгенде бөлмедегі заттар құбыжыққа айналып кеткендей бола ма? Ақ шудан ана құрсағындағы дыбысты қосып, оған бұрыннан таныс мінсіз қауіпсіздік сезімін қайта сыйлаңыз.'),
  ('f4eb03a9-f74f-423a-ab2a-59d54da2db98', 'Логиканы іздеу 🧩', 'Қарапайым ойыншықтар енді оны қызықтырмай, күрделірек ойындар құра бастады ма? Зердесіне көбірек салмақ түсіріп, логикалық ойлауын дамытатын ойындарды «Ұсынылатын өнімдер» бөлімінен іздеңіз.'),
  ('135b57f3-06e7-4fc4-b590-bec1151ee33b', 'Жылы судың сиқыры 🛀', 'Күні бойы «қаламаймын» деумен өтті. Жылы ванна тек тазалық үшін емес, оның ширыққан жүйке жүйесін тыныштандыру үшін де қажет. Судың сылдыры мен жылуы бар қырсықтығын шайып әкетеді.'),
  ('57cfce2e-d64c-49cb-9f8b-295055620f21', 'Табиғат жұмбағы 🍁', 'Үйдегі іш пыстырарлық ахуал екеуіңізді де жалықтырды. Саябаққа барып, пішіні ең ерекше тасты табу миссиясына аттаныңыздар. Табиғат — ол үшін ең үлкен зертхана әрі бүкіл ширығуын басатын орта.'),
  ('682b0a2a-83c6-46cb-a100-02da150309f7', 'Жануарларға еліктеу 🐶', 'Ол жануарлардың дыбысын салып қана қоймай, ит сияқты еңбектеп, мысық сияқты еркелей ме? Дене қимылы мен қиялы таңғаларлықтай үйлесіп жатыр. Кілем үстінде оған қосылып ойнап, Сіз де күйзелістен арылыңыз.'),
  ('01a8a883-66ea-4e90-9796-1cd4c7aa4386', 'Анаға арналған Offline сағат ☕', 'Бала өз әлеміне еніп, ойнап отырғанда үйді дереу жинауға асықпаңыз. Өзіңізге бір кесе ыстық шай құйып, телефонды шетке қойыңыз да, 15 минут ештеңе ойламай, жай ғана отырыңыз.'),
  ('7fc36514-28e6-4738-b9f6-f0c9cd9fa57d', 'Екеуіңізге арналған үзіліс 🥂', 'Бала ұйықтап қалды. Енді үй шаруасын шетке қоя тұрыңыз. Жұбайыңызбен кемінде 20 минут бала мен шығындардан басқа кез келген тақырыпта әңгімелесіңіз. Сіздер ата-ана ғана емес, жұпсыздар да!'),
  ('8b2d61db-8be9-4916-a184-f14d02885b17', '«Бұл не?» машинасы ☝️', 'Барлығын саусағымен көрсетіп, атауын сұрай ма? Ол Сізден айналасындағы дүниенің атауын білгісі келеді. Бұл — қарым-қатынас дамуындағы үлкен серпіліс! Шаршасаңыз да, заттардың атауын сабырмен қайталай беріңіз.'),
  ('6716e6c0-2c87-4096-9dc2-661b570d83da', 'Тоңазытқыштағы пульт 📺', 'Теледидар пультін таба алмай жүрсіз бе? Тоңазытқышты немесе аяқкиім шкафын қарап көріңіз. Ол заттарды өзі ойлап тапқан логикаға сай орналастырып, әлемді зерттеп жүр. Ашуланудың орнына, бұл қисынсыз детектив ойынына күле қараңыз.'),
  ('7e1b9939-5806-440f-9214-8ee42a76c83e', 'Қиялдағы жараны іздеу 🩹', 'Ояна сала денесінен көрінбейтін жара тауып, оған дереу пластырь жапсыруыңызды талап етеді. Бұл физикалық ауырсыну емес, тек назар мен мейірімге деген қажеттілік. Дауласпай-ақ, кішкентай пластырьді жапсырып, сүйіп қойыңыз — сонда күніңіз сәтті өтеді.'),
  ('ce6bc378-f040-49dc-a292-ef6ffa4a4247', 'Кенеттен ашығу синдромы 🥱', 'Төсекке жата бергенде, «Анашым, қарным ашты» деп асүйге жүгіргісі келеді. Ұйықтайтын уақытты кейінге қалдырудың таптырмас амалы! Тамақтану жоспарына кешке ұйқыға көмектесетін шағын тіскебасарды (мысалы, банан) қосып, бұл сылтаудың алдын ала жолын кесіңіз.'),
  ('7a0aa78e-7c5e-4ec5-9361-dc21cc74b32f', 'Тыныштық тудырған алаң 🤫', 'Ол бөлмеде жалғыз өзі суреттерді қарап отыр, ал үйде мүлгіген тыныштық. Сіз бұл тыныштықтан күдіктеніп, әр сәтте бірдеңе болып қалады деп күтесіз. Алаңдамаңыз. Кейде олар да жалғыз қалғысы келеді. Арқаңызды кеңге салып, осындай сирек офлайн сәттен ләззат алыңыз.'),
  ('7dcdfa61-d4a7-4888-bf22-0453312c6bae', 'Дауыстап ойлау 💭', 'Төсекте жатып, күні бойы болған оқиғаларды өзіне-өзі, бірақ дауыстап айтып береді. Ол ақпарат пен естеліктерді осылай қорытады. Даму трекерін ашып, оның еркін әңгіме құрау қабілетінің қаншалықты қарқынды дамығанын мақтанышпен белгілеңіз.'),
  ('dcfa33ac-90f3-4b1d-b8de-e6f8c966ff39', 'Кілемдегі сызықтар 📏', 'Ол кілемдегі сызықтарды баспай жүруге тырысып, Сізден де соны талап етеді. Ірі моторика мен зейін үйлесімі тамаша жұмыс істеп тұр. Ойынды бұзбаңыз, Сіз де бірнеше қадам бойы онымен бірге сызықтардан секіріп өтіңіз.'),
  ('80fe5b22-0f4c-4f31-ac99-30418e5a6c6a', 'Анаға бір сәт тыныс 🌬️', 'Үйдегі у-шу құлағыңызды тұндырып жіберді. Ауа райын тексеріп, лайықты киім таңдаңыз да, қалың киінуге тура келсе де, небәрі 15 минутқа далаға шығыңыз. Ол жердегі тастарды жинай берсін, ал Сіз бетіңізге соққан салқын әрі таза ауаны терең жұтыңыз.'),
  ('93c26bc0-b2a6-4580-91d3-d91792e077a2', 'Динозавр тілі 🦖', 'Бүгін таңертең ол адам емес, динозавр және барлық сұрағыңызға тек ақырып жауап береді. Рөлдік ойындар тұлғалық дамудың тамаша құралы саналады. Сіз де бір сәтке ана емес, басқа динозаврға айналып, оған өз тілінде жауап беріңіз.'),
  ('b992124a-a4ae-4e30-a81b-b79de4b95a68', 'Шаршағаныңызды мойындау 📝', 'Сізді ешкім түсінбейді, еңбегіңізді ешкім байқамайды деп ойлайсыз ба? Жасанды жымиюды доғарыңыз. Көңіл күй күнделігіне бүгін шын мәнінде қаншалықты қажығаныңызды жазыңыз. Экранға түскен әрбір сөз иығыңыздағы ауыр жүктің бір бөлігін жеңілдетеді.'),
  ('075e0950-03bc-496b-a1a2-1172377fb523', 'Жасанды интеллект және алаңдаушылық 🤖', 'Балаңыздың кейбір дыбыстарды айта алмауы кенеттен Сізді алаңдатты ма? Интернеттегі мамандар жазбаған, үрей туғызатын форумдарды жабыңыз. Anacan AI-дан 3 жас шамасындағы баланың сөйлеу дамуының қалыпты көрсеткіштерін сұрап, ғылыми негізделген әрі көңіліңізді тыныштандыратын жауап алыңыз.'),
  ('cfe53a47-5049-4180-8a26-333de41ec18f', 'Таңдап есту синдромы 🙉', 'Ойыншықтарыңды жина дегенде естімейді, бірақ көрші бөлмедегі шоколад орамасының сыбдырын бірден сезе ме? Есту қабілетінде мәселе жоқ, ол тек өзіне керегін ғана естиді. Ережелерді сыбырлап айтып көріңіз, сонда оның қызығушылығы оянады.'),
  ('46cb3019-8e96-4dd4-93b2-6c2a4bab0f53', 'Қалтадан шыққан қазыналар 🪨', 'Шалбарын жуғалы жатқанда қалтасынан 2 тас, бір кепкен жапырақ пен жарты бұтақ шықты ма? Сіз үшін қоқыс болғанымен, бұл заттар — оның әлемді танып-білу кезінде жинаған құнды коллекциясы. Оларды тастамай, шағын қазына қорабына жинаңыз.'),
  ('4c758b24-b5bb-4fba-9fae-76aff0e5119d', 'Брокколи камуфляжы 🥦', 'Сорпадағы жасыл көкөністерді хирургтің дәлдігімен теріп алып тастай ма? Тамақ талғауы шегіне жетті. Тамақтану жоспарынан көкөністерді байқатпай қосып, түрлі түсті котлеттерге айналдыратын арнайы әрі айлакер рецептілерді табатын кез келді.'),
  ('56a63f2b-c314-4614-a2a4-36e4a75775f5', 'Ертегінің режиссері — өзі 🪄', 'Классикалық кітаптардан екеуіңіз де жалықтыңыздар. Ақылды ертегілерді ашып, бүгін кешке оқиғаны оның өзі бағыттасын. «Енді ұшатын көлік қайда барсын?» деп сұраңыз да, өзі ойлап тапқан қисынсыз аяқталумен ұйықтап қалуына мүмкіндік беріңіз.'),
  ('4cbe2cb0-5188-4114-8447-b099245e7121', 'Әкенің ұшу режимі ✈️', 'Үйде бойындағы қуатын шығара алмай, ұйықтағысы келмей жүр. Әкесін көмекке шақырыңыз. Ол баланы аспанға көтеріп, ұшақ болып ойнағанда, бөлме күлкіге толып, жиналған бүкіл физикалық ширығу санаулы секундта жоғалады.'),
  ('9afa0a7d-99d2-4d5f-a4cb-8f47ca178b6a', 'Қауымдастықта тыныстау 💬', 'Қатты шаршап, өзіңізді әлемдегі ең шыдамсыз анадай сезініп жүрсіз бе? Дереу Anacan қауымдастығын ашыңыз. Басқа аналардың да дәл осындай қисынсыз дағдарыстарды бастан кешіретінін оқу — ең үлкен психологиялық қолдау.'),
  ('bd33d5a6-7358-4409-91cf-48f9ce76cb44', 'Шексіз «Неге?» айналымы 🌪️', '«Құстар неге ұшады?», «Су неге сулайды?», «Неге — неге?»... Сұрақтар пойызы Сізге қарай жүйткіп келеді. Шаршасаңыз да, оған қисынды әрі қысқа жауап беріңіз. Ол ғаламның құпияларын Сіздің дауыс ырғағыңыз арқылы танып-біледі.'),
  ('5940af77-4cae-40d5-a543-2bf3a6668855', 'Табиғатқа қашу ⛅', 'Төрт қабырға оның да, Сіздің де ашуыңызды қоздырды. Үйдегі бейберекеттіктен шаршадыңыз. Ауа райы мен киім құралын тексеріп, бірден саябаққа шығыңыз. Таза ауада еркін жүгіру бүлдіршіннің ең ауыр қырсығын да сап тыйып жібереді.'),
  ('9bbc80a7-dd83-4c11-86b7-3f3e1fd0e2b9', 'Төсектегі цирк 🎪', 'Ұйықтайтын уақыт келгенде, төсек әп-сәтте цирк аренасына айналады. Бөпеңіз секіреді, еңбектейді, айқайлайды. Даусыңызды көтермей, жарықты бәсеңдетіңіз. Ол бойындағы энергияның соңғы қалдығын шығарып жатыр. Ақылды ертегілердегі өте баяу ырғақты хикаяның көмегімен бұл дауылды біртіндеп басыңыз.'),
  ('c4897803-48e7-46f1-aca1-db692fe7b9f1', 'Ешкімге берілмейтін есік тұтқасы 🚪', '«Есікті мен ашамын!» деп, Сізден бұрын жүгіріп кетеді. Егер есікті Сіз ашсаңыз, жылап, оны қайта жапқызады да, өзі ашады. Бұл жаста бәрінен маңыздысы — жағдайды өзі басқарып отырғанын сезіну. Есікті өзі ашсын, мұндай шағын жеңістер оның әлі де нәзік өзіне деген сенімін нығайтады.'),
  ('2b40e6c9-46bc-4fb2-8d09-1e690e1a478c', 'Қолдау қауымдастығы 💬', 'Бүгін ол соншалықты көп қарсылық көрсетті, тіпті өзіңізді нашар анадай сезініп тұрсыз. Дереу Anacan Қауымдастығына кіріңіз. Басқа аналардың балалары бүгін қалай бүлік шығарғанын оқығанда, жалғыз емес екеніңізді әрі шын мәнінде бәрін керемет атқарып жүргеніңізді түсінесіз.'),
  ('4f85a7f5-323c-4830-b901-61f69a9b8176', 'Жасырын екіұдайлық 🤔', 'Сізге келіп, «Маған су бер, бірақ берме» деген сияқты мүлде қайшы сөйлемдер айтады. Оның санасында бір-біріне қарама-қайшы екі тілек қатар өмір сүріп жатыр. Бұдан терең қисын іздемей-ақ, суды үстелге қойып, шешімді оның ішкі тартысына қалдырыңыз.'),
  ('fb64f95e-ceac-49e1-96ee-95e171273ead', 'Балға мен бұранда тәжірибелері 🛠️', 'Қолына түскен кез келген қатты ойыншықпен жиһазды ұрып, «жөндеп» жүреді. Бұл дыбыстар миыңызды тесіп жіберердей болса да, бөпеңіз осылайша себеп-салдар байланысын зерттеп жатыр. Оған бос картон қорап пен ағаш қасық беріңіз, шулы жөндеуін сонда жалғастыра берсін.'),
  ('0b8c858b-4b69-4199-b627-a7a497686efd', 'Қоқыс емес, өнер 🎨', 'Ол бөлменің ортасында ұсақ қағаз қиындылары мен кесілген жіптерден үлкен өнер туындысын жасап, оны тастауға рұқсат бермей отыр. Тазалыққа деген шектен тыс ұқыптылықты бір сәтке ысырып қойыңыз. Ол жасаған бейберекеттікке құрметпен қараңыз, жинауды ертеңге де қалдыруға болады.'),
  ('5f97fec7-d72f-4377-af18-4420a1663ca4', 'Дыбыс өлшегіш терапиясы 🤫', 'Үйдегі бітпейтін шу ақыры тынды. Бөпеңіз ұйықтап жатыр. Дыбыс өлшегішті қосып, экрандағы сандардың 0 децибелге дейін төмендеуін бақылаңыз. Бөлмедегі абсолютті тыныштықтың миыңызға көзбен көретіндей әсер беріп, қалай тынықтыратынын сезініңіз.'),
  ('63b3f3e0-ceca-4b44-a2ea-ae171ce3413f', 'Айна алдындағы театр 🎭', 'Таңертең айна алдына тұрып, жылау, күлу және таңданудың әртүрлі мимикаларын қайталап жаттығады. Ол өз эмоцияларын қалай білдіруді және сол кезде бет әлпетінің қалай өзгеретінін үйреніп жатыр! Осы данышпан актердің өнерін алыстан мақтанышпен тамашалаңыз.'),
  ('14f4e22b-ebcd-4b44-af1e-7caf9bc49874', 'Әкенің сиқырлы құшағы 🫂', 'Күні бойы көтеріп, қолдарыңыз үзіліп түсердей болды, ал ол әлі де құшаққа сұранады. Әкесін шақырыңыз. Әкесінің қолында ұшу баланың назарға деген қажеттілігін өтеп қана қоймай, қолдарыңыз бен беліңізге аса қажет демалысты да сыйлайды.'),
  ('8e97dc44-4076-463e-90aa-e9a38f43a406', 'Сұрақтың астарындағы қисын 🧐', 'Балықтар неге жүрмейді? Таң ата оның миы философиялық ойлармен оянады. Сұрақтары Сізді тығырыққа тіресе де, жалықпай түсіндіруге тырысыңыз. Сіздің даусыңыз — ол үшін ғаламды танудың ең сенімді әрі ең тамаша жолы.'),
  ('d78d5945-d2b9-4d6b-be69-c36a9e85a337', 'Сатып алу тізіміндегі бейберекет 🛒', 'Дүкенде кассаның алдында тұрып, ең маңызды нәрсені тағы да ұмытып кеткеніңізді байқадыңыз. Ойыңыз онсыз да мың саққа бөлініп жүр. Бұдан былай бірдеңе қажет болған сәтте-ақ оны қолданбадағы Сатып алу тізіміне жазуды әдетке айналдырып, өзіңізге көмектесіңіз.'),
  ('62d4901b-19ff-4b33-a0e0-89d727535d96', 'Киімді теріс кисе де, мақтаныш 🧦', 'Шұлықтың өкшесі аяғының үстіне шығып кеткен, бірақ өзі кигендіктен, мақтанышпен жүр. Мүлде араласпаңыз. Оның «менің қолымнан келді» деген сезімі әдемі немесе дұрыс киінуден миллион есе маңызды психологиялық негіз қалайды.'),
  ('79c5f477-357d-4a5a-a226-aa71c2153c6a', 'Сыбырлап айтылған хикаялар 🌙', 'Бүгін көп сөйлеп, даусыңыз да, өкпеңіз де шаршады. Жарықты өшіріп, жанына жатыңыз да, күні бойы болған оқиғаларды құлағына сыбырлап айтып беріңіз. Сыбыр оның зейінін шоғырландырып, миын гипноз әсеріндей терең ұйқыға дайындайды.'),
  ('b3b80c54-4891-4e55-9e0b-d88a4a322bdd', 'Асүйдегі концерт 🥄', 'Ол кәстрөлдер мен ағаш қасықтарды шығарып алып, асүйдің ортасында даңғаза концерт қойып жатыр. Басыңыз ауырса да, бұл — оның ырғақты сезінуі мен қимыл-қозғалыс дағдыларының дамуы. Оған «браво» деп айтып, концерттің тезірек аяқталуына үміттеніңіз.'),
  ('26929739-4514-47f4-b2ff-3f79743e2a52', 'Алтын тыныштықтың өлшемі 🤫', 'Үйдегі бейберекет ақыры басылып, ол ұйықтап қалды. Ыдыс жууға асықпаңыз! Дыбыс өлшегішті қосып, бөлмедегі мүлгіген тыныштыққа (0-10 децибел) қарап, 15 минут ішінде миыңыздың қалай тыныққанын көзбен көріп, сезініңіз.'),
  ('691e79df-4ad4-4dc1-80d2-9bb367dfc70e', 'Банан аршудан туған қасірет 🍌', 'Бананды оның орнына Сіз аршып қойғаныңыз үшін таңғы сағат 8-де бөлмеде төңкеріс басталды ма? Бұл жастың алтын ережесі: бәрін өзі шешуі керек. Бананның қабығын қайта жабыстыра алмайсыз, сондықтан назарын дереу басқа бір қисынсыз нәрсеге аударып, дағдарысты басыңыз.'),
  ('7886ad64-9846-4990-9753-652093d6bac5', 'Дұрыс емес түстің кесірі 🔴', 'Суды көк емес, қызыл стақанға құйып бергеніңіз үшін айғай-шу басталды ма? Бұл еркелік емес, ол жай ғана Сіздің шекараңызды және айналасындағы әлемді басқара алатынын тексеріп жүр. Қырсықпай, стақанды ауыстырып беріңіз де, күшіңізді үнемдеңіз.'),
  ('bfa1d504-f493-414c-a978-4ad885726ef7', 'Сезімдеріңізге ерік беріңіз 📝', 'Үйде қаншалықты шаршайтыныңызды ешкім байқамай ма? Көңіл күй күнделігі — ең үнсіз сырласыңыз. Бүгін Сізді ашуландырған барлық ұсақ-түйекті сонда жазып, ойыңыздың қалай жеңілдегенін байқаңыз.'),
  ('1800a436-63cf-4ef5-8469-ebb0dffa942d', 'Жасанды интеллект, нақты шешім 🤖', 'Балаңызда оғаш әдет пайда болды ма (мысалы, шашын саусағына орау), ал интернеттегі мақалалар Сізді қорқытып жіберді ме? Тоқтаңыз. Anacan AI-дан оның педиатрлар растаған нақты себебін сұрап, орынсыз уайымнан арылыңыз.'),
  ('3f147988-5fe0-4104-b53b-bcd1de9eb553', 'Жасырынбақтың қисыны 🙈', 'Ол бөлменің ортасында көзін қолымен жауып алып, Сіздің оны тапқаныңызды күтіп тұр! 3 жастағы баланың қисыны: мен сені көрмесем, сен де мені көрмейсің. Оның осы пәк қиялына сенгендей болып, бөлме ішінде дауыстап іздеңіз.'),
  ('e71a10b9-dee7-4968-a1f7-387196804ef0', 'Жарықты өшірсеңіз, ұйқы келеді 🌙', 'Тезірек ұйықтауы үшін жатардан 1 сағат бұрын бөлмедегі барлық қосымша жарықты өшіріп, планшет экрандарын сөндіріңіз. Мелатонин (ұйқы гормоны) қараңғы әрі технологиясыз ортада жылдамырақ бөлінеді.'),
  ('2cc2d175-4d74-4e12-832a-3885acc3e55b', 'Цифрлық жады 🛒', 'Дүкенге барғанда міндетті түрде бір нәрсені ұмытып кетесіз бе? Сатып алу тізімі қолданбада Сізді күтіп тұр. Қажет заттарды бірден сонда жазып қойыңыз, жұбайыңыз жұмыстан қайтарда бәрін тізім бойынша алып келсін. Миыңызды артық ақпаратпен жүктемеңіз.'),
  ('8949a363-0fca-4998-bc28-ec5b3f0fc9b2', '«Өзім істеймін!» заңы 👟', 'Ол аяқкиімінің бауын өзі байлағысы келеді, ал Сіз үйден шығуға 10 минутқа кешігіп қалдыңыз. Асықтырмаңыз. Баланың дамуы үшін бұзылған уақыт кестесінен гөрі, жараланбаған өзіне деген сенімі маңыздырақ.'),
  ('b6dabad1-9ff8-435e-b107-865df601701d', 'Сыбырдың тылсым күші 🤫', 'Төсекте тым белсенді болып, ұйықтай алмай жүр ме? Дауысыңызды көтерудің орнына, кенет бәсеңдетіп, сыбырлап сөйлеңіз. Бала Сізді есту үшін зейінін шоғырландырғанда, оның миы автоматты түрде ұйқы режиміне ауысады.'),
  ('222c5b3e-e10d-4be3-be74-5b7c060039a8', 'Түнгі тыныштық 🛁', 'Күні бойы жүгіріп, бөпеңіз де, Сіз де әбден шаршадыңыздар. Жылы ванна қабылдаған кезде баяу табиғат дыбыстарын қосыңыз. Судың үйлесімді үні тіпті ең қиқар баланың өзін терең ұйқыға дайындайды.'),
  ('658a0f7f-5501-4d36-97c8-25ebf4c2bf93', 'Жанасудан шаршау 🔋', 'Күні бойы үстіңізге өрмелеп, құшақтауды сұрайды және шашыңызбен ойнайды. Ал Сізге аз ғана физикалық кеңістік қажет. Жанасудан шаршау (touched out) — шынайы сезім. Кемінде 15 минут бір бөлмеде жалғыз қалуға қақыңыз бар.'),
  ('fd872988-ca1c-4392-86ef-3fa893d01f3e', 'Ваннаның су ағатын тесігінен қорқу 🛀', 'Бұрын судан шыққысы келмейтін балаңыз кенет ваннаның су ағатын тесігінен қорқып, жылай бастады ма? Қиялы дамыған сайын негізсіз қорқыныштар пайда болуы мүмкін. Тесіктің үстін пластик ойыншықпен жауып, балаңызға қауіпсіз екенін сездіріңіз.'),
  ('380c78ab-6c26-4edf-8c80-e7615f9b4b80', 'Жұпқа арналған үзіліс 🥂', 'Бала ұйықтады. Енді үй шаруасын бір шетке қойыңыз. Жұбыңызбен кемінде 20 минут бала, мәселелер мен шығындардан басқа кез келген тақырыпта әңгімелесіңіз. Сіздер ата-ана атанбай тұрып-ақ бір жұп едіңіздер!'),
  ('752bc100-4fdb-4f78-84aa-dd9676151255', 'Жансыз заттармен сөйлесу 🗣️', 'Саябақтағы тасқа немесе үйдегі орындыққа өте байыппен бірдеңе айтып, тіпті оларға ұрсуы мүмкін. Символдық ойындар арқылы ол қоршаған ортаны танып, түсініп жүр. Даму трекерінде оның осындай ерекше сценарийлерін міндетті түрде белгілеңіз.'),
  ('7bfbea7d-ee3e-4b33-88e0-e90f78f2538d', 'Әкеден массаж сеансы 💆‍♂️', 'Бүгін көп уақыт тік тұрып, балаңыздың артынан жүгіргеннен беліңіз ауырып кетті. Бала ұйықтаған бойда жұбыңыздан иығыңызға 10 минут массаж жасап беруін сұраңыз. Сіз — үйдің тірегісіз, ал тірек те міндетті түрде қалпына келуі керек.'),
  ('14bae514-5bcb-45ca-923d-75a7333cefe5', 'Ұйқыны кейінге қалдыру айласы ⏱️', 'Ұйықтайтын уақыт келгенде кенет шөлдеп, дәретханаға барғысы келе ме немесе қабырғамен қоштаса бастай ма? Таймер орнатыңыз. Қоңырау соғылғанда бәрі ұйықтайды деген ережені енгізіп, осы бітпейтін қоштасуды сабырмен тоқтатыңыз.'),
  ('4ec63d29-5d5a-4c61-aeca-3683d2926fad', 'Ананың ас-ауқаты 🥗', 'Балаңызды тойдыру үшін түрлі мәзір ойластырдыңыз, ал өзіңіз тағы да аш қалдыңыз ба? Пайдалы рецептілер арасынан 10 минутта дайындалатын, темір мен кальцийге бай түскі ас таңдап, өзіңізге де қамқорлық жасаңыз.'),
  ('d6b3a2c2-7743-47f8-927a-59220b3461a1', 'Кір жуу көмекшісі 🧺', 'Сіз киімдерді көп күш жұмсап бүктейсіз, ал ол көмектесемін деп бәрін қайтадан бөлмеге шашып тастайды. Ашуланудың орнына, бұл істі ойынға айналдырыңыз: Қане, мына шұлықтарды себетке кім тезірек салады екен?'),
  ('95036444-eb4a-4cd7-a33d-678f3daaa180', 'Авангард сән үлгісі 👗', 'Қысқы жемпірдің үстінен жазғы шолақ шалбар киіп алып, шешкісі келмей ме? Ештеңе етпейді. Көпшілік алдына үйлеспейтін киіммен шыққан бала — шын мәнінде өз шешімін батыл қорғай алатын бала. Оның жігерін жасытпаңыз.'),
  ('98f4059e-feba-4e5c-88c8-f44ceadd630c', 'Түнгі үрейдің құпиясы 😭', 'Түн ортасында көзін ашпастан жылап оянып, ешкімді естімей ме? Жылауды талдау арқылы анықтаңыз; егер бұл түнгі үрей болса, оны оятуға тырыспаңыз. Тек жанында болып, үнсіз қауіпсіздік сезімін сыйлаңыз.'),
  ('bfca2126-084c-4371-a225-6bbeaa8fe2d1', 'Ауа райы туралы ескерту ⛅', 'Серуенге шығарда терезеден қарап қана шешім қабылдамаңыз. Ауа райы және киім көмекшісі арқылы даладағы нақты жел мен температураға сай киім үйлесімін таңдап, үйден алаңсыз әрі дайын болып шығыңыз.'),
  ('25567149-e2e9-4c4d-aaff-501c9547f638', 'Қауымдастықтағы сырластық 💬', 'Қатты шаршадыңыз және ешкімге ештеңе түсіндіргіңіз келмейді. Anacan қауымдастығына кіріп, жай ғана оқырман болыңыз. Басқа аналардың да дәл осылай шаршайтынын көру «мен жалғыз емеспін» деген сезім сыйлап, ең жақсы терапияға айналады.'),
  ('3df12920-0213-48db-ae96-b67ec62ae28a', 'Жанды концерт және көршілер 🎤', 'Қолына қасық алып, бөлменің ортасында бар даусымен ән айтып тұр. Көршілер не ойлайды деп уайымдамаңыз. Сіздің үйіңізде бір жұлдыз өсіп келеді, Сіз тек қол соғыңыз.'),
  ('3f3676c6-cf62-4752-a389-70e0f348c529', 'Әуенмен ұйқыға көшу 🎶', 'Кешкісін себепсіз басталатын мазасыздықты баяу классикалық музыкамен басып көріңіз. Көбіне осы қарапайым, бірақ әсерлі тәсіл үйде ғажайып жасап, бөлмеге міндетті түрде тыныштық орнатады.'),
  ('3e411b4b-9fe8-4f71-93e2-682182a18dba', 'Экран уақыты үшін өзіңізді кінәлау 📺', 'Бүгін шаруаларыңызға байланысты оған мультфильмді әдеттегіден көбірек қосып бердіңіз де, өзіңізді кінәлі сезініп жүрсіз бе? Өзіңізді жазғырмаңыз. Кейде цифрлық күтуші — Сізді психологиялық күйзелістен сақтап қалатын жалғыз амал.'),
  ('66770f83-ef83-4481-9f8c-e9788791f68a', 'Телефонды жасыру операциясы 📱', 'Телефоныңызды қайда қойғаныңызды таба алмайсыз, ал біраз уақыттан кейін ол ойыншықтар салынған жәшіктен шығады. Бөпеңіз Сіздің назарыңызды телефонмен бөліскісі келмейді. Құрылғыны шетке қойып, оған 15 минут бойы бар назарыңызды бөліңіз.'),
  ('b18d81af-044b-40e7-b55d-b23baee972a4', 'Тыныштықтың цифрлық өлшемі 🤫', 'Ол ақыры ұйықтап қалды! Үйді жайлаған тыныштыққа сене алар емессіз. Дыбыс өлшегішті қосып, экрандағы 0-10 децибел көрсеткішіне қараңыз да, миыңыздың біртіндеп тынығып жатқанын көзбен сезініңіз.'),
  ('09d17b10-a60b-4930-b773-b0f5bb7e0366', 'Ойыншығымды бермеймін! 🧸', 'Саябақта сырғанақта немесе құм алаңында ешкімге орын бергісі келмей, ойыншықтарын қысып ұстап тұрады. Бұл өзімшілдік емес, өз шекарасын қорғау. Бөлісуге мәжбүрлемей, кезек күтуді ойын арқылы үйретіңіз.'),
  ('0a13d571-0f47-4b38-ba09-6279a4e6c3b5', 'Қараңғылыққа шақыру 🌙', 'Жатын бөлмедегі жарық сөнгенде мазасыздана ма? Бөлменің бір бұрышына жылы түсті шағын түнгі шам қойыңыз. Ал бөлменің қалған бөлігі терең ұйқы үшін толықтай қараңғы болуы керек.'),
  ('f1a7ace3-b71a-47a5-8150-e29d91b1d2f6', 'Ана шаршағанда 🛑', 'Сіз робот емессіз. Егер бүгін тамақ пісіруге күшіңіз болмаса, дайын асқа тапсырыс беріңіз немесе жай ғана макарон қайнатыңыз. Мінсіз ана болу — бәрін жалғыз істеу деген сөз емес. Өзіңізге демалуға рұқсат беріңіз.'),
  ('012a4a46-c01f-4202-b7ec-b6dfb922b323', 'Тізімдегі тосынсый 🛒', 'Дүкенге бармас бұрын Сатып алу тізімін аштыңыз, ал артыңыздан келген бөпеңіздің телефон экранын басып, тізімге әлденелерді шимайлап қойғанын көрдіңіз. Иә, ол Сіздің цифрлық өміріңізді де қайталайды!'),
  ('0f7001d8-21ca-493f-95e3-7b29b5f52d2b', 'Көңіл күй күнделігіндегі сыр 📝', 'Телефонды қолыңызға алыңыз. Әлеуметтік желіде басқалардың өмірін парақтаудың орнына, Көңіл күй күнделігін ашып, оның бүгін жасаған ең күлкілі қылығын болашаққа естелік ретінде жазып қойыңыз. Цифрлық терапия көмектеседі.'),
  ('507a4882-997e-48f9-8d0c-a6ff5f18c3ac', 'Заңгерше келіссөз жүргізу 🗣️', '«Тағы 5 минут ойнайын, сосын киінемін», — дей ме? Ол Сізбен кәсіби деңгейде келісім жасауға тырысып жүр. Сөйлеу қабілетінің дамуы керемет, бірақ өз шекараларыңыз бен ережелеріңізді сүйіспеншілікпен сақтауды ұмытпаңыз.'),
  ('982b6e37-c6cb-46f9-bd93-9fafd76bcda8', 'Тыныштық сағаты 🥱', 'Күндіз ұйықтағысы келмей, жылай ма? Мәжбүрлемеңіз. Бөлменің жарығын бәсеңдетіп, «Кітапты үнсіз парақтау сағатын» жариялаңыз. Осылайша екеуіңізге де тынығуға көмектесетін жаңа әдет қалыптастырыңыз.'),
  ('dd274cad-cc38-4230-a074-0f529d065804', 'Бүгін мұны жемеймін 🥣', 'Кеше сүйсініп жеген сорпасын бүгін аузына да алмайды. Тісіне қатысты мәселе болмаса, бұл жай ғана Сіздің табандылығыңызды сынау. Тамақтану жоспарынан дәл сол дәрумендерді беретін басқа балама рецептілерді қарап көріңіз.'),
  ('ef5d3cbd-0aa0-493b-94cf-cb55ec5a7526', 'Әкесінің қызық дыбыстары 🤡', 'Сіздің айла-тәсілдеріңіз көмектеспей қалғанда, әкесінің қызық дыбыстары мен күлкілі қимылдары жағдайды бірден құтқарады. Кешкі мазасыздық кезінде кезекті бірден оған беріп, өзіңіз тынығып отырып тамашалаңыз.'),
  ('805b4060-d925-4469-abb9-000b87b286a1', 'Табиғат жұмбағы 🍁', 'Үйдегі бірсарынды жағдай екеуіңізді де жалықтырды ма? Саябаққа барып, пішіні ең ерекше тасты табу тапсырмасын орындаңыздар. Табиғат — ол үшін ең үлкен зертхана әрі барлық күйзелісті басатын тамаша орта.'),
  ('88ec7e91-36e6-4aab-9210-fc0f8e69cab3', 'Үстел басындағы қиялдағы қонақтар ☕', 'Бос кесені Сізге ұсынып, «Шай іш» дейді әрі бөлмеде жоқ досымен сөйлесе ме? Бұл — қиял дамуының нағыз жауһары. Бөлменің бір бұрышында өтіп жатқан бұл көріністі бұзбаңыз, Сіз де сол шайды ішіңіз.'),
  ('9c237165-d4a6-41d4-ba0a-333830a89409', 'Ақылды ертегідегі мен 🪄', 'Классикалық кітаптарды жатқа білесіз. Ақылды ертегілерді ашып, басты кейіпкер етіп балаңызды, ал бағындыратын мекен етіп оның бөлмесін таңдаңыз да, ұйықтар алдындағы ерекше ертегі сәтін ұйымдастырыңыз.'),
  ('62114884-cb2a-44c8-ab0b-33ab815b8e09', 'Ваннадағы бейбіт келісім 🛀', 'Сумен ойнау соншалық қызық болғандықтан, саусақтары бүрісіп қалса да, ваннадан шыққысы келмейді. Оған 5 минут бұрын ескертіп, таймерді орнатыңыз. «Қоңырау соғылғанда шығамыз» деген ереже көбіне көмектеседі.'),
  ('9f52c47e-5431-4d83-b54d-9c8d7cbf5228', '«Қолымнан ұстама!» еркіндігі 🚶‍♂️', 'Көшеде қолыңыздан ұстаудан үзілді-кесілді бас тартып, еркін жүгіргісі келеді. Қауіпсіз жерлерде оған осындай еркіндік беріңіз. Көзден таса қылмай, әлемді өз қадамдарымен танып-білуіне мүмкіндік беріңіз.'),
  ('d319859d-6f77-4ec4-b4f9-90c9441fac9e', 'Даму іздері 📈', '3 жасында оның қимыл-қозғалысы, сөздік қоры мен эмоциялық интеллекті қарқынды дамиды. Оның кішкентай жаңалықтарын ұмытпау үшін Даму трекеріне үнемі жазып, мұрағаттап отырыңыз.'),
  ('01326cb0-274c-49ad-8b92-7ce1373a0568', 'Кешірім сұрап, қайтадан солай істеу 🧸', 'Біреуді ұрғаны немесе бір нәрсені сындырғаны үшін шын жүректен кешірім сұрап, 5 минуттан кейін дәл сол әрекетін қайталай ма? Ол әлі өз импульстерін басқара алмайды. Ережені сабырмен қайта-қайта түсіндіріңіз.'),
  ('1efb2536-bf55-4365-890d-581fbbac3193', 'Ішіңіздегіні бөлісу қажеттілігі 💬', 'Күрделі шешім қабылдауыңыз керек пе? (Балабақша, түбек, ұйқы). Anacan қауымдастығындағы тәжірибелі аналардың кеңестері — ешбір кітапта жазылмаған, өмірден алынған ең шынайы шешімдер.'),
  ('d2d2c46d-7705-4c59-b1ff-a6a3d0986863', 'Ертегінің соңын өзі жазсын 🪄', 'Классикалық кітаптардан екеуіңіз де жалықтыңыздар. Бұл жолы Ақылды ертегілерде оқиғаның соңын балаңызға таңдауға мүмкіндік беріңіз. «Қалай ойлайсың, кейіпкерге кім көмектесті?» деп сұрап, ұйықтар алдында оның қиялына ерік беріңіз.'),
  ('37e65e72-e2dc-4492-b8ea-92aeab4db745', 'Дені сау ана, дені сау бала 🥑', 'Күнделікті қарбаласта түскі асты жүріп-жүріп ішпеңіз. Отырып, асықпай, темір мен кальцийге бай ерекше салат дайындап, рақаттанып жеңіз. Сіздің энергияңыз — осы үйдің қозғалтқышы, оны сақтаңыз.'),
  ('9a78401e-398c-45fd-a3a7-dae1cd59ed31', 'Тыныштықтың дәлелі 🤫', 'Шулы күннен кейін бала ұйықтағанда, Дыбыс өлшегішпен бөлмедегі тыныштық деңгейін өлшеңіз. Нөлге жақындаған сандарды көрудің өзі ананың миына ең жақсы визуалды массаждай әсер етеді.'),
  ('ba7f66f9-da13-4eea-9e4a-a968d14f269b', 'Ас дайындауға араласу 🧑‍🍳', 'Сіз қамыр жайып жатқанда, ол міндетті түрде жаныңызға орындық қойып, іске араласады. Оған өзінің пластик ыдысына ұн салуға рұқсат етіңіз. Асүй шашылады, бірақ оның байсалды, іскер кейпі кейінгі тазалыққа әбден тұрарлық.'),
  ('06f0acb2-a541-42e5-8b33-ed2285d3285f', 'Бір-біріңізге алғыс айту 🥂', 'Қиын күнді артта қалдырдыңыздар. Бала ұйықтағаннан кейін серігіңізбен бірге шай құйып, «Осындай аласапыран күні маған көп көмектестің» деп алғыс айтыңыз. Командалық рух осылай қалыптасады.'),
  ('354da7a1-73e7-4191-ab3d-5f7d75ac4224', 'Уақыт түсінігі қалыптасып келеді ⏱️', '«Ертең», «кеше», «кейін» деген сөздерді жиі, бірақ кейде орынсыз қолдана ма? Демек, уақытты қабылдауы қалыптасып келеді! Оның бұл талпыныстарын жымиып тыңдаңыз.'),
  ('8b9fda41-95cb-4937-8a79-67166a02c4b7', 'Анаға арналған үзіліс ☕', 'Балаңыз өз бетімен ойнап отырғанда, бірден үй шаруасына кірісіп кетпеңіз. Бөлмедегі шашылған заттар ешқайда қашпайды, ал Сіздің күшіңіз таусылуы мүмкін. Отырып, ыстық кофеңізді ішіңіз.'),
  ('c1a7e066-6918-4641-ab6d-c5c20c553974', 'Кереуеттен қашу жоспары 🛌', 'Кереуетінен өрмелеп шығуға тырыса ма? Қауіпсіздік үшін бөлмені қайта тексеріп шығыңыз. Үлкен балаларға арналған кереуетке ауысатын уақыт жақындап қалды.'),
  ('46401ae3-aa9a-4ec9-afa2-b6cab38572ff', 'Қиялдағы оқиғалар 🧸', 'Ойыншықтарын тамақтандырып, емдей ме? Символдық ойындар — эмпатияның негізі. Даму трекеріне осы танымдық серпілісті мақтанышпен белгілеңіз.'),
  ('4cba464d-475d-46de-93c9-1a54b6d0a768', 'Сиқырлы түнгі көрініс 🪄', 'Ұйықтауы қиын ба? Ақылды ертегілерде тісін тазалайтын батыр қонжық туралы оқиға құрып, жаңа әдеттерді ертегіге айналдырыңыз.'),
  ('7ef518fa-cecf-4467-bd34-eb7fb3a21761', 'Саябақтағы қарым-қатынас 🌳', 'Басқа балалармен бірге ойнағаннан гөрі, олардың жанында өз ойынын ойнай ма? Қатар ойнау бұл жас үшін мүлде қалыпты. Оған қысым жасамай, әлеуметтенуіне қолдау көрсетіңіз.'),
  ('85dcc8b6-3ff2-43d3-9d96-7c1edd51dcff', 'Брокколи детективі 🥦', 'Сорпаның ішіндегі жалғыз жасыл көкөністі тауып алып, тамақтан бас тарта ма? Тамақтану жоспарынан көкөністерді түрлі түсті макаронмен араластырып, назарын басқаға аударудың және пайдалы тағамдарды байқатпай ұсынудың ең дәмді тәсілдерін табыңыз.'),
  ('9d17ee0d-df59-4f5d-b9e7-c0b06e40eb21', 'Сезімдерді мойындау 📝', 'Күні бойы бәріне «жоқ» дей бергеніңіз үшін өзіңізді кінәлі сезінесіз бе? Көңіл күй күнделігін ашыңыз. Бүгін ішіңіздегі ең қараңғы «жалғыз болсам ғой» деген ойды еш сүзгісіз жазыңыз. Өзіңізді кінәламаңыз: әр ана кейде шаршап, бәрінен қашып кеткісі келеді.'),
  ('4217bad1-d028-470b-a2a2-ceacb5b15105', 'Жасанды интеллект, шынайы жауап 🤖', '3 жас дағдарысының ғылыми және педиатрлар растаған себептері қандай? Интернеттегі қорқынышты пікірлерді оқығанша, Anacan AI-дан баланың психологиясы туралы нақты әрі кәсіби талдауды бірден сұраңыз.'),
  ('50050f6d-75e8-48b1-9632-bcebb31ce6fa', 'Сенсорлық шамадан тыс жүктеме 🔋', 'Күні бойы үстіңізге өрмелеп, шашыңызды тартып, шулады. Жүйке жүйеңіз дабыл қағып тұр. Жанасудан шаршау — әбден шынайы құбылыс. Баланы жұбайыңызға беріп, бөлмеге барып тынығыңыз.'),
  ('0efdad7b-f986-4a21-8e04-fc9cffca1b7d', 'Қызық айтылатын сөздер 🗣️', 'Сөздерді қызық әрі өзіне ғана тән мәнермен айтатыны сонша, күлмеу мүмкін емес. Оған күліп, айтқанын түзетпеңіз. Оның орнына мұқият тыңдап, сөйлемнің дұрыс нұсқасын жай ғана қайталап жауап беріңіз.'),
  ('6d1f309e-d64f-4916-a1e2-48f064024563', 'Дүкендегі ұмытшақтық машақаты 🛒', 'Жадыңызға сеніп дүкенге барып, баланың жөргегін ұмытып қайттыңыз ба? Ондай да болады. Барлық қажетті затты бірден Сатып алу тізіміне жазуды әдетке айналдырыңыз — цифрлық жадыңыз көмекке келсін.'),
  ('b478188b-090e-49fa-8067-44d7985fc9d2', 'Сезімдеріңізді қағазға түсіріңіз 📝', 'Қатты шаршағаныңызды ешкім байқамай жүр ме? Көңіл күй күнделігі Сізді тыңдауға әрқашан дайын. Бүгін жүйкеңізге тиген барлық ұсақ-түйекті сол жерге жазып, ойыңызды тазартыңыз.'),
  ('51755ad7-f4a2-46b5-9170-1977fdac0046', 'Ұйқы гормонына қолайлы жағдай 🌙', 'Тезірек ұйықтауы үшін жатардан 1 сағат бұрын бөлмедегі барлық қосымша жарықты өшіріп, планшет экрандарын сөндіріңіз. Ұйқы гормоны тек қараңғы әрі технологиясыз ортада бөлінеді.'),
  ('556d15ad-f396-4daf-9a38-c5bd773f19f0', 'Саябақтағы еркіндік 🌳', 'Төрт қабырға оны ашушаң етеді. Ауа райы және киім көмекшісі арқылы даладағы желге барынша сай киім үйлесімін таңдап, саябаққа шығыңыз. Құмға аунасын, жүгіріп жүріп құласын. Еркіндік — оның дамуына ең жақсы ем.'),
  ('b2f0448e-4bda-4f45-8af5-d1f543150cda', 'Күтпеген құшақ 💖', 'Бөлменің ортасында ойнап отырып, кенет Сізге қарайды да, жүгіріп келіп мойныңыздан құшақтайды. Барлық ұйқысыз түн мен шаршауға тұрарлық сәт! Осы сәт сыйлаған терең әрі ерекше тыныштықтан ләззат алыңыз.'),
  ('ece2fe16-c57e-4a1f-a594-5e39da1118d6', 'Қауымдастықтағы сырласу 💬', 'Сіз қатты шаршадыңыз әрі ешкімге ештеңе түсіндіргіңіз келмейді. Anacan қауымдастығына кіріп, тек оқырман болыңыз. Басқа аналардың да дәл осылай шаршайтынын және балаларының күлкілі дағдарыстарын көргенде, «мен жалғыз емеспін» деген сезім пайда болады. Бұл — жанға жай беретін ең жақсы демеу.'),
  ('fabbf657-c431-4c98-ba31-613ca3dc8a47', 'Асүйдегі кішкентай аспаз 🧑‍🍳', 'Сіз қамыр жайып жатқанда, ол міндетті түрде жаныңызға орындық қойып, іске араласады. Оған жеке пластик ыдыс беріп, ішіне ұн салуға рұқсат етіңіз. Асүй шашылып қалуы мүмкін, бірақ оның байсалды, іскер кейпі мен «менің де қолымнан келеді» деген сезімі кейінгі тазалыққа әбден тұрарлық.'),
  ('7e88dfb0-8648-40c5-a6ab-3a3cf4987fb3', 'Киімді теріс кисе де, мақтаныш 🧦', 'Шұлығының өкшесі аяғының үстіне келіп тұр, бірақ өзі кигендіктен, мақтанышпен жүр. Еш араласпаңыз. Оның «менің қолымнан келді» деген сезімі әдемі немесе дұрыс киінуден миллион есе маңызды психологиялық негіз қалыптастырады. Осы күйінде күні бойы жүре берсін.'),
  ('ca2fd133-6b0b-4852-a4b2-b830a12f0bc0', 'Анаға арналған офлайн минуттар ☕', 'Ол өз бетінше пазл құрастырып, 10 минуттан бері тыныш отыр. Ал Сіз сол уақытты үй жинауға жұмсағыңыз келеді. Жоқ! Барып, диванға жатыңыз. Кешке дейін осы қарқынға шыдау үшін Сіздің де қуатыңыз толуы керек.'),
  ('e264b682-e7a9-4579-80a1-6e47fe7bccb3', 'Қараңғылықпен достасу 🐰', 'Ұйықтағысы келмей, бөлмедегі көлеңкелерден қорқатынын айта ма? Бөлмені толық қараңғылап, қолдарыңызбен қабырғаға құс пен иттің көлеңкесін түсіріңіз. Қорқынышты ойынға айналдырып, оның қараңғылықпен достасуына және қиялын басқаруына көмектесіңіз.'),
  ('03f9e2c0-9e7a-47b1-892e-0261f73bfa13', 'Жасанды интеллект және алаңдаушылық 🤖', 'Балаңыздың кейбір әріптерді әлі де дұрыс айта алмауы Сізді алаңдата ма? Интернеттегі үрей туғызатын форумдарды жабыңыз. Anacan AI-дан 38 ай шамасындағы сөйлеу дамуының қалыпты көрсеткіштері туралы сұрап, ғылыми әрі шынайы жауап алыңыз.'),
  ('8c0fa05b-b55a-47a2-b4af-b9fb41bdabf9', 'Сен бала бол, мен ана болайын 👩‍👧', 'Рөл алмасу ойыны басталды! Ол Сізге «мұнда кел», «тамағыңды же», «жылама» деп нұсқау береді. Оның көшбасшы болу тәжірибесін қуана қабылдап, үндеместен баласының рөлін ойнаңыз. Бұл — эмпатияны дамытудың ең негізгі жолдарының бірі.'),
  ('b97073a4-f745-41b1-953a-0e776ded1591', 'Жарықты өшірсеңіз, ұйқы келеді 🌙', 'Тезірек ұйықтауы үшін ұйықтардан 1 сағат бұрын бөлмедегі барлық қосымша жарықты және планшет экрандарын өшіріңіз. Мелатонин қараңғы әрі технологиялық құрылғылар жоқ ортада ғана жылдам бөлінеді.'),
  ('df69592f-4c0f-4591-8df6-51164eef4e12', 'Бұл менің кінәм емес! 🤷‍♂️', 'Суды әдейі еденге төкті, бірақ кінәні үстелге артып: «Үстел сырғып кетті», — деді. Бұл өтірік емес, баланың жауапкершіліктен жалтарып, өзін қорғауға тырысатын табиғи инстинкті. Қырсықпаңыз, «Кел, үстелге көмектесіп, бірге сүртейік», — деп, көңіліне тимей жауапкершілікке үйретіңіз.'),
  ('7ac03452-73e8-4680-9a3a-f2917f96ee7f', 'Төрт қабырға психологиясы ⛅', 'Үйде отыру Сізді қажытады, ал бала ашушаң бола бастайды. Ауа райын тексеріп, лайықты киім таңдаңыз да, үйден шығып, саябаққа асығыңыз. Таза ауа мен еркін қимылдау оның миына да, Сіздің шаршаған жүйкеңізге де ең жақсы детокс болады.'),
  ('ab102c70-f16b-4f7f-8521-b11e20c36d7a', 'Киім бүктеу операциясы 🧺', 'Сіз таза киімдерді бар ынтаңызбен бүктеп отырсыз, ал ол 2 секундтың ішінде арасына кіріп, бәрін шашып тастайды. Бөлмеде терең тыныштық орнайды... Жүйкеңіз әбден жұқарды ма? Терең тыныс алыңыз. Шашылған киімдердің үстіне өзіңізді тастап, осы бейберекеттікке күле отырып беріле салыңыз.'),
  ('e3d6247b-8c6f-4322-9f82-93d3245cab38', 'Ақылды ертегінің режиссері 🪄', 'Классикалық кітаптардағы кейіпкерлерден екеуіңіз де жалықтыңыздар. Ақылды ертегілерді ашып, бүгін кешке оқиғаны оның өзі ойлап табуына мүмкіндік беріңіз. «Енді мына ұшатын динозавр қайда барсын?» — деп сұраңыз да, өзі қиялдаған әлемде ұйықтап кетуіне жағдай жасаңыз.'),
  ('62178f50-5d62-4afb-bacf-33c6e7bf5732', 'Әкенің ұшу режимі ✈️', 'Үйде энергиясын шығара алмай, төсекке жатпау үшін мың түрлі сылтау ойлап табады. Әкесін шақырыңыз. Ол баланы әуеге көтеріп, ұшақ болып ұшырғанда, бөлме сыңғырлаған күлкіге толып, жиналған бүкіл физикалық ширығу термен бірге жоғалады.'),
  ('7338bae4-7d68-4f02-8b9f-7e3603f62bb9', '«Сен жаман анасың!» деген соққы 💔', 'Қалаған ойыншығын алып бермегеніңіз үшін бетіңізге қарап: «Сен жамансың», — деді ме? Жүрегіңізге жақын қабылдамаңыз. Ол әлі сезімдерін дұрыс сөздермен жеткізе алмайды, шын мәнінде: «Мен қатты ашулымын әрі көңілім қалды», — дегісі келеді. Көзіне қарап, оның сезімін түсінетініңізді білдірсеңіз жеткілікті.'),
  ('c4d16b0b-f2b1-40f5-8462-8e7c3419883e', 'Дүкендегі «Арбаны өзім итеремін» деген қырсықтық 🛒', 'Дүкен арбасын өзі итергісі келіп, сөрелерге соғылып, жұрттың назарын аударады. Араласқан сайын жылайды. Арбаны бірге итеріңіздер. Ал ештеңені ұмытпау үшін қолданбадағы «Сатып алу тізімін» белсенді ұстаңыз, сонда миыңыз азырақ шаршайды.'),
  ('159b5a7f-d190-47d4-8cda-ba692f07b0d0', 'Дыбыс өлшегіштегі тыныштық 🤫', 'Ол ақыры ұйықтап қалды! Үйді жайлаған тыныштықтың тереңдігі сонша, құлағыңыз шыңылдайды. Дыбыс өлшегішті іске қосып, экрандағы 0-10 децибел көрсеткішіне қараңыз да, миыңыздың біртіндеп қалай қалпына келіп жатқанын көзбен сезініңіз.'),
  ('66da20be-59e4-4c6a-b44a-168bd86bf8c2', 'Айна алдындағы театр 🎭', 'Таңертең айна алдына тұрып, жылау, күлу, таңғалу сияқты түрлі мимикаларды жаттықтырады. Ол өз эмоцияларын қалай білдіруге болатынын және бет әлпетінің қалай өзгеретінін зерттеп жүр. Осы ғажайып актерлік өнерін алыстан жымиып тамашалаңыз.'),
  ('69d26c82-f68d-4fca-acec-f2cabf4901f8', 'Әкенің сиқырлы құшағы 🫂', 'Күні бойы көтеріп, қолдарыңыз талса да, ол әлі де құшаққа сұранады. Әкесін шақырыңыз. Әкесінің қолында «ұшу» баланың назарға деген қажеттілігін өтеп қана қоймай, Сіздің қолдарыңызға да көптен күткен демалыс сыйлайды.'),
  ('b233c7da-a3d8-4dbb-a50a-7267ec7bfbc6', 'Қоқыс емес, өнер 🎨', 'Ол бөлменің ортасында ұсақ қағаз қиындылары мен кесілген жіптерден үлкен өнер туындысын жасап, оны тастауға рұқсат бермей тұр. Тазалыққа деген тым қатал талабыңызды бір сәтке қоя тұрыңыз. Ол жасаған бейберекеттікке құрметпен қараңыз, жинауды ертеңге де қалдыруға болады.'),
  ('3613ef28-90fe-4c93-a13a-cc4ded2b5ad4', '«Өзім істеймін!» деген қарсылық 🛑', 'Ол аяқкиімінің бауын өзі байлағысы келеді, ал Сіз үйден шығуға 10 минутқа кешігіп жатырсыз. Асықтырмаңыз. Даму үшін кестенің сәл бұзылғанынан гөрі, оның өзіне деген сенімінің сақталғаны маңыздырақ. Өзі жасап көруіне мүмкіндік беріңіз.'),
  ('67736a86-09e4-4211-ade6-1d5d48e8a05f', 'Сыбырлап айтылған оқиғалар 🌙', 'Бүгін көп сөйлеп, даусыңыз да, өкпеңіз де шаршады. Жарықты өшіріп, жанына жатыңыз да, күні бойы болған оқиғаларды құлағына жай ғана сыбырлап айтып беріңіз. Сыбыр оның назарын шоғырландырып, миын гипнозға ұқсас әсермен терең ұйқыға дайындайды.'),
  ('8d9fad31-a8cd-481f-953a-35d411108040', 'Мінсіз ана туралы мифтер 🛑', 'Әлеуметтік желідегі балалар түстерді де біледі, сандарды да ағылшынша санайды, ал Сіздің балаңыз мұны қаламай ма? Салыстыруды дереу тоқтатыңыз! Әр баланың даму қарқыны бірегей әрі өзгеше. Ол өз қарқынымен дамып келеді және дәл сол қалпында мінсіз.'),
  ('4c7e076f-90de-4c2c-ae58-d9d897931fd4', 'Күндізгі ұйқы аяқталды ма? ⏱️', 'Кешке ұйықтап кетуіне 1 сағаттан артық уақыт кете ме? Ұйқы кестесіне назар аударыңыз. 3 жас кезеңіндегі өзгерістер кезінде күндізгі ұйқыдан толық бас тартып, кешкі ұйқы уақытын ертерек жылжытатын кез келген болуы мүмкін.'),
  ('b52dda4e-86c5-4200-973f-b7fbeb8869cc', 'Таусылмайтын «Неге?» сұрақтары 🌪️', '«Балықтар неге жүрмейді?», «Күн қайда кетті?» Таңертеңнен бастап оның миы сағатына 100 сұрақ жылдамдығымен дүниенің сырын іздейді. Шаршасаңыз да, оған қысқа әрі қисынды жауап беріңіз. Ол ғаламның құпияларын Сіздің дауыс ырғағыңыз арқылы танып-біледі.'),
  ('c583d30d-5142-4b40-bcb3-399830284928', 'Ластануға толық рұқсат 🏖️', 'Балшықпен, құммен ойнағысы келе ме? Ластана берсін! Сенсорлық дамуды қолдайтын мұндай ойындарға қажет, оңай тазаланатын құралдарды Ұсынылатын өнімдерден тауып, бөпеңізге еркіндік беріңіз.'),
  ('0446eb50-5fac-4056-ad65-76a95baf67f3', 'Көлеңкемен күрес 👻', 'Қабырғадағы көлеңкесінен қорқып, Сіздің артыңызға тығыла ма? Баланың қиялында шек жоқ. Бөлмені қараңғылап, қолшамның көмегімен қабырғада қолдарыңызбен көлеңке театрын жасаңыз.'),
  ('b090e002-92d1-408a-8249-476d9566115b', 'Әуенмен ұйқыға дайындалу 🎶', 'Кешкісін себепсіз басталатын мазасыздықты баяу классикалық музыкамен басып көріңіз. Көбіне осы қарапайым әрі тиімді әдіс үйде нағыз ғажайып жасап, бөлмеге тыныштық пен жайлылық сыйлайды.'),
  ('ba177a78-642c-483b-9a15-4d4a68a758af', 'Дененің дабылы 🩸', 'Себепсіз ашушаңдық пен шаршауға бой алдырмаңыз. Етеккір күнтізбесіне қараңыз — денеңіз белгі беріп тұр. Өзіңізді кінәлаудың орнына магнийге бай тіскебасар жеп, демалыңыз.'),
  ('1a2422fa-5d4e-4bbc-9f26-d69dd838496d', 'Сөздерді әдейі өзгерту 🗣️', '«Көлік» деудің орнына қасақана «ліккө» деп, Сіздің күлгеніңізді күте ме? Ол әзілдің не екенін түсіне бастады. Күліңіз, бірақ миы дұрыс нұсқаны да есте сақтауы үшін әр жолы сөздің дұрыс айтылуын жайлап қайталауды ұмытпаңыз.'),
  ('21b5ead3-32a1-4d0e-96a9-1e38bf19fcec', 'Анашым, өзіңіз де тамақтаныңыз 🥗', 'Оны тамақтандыру үшін жұмыртқаны 4 түрлі әдіспен пісірдіңіз, ал өзіңіз не жедіңіз? Пайдалы рецептілерден 5 минутта дайын болатын, темір мен кальцийге бай арнайы ас әзірлеп, өзіңізді қуантыңыз әрі күш-қуатыңызды сақтаңыз.'),
  ('cc6b3853-5963-47b7-b4f5-310bfd1919c2', 'Ұйқыны кейінге қалдыру айласы ⏱️', 'Ұйықтайтын уақыт келгенде кенеттен су сұрап, дәретханаға барғысы келе ме немесе қабырғамен қоштаса бастай ма? Таймер орнатыңыз. «Қоңырау соғылғанда, бәрі ұйықтайды» деген ережені енгізіп, осы бітпейтін қоштасудан сабырмен әрі байсалды түрде арылыңыз.'),
  ('629ea652-62bd-4947-96b6-0e7f4cabb751', 'Ойыншықтармен жиналыс 🧸', 'Барлық қонжықтары мен көліктерін қатарға тізіп, оларға саусағын шошайтып, әлденені өте байыппен түсіндіріп жүр ме? Оның көшбасшылық қабілеті мен зейіні қалыптасып келеді. Бөлменің бір шетінде тұрып, осы қиялдағы жиналысты бөпеңізге кедергі келтірмей, үнсіз бақылаңыз.'),
  ('2fc82c8d-f425-4306-866a-3f621177b592', 'Мультфильм сыншысы 📺', 'Көрген мультфильмін Сізге өзінше әңгімелеп, кімнің қайда барғанын байыппен түсіндіреді. Оны мұқият әрі таңғалғандай тыңдаңыз. Өзін әлемдегі ең ақылды баладай сезінуіне мүмкіндік беріңіз.'),
  ('63daef22-cfd1-421f-8f7d-267873d17f9e', 'Мінсіздік болмайды 🛑', 'Бүгін бәрі жоспардан тыс кетті ме? Өзіңізді кінәламаңыз. Сіз әлеуметтік желідегі сүзгіден өткен жалған бейне емес, шынайы анасыз. Балаңызға тек Сіздің күлкіңіз бен құшағыңыз қажет.'),
  ('e3cb9a40-b6ca-4e32-b4da-ab6d4899625b', 'Түнгі қорқыныштың құпиясы 😭', 'Түн ортасында көзі жұмулы күйде жылап оянып, ешкімді естімей ме? Жылау талдауы арқылы анықтап көріңіз; егер бұл түнгі қорқыныш болса, оны оятуға тырыспаңыз. Тек жанында болып, үнсіз қауіпсіздік сезімін сыйлаңыз.'),
  ('10d94f4d-5823-4afc-963c-ff0397bf1a29', 'Тек құшақтаңыз 🫂', 'Ешқандай ойынның, кітаптың немесе ертегінің қажеті жоқ. Бүгін кешке оны жай ғана бауырыңызға басып, жұпар иісін құшырлана иіскеңіз де, қараңғыда оның қаншалықты қымбат екенін сыбырлап айтыңыз.'),
  ('3860d960-f463-4c1e-873a-4917b9b7c101', 'Тыйым салынған сөздер 🤐', 'Бір жерден естіген жаман сөзді күліп қайталап, Сіздің реакцияңызды күтіп жүр ме? Ең мықты қаруыңыз — еш реакция білдірмеу. Күлмеңіз де, ашуланбаңыз да, жай ғана елемеңіз. Ол бұл сөзді көп ұзамай ұмытады.'),
  ('fbd7d1b9-4e13-463d-80fa-fbbd34869d9e', 'Үйді жинамауға рұқсат 🌪️', 'Күн сайын бір ойыншықтарды қайта-қайта жинаудан шаршадыңыз ба? Бүгін жинамаңыз! Үй — мұражай емес, тіршілік қайнап жатқан мекен. Шашылған заттарға емес, балаңыздың еркін танып-білу қуанышына назар аударып, демалыңыз.'),
  ('267500b1-a84b-4046-a247-9d2097325550', 'Төменге қараңызшы, ол нені зерттеп жүр? 👣', 'Ол жалаңаяқ жүріп, кілемді немесе бөлмедегі тас еденді аяғымен сезінгенді ұнатады. Табандағы жүйке ұштарының белсенді болуы оның тепе-теңдігі мен қимыл-қозғалысының дамуы үшін өте маңызды, сондықтан шұлықсыз жүруіне рұқсат етіңіз.'),
  ('2b6e6b05-f741-49ca-84e3-fa8deb8b2661', 'Екеуіңізге арналған үзіліс 🥂', 'Бала ұйықтады. Енді үй шаруасын қоя тұрыңыз. Жұбыңызбен кемінде 20 минут бала мен шығындардан басқа кез келген тақырыпта әңгімелесіңіз. Сіздер ата-ана ғана емес, жұп та екендеріңізді ұмытпаңыздар!'),
  ('8fdbd74e-0b03-4420-a816-6a0ea6ecdb73', 'Әкенің оғаш дыбыстары 🤡', 'Сіздің барлық амалыңыз таусылғанда, әкенің жануарларға еліктеп шығаратын оғаш дыбыстары мен күлкілі қимылдары жағдайды бірден құтқарады. Кешкі мазасыздық кезінде кезекті оған беріп, көңілді күлкіні сырттай тамашалаңыз.'),
  ('b32c30b6-11a0-4afc-aed3-bdfb0cc56622', 'Күндізгі ұйқыға қарсылық 🥱', 'Төсекке жатқысы келмей, жылай ма? Мәжбүрлемеңіз. Бөлмедегі жарықты бәсеңдетіп, тыныш кітап қарау уақытын жариялаңыз. Осылайша екеуіңізге де демалуға мүмкіндік беретін жаңа әдет қалыптастырасыз.'),
  ('07209316-984c-477d-a3c0-ff2c7202c5fa', 'Балабақша туралы ойлар 🏫', 'Оған енді көбірек араласу қажет екенін сезіп жүрсіз бе? Балабақшаға баратын уақыт келді ме? Anacan қауымдастығына қосылып, басқа аналардың бейімделу туралы шынайы тәжірибесін оқыңыз — бұл шешім қабылдауды жеңілдетеді.'),
  ('3f7992d5-c092-46f7-84f8-f10e51f36593', 'Кенеттен ашулану ұстамасы 💥', 'Ойнап отырып, кенет ашуланып, ойыншықтарын лақтырып жіберді ме? Ол әлі эмоцияларын басқара алмайды. Айқайлаудың орнына: «Ашуланып тұрғаныңды көріп тұрмын, кел, бірге терең тыныс алайық», — деп жанашырлық танытып, жанында болыңыз.'),
  ('a376f906-e66c-4618-827e-79f3b75ebd16', 'Жатын бөлмеде жарық сөнгенде мазасыздана ма? 🌙', 'Бөлменің бір бұрышына жылы түсті шағын түнгі шам қойыңыз. Ал бөлменің қалған бөлігі терең ұйқы үшін толықтай қараңғы болып қалуы керек.'),
  ('171bedf4-3516-44a5-9404-c089661d5bbd', 'Жансыз заттармен әңгімелесу 🗣️', 'Саябақтағы тасқа немесе үйдегі орындыққа бар ынтасымен бірдеңе айтып, тіпті оларға ұрса ма? Символдық ойындар арқылы ол қоршаған ортаны танып, түсініп жүр. Оның осындай ерекше ойын желілерін Даму бақылағышында міндетті түрде белгілеңіз.'),
  ('a74f3aea-565f-455f-bdbe-9ee44f6c7e35', 'Жылы судың кереметі 🛀', 'Кейде ешбір амал көмектеспей, ол бәріне жылай береді. Оны жылы су толтырылған ваннаға отырғызып, аздап көбік қосыңыз. Судың сол бір тылсым, ширығуды басатын күші бүкіл бөлмеге де, оның жүйке жүйесіне де бірден тыныштық сыйлайды.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_kk = v.t, body_kk = v.b
FROM (VALUES
  ('b4c6b7ac-81bd-476f-9816-9e8c14627206'::uuid, 'Ауа райы туралы ескерту ⛅', 'Серуенге шығарда терезеден қарап қана шешім қабылдамаңыз. Ауа райы және киім көмекшісі арқылы сырттағы жел мен нақты температураға сай киім жиынтығын таңдап, үйден қамданып әрі алаңсыз шығыңыз. Балаға таза ауада бойындағы энергиясын шығаруға мүмкіндік беріңіз.'),
  ('9d8da9d6-f615-4275-a01c-20687a161090', 'Дүкендегі көмекшіңіз 🛒', 'Дүкенге барғанда ең қажетті затты үнемі ұмытып кетесіз бе? Сатып алу тізімі қолданбада Сізді күтіп тұр. Қажет заттарды сонда жазып қойыңыз, жұбайыңыз жұмыстан қайтарда бәрін тізім бойынша алып келсін, ал Сіз бас қатырмаңыз.'),
  ('2b451101-7b49-4ea1-a25f-f07ea36f7e85', 'Күнделікке ішіңіздегіні төгіңіз 📝', 'Біреу Сізге «Үйде отырсаң да, несіне шаршайсың?» деді ме? Дереу «Көңіл күй күнделігін» ашып, бар ашуыңызды саусақтарыңызбен экранға төгіңіз. Жасанды күлімсірегеннен гөрі шынайы сезімдеріңізді жазу — нағыз терапия.'),
  ('5163d6f3-dfbf-4dc7-9c33-5c739a29b5c5', 'Саған түсіндіріп берейін! ☝️', 'Ол Сіз бұрыннан білетін нәрсені өте байсалды әрі ақылды кейіппен түсіндіреді. Осылайша өз білімін сынап жүр. Күлмеуге әрең шыдап тұрсаңыз да, оны мұқият тыңдап, ойын мақұлдаңыз.'),
  ('62a5480b-e62d-48dc-a56f-7c512e104949', 'Тыныштықтың цифрлық өлшемі 🤫', 'Ол ақыры ұйықтап қалды! Үй ішін жайлаған тыныштыққа сенер емессіз. Дыбыс өлшегішті қосып, экрандағы 0-10 децибел көрсеткішіне қарап, миыңыздың біртіндеп тынығып жатқанын сезініңіз.'),
  ('523ef85e-fa2f-49a1-b3f9-34f2d35d22a1', 'Ауа райын барлау ⛅', 'Сырттағы ауа райы түсініксіз бе? «Ауа райы және киім» құралы терезеден байқалмайтын желдің жылдамдығын көрсетіп, лайықты киім үйлесімін бірден ұсынсын.'),
  ('5b3dc48b-525e-45b8-ba47-dd1abb851741', 'Аяқ киімін өзі шешеді 👟', 'Киіндіру күрестің бір түріне айналды ма? Ол шұлығы мен аяқ киімін өзі тартып шешеді. Қимыл-қозғалыс дағдысына сүйсініңіз!'),
  ('cd7f1c0e-ee93-462d-ae3c-cb3021a5d6c8', 'Әкенің қолдауы 🫂', 'Түнде бөпе оянғанда бірде Сіз, бірде жұбайыңыз тұрыңыз. Жүктемені бір команда ретінде тең бөлісіңіздер.'),
  ('3522ca83-324c-49f9-ba7a-ffdc8c379ba2', 'Ұйқыға кедергі болатын дәретхана 🚽', 'Енді ұйықтай бергенде, кенеттен дәретханаға барғысы келетінін айтады. Апарасыз, бірақ ештеңе жоқ. Бұл — ұйықтау уақытын созудың ең айлакер тәсілі. Айқайламаңыз, «Соңғы рет барамыз да, бірден төсекке қайтамыз» деген шекараны анық белгілеңіз.'),
  ('676880bc-91f2-426e-9b15-e2ce61b68fc4', 'Төсек саяхатшысы 🛏️', 'Түнді өз төсегінде бастап, таңертең Сіздің төсегіңізде көлденеңінен жатып, аяғын бетіңізге қойып оянады. Оның кеңістікті осылай жаулап алуын күліп қабылдаңыз. Сіздің жылы иісіңіз — ол үшін ең қауіпсіз мекен.'),
  ('bf74dbb7-0eae-47bc-acea-2beeb831e679', 'Қораптың сиқыры 📦', 'Сіз сатып әперген қымбат әрі дыбысы қатты ойыншықты бір жаққа тастап, 1 сағат бойы оның қорабымен ойнап отыр ма? Баланың миы дайын сценарийлерді емес, қиялын еркін сыйғыза алатын бос заттарды ұнатады. Картон қорап ол үшін ғарыш кемесі, тиіспеңіз.'),
  ('42b797ef-b169-4515-ad62-c08b78bfdaca', 'Қыстағы жазғы бүлік ❄️', 'Далада жел соғып тұр, ал ол жазғы шортысын киемін деп қасарысады. Түсіндіруге уақыт жоғалтпаңыз. Ауа райы мен киім құралын ашып, экрандағы қалың киінген бала белгісін көрсетіңіз. «Міне, телефон да бүгін шалбар киюіміз керек деп тұр» деген айла керемет көмектеседі.'),
  ('74bf7168-d7dc-468c-87a3-562a3bef9f2a', 'Қиялдағы алманы тістеу 🍏', 'Қолында ештеңе жоқ болса да, Сізге жақындап, «Мә, тісте» деп қиялдағы алманы ұсынады. Рөлдік ойындар — баланың тұлғасы қалыптасатын ең маңызды орта. Бос тұрған жерді тәбетпен «қытыр» еткізіп тістеп, оның әлемдегі ең дәмді алма екенін растаңыз.'),
  ('d3d1367f-aa40-489c-9f91-b803403dff09', 'Терезедегі құбыжық 👻', 'Далада тербелген ағаштың көлеңкесі бөлмеге түсіп, ол қорқып, артыңызға тығылады. Бөлменің жарығын жақпаңыз. Қолыңызға шам алып, көлеңкеге бағыттаңыз да: «Қарашы, бұл жай ғана ағаштың биі», — деп, қорқынышты сиқырға айналдырыңыз.'),
  ('2297d6cd-94fd-4ed9-af73-4f9ce43ef7d6', '«Маған қара!» марафоны 👀', 'Таңертең ояна сала тура 40 рет «Анашым, маған қарашы» деді ме? Ол секіріп, айналып, Сіздің мақұлдауыңызды күтеді. Телефоннан көзіңізді алып, бар болғаны 3 минут бойы бар назарыңызды оған аударып, «Кереметсің!» деңіз. Осындай үздіксіз көңіл бөлу оның назарға деген қажеттілігін қанағаттандыруға жеткілікті.'),
  ('4e536027-0b7a-4ac3-acef-a7ba874bd609', 'Ананың жалқаулануға құқығы 🍕', 'Бүгін бәріне айқайлағыңыз келе ме? Үйдің астаң-кестеңі шықты ма? Үй жинауды қоя тұрып, асүйге кірмеңіз. Сырттан пицца немесе оңай бір тағамға тапсырыс беріңіз. Мінсіз ана болу елесін бұзыңыз: Сіздің психологиялық саулығыңыз үйде дайындалған тамақтан әлдеқайда маңызды.'),
  ('c57f5d91-caec-47eb-964d-abcee011e0e2', 'Жұптық кома 📺', 'Бала ұйықтап қалды! Ақыры жұбайыңызбен фильм көру үшін диванға жайғастыңыздар, бірақ 10 минуттан кейін екеуіңіз де ұйықтап қалдыңыздар. Бұл — Сіздің шынайы өміріңіз. Бір-біріңізге сүйеніп ұйықтап қалған сол шаршаңқы, бірақ сондай сүйкімді көрініс — махаббаттың өзі.'),
  ('c58d19cd-28c0-452e-ab4b-85c75da1f2b0', 'Алғашқы мағынасыз әзіл 🤡', '«Ит көлікке мінді де, жарылып кетті!» деп, өз сөзіне өзі қарқылдап күледі. Мұнда ешқандай мағына жоқ, бірақ ол әзіл әлемін енді ғана танып жатыр. Логика іздемеңіз, оның осы риясыз әрі көңілді күлкісіне Сіз де бар даусыңызбен қосылыңыз.'),
  ('0a22f56d-c8f3-477d-a3c0-1cf48a52b75f', 'Сырғанақ саясаты 🛝', 'Саябақта сырғанақтың төбесінде тұрып алып, басқа балалардың сырғанауына жол бермейді. Ұялып, оны күшпен төмен қарай тартпаңыз. Айналадағы адамдарға мән бермей, кезек сақтау керегін оған жай дауыспен еске салыңыз. Ол өзінің иелік сезімін осылай қорғайды.'),
  ('2e61e71c-40b9-4acb-82fb-ac9b3ee6a222', 'Ол енді бөпе емес! 🌟', 'Ол — өз шешімдері, қызық сұрақтары және үлкен жүрегі бар толыққанды тұлға. Оның қайсар мінезін жасытпай, дұрыс бағыт беріп өсіріп жатқаныңыз үшін өзіңізге үлкен алғыс айтыңыз. Сіз керемет жұмыс атқарып жүрсіз.'),
  ('a5162fa5-e190-42b6-b85c-5309ce76b381', 'Шампансыз жеңіс 🥂', 'Қиын күннен кейін стақандарға кәдімгі ыстық шай құйыңыз. Жұбайыңызбен диванда бір-біріңізге қарап отырып, «Бүгін де сол аласапыраннан аман өттік» деп стақандарыңызды соғыстырыңыз. Сіздер — осы үйдің әрі қолбасшылары, әрі біртұтас командасысыздар.'),
  ('1681892e-80a4-445a-827d-19733c9c6b73', 'Қауымдастықтың күші 💬', '«Неліктен менің балам сонша қырсық?» деген ой мазаңызды алады. Anacan қауымдастығына қосылыңыз. Басқа аналардың үйінде де осындай ақылға сыймайтын дағдарыстар болатынын оқығанда, жалғыз емес екеніңізді және бәрі қалыпты екенін түсінесіз.'),
  ('450f109f-b886-4ee2-8c86-66186d74b732', 'Жарық ырғағы 🌙', 'Оның тезірек ұйықтауы үшін жатардан 1 сағат бұрын бөлмедегі барлық қосымша жарықты және планшет экрандарын өшіріңіз. Мелатонин қараңғы әрі технологиясыз ортада жылдам бөлініп, ұйықтауды жеңілдетеді.'),
  ('b4a0c1d1-e187-401c-89d3-83448ef5f879', 'Динозаврдың таңғы асы 🦖', 'Таңғы ас кезінде қолын пайдаланбай, аузын тікелей тәрелкеге апарып, динозавр сияқты тамақтанғысы келеді. Әдеп сабағын өткізбеңіз! 5 минут динозавр бола тұрсын, бұл ойыннан жалыққан соң қасықты өзі-ақ қолына алады.'),
  ('331d91d4-ea8d-4af5-be08-e82eb1b8836d', '«Өзім істеймін» жылдамдығы 🐢', 'Үйден шығуыңыз керек, бірақ ол аяқкиімін міндетті түрде өзі киеді және тасбақа жүрісімен оған 15 минут кетеді. Араласа қалсаңыз, жылау дағдарысы 30 минутқа созылады. Өтіп жатқан уақытқа емес, оның өзіне деген сенімін сақтауға мән беріп, сабырмен күтіңіз.'),
  ('2333a8bc-122b-4087-9603-3c895b2daf77', 'Тамақ талғауда қисын жоқ. 🥦', 'Кеше ғана сүйсініп жеген сорпасын бүгін аузына да алмай ма? Пайдалы рецепттерге өтіп, көкөністерді езбеге айналдырып, түрлі түсті макарон тұздықтарына жасыру жолдарын үйреніңіз. Жасыру өнерін меңгеріңіз.'),
  ('5e903417-88bd-42b5-bb8c-507e12e432bf', 'Суасты патшалығы 🛀', 'Ваннаға түсу енді жай ғана жуыну емес, суасты қайығының миссиясына айналды. Су жан-жаққа шашырай берсін. Судың сол ғажайып әсері күні бойы бойына жиналған қырсықтық пен жағымсыз энергияны шайып, кәрізге ағызып әкетеді.'),
  ('d3d2b281-0b44-4f04-8791-8ceca32ccdb3', 'Данышпан өнертапқыш 👟', 'Аяқ киімін құлағына тақап, байыпты түрде «Алло» деп әлденені айтып отыр. Ол заттарға жаңа қызмет ойлап табуда! Осындай күлкілі әрі тапқыр сәтті жіберіп алмаңыз. Бөпеңізге фотосессия жасап, осы көңілді өнертапқышты суретке түсіріп, мұрағатыңыздың ең көрнекті жеріне сақтап қойыңыз.'),
  ('185309c1-aba3-48ec-9411-535c92af4024', 'Цифрлық тыныштық терапиясы 🤫', 'Ақыры бөлме мүлгіген тыныштыққа бөленді. Ыдыс жуғыш машинаны толтыруға асықпаңыз. Дыбыс өлшегішті іске қосып, экрандағы көрсеткіштердің 0 децибелге дейін төмендеуін бақылаңыз да, шаршаған миыңыздың қалай тынығып жатқанын сезініңіз.'),
  ('4794fa88-36bd-4251-a4ea-871854d0d5ac', 'Қоқысты көбейтетін өнерпаз ✂️', 'Қолына түскен таза қағазды мыңдаған ұсақ бөлікке жыртып, бөлмеге шашып жүр ме? Бұл — ұсақ моториканың дамуы! Ашуланып, сыпырғышқа жүгірмеңіз. Қағаз қиындыларын бір қорапқа жинап, қар жаудыру ойынын ойнаңыз.'),
  ('bcbae78a-e00a-4482-8778-25c54ab9a376', 'Айнадағы қарсылас 🪞', 'Айнаның алдында тұрып, өзіне-өзі қабағын түйіп, ашулы әрі оғаш қимылдар жасап тұр. Ол эмоциялардың жүзінде қалай көрінетінін зерттеп жатыр. Сырттай дыбыс шығармай, осы кішкентай театр актерінің жаттығуын қызыға тамашалаңыз.'),
  ('9ecbc8da-836b-48fc-a294-6aaa4bafb6f3', 'Жалғыздықты аңсау 🚪', 'Күні бойы үстіңізге өрмелеп, жабыса берген баладан шаршадыңыз. Дәретханаға кіріп, есікті жаптыңыз да, 5 минут жалғыз қалдыңыз. Бірден Көңіл күй күнделігін ашып, ішіңізде жиналған қысымды экранға шығарып, жеңілдеп алыңыз.'),
  ('acb8e717-26b4-427c-9df9-4c6aeb16734c', 'Оқиғаның режиссері 🪄', 'Бүгін кешке сөйлеуге даусыңыз да, өзіңіз де шаршадыңыз. Ақылды ертегілерді қосыңыз. Балаңызға «Бүгін басты кейіпкер өзің боласың, ал артқы фонда жаңбыр жауып тұрады» деп, оған арнайы, тыныштандыратын әрі жеке дыбыстық орта жасап, тәтті ұйқыға батырыңыз.'),
  ('bd96c118-6b22-4005-829a-5d2036e47887', 'Жоғалған кілттер 🔑', 'Үйдің кілттерін таба алмай жүрсіз бе? Тоңазытқышты немесе аяқкиім шкафын қарап көріңіз. Бөпеңіз заттарды жасыру арқылы олардың көзден таса болса да бар екенін түсіну қабілетін тексеріп жүр. Осы қызық қазына іздеу кезінде ашуланбай, күле қарауға тырысыңыз.'),
  ('c22e7a31-d31e-4595-845a-77f2550b33d1', 'Сыбырдың гипнозы 🤫', 'Төсекте жатып, аяқтарын жоғары көтереді де, ұйықтағысы келмейді. Айқайлаудың орнына даусыңызды кенет бәсеңдетіп, онымен тек сыбырлап сөйлесіңіз. Бала Сізді есту үшін бар зейінін салғанда, миы біртіндеп тынышталып, ұйқы режиміне ауысады.'),
  ('11c8bab9-c92e-47a2-b7c0-34d8c43e8735', 'Қолдарыңызға демалыс 🫂', 'Күні бойы үстіңізге өрмелеп, құшаққа сұрана бергеннен денеңіз ауырып кетті ме? Кешке кезекті әкесіне беріңіз. Ол баланы арқасына мінгізіп, ат болып ойнағанда, баланың назарға деген қажеттілігі өтеледі, ал қолдарыңыз әбден қажет еткен демалысын алады.'),
  ('5ddf0bc2-3619-404d-a56d-27e47d73626e', 'Таңғы концерт 🎤', 'Күн әлі толық шықпаған, ал ол төсекте секіріп, Сіз түсінбейтін тілде бар даусымен ән айтып жүр. Иә, ұйқыңыз келіп тұр, бірақ бөлмені кернеген осы тіршілік қуаты Сізді де сергітеді. Оның даусына жай ғана жымиып қойыңыз.'),
  ('c7c4ce1e-98e4-4beb-992c-e1f8c9783567', 'Жасанды интеллект көмекке келеді 🤖', 'Анашым, күн ұйықтауға қайда кетеді? Мұндай сұрақтан абдырап қалдыңыз ба? Түсіндірмені күрделендірмеңіз. Anacan AI-ға баланың жасын көрсетіп, осы сұрақты қойыңыз. Сонда 3 жастағы бала оңай түсінетін, ертегіге ұқсас тамаша жауап алып, оған айтып бере аласыз.'),
  ('0daa509c-a73b-47b1-a76d-b85764cf98f2', 'Үнсіз төгілген жас 💖', 'Ол күні бойы Сізді әбден шаршатты. Бірақ қазір төсекте сондай бейкүнә болып ұйықтап жатыр, қарап отырып көңіліңіз босайды, солай емес пе? Ана болудың ең үлкен парадоксы — осы. Көзіңізден сырғыған бір тамшы жас — оның барына деген шүкіршілігіңіз.'),
  ('2d96922a-7550-4150-a8ed-19cdd56a8801', 'Жасырын тағам операциясы 🥣', 'Кеше ғана сүйіп жеген жұмыртқасын бүгін аузына да алмайды. Оның қырсықтығымен күреспеңіз. Пайдалы рецептілердегі ақуызды тағамдарды өзгеше, түрлі түсті әрі қызықты пішінде ұсынатын тапқыр тіскебасар рецептілерін қолданып, жағдайды өз пайдаңызға шешіңіз.'),
  ('a6a15ff2-f8a6-4007-b1d8-974680e64a8d', 'Логика істемей қалғанда 🛑', 'Суын қызыл стақанға құйып беруді талап етіп айқайлайды, ал қызыл стақанға құйсаңыз, енді неге бұған құйдыңыз деп жылайды. Мұнда логика жоқ. Ол жай ғана шаршаған және эмоциясын сыртқа шығарғысы келеді. Сабырмен күте тұрыңыз, дауыл өздігінен басылады.'),
  ('15c2879b-fa80-4ef3-b734-53366c8b7916', 'Кенеттен төгілген махаббат 🥰', 'Ойнап отырған жерінде ойыншығын тастай салып, жүгіріп келіп, мойныңыздан құшақтайды да: «Мен Сізді жақсы көремін», — дейді. Міне, осы сәт бүкіл шаршау мен ұйқысыздықты ұмыттыратын нағыз сиқыр. Оны кеудеңізге қатты қысып, жұпар иісін терең жұтыңыз.'),
  ('c0446dd4-cfe7-4c72-9419-07304cef46d7', 'Әкесінің өзгеше ертегісі 📖', 'Бүгін кешке даусыңыз шаршады. Ертегі оқуды әкесіне тапсырыңыз. Ол кітаптағы суретке мүлде қатысы жоқ, ойдан шығарылған күлкілі оқиғаны айтып, баланы мәз-мейрам етеді. Ал Сіз бір шетте бір кесе шайыңызды ішіп, бұл көріністі сүйсіне тамашалаңыз.'),
  ('df2fef22-961b-4197-8f8b-a55345b6bbaa', 'Сауда арбасымен арпалыс 🛒', 'Үлкен сауда арбасы өзінен биік болса да, оны міндетті түрде өзі итергісі келеді. Жұрттың көзінше жылатқанша, қолдарын арбаның шетінде ұстай берсін, ал Сіз білдірмей бағыттап отырыңыз.'),
  ('1528a888-1cfa-4bf5-b2b7-c533244518f5', 'Теріс киілген еркіндік 👗', 'Шалбарын теріс киіп алып, «өзім кидім» деп нық айтып тұр. Сыртқы көрінісіне мән бермей-ақ қойыңыз. Оның артып келе жатқан өзіне деген сенімі мен дербестік сезімі киімінің дұрыс киілгенінен әлдеқайда маңызды. Осы кішкентай бүлікшіңізді мақтан тұтыңыз.'),
  ('3b7890c9-fcdd-4513-a90d-c39e56fa7a0a', 'Астан-кестеңнің ортасындағы кофе ☕', 'Бөлменің ортасына барлық ойыншығын шашып, өзіне қамал тұрғызып жатыр. Сіз жинап болған бойда ол бәрін қайта шашады. Сондықтан күресе бермей, бөлменің бір шетіне жайғасып, кофеіңізді суытпай ішіңіз де, астан-кестеңді сырттай бақылап, тынығып алыңыз.'),
  ('903ab62c-4fd0-4ad9-9a8c-ad3cf62e1e9a', 'Бөлмедегі көлеңкелер 🐰', 'Қараңғыдан қорқа бастады ма? Бөлмені толық қараңғылап, кішкентай қолшаммен төбеге жарық бейнелерін және жануарлардың көлеңкелерін түсіріңіз. Ол қорқатын қараңғылықты көңілді ойынға, ұйықтар алдында бірге күлетін шағын зерттеуге айналдырыңыз.'),
  ('86b8fc9f-0ab7-4475-bc84-a0cb2dacfefd', 'Түні бойы үзілмейтін ұйқыға үміт 🤞', 'Ол ұйықтап қалды да, үй іші терең тыныштыққа бөленді. Сіздің ең үлкен тілегіңіз — оның бүгін түнде оянбауы. Дыбыс құрылғысындағы орманның баяу сыбдырын фондық дыбыс ретінде ақырын қосып, оның терең ұйқы кезеңінде қалуына жағдай жасаңыз.'),
  ('906c34fb-a999-448f-8756-7ba4d8fc80cd', 'Табиғат зертханасы 🍂', 'Үйде отыру Сізді жалықтырды, ал бала мазасызданып жүр. Ауа райын тексеріп, лайықты киім таңдап, оны міндетті түрде далаға алып шығыңыз. Қураған бұтақтар мен жапырақтарды жинау тапсырмасын беріп, оның бойындағы энергиясын шығаруына мүмкіндік жасаңыз, ал өзіңіз төрт қабырғадан шығып, таза ауа жұтыңыз.'),
  ('af0535a2-83d1-4838-8bfc-0cfb607ff2f5', 'Ойыншықтардың анасы 🧸', 'Бөлмеден дауыс естіледі. Мұқият тыңдасаңыз, ол қонжығын дәл Сіздің дауыс ырғағыңызбен, Сіздің сөздеріңізбен ұрсып жатыр! Ол — Сіздің айнымаған көшірмеңіз. Бұл — өз мінез-құлқыңызға сырт көзбен қараудың тамаша мүмкіндігі.'),
  ('0300b128-8698-433f-8d28-7ef165f88a96', 'Бөлісуге келмейтін таңғы ас 🍳', 'Өз тәрелкесіндегісінен Сізге мүлде бермейді, бірақ Сіздің тәрелкеңіздегі жұмыртқадан жегісі келіп, қояр емес. Балалар әрдайым ата-анасының таңдауына көбірек сенеді. Таласпай-ақ, бір үзіміңізді осы кішкентай өзімшілге сүйіспеншілікпен бере салыңыз.'),
  ('334f9c8b-ef27-4cd7-845a-eb18706654fc', 'Тізімсіз апат 🛒', 'Жадыма сенемін деп үйге келдіңіз де, балаға ең қажет сүтті алмағаныңызды байқадыңыз. Онсыз да ойыңызда шаруа көп. Енді бір нәрсе қажет болған сәтте оны қолданбадағы Сатып алу тізіміне жазуды әдетке айналдырып, өзіңізді күйзелістен қорғаңыз.'),
  ('ea78fdb3-c1ec-46eb-bb72-f6ee58c3526f', 'Ваннадағы мұхит 🌊', 'Ваннаға түсу енді жай ғана жуыну емес, толқын жасайтын ойынға айналды. Су жан-жаққа шашырай берсін. Судың сол бір ғажайып әсері күні бойы бойына жиналған жағымсыз, қырсық энергияны шайып, кәрізге ағызып жібереді әрі ұйқысын тереңдетеді.'),
  ('056e606b-664d-4a4e-94b5-81db6f2adf23', 'Сіз мінсізсіз 🛑', 'Әлеуметтік желіде күн сайын баласымен бірге өнер туындыларын жасап, үйін жарқыратып ұстайтын аналарды көріп, өзіңізді кінәлайсыз ба? Ол сүзгілерге сенбеңіз. Сіздің шашылған, у-шулы әрі шынайы үйіңіз — балаңыз үшін мейірімге толы ең жылы, ең мінсіз ұя.'),
  ('156b6d8e-1bbe-4769-b258-c89d41a67564', 'Кішкентай адвокаттың уәжі 🗣️', '«Мен өстім, сондықтан шоколад жеймін». Ол себеп-салдар байланысын құрып, Сізбен келісуге, тіпті саудаласуға тырысып жүр! Сөйлеу қабілеті тамаша дамып келеді. Оны мақтаңыз, бірақ өз шекараларыңыз бен ережелеріңізді де мейіріммен сақтаңыз.'),
  ('838e23dd-ecaf-4568-9687-59518e77bc77', 'Тыныштық терапиясы 🤫', 'Ол ақыры ұйықтап қалды! Дыбыс өлшегіш құралын қосып, экрандағы көрсеткіштің 0 desibel деңгейіне дейін төмендеуін бақылаңыз. Шаршаған миыңыздың қалай тынығып, осы көзге көрінетін тыныштықтың Сізге массаж жасағандай әсер сыйлайтынын сезініңіз.'),
  ('1645ac24-40c0-4cef-8645-e26caf67a799', 'Асүйдегі оқыс жағдай 🧑‍🍳', 'Сіз қамыр жайып жатқанда, ол келіп қолын ұнға салып, айналаның бәрін аппақ етеді. Иә, асүй ластанды, жұмысыңыз көбейді. Бірақ оның байыпты, іскер кейпін Бөпенің фотосессиясы арқылы бірден суретке түсіріп алыңыз. Ластық кетеді, ал сол естелік қалады.'),
  ('58f0130e-9824-44fe-9963-a1e86c3e18cc', 'Өзіңізді мақтан тұтыңыз 🚀', 'Өткенге көз жүгірткенде, оның қаншалықты мықты тұлға болып қалыптасқанын көресіз. Бүгін оған ұзақ қарап, осындай тамаша адамды өсіргеніңіз үшін өзіңізді мақтан тұтыңыз.'),
  ('f65305c4-c08d-4180-9df9-53864d7df4a9', 'Командаға алғыс 🥂', 'Тағы бір қиын әрі аласапыран күнді артта қалдырдыңыз. Бала ұйықтағаннан кейін серігіңізбен бірге шай ішіп отырып: «Бүгін маған көп көмектестің, рақмет», — деп айтыңыз. Бала тәрбиесі жалғыз атқарылатын міндет емес, тату команда болса, бәрі де жеңіл әрі жақсы болады.'),
  ('52fd1b46-da9f-4903-91e9-9855c04a5c68', 'Жанашырлықтың алғашқы белгілері 🧸', 'Ойыншығы құлап қалғанда, оны сипап: «Жылама», — дей ме? Демек, оның бойында жанашырлық сезімі қалыптасып келеді! Осы сүйкімді кезеңді Даму бақылаушысына міндетті түрде белгілеңіз.'),
  ('8cc847d7-8dbe-41eb-84d4-4cb88879af35', 'Теріс киілген киімдер 👗', 'Қолындағы жейдені міндетті түрде теріс қаратып кигісі келе ме? Қарсыласпаңыз. Бір күн үйде солай жүре берсін, оның жігерін жасытпаңыз.'),
  ('8ec0eb18-27f1-4127-9c31-f0777f9a4904', 'Біз бір командамыз! 💖', 'Қиын күннен кейін жұбайыңызбен бетпе-бет отырып, ашық сөйлесіңіз. Бір-біріңізге қолдау көрсету жүкті тура екі есе жеңілдетеді.'),
  ('47e4625b-1969-49f3-9819-a17d4bddc0c8', 'Көрпе инженериясы 🛏️', 'Енді ұйықтап кеткелі жатқанда, кенет жылай бастайды: көрпенің шеті бүктеліп қалыпты! Көрпенің миллиметріне дейін тегіс жатуы ол үшін өмірлік маңызға ие. Терең тыныс алыңыз, көрпені үтіктегендей етіп тегістеңіз де, осы күлкілі кірпияздығына жай ғана жымиыңыз.'),
  ('743bf968-dea7-4d72-ac2d-22654230f0a2', 'Күмәнді тыныштық 🤫', 'Үйде кенет мүлгіген тыныштық орнады. Дыбыс өлшегіш 0 децибелді көрсетіп тұр. Бала тым-тырыс болса, демек, бір жерде үлкен зерттеу жүріп жатыр. Қабырғадағы суреттерді немесе қиылған қағаздарды көруге психологиялық тұрғыдан дайындалып, бөлмеге кіріңіз.'),
  ('9fa0703c-5759-4d65-aa22-1042aa7b5843', 'Дауласпаңыз. 💼', '«Мен бұл ботқаны жемеймін, өйткені ол сары!» Оның қисынсыз уәжі соншалықты мінсіз әрі сенімді естіледі, тіпті өзіңізді кінәлі сезініп қала жаздайсыз. Дауласпаңыз. «Дұрыс айтасың, ол сары. Ал ішіне қызыл жидектер салсақ қалай болады?» — деп, кішкентай адвокатпен келісімге келіңіз.'),
  ('e4995ac6-5e09-45b3-8f40-851f3616a9f6', '«Анашым, қарашы!» кезеңі 👀', 'Диваннан секіріп, бір қимылды тура 50 рет қайталайды да, әр жолы: «Анашым, маған қарашы!» — дейді. Телефоннан көзіңізді алыңыз. Ол қимылдың өзі үшін емес, Сіздің көзіңізден мақұлдауды көру үшін секіреді. Оған еш алаңдамайтын 5 минут бөліңіз, назарыңызға тойсын.'),
  ('41b57fa8-5ee9-47c4-bdaf-6650d5ddc287', 'Музыкалық гипноз 🎶', 'Кешкісін аяқ астынан мазасызданып, жылау ұстамалары басталады. Теледидарды өшіріп, жарықты бәсеңдетіңіз де, бөлмеге өте баяу классикалық музыка қосыңыз. Музыканың терең әуені атмосфераны сиқырлы түрде өзгертіп, бөлмеге тыныштық сыйлайды.'),
  ('bfa22ff0-d771-4756-a950-034bebcc6d6a', 'Мультфильм сценарисі 📺', 'Көрген мультфильмін Сізге мүлде басқа оқиғамен әрі сенімді етіп айтып береді, тіпті сеніп қала жаздайсыз. Бұл — керемет қиялдың қалыптасып келе жатқанының белгісі.'),
  ('d113ec32-8781-4153-b853-ad718dad74e9', 'Ананың қайта жүктеу түймесі 🚪', 'У-шу миыңызды тесіп бара жатқандай, бәріне айқайлағыңыз келеді. Көңіл күй күнделігін ашыңыз. Бойыңыздағы бар қажуды еркін түрде жазып шығыңыз. Осы қысқа цифрлық терапия Сізді қайта сергітеді.'),
  ('0b46f253-2b1f-4b21-b471-54a500b94e42', 'Қараңғылықпен би 🌙', 'Тезірек ұйықтауы үшін ұйқыға жатардан 1 сағат бұрын бөлмедегі барлық артық жарықты және планшет экрандарын өшіріңіз. Мелатонин (ұйқы гормоны) тек қараңғы әрі технологиясыз ортада жылдам бөлініп, ұйықтап кетуге көмектеседі.'),
  ('53f4b2ce-2dcb-457d-bccf-d9242c156c63', 'Көшедегі қазына 🍁', 'Жерден тапқан лас бөтелке қақпағын немесе өзгеше түсті тасты алтын тапқандай қуанып, Сізге көрсетеді. «Таста, ол лас» деудің орнына: «Түсі қандай ерекше, жүр, үйде жуып алайық», — деп, оның жаңалық ашуға деген құштарлығын қолдаңыз.'),
  ('d8d7f0fc-2a92-4098-ba6e-6f7e5e3ee95f', 'Философия сағаты қайта басталды 🤔', 'Жел неге соғады? Жапырақтар неге түседі? Таң атпай қойылған терең философиялық сұрақтар миыңызды қыздырады. Түсіндіруді қиындатпай, табиғатты оған түсінікті ертегі тілімен баяндаңыз. Сіздің дауыс ырғағыңыз — ол үшін ғаламды танудың ең сенімді жолы.'),
  ('4a8b061c-822f-4468-b267-6996ffaeb6d8', 'Асүйдегі концерт 🥄', 'Кәстрөлдер мен ағаш қасықтарды шығарып алып, асүйдің ортасында концерт қояды. Басыңыз ауырса да, бұл — оның ырғақ сезімі мен шығармашылығының дамуы. Бірден тоқтатуға асықпаңыз, сол тасыған энергияның дыбыс толқындарымен бөлмеге бірнеше минут таралуына мүмкіндік беріңіз.'),
  ('15c2d5ec-3e4a-4b1d-b6d2-a891cc587847', 'Әкенің су шайқасы 🛁', 'Бүгін кешкі шомылдыру рәсімі толығымен әкесінің мойнында. Олар суды жан-жаққа шашып ойнай берсін, ал Сіз есіктің ар жағында тыныштықтың рақатын көріңіз.'),
  ('2054a805-49e3-459b-8315-84f392392707', 'Киімге қатысты бүлік 🥽', 'Ол үйде жүзуге арналған көзілдірік пен қысқы бас киім киіп жүргісі келеді. Қасарысып, оларды шешпейді. Қоғамдық нормаларды ұмыта тұрыңыз. Оның шығармашылығы мен таңдау еркіндігін шектемеу үшін сол ерекше әрі күлкілі киім үйлесімімен күні бойы жүруіне рұқсат етіңіз.'),
  ('5be61e62-9e95-417b-9db3-15386a93c72a', 'Сауда арбасындағы тосынсый 🛒', 'Кассаға жақындағанда сауда арбасынан Сіз таңдамаған 3 түрлі шоколад пен пішіні оғаш 1 сабын табылды. Епті қимылдап, оларды орнына қайтарыңыз. Ал ештеңені ұмытпау және мақсатыңыздан ауытқымау үшін үнемі Сатып алу тізіміне қарап жүріңіз.'),
  ('22ac2508-9b42-4e19-b15b-cc1dca8c750b', 'Есту құрылғысы өшіп қалды 🙉', '«Ойыншықтарды жина», «Кел, қолыңды жу» дейсіз, бірақ еш реакция жоқ. Естімеген кейіп таныту — 3 жастағы баланың сүйікті әуестіктерінің бірі. Айқайлаудың орнына қасына барып, құлағына өте жай дауыспен сыбырлаңыз. Дауыс ырғағының кенет өзгеруі оның назарын бірден аударады.'),
  ('4bb7714f-90ea-44a6-8f84-3a989d3c428e', 'Жуынатын бөлмедегі бопсалау 🛀', 'Ваннаға кіргенде жылаған еді, енді судан шықпау үшін айғайлап жатыр. Судың магниттей тартатын күші оны арбап алды. Алдын ала 3 минут қалғанын ескертіп, таймер орнатыңыз. Қоңырау соғылғанда ойын аяқталатынын білдіретін рәсімдер әрдайым көмектеседі.'),
  ('a6053646-98c9-47f9-ae28-32c8e38f416e', 'Тағам дизайнері 🥦', 'Тәрелкедегі тағамдарды түсі мен пішініне қарай бөліп, жасылдарын үстелдің шетіне ысырады. Тамақтану жоспарын іске қосыңыз. Көкөністерді көзге көрінбейтіндей етіп езбеге айналдырып, котлеттер мен тұздықтардың ішіне жасыру жолын тауып, бұл ойында жеңіске жетіңіз.'),
  ('454d0433-fa13-4bd5-95fe-c40365aff560', 'Үйдің бас дәрігері 🩺', 'Ойыншық стетоскопын кеудеңізге қойып, қабағын түйіп: «Дем алыңыз», — дейді. Ал Сіз — айтқанын орындайтын емделушісіз. Осы рөлдік ойынды өз пайдаңызға жаратыңыз: көзіңізді жұмып, 3 минуттық тексеру кезінде еденде жата тұрып, арқаңызды тынықтырыңыз.'),
  ('603f7d3e-e83f-41b9-ade3-bd0fa858fbaf', 'Әкенің дауыс желбезегі 📖', 'Бүгін даусыңыз шаршап, тамағыңыз құрғады. Кешкі ертегіні әкесіне тапсырыңыз. Ол кітаптағы суретке мүлде қатысы жоқ, күлкілі әрі ойдан шығарылған оқиғаны айтып, баланы мәз-мейрам етеді. Ал Сіз осы жылы көріністі бір шетте отырып, ыстық шаймен тамашалаңыз.'),
  ('79b03a5c-cc04-4f7b-9361-f8120f787406', 'Қауымдастықтан жұбаныш 💬', '«Неліктен менің балам соншалықты қырсық?» деген ой Сізді іштей мазалайды. Anacan қауымдастығына қосылыңыз. Басқа аналардың үйінде болып жатқан осыған ұқсас қисынсыз қылықтар туралы оқығанда, жалғыз емес екеніңізді және дені сау, қалыпты бала өсіріп жатқаныңызды түсінесіз.'),
  ('c0b67368-8315-449a-b685-71a8e309a2c6', 'Демінің жылуы 💖', 'Ол күні бойы Сізді әбден әбігерге салып, әр нәрсеге жылады. Ал қазір төсекте кеудеңізге жабысып жатыр, бөлмені оның бірқалыпты, жылы демі тербетеді. Ана болудың ең үлкен сыйы — дәл осы. Оны бауырыңызға басып, бүкіл шаршауыңыз осы деммен бірге сейіліп кеткенін сезініңіз.'),
  ('07a807e7-5500-4214-ab98-d5372a84c109', 'Командалық еңбектің жемісі 🥂', 'Тағы бір қиын да дауылды күнді артта қалдырдыңыздар. Бала ұйықтағаннан кейін серігіңізбен бірге шай құйып, «Бүгін де осы бейберекеттен аман өттік, біз керемет командамыз» деп бір-біріңізге алғыс айтыңыздар. Бала тәрбиесі жалғыз атқарғанда емес, қолдау болғанда көркейе түседі.'),
  ('7715199a-4ef6-480d-9548-a833acc549dd', 'Теріс киілген аяқкиім 👟', 'Аяқкиімін теріс киіп алған, бірақ әлемді бағындырғандай соншалықты мақтанышпен жүр. Араласып, түзетуге тырыссаңыз, бәрі бұзылады. Оның өзіне деген сенімі мен дербестігі сыртқы көріністен маңыздырақ. Осы кішкентай бүлікші мақтанышпен адымдай берсін.'),
  ('b205ec5f-9776-4abd-8a5c-b967e050819e', 'Асүйдегі ойран 🧑‍🍳', 'Сіз қамыр жайып жатқанда, ол келіп ұнға қолын салып, айналаның бәрін аппақ етеді. Иә, асүйдің астан-кестені шықты. Бірақ оның байсалды, іске берілген кейпін «Бөпе фотосессиясы» арқылы бірден суретке түсіріп алыңыз. Асүйді тазалап аласыз, ал сол күлкілі кадр мәңгі қалады.'),
  ('18bd2439-9788-43c4-81c5-8852d0241a0d', 'Жанды айна 🦜', 'Сіз ашуланғанда жасайтын бет әлпетіңізді айнытпай салып, ойыншығын ұрсып жатыр. Дәл қазір өзіңізге сырт көзбен қарап көріңіз! Ол не көрсе, соны қайталайды. Бұл күлкілі әрі ойландыратын көрініс — өз іс-әрекетіңізге мұқият болуға көмектесетін тамаша айна.'),
  ('57b60f69-46b8-4792-b8f6-95c7ec477f5b', 'Ақылды ертегідегі мен 🪄', 'Классикалық кітаптарды жатқа білесіз әрі оларды оқудан шаршадыңыз. Ақылды ертегілерді қосыңыз. Басты кейіпкерді балаңыз етіп, фонға тыныштандыратын орман дыбыстарын қойып, ерекше әрі еш күш жұмсауды қажет етпейтін ұйқы сеансын жасаңыз.'),
  ('8391ff6e-4225-4aa9-9011-6c07f64cfe8a', 'Таза ауа ⛅', 'Ауа райы мен киімін тексеріп, оны міндетті түрде далаға алып шығыңыз. Қураған бұтақтар мен тастарды жинау тапсырмасын беріп, оның бойындағы артық энергиясын шығарыңыз, ал өзіңіз төрт қабырғадан босап, терең тыныстаңыз.'),
  ('1d548457-d3f9-490c-889a-735e0fede3a4', 'Төсектегі көші-қон 🛏️', 'Түнде дұрыс қалыпта ұйықтап, таңертең аяғы жастықта, ал басы төсектің қарама-қарсы бұрышында оянады. Тіпті ұйықтап жатып та әлемді зерттейді! Оятпас бұрын оның төсектегі осы күлкілі көші-қонын күле отырып тамашалаңыз.'),
  ('9fa8e885-34cc-4a52-b9b9-6155faa47396', 'Философиялық ұйқыны созу 🦉', 'Төсекке жата салысымен Анашым, жұлдыздар неге құлап кетпейді? деген сияқты терең сұрақтар қояды. Мақсаты ғылым үйрену емес, ұйықтайтын уақытты созу. Сұрақтарына қысқа, ойдан шығарылған әрі сүйкімді жауаптар беріп, бірден Ақылды ертегілер арқылы бөлмеге ұйқы тыныштығын орнатыңыз.'),
  ('b5e65866-a678-4ef1-91b0-5f12331c2cae', 'Костюм киген қаһарман 🦸‍♂️', 'Үйдің ішінде міндетті түрде қысқы етікпен немесе суперқаһарманның маскасымен жүргісі келе ме? Қоғамның қалыптары мен эстетиканы қоя тұрыңыз. Бұл — оның өзін танып-білу жолы. Бөлмеде етігін киіп, өзін қаһарман сезінуіне мүмкіндік беріңіз.'),
  ('0497aa5e-024a-43eb-ba38-bda044dfec73', 'Динозаврдың тістері 🦖', 'Тісін тазалаудан үзілді-кесілді бас тартып, щетканы лақтырып жібере ме? Ойынға көшіңіз! Қолына қосалқы щетка беріп, Алдымен ойыншық динозаврыңның тісін тазалайық деңіз. Ол динозаврдың тісін тазалап жатқанда, Сіз де білдірмей оның тістерін тазалаңыз.'),
  ('2824815e-ab93-4e74-b868-7dee6ae3bcac', 'Дербестіктің дақтары 🥣', 'Йогуртты міндетті түрде шанышқымен жегісі келіп, айналаның бәрін былғай ма? Араласып, қолынан тартып алмаңыз. Шашылған тағамды тазалауға болады, ал оның мен өзім істеймін деген сенімін қалпына келтіру қиын. Силикон алжапқышын тағып, бұл көріністі сабырмен бақылаңыз.'),
  ('33c034f1-168d-424b-b367-21b9eb4799c9', 'Ананың 10 минуты 🚪', 'У-шу миыңызды шаршатты. Көңіл күй күнделігін ашып, бүгін Сізді ашуландырғанның бәрін экранға еркін жазып, ішкі қайта жүктеу түймесін басыңыз.'),
  ('1fc95e57-80a1-42af-8907-c939c12adef9', 'Қоқыс жәшігінің тартымдылығы 📦', 'Қымбат әрі жарқыраған ойыншықтары сонша көп болса да, ол бос пластик су бөтелкесімен немесе картон қораппен сағаттап ойнайды. Баланың қиялы дайын сценарийлерді емес, шығармашылыққа еркіндік беретін қарапайым заттарды ұнатады. Бақылаңыз және үйреніңіз.'),
  ('61bc311a-ba5b-43dc-b36e-6a65967f1df0', 'Ұйқыдағы төңкеріс ☁️', 'Таңертең ояна сала Сізге қабағын түйіп, өкпелейді. Себебі неде? Түсінде Сіз оған қалаған ойыншығын бермепсіз! Баланың миы түс пен шындықты әлі толық ажырата алмайды. Шын көңілмен кешірім сұрап, осы қисынсыз жағдайға іштей жымиыңыз.'),
  ('c193e688-7d18-417e-aa1d-53580a727596', 'Үнсіз көзқарас 🥂', 'Бөпе ақыры ұйықтады. Сіз жұбайыңызбен диванда қатар отырсыздар, тіпті сөйлесуге де шамаларыңыз жоқ. Тек үнсіз бір-біріңізге қарап, жымиып қоясыздар. Иә, бұл үнсіз көзқарас — «біз осы бейберекетті еңсеріп жүрміз» деудің ең әдемі жолы.'),
  ('98f98e2b-5170-4983-96d7-fe8b44837cdf', 'Қабырғадағы театр 🐰', 'Қараңғыдан қорқатынын сылтауратып, төсегінен қашып шығады. Бөлмедегі барлық жарықты өшіріп, қолшамды жағыңыз да, қолдарыңызбен қабырғаға құс пен иттің көлеңкесін түсіріңіз. Сонда ол қорқатын қараңғылық әп-сәтте әлемдегі ең қауіпсіз театрға айналады.'),
  ('bf60fea7-a806-46ec-a023-ae8a1e62e95a', 'Саябақтан шығу тәсілі 🌳', 'Саябақтан қайтатын уақыт келді, ал жылау мен қырсығу басталды. Оны сүйреп әкетуге тырыспаңыз. «Көлікке дейін кім бірінші жетеді екен?» деп, жарыс ұйымдастырыңыз. Балалар жарысып, жеңіске жетуге ешқашан «жоқ» демейді.'),
  ('e6013d08-4f44-4955-a2ce-c8556d1e2010', 'Көрінбейтін қонақ 👻', 'Таңғы ас кезінде қиялындағы досына да тәрелке қоюыңызды талап етеді. Бұл психологиялық олқылық емес, ақыл-ой дамуының серпілісі. Сол тәрелкені қойып, қонағыңызға қиялдағы шай құйыңыз да, осы керемет қойылымның бір бөлігіне айналыңыз.'),
  ('3cde3483-1ec6-4721-b8a3-2803d38e22f1', 'Сөздік қордағы жаңа жаңалықтар 🗣️', 'Заттарға өзі ойлап тапқан, ешбір тілде жоқ жаңа атаулар береді. Сізден де сол сөзді қолдануды табанды түрде талап етеді! Даму трекерін ашып, болашақта оқып күлу үшін оның осы күлкілі сөздерін міндетті түрде жазып қойыңыз.'),
  ('50316f93-f1fa-4052-831d-66931b46940d', 'Үйдің жасырын қазыналары 🔑', 'Үйдің кілттерін немесе қашықтан басқару пультін таба алмай жүрсіз бе? Ойыншық пештің ішін немесе төсегінің астын қарап көріңіз. Ол заттарды жасыру арқылы әлемнің қалай жұмыс істейтінін зерттеп жүр. Осы қызықты қазына іздеу кезінде ашуланудың орнына күліп, терең тыныстауды таңдаңыз.'),
  ('e6c3f535-9f72-4297-8076-fd7145c977da', 'Шомылу парадоксы 🛀', 'Ваннаға түскісі келмей жылаған еді, енді шыққысы келмей айқайлап жатыр! Судың сиқырлы әрі тыныштандыратын әсері оны баурап алды. Судан шығуды үлкен мәселеге айналдырмау үшін сүлгіні «жылы құшақ» деп атап, оған орап шығарыңыз.'),
  ('0d31e21b-368c-475e-b2bc-811f2bd6c64c', 'Менікі! деген қырсықтық 🧸', 'Үйдегі кез келген затты құшақтап алып, «Бұл менікі!» деп айқайлайды және ешкімге бермейді. Ол меншік шекараларын танып-біліп жүр. Оны өзімшіл деп айыптамаңыз, сол сәтте бұл заттың оған тиесілі екенін қабылдай салыңыз.'),
  ('297d6ab5-a5e9-4978-98b2-bd85528e89d5', 'Көрінбейтін қоқымдар 🧹', 'Қолындағы кішкентай сыпырғышпен кілем үстіндегі көрінбейтін шаңды аса байсалды кейіппен тазалап жүр. Ол бар болғаны Сізге еліктеп жүр. Оның осы жауапты сәтін Бөпе фотосессиясына түсіріп алыңыз: үйдің ең кішкентай әрі ең сүйкімді тазалықшысы жұмыс үстінде.'),
  ('79e7bb66-f1dd-4164-bbd9-7c802b073b10', 'Дыбыс өлшегіш терапиясы 🤫', 'Үйдегі әлгі тынымсыз құйын ақыры ұйқыға берілді. Бөлмеде ыдыс жуғыш машинаның дыбысынан басқа ештеңе естілмейді. Дыбыс өлшегішті қосып, экрандағы децибелдің ең төмен көрсеткіштеріне қарап отырып көзіңізді жұмыңыз. Бұл көрнекі тыныштық — миыңыз үшін ең жақсы массаж.'),
  ('fee25f48-2972-4bf2-9d26-d0fbea33a7f3', 'Мысық болып ояну 🐾', 'Бүгін таңертең ол адам емес. Төрт аяқтап жүріп, аяғыңызға үйкеледі де, тек «мияу» деп тілдеседі. Бұл — қиялдың ең сүйкімді, шырқау шегі. Ереже орнатудың орнына, Сіз де оған қиялдағы сүт құйылған ыдысты ұсынып, осы ойыннан ләззат алыңыз.'),
  ('0d53c056-84aa-4820-a905-2f2e60542791', 'Қауымдастықта сыр бөлісу 💬', 'Бүгін бәріне айқайлап, өзіңізді әлемдегі ең шыдамсыз анадай сезіндіңіз бе? Жалғыз емес екеніңізді ұмытпаңыз. Anacan қауымдастығына кіріп, басқа аналардың да бүгін дәл Сіз сияқты әбден қалжырағанын оқыңыз да, ар-ұжданыңызды мазалаған сезімді басыңыз.'),
  ('844a3d1a-225d-46c7-945c-c5eaf88248c4', 'Әкенің күлкілі ертегісі 📖', 'Бүгін кешке бөлмеде Сіздің емес, әкенің даусы естілсін. Ертегі кітабын әкесіне беріп, оқиғаны әдейі бұрмалап, күлкілі әрі қисынсыз етіп айтып беруіне мүмкіндік беріңіз. Балаңыздың оны түзеткеннен қалай ләззат алып, әкесіне қалай қарқылдап күлетінін сырттай тамашалаңыз.'),
  ('c862c51e-5b03-4e55-bd66-35165e58d3d8', 'Авангард сәулетші 🥞', 'Таңғы асқа берілген құймақтарды бірінің үстіне бірін қойып, мұнара тұрғызады, ортасын тесіп, ішінен саусағын өткізеді. Тамақпен ойнау — ол үшін жаңа инженерлік жоба. Үстелдің былғанғанына көз жұма қараңыз: осылайша ол тағамның құрылымын зерттеп жүр.'),
  ('772055c7-02e3-4df1-ab25-b0a7ed011afe', 'Қиялдағы дүкен 🍅', 'Бөлменің бір бұрышына ойыншықтарын жинап, Сізге қиялдағы ақшаға қиялдағы қызанақ сатып отыр. Бұл сауда ойынына барынша байыппен қатысыңыз. Қиялдағы қызанақты сатып алып, тәбетпен жеп жатқандай кейіп танытыңыз. Рөлдік ойындар — оның әлеуметтік зердесі мен математикалық ойлау қабілетінің берік іргетасы.'),
  ('9c4fcd9f-eca4-4781-b7b6-58a379dc2126', 'Ананың жасырын шоколады 🍫', 'Асүй шкафының тасасында балаңызға көрсетпей бір тілім шоколад жеп тұрған ана, бұл глюкоза — Сіздің табиғи құқығыңыз. Күні бойы сол сарқылмас қуат пен толассыз «негелерге» төтеп беру үшін Сізге де күш жинау қажет. Терең тыныстап, рақаттана шайнаңыз.'),
  ('a0a70ea3-00c4-4338-848e-bcb45a1157ff', 'Түнгі қорқыныш 😭', 'Түн ортасында көзі жұмулы күйде жылап оянып, ешкімді естімей ме? Жылау талдауы арқылы анықтаңыз; егер бұл түнгі қорқыныш болса, оны сілкілемеңіз және оятуға тырыспаңыз. Тек жанында үнсіз тұрып, қауіпсіздікте екенін сездіріңіз, бұл өтіп кетеді.'),
  ('2d19f095-845a-4bde-a575-de7451355856', 'Мұздай логика 🥶', 'Тоңазытқышты ашып, мұз салатын қалыпты сұрайды да, қолы тоңса да оны жібермей ме? Ол ыстық пен суық ұғымын өз денесімен тексеріп жүр. Бір ыдысқа жылы, екіншісіне мұздай су құйып, бұл зерттеуді шағын ғылыми тәжірибеге айналдырыңыз — қырсықтығы бірден басылады.'),
  ('5b70990d-933c-46b2-be30-1407db2c7b1b', 'Табиғатқа міндетті түрде шығу ⛅', 'Төрт қабырғаның арасында оның энергиясы агрессияға айналып, әрбір сөзі «жоқ» деп басталады. Ауа райы мен киімге қарамастан, лайықты қамданып, оны міндетті түрде далаға шығарыңыз. Топыраққа қол тигізу оның жүйке жүйесін бірден қалпына келтіруге көмектеседі.'),
  ('72b51261-3fd9-4ba4-a07e-a52ab32038d0', 'Түнгі шам 🌙', 'Жатын бөлмедегі жарық сөнгенде мазасыздана ма? Бөлменің бір бұрышына жылы түсті (қызғылт сары немесе қызыл) шағын түнгі шам қойыңыз. Ал бөлменің қалған бөлігі мелатониннің бөлінуі және терең ұйқы үшін тас қараңғы болуы керек.'),
  ('0bee47e7-94df-4d8c-b500-e8adc690d1ff', 'Құтқарушы цифрлық тізім 🛒', 'Дүкеннің ортасында тұрып, «Мен мұнда не алуға келіп едім?» деп ойланасыз ба? Ананың ойы онсыз да мың нәрсеге бөлінеді. Бірдеңе қажет болған сәтте-ақ оны қолданбадағы Сатып алу тізіміне жазуды әдетке айналдырып, жүгіңізді жеңілдетіңіз.'),
  ('7574c80e-2022-481c-9e84-dd04a5dc3520', '«Саған көмектесейін!» арандатуы 🧽', 'Сіз ыдыс жуып жатқанда, жаныңызға орындық қойып, сумен ойнағысы келе ме? Шын мәнінде, ол көмектескісі келгеннен емес, үдерістің дәл ортасында болғысы келеді. Оған кішкентай пластик ыдыс пен ысқыш беріңіз. Асүй су болады, есесіне оның мерейі өседі.'),
  ('ed6ba029-b0b0-4d21-8825-996dcfdf7f9e', 'Музыканың сиқырлы жиілігі 🎶', 'Кешкісін себепсіз басталатын дауыл мен айқай-шуды баяу классикалық музыкамен басып көріңіз. Көбіне осы қарапайым, бірақ тиімді әдіс бөлмедегі агрессиялық ахуалды сиқырлы түрде өзгертіп, баланы тыныштыққа бөлейді.'),
  ('df056dc0-b341-46d5-89e8-51170248ba0c', 'Киім шкафының инженері 👗', 'Бүгін далаға екі түрлі шұлық киіп, жейдесін теріс айналдырып шыққысы келеді. Қоғамның үйлесімділік талаптарына мән бермеңіз. Өз бетінше шешім қабылдап, оны қорғау еркіндігі — түстердің үйлесімінен әлдеқайда маңызды өмір сабағы. Рұқсат етіңіз.'),
  ('81e2b129-a3fd-4f20-b3aa-69e3df1d9014', 'Дауыстың бояуы 🌙', 'Ол кітаптағы ертегінің желісін емес, Сіздің дауыс ырғағыңызды тыңдайды. Бүгін кешке оқиғаның желісін ұмытыңыз. Ертегіні асықпай, созыңқырап, баяу әуендей бәсең дауыспен оқып, оның жүйке жүйесіне тікелей ұйқы белгісін жіберіңіз.'),
  ('92e01489-6842-4c96-9e36-b31b3377a1e1', 'Әлеуметтік желідегі елес 📱', 'Интернеттегі мінсіз аналарды көріп, үйіңіздің шашылып жатқаны үшін өзіңізді кінәлайсыз ба? Тоқтаңыз. Сүзгіден өткен сол 15 секундтық видеоларға сенбеңіз.'),
  ('267b7226-68df-4c3e-8db0-91462616e5aa', 'Тыныштықтың децибелі 🤫', 'Ақыры ұйықтап қалды! Бөлмені жинауға асықпаңыз. Дыбыс өлшегішті қосып, экрандағы 0-10 децибел көрсеткішіне қараңыз. Үйдегі мүлгіген тыныштықтың сол көрнекі дәлелі шаршаған миыңызға ең керемет массаждай әсер етеді.'),
  ('9a9573ec-71e1-4545-84fd-a3a1f5b2af6b', 'Философия профессоры 🧐', 'Анашым, күн неге ана жерде? деп емес, жай ғана Күн неге бар? деп сұрайды. Оның сұрақтары барған сайын дерексіз бола түседі. Сағаттап ғылыми түсініктеме беруге тырысып, өзіңізді шаршатпаңыз. Өйткені Бізді жылытқанды жақсы көреді ғой деген сияқты қысқа, ертегіге ұқсас әрі жылы жауап оны толық қанағаттандырады.'),
  ('c8cadde3-c829-4a73-89c2-d28ffc494046', 'Аяқтар демалыста 🚶‍♂️', 'Көшенің қақ ортасында кенет жерге отыра қалып, аяғым сынып қалды, мені көтеріп ал дейді. Жоқ, ол шаршаған жоқ, жай ғана Сізді сынап отыр. Бұл қулығына көне салмаңыз. Кәне, көлікке дейін пингвин сияқты қалай жететінімізді көрейікші? деп, оны ойынға тартыңыз.'),
  ('d2c59147-ed1d-426c-a22f-74bab5a93a1b', 'Түрлі түсті ас мәзірі 🥕', 'Бүгін тек қызғылт сары түсті тағамдарды жеуге шешім қабылдап, қалғанының бәрінен бас тартып отыр. Баланың қисыны тағы да іске қосылды! Пайдалы рецептілерде көкөністерді қалай жасыруға болатынын біліңіз. Асқабақ пен сәбіз езбесінен жасалатын әртүрлі тағамдар арқылы бұл қырсықты жеңіңіз.'),
  ('d7d30904-6d53-4964-8b13-c4680a8d7346', 'Таңғы әнші 🎤', 'Таңсәріде Сіз көзіңізді әрең ашып жатқанда, ол қолындағы ойыншығымен бөлменің ортасында концерт қойып жүреді. Оның үнін өшіруге тырыспаңыз. Балалардың осындай тентек те таусылмас өмірлік қуаты үйге шын мәнінде береке мен қуаныш әкеледі. Оған жымиып қараңыз.'),
  ('e2fc49a4-e751-47d3-a247-fa5b6429b0ca', 'Шипалы жанасу 💆‍♂️', 'Төсекте еш тыныштала алмай жатыр. Ертегі мен музыканы қоя тұрыңыз. Оның кішкентай аяқтарын немесе арқасын өте жеңіл, сипалай отырып уқалаңыз. Дене жанасуы оның да, Сіздің де ағзаңыздағы кортизолды (күйзеліс гормонын) бірден азайтып, ұйқы шақырады.'),
  ('ed70e165-6613-45b8-9098-e5a1501e357a', 'Жасанды интеллект және тыныштық 🤖', 'Бөпеңіз үш жарым жасқа таяғанда оның көңіл күйінің күрт өзгеруі Сізді алаңдата бастады ма? Интернеттегі үрей туғызатын, жанға бататын форумдарды жауып қойыңыз. Anacan ЖИ-ден осы жас кезеңіндегі дағдарыстар туралы ғылыми және психологиялық тұрғыдан негізделген, көңіліңізді тыныштандыратын жауап алыңыз.'),
  ('fd525f60-163f-4a76-b89b-734831b1ea09', 'Оқиғаны өзі құрастырсын 🪄', 'Классикалық кітаптардан екеуіңіз де жалығып, бөлме ішін зеріктіретін көңіл күй басса, ақылды ертегілерді қосыңыз да, бүгін кешке оқиғаны бөпеңіздің өзі бағыттасын. «Енді ұшатын көлік қайда барсын?» деп сұраңыз. Қиял әлемін бағындырып жүріп ұйықтап қалсын.'),
  ('4cc9dfab-73bb-408b-8fd7-0cdb3ba02840', 'Сыбырдың гипнозы 🤫', 'Төсекте жатып, аяқтарын көкке көтеріп, ұйықтағысы мүлде келмей ме? Айқайлаудың орнына даусыңызды кенет бәсеңдетіп, онымен тек сыбырлап сөйлесіңіз. Бөпеңіз Сізді есту үшін бар зейінін салғанда, миы біртіндеп тынышталып, ұйқы режиміне ауысады.'),
  ('815c8c47-103f-4098-9702-cdb4705b486d', 'Анаға арналған офлайн сәт 🛋️', 'Ол мультфильм көріп немесе ойыншықтарына беріліп отырғанда, Сіз ыдыс жуғыш машинаны босатуға не кір жаюға асығасыз ба? Тоқтаңыз! Сол 10 минутты диванға жатып, төбеге қарап, ештеңе ойламауға арнаңыз. Сіз робот емессіз.'),
  ('ac5c326d-30b1-4f87-8420-9236c8047849', 'Аяқталмаған сөйлемдерді толықтырыңыз 🗣️', 'Бір сөзді ұмытып қалғанда, қолымен ымдап, қабағын түйіп, Сіздің тауып беруіңізді күтіп тұрады. Оның сөздік қоры артып келеді, тек миы тілінен жылдамырақ жұмыс істейді. Сөйлемін сабырмен толықтырған кезде жүзінен көрінетін «иә, дәл осыны айтқым келген» деген жеңілдікті тамашалаңыз.'),
  ('7eaa01a6-6e1b-4778-9360-22935e0a6bcc', 'Тағам дизайнері 🥦', 'Тәрелкедегі тағамдарды түсі мен пішініне қарай бөліп, жасылдарын шетке ысырып қоя ма? Пайдалы рецепттер бөліміне кіріңіз. Көкөністерді езбеге айналдырып, дәмді тұздықтардың ішіне байқатпай жасыру жолдарын тауып, бұл ойында білдіртпей жеңіске жетіңіз.'),
  ('91e22232-e032-41dd-a3bf-200483eec697', 'Әкенің арқасындағы ат ойыны 🐴', 'Бөпеңіз бойындағы энергиясын толық шығара алмай, төсекке жатудан бас тарта ма? Әкесін көмекке шақырыңыз. Әкесі оны арқасына мінгізіп, ат болып шапқанда, бөлме күлкіге толады, ал жиналған физикалық ширығу мен таусылмайтын энергия санаулы секундтарда термен бірге жоғалады.'),
  ('f8f487ed-ac2b-4c2b-a252-bb33ce8ad0c5', 'Жағымсыз сөздер 🤐', 'Көшеден немесе теледидардан естіген жағымсыз сөзді күліп қайталап, Сіздің реакцияңызды асқан қызығушылықпен күтіп тұр ма? Ең мықты амалыңыз — еш реакция білдірмеу. Күлмеңіз, ашуланбаңыз, жай ғана елемеңіз. Ол бұл сөзді көп ұзамай ұмытып кетеді.'),
  ('07324b19-8c8c-4d15-8c79-0b07b4d8c8cf', 'Ваннадағы мұхит 🌊', 'Ваннаға түсу енді жай ғана тазалану емес, толқын жасайтын ойынға айналды. Су жан-жаққа шашырап, жуынатын бөлме су болса да, еркіне қойыңыз. Судың сол бір магниттей әсері күні бойы оның бойына жиналған қырсықтық пен жағымсыз энергияны шайып, кәрізге ағызып әкетеді.'),
  ('501e8f67-b2b7-4164-9b32-0326fabd781c', 'Жабық есіктің ар жағындағы сырлар 🚪', 'Бөлмесіне кіріп, есікті жауып, жалғыз қалғысы келе ме? Бұл жеке кеңістік туралы түсінігі мен даралығы қалыптасып келе жатқанын білдіреді. Қауіпсіздік шараларын қамтамасыз етіп, оның оңаша қалуға деген шағын құқығын мойындаңыз. Ол өсіп келеді.'),
  ('9e8cbc80-ee70-4ea5-ab36-76dd4e2487c7', 'Көңіл күй күнделігіндегі сыр 📝', 'Телефоныңызды қолыңызға алыңыз. Әлеуметтік желідегі өзгенің мінсіз өмірін парақтаудың орнына, Көңіл күй күнделігін ашып, оның бүгінгі ең күлкілі, Сізді ең қатты күлдірген сәтін болашаққа естелік ретінде жазып қойыңыз. Оған ойыңызды жазу — ең таза терапия.'),
  ('4acc88e2-20b2-4215-8fcd-8a14393b92b9', 'Жұптарға арналған шампан 🥂', 'Бала ұйықтады. Шампан болмаса да, стақандарға ыстық шай құйып, жұбайыңызбен «Осы бір аласапыран күнді де аман-есен аяқтадық» деп стақан түйістіріңіз. Сіздер — осы үйдің әрі қолбасшылары, әрі мызғымас командасысыздар.'),
  ('4b9f4b0d-becb-4db4-85ec-0a0caae64162', 'Қисынсыз көз жасы 🐶', 'Көшеде көрген ит оған қарамады немесе жапырақ жерге түсті деп өксіп жылады ма? Бұдан қисын іздемеңіз. Ол үшін бұл шынымен де терең қайғы. «Білемін, сен оның саған қарағанын қаладың» деп, оның сезімін жай ғана қабылдаңыз.'),
  ('9ae0817a-4137-49f1-8c45-fb16cc1d750b', 'Саябақтағы саясат 🤝', 'Сырғанақта басқа баланы итеріп жіберіп, өзі сырғанағысы келе ме? Бөлісу — ол үшін әлі толық қалыптаспаған, күрделі ұғым. Ұялтудың немесе жазалаудың орнына, «Қазір оның кезегі» деп, ортақ тәртіпті жай ғана еске салыңыз.'),
  ('23303195-392c-42b3-a778-b5f932e7d2fb', 'Дененің дабылы 🩸', 'Себепсіз ашушаңдық пен шаршауға берілмеңіз. Етеккір күнтізбесіне қараңыз, денеңіз Сізге белгі беріп тұр. Өзіңізді кінәлаудың орнына, құрамында магний бар тіскебасар жеп, демалыңыз.'),
  ('455a26dd-2714-4e7f-a8b0-c2319880fdbd', 'Көлеңкемен шайқас 👻', 'Қабырғадағы өз көлеңкесінен қорқып, артыңызға тығыла ма? 3 жастың ортасына қарай баланың қиялы шексіз болады. Бөлмені қараңғылап, қолшамның көмегімен қабырғада қолдарыңызбен көлеңке ойынын ойнаңыз. Ол қорқатын қараңғылықты ең қызықты ойынға айналдырыңыз.'),
  ('ca0412c4-f03e-412b-a720-1ce839d731c8', 'Ертегілердің сиқыры 🪄', 'Кәдімгі мәнерде оқуды бір сәтке қоя тұрыңыз. Қиялыңызды қосып, ертегіні жандандырыңыз. Ертегідегі желдің гуілін, есіктің сықырын, кейіпкердің аяқ дыбысын аузыңызбен салып, бөлмеде шағын дыбыс театрын жасаңыз. Бөпеңіз бұл қойылымға таңдана қарайды.'),
  ('5ee7392d-5b0b-4213-bc93-84f42871cfbd', 'Ұйқыны кейінге қалдыру айласы ⏱️', 'Ұйықтайтын уақыт келгенде кенеттен су сұрап, дәретханаға барғысы келе ме немесе тіпті қабырғамен қоштаса бастай ма? Таймер орнатыңыз. «Қоңырау соғылғанда, бәрі ұйықтайды» деген ережені енгізіп, осы бітпейтін қоштасу мен шебер айладан сабырмен құтылыңыз.'),
  ('8ed6ac5e-566a-43de-a26f-f6688bac7a5c', 'Ойыншықтардың анасы 🧸', 'Бөлмеден дауыс естіледі. Мұқият тыңдасаңыз, бөпеңіз қонжығын дәл Сіздің дауыс ырғағыңызбен, өзіңіз жиі айтатын сөздермен ұрсып жатыр! Ол — Сіздің айнымас көшірмеңіз. Бұл өз мінез-құлқыңызға сырт көзбен қарауға таптырмас мүмкіндік.'),
  ('fcc9b956-df18-4d44-8e28-2c6ce0162f8e', 'Ауа райын барлау ⛅', 'Даладағы ауа райы түсініксіз бе: күн жарқырап тұр, бірақ жел де соғып тұр ма? Ауа райы мен киім таңдау құралы терезеден байқалмайтын желдің жылдамдығын көрсетіп, қандай киім үйлесімін таңдаған дұрыс екенін бірден айтып берсін. Есік алдында ойланып уақыт жоғалтпай, серуенге шығыңыз.'),
  ('542ab746-c3f8-40a2-81ae-c00828c5ed07', 'Әкенің құпия тәсілі 👨‍🍼', 'Күндізгі шаршау мен шу Сізді әбден қажытты. Кешке баланы ұйқыға дайындау мен тісін тазалату ісін әкесінің ойындарына тапсырып, өзіңіз басқа бөлмеде мүлгіген тыныштықта міндетті түрде демалыңыз.'),
  ('843abd1b-ca68-4402-b6ea-b248f8954a8f', 'Ананың қуат батончигі 🥑', 'Оны тамақтандыру үшін мәзірді 4 түрлі етіп дайындадыңыз, ал өзіңіз не жедіңіз? Пайдалы рецептілер арасынан 5 минутта әзірленетін, кальцийге бай арнайы тіскебасарды таңдап, тіпті түрегеп тұрсаңыз да, дәмін асықпай сезініңіз. Сіз — осы үйдің қозғаушы күшісіз.'),
  ('9b9022d6-2ceb-4fd3-b3c5-141395cf895c', 'Бөлісуге келмейтін таңғы ас 🍳', 'Өз тәрелкесіндегіні Сізге мүлде бермейді, бірақ келіп, Сіздің тәрелкеңіздегі жұмыртқа немесе ірімшіктен жегісі келіп, қоймай ма? Балалар ата-анасының таңдауына әрдайым толық сенеді. Таласпаңыз, аузыңыздағы дәмді үзіміңізді оған сүйіспеншілікпен ұсыныңыз.'),
  ('3a219301-d574-4311-87ab-5dc04ddcfd8f', 'Командалық массаж 💆‍♂️', 'Бала ұйықтағаннан кейін күн бойы жиналған физикалық және психологиялық күйзелістен арылу үшін серігіңізбен бір-біріңіздің иығыңызға массаж жасаңыз. Сіздер бір үйде тұратын ата-аналар ғана емес, бір-біріне мызғымас тірек болатын командасыздар.'),
  ('b2fc2b4c-64df-4f47-be2c-e630a4d24c5c', 'Табиғатқа міндетті түрде шығыңыз ⛅', 'Төрт қабырға арасында оның энергиясы агрессияға айналып, әр сөйлемі «жоқ» деген сөзден басталады. Ауа райы мен киімге қарамастан, қажет жабдықтарды алып, оны міндетті түрде далаға шығарыңыз. Топыраққа қол тигізу оның жүйке жүйесін бірден тыныштандырады.'),
  ('20cf0e7c-3293-4269-b577-f8012d7d5117', 'Логиканың күйреуі 🔴', 'Суды қызыл стақанға құйып беріңіз деп айқайлайды, ал қызыл стақанға құйсаңыз, бұл жолы «неге бұған құйдыңыз?» деп жылайды. Мұнда логика жоқ. Ол жай ғана шаршаған әрі эмоциясын сыртқа шығаруы керек. Сабырмен күтіңіз, дауыл өздігінен басылады.'),
  ('3d467b3e-4418-42f9-965d-e11c13d74805', 'Қалтадан шыққан қазыналар 🪨', 'Шалбарын жуғалы жатқанда қалтасынан 2 тас, бір кепкен жапырақ пен сынық таяқша шықты ма? Сіз үшін қоқыс болған бұл заттар — оның әлемді зерттеу кезінде жинаған құнды топтамасы. Оларды тастамай, шағын қазына қорабына жинаңыз.'),
  ('78fd11f7-de1e-4540-906f-51f08156be41', 'Ақылды ертегідегі мен 🪄', 'Классикалық кітаптарды жатқа білесіз. Ақылды ертегілерді ашып, басты кейіпкер етіп балаңызды, ал бағындыратын мекен ретінде оның бөлмесін таңдап, ерекше әрі еш күш салуды қажет етпейтін дыбыстық ұйқы сеансын жасаңыз.'),
  ('5294e5b4-881b-4e55-b798-fa4dd914d649', 'Қоқыс емес, өнер 🎨', 'Ол бөлменің ортасына ұсақ қағаз қиындылары мен кесілген жіптерден үлкен өнер туындысын жасап, оны тастауға рұқсат бермей ме? Тазалыққа деген тым қатал талапты бір сәтке ысырып қойыңыз. Ол жасаған ретсіздікке құрметпен қараңыз, тазалықты ертең де жасай аласыз.'),
  ('b303b530-f33d-4aed-9563-288f674e5686', 'Жылау талдауының көмегі😭', 'Түн ортасында көзін ашпастан жылап оянып, ешкімді естімей ме? Жылау талдауы арқылы тексеріңіз; егер бұл түнгі қорқыныш ұстамасы болса, оны оятуға тырыспаңыз. Тек жанында үнсіз тұрыңыз, ол бірнеше минуттан кейін қайта ұйықтап кетеді.'),
  ('d0b48160-e2df-4f83-a2aa-8dad8ce91b39', 'Жансыз заттармен әңгімелесу 🗣️', 'Саябақтағы тасқа немесе үйдегі орындыққа барынша байыппен бірдеңе айтып, тіпті оларға ұрса ма? Символдық ойындар арқылы ол әлемді және оның ережелерін түсініп, ой елегінен өткізеді. Даму трекерінде оның осындай ерекше сценарийлерін міндетті түрде белгілеңіз.'),
  ('3486268f-4b63-480f-87b2-0334f163c85e', 'Ваннадағы ойын 🌊', 'Ваннаға түсу енді жуыну емес, толқын жасау ойынына айналды. Су жан-жаққа шашырап, жуынатын бөлме суланса да, рұқсат етіңіз. Судың сол магниттей әсері күні бойы оның бойында жиналған қырсықтық пен жағымсыз энергияны шайып, кәрізге ағызып жібереді.'),
  ('77e473a7-cc66-4af3-964b-ebd4e0ce22a0', 'Бұл менің кінәм емес! 🤷‍♂️', 'Суды әдейі еденге төгіп алды да, кінәні үстелге артып: «Үстел сырғып кетті», — деді. Бұл өтірік емес, өзін қорғау инстинкті. Қырсықпаңыз, «Кел, үстелге көмектесіп, бірге сүртейік», — деп, көңіліне тимей жауапкершілікке үйретіңіз.'),
  ('a43b3c7f-b8b9-440c-abc6-6650d2627176', 'Қауымдастықтың қолдауы 💬', '«Мен енді ешқашан бұрынғы еркін қалпыма оралмаймын» деген ой кенеттен жаныңызды қыса ма? Осы өткінші болғанымен, өте ауыр әрі терең сезімді Anacan қауымдастығындағы аналармен бөлісіп, олардың да осындай жолдан өткенін біліп, жұбаныш пен қолдау табыңыз.'),
  ('1eb146d3-b624-4eb5-88ee-21bab3e1a546', 'Жай ғана құшақтаңыз 🫂', 'Ешқандай ойынның, дыбысты кітаптың немесе ертегінің қажеті жоқ. Бүгін кешке оны жай ғана бауырыңызға басып, жұпар иісін терең жұтыңыз да, қараңғыда оның қаншалықты қымбат екенін және оны қалай жақсы көретініңізді сыбырлап айтыңыз.'),
  ('39c13cd6-54ea-4fd8-a9da-7ceece969e6d', 'Дүкендегі «Өзім жүргіземін» деген қырсықтық 🛒', 'Дүкен арбасын өзі жүргізгісі келіп, сөрелерге соғылып, айналаны астаң-кестең етеді. Жұрттың көзінше жылатқанша, қолдарын арбаның шетінде ұстай берсін, ал Сіз білдірмей бағыттап отырыңыз. Ұмытып кеткен заттарыңызды «Сатып алу тізімінен» тексеріңіз.'),
  ('dcf51c40-2de5-47dc-a87f-c99740f37d0f', 'Ойыншықтар әлеміндегі бейберекет 🌪️', 'Күн сайын бір ойыншықтарды қайта-қайта жинаудан шаршадыңыз ба? Бүгін жинамаңыз! Үй — мұражай емес, тіршілік қайнап жатқан, кішкентай зерттеуші өсіп келе жатқан жылы мекен. Шашылған заттарға емес, балаңыздың еркін зерттеуден алатын қуанышына назар аударып, демалыңыз.'),
  ('7f0898f3-4281-4b25-877c-f3060088913f', 'Төменге қараңызшы, ол нені зерттеп жүр? 👣', 'Ол жалаңаяқ жүріп, кілемді, бөлмедегі тастарды немесе салқын кафельді аяғымен сезінгенді ұнатады. Табандағы жүйке ұштарының белсенді болуы оның тепе-теңдігі мен неврологиялық дамуы үшін өте маңызды, сондықтан шұлықсыз жүруіне кедергі жасамаңыз.'),
  ('a17ad881-1738-43fa-b18c-dd0c7b263be1', 'Жасанды интеллект, нақты шешім 🤖', 'Балаңыздың бәріне қатты реакция білдіруі Сізді қорқытты ма? Интернеттегі үрей туғызатын мақалаларды ұмытыңыз. Anacan AI-дан бұл жай ғана уақытша күйзеліс реакциясы болуы мүмкін бе деп сұрап, ғылыми негізделген әрі педиатрлар мақұлдаған жауап алып, көңіліңізді тыныштандырыңыз.'),
  ('be73d9bc-5d86-4bdb-a6da-ef74ea88ee1e', 'Тыныштықтың цифрлық өлшемі 🤫', 'Ол ақыры ұйықтап қалды! Үйді жайлаған тыныштыққа сене алар емессіз. Дыбыс өлшегішті іске қосып, экрандағы 0-10 децибел көрсеткішіне қараңыз да, миыңыздың біртіндеп қалпына келіп, тынығып жатқанын көзбен көріп сезініңіз.'),
  ('c30e7d23-adbf-430f-894c-89ab12e4b61e', 'Мақсатты қирату 🧱', 'Ол барын салып мұнара тұрғызады да, кейін күліп тұрып оны бір соққымен қиратады. Осылайша ол физиканы және себеп-салдар байланысын танып-біледі. Ашуланбаңыз: қираған мұнаралар — оның миында қалыптасып жатқан жаңа нейрондық байланыстар. Мұнараны қайта тұрғызуына көмектесіңіз.'),
  ('f4280214-1e8a-4015-949d-34ae67c41790', 'Күндізгі ұйқыға қарсылық 🥱', 'Төсекке жатқысы келмей, жылап жатыр ма? Мәжбүрлемеңіз. Бөлмедегі жарықты бәсеңдетіп, Үнсіз кітап парақтау сағатын жариялаңыз. Осылайша екеуіңізге де тынығуға көмектесетін жаңа әдет қалыптастырып, әрқайсыңыз өзіңізге ыңғайлы түрде демаласыз.'),
  ('4a5979ea-637a-48c3-a6a9-1af57b3d55c4', 'Қиялдағы дүкен 🍅', 'Ол бөлменің бір бұрышына ойыншықтарын жинап, Сізге қиялдағы ақшаға қиялдағы қызанақ сатып отыр. Бұл сауда ойынына барынша байыппен қатысыңыз. Қиялдағы қызанақты сатып алып, тәбетпен жеп жатқандай кейіп танытыңыз. Рөлдік ойындар — оның әлеуметтік зердесінің ең берік негізі.'),
  ('58c30ae3-2599-434d-af6b-bb25c9a1766d', 'Музыкалық гипноз 🎶', 'Кешкісін себепсіз мазасыздық пен жылау ұстамалары басталды ма? Теледидарды өшіріп, жарықты бәсеңдетіңіз де, бөлмеде классикалық музыканы өте ақырын қосыңыз. Музыканың терең жиілігі бөлменің атмосферасын сиқырлы түрде өзгертеді.'),
  ('d8b0e257-5429-4bf7-b2a7-1bb116658651', 'Мінсіздік болмайды 🛑', 'Бүгін шыдамыңыз таусылды ма? Өзіңізді кінәламаңыз. Интернеттегі мінсіз ана туралы жалған бейнелерден аулақ болыңыз. Сіз — шынайы анасыз, сондықтан эмоцияларыңызды сезінуге де, шаршауға да құқығыңыз бар.'),
  ('4673a3e6-d285-4515-9173-039b8bcbc1e0', 'Дүкендегі көмекші 🛒', 'Дүкенге барғанда ең қажетті затты үнемі ұмытып кетесіз бе? Қолданбада Сізді сатып алу тізімі күтіп тұр. Қажетті заттарды сонда жазып қойыңыз, жұбайыңыз жұмыстан қайтарда тізім бойынша бәрін дәл алып келсін. Ал Сіз ойыңызды артық жүктемеңіз.'),
  ('dd38c03c-a89e-4942-af31-f459dbf71386', 'Анашым, маған қара! кезеңі 👀', 'Ол диваннан секіріп, бір қимылды тура 50 рет қайталап, әр жолы Анашым, маған қара! дейді. Назарыңызды телефоннан аударыңыз. Ол Сіздің көзіңізден мақұлдау мен қолдауды көру үшін секіреді. Оған 5 минут бойы бар назарыңызды бөліңіз, көңілі толсын.'),
  ('effd03a1-4f68-42a7-8c25-eabba9947bc3', 'Сыбырлап айтылған әңгімелер 🌙', 'Бүгін даусыңызды көп шығарып, әбден шаршадыңыз. Жарықты өшіріп, бөпеңіздің жанына жатыңыз да, күні бойы болған оқиғаларды құлағына жай ғана сыбырлап айтып беріңіз. Сыбыр оның зейінін шоғырландырып, миын терең ұйқыға гипноз әсеріндей дайындайды.'),
  ('602df0e4-a84c-493f-a594-485626339a2a', 'Шамдарды өшіріңіз, ұйқы келсін 🌙', 'Бөпеңіздің тезірек ұйықтауы үшін ұйықтардан 1 сағат бұрын бөлмедегі барлық қосымша жарықты өшіріп, планшет экрандарын сөндіріңіз. Мелатонин (ұйқы гормоны) тек қараңғы әрі технологиялық құрылғылар жоқ ортада жылдам бөлініп, ұйқыға кетуді жеңілдетеді.'),
  ('871e1c8b-981d-456b-8f8e-49b3f9df1255', 'Блогтардан шабыт алу 📱', '40-шы айға қарай баланың дамуында қандай серпілістер болады? Ол нені істей алуы керек? Қосымшадағы даму туралы блогтарды қарап шығыңыз да, балаңыздың қабылдау мен логика жағынан қаншалықты алға басқанын көріп, іштей қуаныңыз.'),
  ('dc309f01-53dd-4d8e-b0a5-566a9cb979d1', 'Аяқталмаған сөйлемдер 🗣️', 'Бір сөзді ұмытып қалса, қолымен ымдап, қабағын түйіп, Сіздің тауып айтуыңызды күтеді. Сөйлемін сабырмен аяқтап бергенде, жүзінен «иә, дәл осыны айтқым келген» деген жеңілдеуді байқаңыз. Оның тілін түсінетін жалғыз аудармашы — Сіз.'),
  ('35170eca-5526-4a79-8f60-bb6c6204b11e', 'Кенеттен ашығу синдромы 🥱', 'Төсекке жата бергенде «Анашым, қарным ашты» деп, асүйге жүгіргісі келе ме? Ұйқыны кейінге қалдырудың нағыз шебер тәсілі! Тамақтану жоспарында кешке ұйқыға септігін тигізетін шағын тіскебасар таңдап, бұл сылтаудың алдын алыңыз.'),
  ('a52300ac-c13a-4b61-bfa8-c7cb27b41cfa', '«Аяғым шаршады» деген қулық 🚶‍♂️', 'Көшеде келе жатып кенет жерге отыра қалып, «Аяғым сынып қалды, мені көтерші» дей ме? Бұл физикалық шаршау емес, анасын өз дегеніне көндіру амалы. Мұны ойынға айналдырыңыз: үйге дейін қоян сияқты кім тезірек секіріп жетер екен?'),
  ('ed5f6008-15d7-44f7-a33c-21fd4bedec89', 'Ананың Reset түймесі 🚪', 'У-шудан басыңыз шыңылдап, бәріне айқайлағыңыз келеді. Көңіл күй күнделігін ашыңыз. Оған әбден қажығаныңызды бүкпесіз жазып шығыңыз. Бұл қысқа цифрлық терапия күшіңізді қайта қалпына келтіреді.'),
  ('045a4c72-4a86-41d2-b03b-ae2eaef10270', 'Әкенің ертегісі 📖', 'Бүгін кешке даусыңыз шаршады. Ертегі оқуды әкесіне тапсырыңыз. Ол кітаптағы суретке мүлде қатысы жоқ, өзі ойдан шығарған күлкілі хикаяны айтып, баланы қарқылдатып күлдіреді. Ал Сіз бір шетте бір кесе шай ішіп отырып, бұл көріністі сүйсіне тамашалаңыз.'),
  ('4f62a7a1-3c14-48ad-8798-069c557ed2c1', 'Кір жууға көмектесуші 🧺', 'Сіз бар күшіңізді салып киімдерді жинап, бүктеп қоясыз, ал ол «көмектесіп жатырмын» деп, бәрін қайтадан бөлмеге шашып тастайды. Ашуланудың орнына мұны ойынға айналдырыңыз: мына шұлықтарды себетке кім тез әрі дәл лақтырып салар екен?'),
  ('b2543089-e56e-4e5f-b7a7-8528d7fea1b5', 'Таңғы диктатор іске кірісті 👑', 'Ол жерге сен отырма, қонжығым отырады! Таңғы ас кезінде бүкіл үстелге сол басшылық етеді. Оның еркін бірден басып тастамай: «Жарайды, қонжығың сол жерде отырсын, ал мен мұнда отырайын», — деп, тепе-теңдік пен үйдегі тыныштықты сақтаңыз.'),
  ('c7639a79-f169-46c8-bd32-85e01fd08685', 'Шам жарығындағы шай 🕯️', 'Бала ұйықтап қалды. Жарықты өшіріп, үстел үстіне бір шам жағыңыз. Бұл романтика үшін емес, күні бойы ширыққан жүйкеңізді және экрандар мен шудан шаршаған көзіңізді тынықтыру үшін.'),
  ('c83edf54-e27c-4125-b28b-f2d18dfa66d3', 'Жанасудан шаршау 🔋', 'Күні бойы үстіңізге өрмелеп, құшақтауды сұрайды әрі шашыңызбен ойнайды. Жанасудан шаршау (touched out) — шынайы күй. Кем дегенде 15 минут бір бөлмеде жалғыз қалып, тәніңіздің тек өзіңізге ғана тиесілі екенін сезінуге құқығыңыз бар.'),
  ('01e96341-0baa-4735-9565-edc8b43ed916', 'Әкенің арқасындағы ат ойыны 🐴', 'Бөпе энергиясын толық шығара алмай, ұйықтауға қарсылық танытып жүр. Әкесін көмекке шақырыңыз. Ол баланы арқасына мінгізіп, ат болып шапқанда, бөлме күлкіге толады да, жиналған бүкіл дене ширығуы мен сарқылмас энергиясы бірнеше секундтың ішінде термен бірге жоғалады.'),
  ('384ff620-f71d-4bc9-9283-5e83ec033e38', 'Қауымдастықтағы сырласу 💬', 'Бүгін бәріне айқайлап, өзіңізді әлемдегі ең шыдамсыз анадай сезіндіңіз бе? Өтінеміз, жалғыз емес екеніңізді біліңіз. Anacan қауымдастығына кіріп, басқа аналардың да бүгін дәл сіздей қалжырағанын оқып, көңіліңізді жұбатыңыз.'),
  ('da72ebf1-980c-4fb3-a9bf-5164e9b3b0a9', 'Айнадағы қарсылас 🪞', 'Айна алдында тұрып, өзіне-өзі қабағын түйеді, ашулы әрі оғаш бет қимылдарын жасайды. Ол эмоциялардың бет-жүзінде қалай көрінетінін байқап жүр. Сырттай дыбыс шығармай, осы кішкентай театр әртісінің жаттығуын қызыға тамашалаңыз.'),
  ('2c31302d-18e1-44cd-8719-76e1444cd735', 'Құпия тамақ операциясы 🥣', 'Кеше ғана жақсы көрген жұмыртқаны бүгін аузына да алмайды. Оның еркімен күреспеңіз. Пайдалы рецептілерде ақуызды тағамдарды әртүрлі, түрлі-түсті әрі қызықты пішінге келтіретін айлалы тіскебасар рецептілерін қолданып, жеңіске жетіңіз.'),
  ('723d3b58-0a46-493d-ba9b-9e4d8c6656ee', 'Тыныштықтың дәлелі 🤫', 'Шулы күннен кейін бала ұйықтағанда, дыбыс деңгейін өлшейтін құралмен бөлмедегі тыныштықты өлшеңіз. Нөлге жақындаған сандарды көру — сол көзге көрінетін тыныштық ананың миына ең жағымды массаждай әсер етеді.'),
  ('f226f50f-54a9-4f4e-ad02-b0959087d7d6', 'Кенеттен «Сені жақсы көремін» 💖', 'Бөлменің ортасында ойнап жүріп, кенет Сізге қарап, жүгіріп келіп мойныңыздан құшақтайды. Осы сәт барлық ұйқысыз түндер мен шаршауға тұрарлық! Бұл сәт сыйлаған терең әрі ерекше тыныштықтан ләззат алыңыз.'),
  ('3517ce10-8615-407d-be3b-394eda1c9fa6', 'Жарықты өшіріңіз, ұйықтайтын уақыт келді 🌙', 'Тезірек ұйықтауы үшін жатардан 1 сағат бұрын бөлмедегі барлық артық жарықты өшіріп, планшет экрандарын сөндіріңіз. Мелатонин (ұйқы гормоны) тек қараңғы әрі технологиясыз ортада жылдам бөлінеді.'),
  ('7daa2d64-db1d-42ea-8cec-a0101d304bbf', 'Талшыққа қажеттілік 💩', 'Көп жүгіреді, бірақ су ішуді ұмытып кетеді. Түбекке отырғаннан кейін үлкен дәретін бақылаңыз. Іш қату қаупі болса, оны қолданбаға белгілеп, бірден Тамақтануды бақылау құралы арқылы мәзірге сұлы мен қара өрік қосыңыз.'),
  ('e079d221-e081-498b-8457-7e4dc4555c89', 'Жаман сөздер 🤐', 'Көшеден немесе теледидардан естіген жаман сөзді күліп тұрып Сізге қайталайды да, реакцияңызды асқан қызығушылықпен күтеді. Сіздің ең мықты қаруыңыз — еш реакция білдірмеу. Күлмеңіз, ашуланбаңыз, жай ғана елемеңіз. Ол бұл сөзді көп ұзамай ұмытады.'),
  ('2b47e995-a54a-442e-b303-43e9894db748', 'Ертегінің соңын өзі жазсын 🪄', 'Классикалық кітаптардан екеуіңіз де жалықтыңыздар. Бұл жолы ақылды ертегілерде оқиғаның соңын балаңызға таңдатыңыз. «Сеніңше, сол кейіпкерге кім көмектесті?» деп сұрап, ұйықтар алдында қиялына ерік беріңіз.'),
  ('e7a2ec95-d6ca-43e4-8ed9-23193c18bf3a', 'Мұздай логика 🥶', 'Тоңазытқышты ашып, мұз салатын қалыпты сұрайды да, қолы тоңса да оны жібермейді. Ол ыстық пен суық ұғымдарын өз денесімен зерттеп жүр. Бір ыдысқа жылы, екіншісіне мұздай су құйып, бұл жаңалықты шағын ғылыми тәжірибеге айналдырыңыз.'),
  ('fd41f13f-2abd-4cce-ba8e-06a55c0b506f', 'Әкемен саябақта жүгіру 👨‍👧', 'Ана болу — 24/7 жалғасатын кезекшілік емес. Серіктесіңізді іске қосыңыз! Бүгін бөпенің сарқылмас энергиясын әкесі саябақта шығарсын, ал Сіз үйде мүлгіген тыныштықтан ләззат алыңыз.'),
  ('587f6b4e-5494-4f6a-8efa-28e0cb53f529', 'Асүйдегі концерт 🥄', 'Кәстрөлдер мен ағаш қасықтарды шығарып алып, асүйдің ортасында концерт қояды. Басыңыз ауырса да, бұл — оның ырғақ сезімі мен шығармашылығының дамуы. Бірден тоқтатуға асықпаңыз, сол тасыған энергияның дыбыс толқындарымен бөлмеге бірнеше минут таралуына мүмкіндік беріңіз.'),
  ('a36ee256-d6c9-4345-a732-3a052e7dd260', 'Ауа райын барлау ⛅', 'Сыртта күн ашық болғанымен, жел соғып тұр ма? Ауа райы мен киім таңдау құралы терезеден байқалмайтын желдің жылдамдығын анықтап, не кию керегін бірден айтсын. Осылайша есік алдында ойланып, уақыт жоғалтпай серуенге шыға аласыз.'),
  ('c95b298d-8316-46aa-ace1-1fc1956a0fda', 'Командалық массаж 💆‍♂️', 'Бала ұйықтағаннан кейін күндізгі күйзелістен арылу үшін серігіңізбен бір-біріңіздің иығыңызға массаж жасаңыздар. Сіздер бір үйде тұратын ата-ана ғана емес, бір-біріне мызғымас тірек болатын командасыздар.'),
  ('272c7bb7-edd9-4323-8db9-05fe3c752757', 'Көңіл күйдің күрт өзгеруі 🤖', 'Үш жарым жасқа таяған балаңыздың көңіл күйі күрт өзгеріп, Сізді алаңдата ма? Интернеттегі үрей туғызатын, жанға бататын форумдарды жабыңыз. Anacan AI-дан осы жас кезеңіндегі дағдарыстар туралы ғылыми және психологиялық тұрғыдан негізделген, көңіліңізді орнықтыратын жауап алыңыз.'),
  ('53a9bbe1-a99a-4438-963b-9b63a44c8eb3', 'Жылы судың кереметі 🛀', 'Кейде ештеңе көмектеспей, ол болмашы нәрсенің бәріне жылай береді. Оны жылы су толтырылған ваннаға отырғызып, аздап көбік қосыңыз. Судың бойдағы ширығуды басатын ғажайып күші бүкіл бөлмеге тыныштық орнатып, оның жүйке жүйесін де бірден жайландырады.'),
  ('b49dbabf-98b6-4f35-8748-de30793c2722', 'Киім үйлестіру шебері 👗', 'Бүгін ол далаға екі түрлі шұлық киіп, жейдесін теріс айналдырып шыққысы келеді. Қоғамның бәрі үйлесімді болуы керек деген талабына мән бермеңіз. Өз бетінше шешім қабылдап, оны қорғай білу еркіндігі — түстерді үйлестіруден әлдеқайда маңызды өмірлік сабақ. Рұқсат етіңіз.'),
  ('00f8be55-b6c0-4a3e-8a0e-ee6c807fdab5', 'Жанды диктофон 🎙️', 'Кеше серігіңізбен сөйлескенде байқамай айтып қалған, бәлкім, орынсыз бір сөзіңізді ол бүгін таңертең ойыншығына айтып отыр! Ол — Сіздің тірі айнаңыз. Оның жанында қандай эмоциямен сөйлейтініңізге ерекше мән беріңіз: ол бәрін бір-бірлеп қайталайды.'),
  ('885b2dd9-966f-46c2-bbae-00f0fd65a479', 'Әкенің көңілді ертегісі 📖', 'Бүгін кешке бөлмеде Сіздің емес, әкесінің даусы естілсін. Ертегі кітабын әкесіне беріп, оқиғаны әдейі бұрмалап, күлкілі әрі қисынсыз етіп айтып беруіне мүмкіндік жасаңыз. Балаңыздың оны түзеткеніне қалай мәз болып, әкесіне қарап қалай қарқылдап күлетінін сырттай бақылаңыз.'),
  ('fdf68496-5c5f-493c-aaed-7e9ab140b9c8', 'Қауымдастықтың күші 💬', '«Менің балам неге сонша қырсық?» деген ой мазаңызды алып жүр ме? Anacan Қауымдастығына қосылыңыз. Басқа аналардың үйінде де болатын осындай қисынсыз дағдарыстар туралы оқығанда, жалғыз емес екеніңізді және бұл жолдан өтуіңіз әбден қалыпты екенін түсінесіз.'),
  ('cc3a0c4f-7f53-45a5-9f17-0dcfdb18b0c4', 'Эмпатия шыңы 🩹', 'Ойыншық қонжығының қолы ауырып тұр деп, оған жапсырма жабыстырып, сүйіп қоя ма? Оның осындай кең әрі мейірімді жүрегіне сүйсініңіз. Бұл терең эмпатия сезімін Даму трекеріне мінезінің ең көркем қыры ретінде мақтанышпен белгілеңіз.'),
  ('1f4d8560-3286-4e95-8474-fcafd793fada', 'Әкесінің алаңы 👨‍👧', 'Шыдам таусылып бара ма? Бөлменің есігін жауып, баланы әкесімен оңаша қалдырыңыз. Бүгін кешке үйдегі ойындарды тек әкесі басқарсын, ал Сіз демалыңыз.'),
  ('cd8e0cdd-1b7c-42e3-856f-3b4914ee1697', 'Көкөніс шайқасы 🥦', 'Тәрелкедегі жасыл көкөністерді шетке ысырып қоя ма? Қарсыласпаңыз. Пайдалы рецепттерден көкөністерді кекс немесе котлеттің ішіне білдірмей қосуға болатын айла-тәсілдерді табыңыз.'),
  ('52a1e30d-f365-493c-8480-78b508714eb6', 'Қараңғыдан қорқа ма? 👻', '3.5 жасқа қарай қараңғыдан қорқу жиі байқалады. Бөлмеге шағын түнгі шам қойып, Ақылды ертегілерде батыл кейіпкерлер туралы хикаялар құрастырыңыз.'),
  ('cbfa1fac-401d-41c2-974d-c9424b7436ce', 'Аналар әңгімесі 💬', '«Менің балам неге әлі күнге дейін түбекке толық үйренбеді?» деген ой Сізді қажыта ма? Anacan қауымдастығына қосылсаңыз, әр баланың даму қарқыны әртүрлі екенін көресіз.'),
  ('cde5f67f-33e9-4a06-9155-b70a56cb6c73', 'Сөздерді өзгерте ме? 🗣️', 'Кейбір әріптерді әдейі өзгертіп, күлкілі дыбыстар шығарады да, соған өзі күле ме? Ол тілдің икемділігін зерттеп жүр. Сіз де оған қосылып, сөз ойындарын ойнаңыз.'),
  ('57748696-ab80-425d-85cf-6283ca454879', 'Достық сезімі 👫', 'Саябақта басқа балалармен қатар ойнамай, енді олармен бірге белсенді ойнауға талпына ма? Әлеуметтену ресми түрде басталды! Қауіпсіздігін алыстан бақылап, осы сәтті тамашалаңыз.'),
  ('7a91d538-17ac-47d6-a73e-975aed76abb5', 'Кішкентай кәсіпкер 🍅', 'Бөлменің бір бұрышына ойыншықтарын жинап, Сізге қиялдағы ақшаға қиялдағы қызанақ сатады. Бұл сауда ойынына барынша байыппен қараңыз. Қиялдағы қызанақты сатып алып, тәбетпен жеп жатқандай кейіп танытыңыз. Рөлдік ойындар — оның әлеуметтік зердесі мен математикалық ойлау қабілетінің берік негізі.'),
  ('87c32869-7e9b-4faa-bbbe-1c640a3da5bb', 'Кальций қалқаны 🦴', 'Жылдам өсіп жатқан сүйектерге кальций өте қажет. Сүт ішпей ме? Тамақтануды бақылау құралы арқылы бүгін жеген ірімшік, айран немесе брокколи мөлшерін міндетті түрде есептеңіз.'),
  ('dca4203c-2783-4935-8d52-5e2abbd31c77', 'Төсектен қашу 🏃‍♂️', 'Су берші, ойыншығымды тауып берші... Ұйықтамау үшін 3 жастағы бөпенің сылтауы таусылмайды. Ұйқы таймерін қосып, белгіленген шекараны нық сақтаңыз.'),
  ('0f8f4362-f6e4-4b76-8a62-4dbaf7dbf605', 'Алып жүк 🎒', 'Сіздің ауыр сөмкелеріңізді немесе үлкен қолшатырыңызды міндетті түрде өзі көтергісі келеді. Әзер сүйреп бара жатса да, көмектен үзілді-кесілді бас тартады. Күшін сынап көрсін: ол өзін үйдегі ең мықты қаһарман сезінгісі келеді. Дербес болуына кедергі жасамаңыз.'),
  ('13ddaeb9-9c7f-4a7b-ad20-6e0285eb57cf', 'Жаңа болмыс 🕷️', 'Таңертең оянып, Сізге өте байыппен: Мен бала емеспін, мен өрмекшімін, дейді. 40-шы айға қарай қиялы шексіз дами бастайды. Таласпай-ақ қойыңыз, оған таңғы асын жейтін өрмекшінің рөлін беріп, осы қызық театрға қосылыңыз.'),
  ('b2a11f30-5597-4b15-9f01-835c2894a09b', 'Таусылмайтын сылтаулар 🦶', 'Ұйықтап бара жатқанда Аяғымның башпайы қышып тұр деген сылтаумен төсектен тұрғысы келеді. Ұйқыны кейінге қалдыру өнерін әбден меңгерген. Байыпты болыңыз, аяғын қасығандай болып, жарықты нық қимылмен өшіріңіз. Шекараны Сіз белгілейсіз.'),
  ('417acfcf-4492-4093-aa86-48285ecc470a', 'Әкенің баскиім шарты 🧢', 'Төсекке жату үшін әкесінің міндетті түрде қысқы баскиім киюін талап етеді. Әкесі сол баскиімді киіп, күлкілі дыбыстар шығарсын. Кешкі осы бір қызық көрініс ұйықтар алдында Сіздерді күлдіріп қана қоймай, баланың қырсықтығын да бірден басады.'),
  ('7516076d-1a63-4620-b73e-63a31b706bac', 'Физикаға бағынбайтын қырсықтық 💧', 'Суды құрғақ қылып беріңіз деп өксіп жылай ма? Бала миы мүмкін емес нәрселерді талап ету арқылы шын мәнінде Сіздің ерік-жігеріңізді сынайды. Бұл жағдайда қисын іздемеңіз, жай ғана басқа түсті зат көрсетіп, назарын бірден басқа жаққа аударыңыз.'),
  ('61cf1118-2d1d-4e42-9dac-f7a6ca616e71', 'Үнсіз сырлас 📝', 'Сізді ешкім түсінбейтіндей болып, үйде қатты шаршап жүрсіз бе? Жалған жымиюды доғарыңыз. Көңіл күй күнделігіне бүгін шын мәнінде қаншалықты қажығаныңызды жазыңыз. Экранға жазылған әрбір сөз иығыңыздағы ауыр жүктің бір бөлігін жеңілдетеді.'),
  ('a2f88e5e-134a-4514-9134-a36d1a155887', 'Едендегі ұйқы 🥱', 'Күндіз ұйықтағысы келмей, қасарысып еді, ақыры ойыншықтарының ортасында, кілемнің үстінде бүрісіп ұйықтап қалды. Төсегіне апарып, оятып алмаңыз. Бөлменің ортасында пәк күйінде тәтті ұйқысын қандыра берсін, ал Сіз 1 сағат демалып алыңыз.'),
  ('489a0197-f1e2-44a5-bece-55d85fa323ae', 'Ауа райын зерттеу ⛅', 'Күн шығып тұр, бірақ ол қыстық күртесін кигісі келеді. Дауласпаңыз. Ауа райы мен киім құралын ашып, экрандағы жеңіл киінген бала белгішесін көрсетіңіз. «Қарашы, телефон бүгін күн жылы деп тұр» деген айла әрдайым керемет көмектеседі.'),
  ('64df174c-9f28-403f-83be-8452dd687caf', 'Оқиға желісі оның қолында 🪄', 'Классикалық ертегілер енді оның назарын аудармайды. Ақылды ертегілерді ашып, одан: «Енді бұл сиқырлы пойыз қайда барсын?» — деп сұраңыз. Өзі ойлап тапқан сол бір оғаш әрі мүлде қисынсыз финалмен қиялға беріліп, ұйықтап қалсын.'),
  ('e9ba59d9-6287-434c-823d-456c6d21f0ef', 'Тіс дәрігерінің қабылдауы 🦷', 'Қолына тіс щеткасын алып, тістеріңізді мұқият тексергісі келе ме? Аузыңызды ашып, осы күлкілі дәрігердің айтқанын орындаңыз. Рөлдік ойындар — тұлғалық дамудың және қорқынышты жеңудің ең тиімді әрі ең қызықты жолы.'),
  ('cafa10cc-4494-418e-834e-6ddf05c49140', 'Қоқыс емес, қазына 🍬', 'Бірнеше күн бойы сақтап жүрген, бірақ ойнамаған ескі шоколад қағазын қоқысқа тастағаныңыз үшін үйде айқай-шу басталды ма? Сіз үшін қоқыс болған нәрсе оның құнды коллекциясының бір бөлігі болуы мүмкін. Жылауын тоқтату үшін назарын бірден одан да қызықты затқа аударыңыз.'),
  ('d9ad6664-d013-4d53-b45b-e81b7aa6c58c', 'Шампансыз жеңіс 🥂', 'Бала ұйықтап қалды. Шампан болмаса да, стақандарға ыстық шай құйып, жұбыңызбен «Бүгін де осы аласапыранды еңсере алдық» деп, стақандарыңызды соғыстырыңыз. Сіздер — отбасының мызғымас әрі қажымас командасысыздар.'),
  ('e8db8e88-207e-4ac3-9421-9b1c49bdfd27', 'Брокколи детективі 🥦', 'Сорпаның ішіндегі жалғыз жасыл көкөністі байқап қалып, тамақтан бас тартып отыр ма? Тамақтану жоспарындағы көкөністерді түрлі түсті макаронмен араластырып, назарын аударудың және езбе жасап жасырудың ең шебер тәсілдерін қолданыңыз.'),
  ('b726a724-b8d0-4de2-92f7-30636fde8d1a', 'Шкаф ішіндегі тыныштық 🚪', 'Үй іші кенеттен тып-тыныш болып, оны шкафтың ішіне тығылып, өз бетімен ойнап отырған жерінен таптыңыз. Бұл — жеке кеңістікке деген қажеттілік. Оны бірден ол жерден шығармаңыз: ол да шудан алыстап, жалғыз қалып, миын тынықтырғысы келеді.'),
  ('4b514d29-e0d8-49a4-850f-900d0c46bffa', 'Үнсіз ашу 😤', 'Қалағаны болмаған кезде жылаудың орнына қолын айқастырып, қабырғаға қарап, Сізге ренжіп қалады. Бұл — эмоцияларды басқаруды үйренудегі жаңа әрі өте маңызды кезең. Оған тиіспей, біраз уақыт беріңіз: 3 минуттан кейін ештеңе болмағандай күліп, қайта оралады.'),
  ('4b721431-3565-4047-8fb3-144c9d3a8f8b', 'Алтын тыныштықтың өлшемі 🤫', 'Үйдегі шу құлағыңызды тұндырады. Ол ақыры ұйықтап қалғанда, Дыбыс өлшегіш құралын іске қосыңыз. Экрандағы нөлге жуық сандарды, цифрлық тыныштықты бақылау — шаршаған ананың миына арналған ең жағымды визуалды массаж.'),
  ('6fcf10ba-99bd-4b23-bbff-0487161fbfe4', 'Жаңа тілдің ашылуы 🗣️', 'Ол Ұшатын-қашатын, Ыстық-суық секілді өзі ойлап тапқан күрделі әрі қызық сөздерді қолдана бастады. Сөздік қоры таңғаларлық жылдамдықпен кеңейіп келеді. Оның өзі ойлап тапқан осындай күлкілі сөздерін ұмытылмас мұрағат ретінде Даму бақылағышына міндетті түрде жазып қойыңыз.'),
  ('2c413ba6-81fc-4861-95ac-e87a4f29055d', 'Ерекше жолсерік 🥄', 'Саябаққа барарда ойыншық көліктерін емес, асүйден тауып алған шөмішті өзімен бірге алып жүруге табандап тұрады. Кедергі жасамаңыз! Бүгін сол шөміш саябақта құм қазуға арналған ең ерекше, бірақ ең пайдалы ойыншығына айналады.'),
  ('b865240d-5ee4-4c57-917c-6139d1ce4039', 'Мысықтар судан қорқады 🐈', 'Ваннаға түспеу үшін: «Мен мысықпын, ал мысықтар шомылмайды», — дейді. Оның рөлін қабылдап, ойынды жалғастырыңыз: «Ал мына мысық сабын көпіршіктерімен ойнағысы келе ме?» — деп қызықтырыңыз. Осылайша қиялдың көмегімен қарсылығын жеңіңіз.'),
  ('f573b98e-335c-4b92-b5f7-06c122ba5b12', 'Кәсіби саудаласу 🛒', 'Дүкенде кәмпит сұрап жылаудың орнына: «Мынаны алып берсеңіз, сорпамды ішемін», — деп саудаласады. Құттықтаймыз, кішкентай адвокатыңыз өсіп келеді! Бірдеңені ұмытып кетпеу үшін Сатып алу тізімін ашық ұстаңыз, онымен пікір таластырған кезде ойыңыз бөлініп кетпесін.'),
  ('605e9c74-a673-4f1f-9b27-383f6a4810eb', '«Маған қараңыз!» кезеңі 👀', 'Ол диваннан секіріп, бір қимылды тура 50 рет қайталап, әр жолы Сіздің мақұлдауыңызды күтеді. Көзіңізді телефоннан алыңыз. Ол қимылдың өзі үшін емес, Сіздің көзіңіздегі сүйіспеншілікке толы мақұлдау нұрын көру үшін секіреді.'),
  ('465bfed4-fe0b-4cbe-96cc-61ab753a7ff8', 'Денедегі өнер 🖍️', 'Кенет орнаған тыныштықтан күдіктеніп, оны қолына фломастермен сурет салып отырған жерінен таптыңыз. Ашуланбаңыз. Бөпеңіз ұсақ моторикасын дамытып жатыр, ал терідегі бояу сумен-ақ жуылады. Терең дем алып, осы күлкілі сәтті видеоға түсіріп алыңыз.'),
  ('5f1b9ed1-3342-457d-874b-d33366fcceaf', 'Сыбыр гипнозы 🤫', 'Төсекте белсенді қимылдағаны сонша, ұйықтай алмай жүр. Даусыңызды көтерудің орнына, кенет бәсеңдетіңіз. Онымен тек сыбырлап сөйлесіңіз. Бала Сізді есту үшін бар зейінін салғанда, миы автоматты түрде ұйқы режиміне ауысады.'),
  ('6ac2df5a-944c-4a22-9450-7bfad30550c4', 'Аналар қауымдастығының күші 💬', '«Бұл бала ешқашан тынышталмайды» деген ой Сізді шаршатты ма? Anacan қауымдастығына қосылыңыз. Ондағы аналардың осыған ұқсас, тіпті одан да күлкілі қырсықтық оқиғаларын оқығанда, жалғыз емес екеніңізді түсініп, бір жеңілдеп қаласыз.'),
  ('7b051600-3f87-4940-baec-461cd64e5af1', 'Философия профессоры 🤔', '«Жел неге көрінбейді?», «Жапырақ неге түседі?» Таңсәріден қойылған терең сұрақтар басыңызды қатырады. Сағаттап ғылыми түсініктеме беруге тырыспаңыз. Өйткені «ағаштар киімдерін ауыстырып жатыр» деген сияқты қиялға толы сүйкімді жауаптар бұл жаста оны толық қанағаттандырады.'),
  ('7bab0bc1-e2b8-4588-8d81-ecc8ddbde523', 'Көлеңкелермен би 🐰', 'Қараңғыдан қорқатынын сылтауратып, төсектен қашып кетеді. Бөлмедегі барлық жарықты өшіріп, қолшамды жағыңыз да, қабырғаға қолыңызбен құс пен иттің көлеңкесін түсіріңіз. Ол қорқатын қараңғылық санаулы секундта театрға айналады.'),
  ('d0ef94fa-1acc-4932-b3b2-947791c88119', 'Жасанды интеллект — көмекші 🤖', 'Баланың сұрақтарына немесе оғаш қылықтарына жауап таба алмай жүрсіз бе? Anacan AI-ға жүгініңіз. Ол 3 жастан асқан балалардың миы қалай жұмыс істейтінін Сізге педиатрдың тілімен қысқа әрі көңіліңізді тыныштандыратындай етіп түсіндіреді.'),
  ('2e15df12-458b-434c-ac05-d42b6b0a04b3', 'Демінің жылуы 💖', 'Ол күні бойы Сізді әбден әбігерге салып, бәріне қырсықты. Бірақ қазір төсекте кеудеңізге тығылып жатыр, ал бөлме оның бірқалыпты тынысымен тербелуде. Ана болудың ең үлкен сыйы — дәл осы. Оны бауырыңызға басып, бар шаршағаныңызды ұмытыңыз.'),
  ('b9503491-2c22-4639-94ac-cc1a79aea888', 'Теріс киілген аяқкиім мақтанышы 👟', 'Аяқкиімін теріс киіп алған, бірақ әлемді бағындырғандай мақтанышпен жүр. Араласып, дұрыстауға тырыспаңыз. Баланың өзіне деген сенімі мен дербестігі киімінің әдемі көрінуінен миллион есе маңызды.'),
  ('9fedc843-d647-418d-b31f-ad9bf956e849', 'Қалтаңыздағы тізім 🛒', 'Күнделікті қарбаласта сусабын таусылды ма, әлде дымқыл майлық па? Бәрін есте сақтауға тырыспай-ақ, бірден Сатып алу тізіміне жазып, жұбайыңызбен синхрондаңыз.'),
  ('ac1c42c5-b375-4935-bfbe-c3b0f8da74a1', 'Тыныштық қажет 🤫', 'Бөпе ұйықтап кеткеннен кейінгі алғашқы жарты сағат — ең сезімтал кезең. Дыбыс өлшегішпен бөлмедегі децибел деңгейін тексеріп, көрші бөлмедегі теледидардың дауысын бәсеңдетіңіз.')
) AS v(id, t, b)
WHERE x.id = v.id;
